```cpp
#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <unordered_map>

struct TX_POWER_REPORT {
    int rnti;
    long timestamp;
    float power_level;
};

class PowerReportManager {
public:
    void add(int rnti, long timestamp, float power_level) {
        std::lock_guard<std::mutex> lock(_mutex);
        _power_reports.push_back(TX_POWER_REPORT{rnti, timestamp, power_level});
    }

    void update(int rnti, long timestamp, float power_level) {
        std::lock_guard<std::mutex> lock(_mutex);
        for (auto it = _power_reports.begin(); it != _power_reports.end(); ++it) {
            if ((*it).rnti == rnti) {
                (*it).timestamp = timestamp;
                (*it).power_level = power_level;
                break;
            }
        }
    }

    void delete(int rnti) {
        std::lock_guard<std::mutex> lock(_mutex);
        for (auto it = _power_reports.begin(); it != _power_reports.end(); ++it) {
            if ((*it).rnti == rnti) {
                _power_reports.erase(it);
                break;
            }
        }
    }

    std::vector<TX_POWER_REPORT> retrieve() {
        std::lock_guard<std::mutex> lock(_mutex);
        return _power_reports;
    }

private:
    std::mutex _mutex;
    std::condition_variable _cv;
    std::unordered_map<int, TX_POWER_REPORT> _power_reports;
};
```
