// Function to copy a specified number of bytes from a list of buffered data chunks into a new buffer without modifying the original data.
void copyBuffer(const std::vector<std::shared_ptr<char>>& buffers, size_t numBytes, std::shared_ptr<char>& newBuffer) {
    // Calculate the total number of bytes to be copied.
    size_t totalBytes = 0;
    for (auto buffer : buffers) {
        totalBytes += buffer->size();
    }

    if (numBytes > totalBytes) {
        throw std::invalid_argument("Invalid number of bytes specified");
    }

    // Allocate the new buffer.
    newBuffer = std::make_shared<char>(numBytes);

    // Copy the data from the buffers to the new buffer.
    size_t offset = 0;
    for (auto buffer : buffers) {
        memcpy(newBuffer->get() + offset, buffer->get(), buffer->size());
        offset += buffer->size();
    }
}

