        std::cerr << "Error opening input file: " << inputFilePath << std::endl;
        return 1;
    }

    // Initialize the worker threads.
    const int numThreads = std::thread::hardware_concurrency();
    std::vector<std::thread> threads(numThreads);
    std::mutex bufferMutex;
    std::condition_variable bufferCondVar;
    std::atomic<bool> done{false};

    // Define the function to be executed by each worker thread.
    auto work = [&](int id) {
        // Read the input file in parallel using multiple worker threads.
        while (!done) {
            // Acquire a buffer from the pool.
            std::shared_ptr<char> buffer;
            {
                std::lock_guard<std::mutex> lock(bufferMutex);
                if (bufferPool.empty()) {
                    bufferCondVar.wait(lock);
                    continue;
                }
                buffer = bufferPool.front();
                bufferPool.pop_front();
            }

            // Read the data from the input file into the buffer.
            if (!std::fread(buffer->get(), sizeof(char), buffer->size(), inputFile)) {
                break;
            }

            // Add the buffer to the output queue.
            std::lock_guard<std::mutex> lock(outputMutex);
            outputQueue.push_back(buffer);
        }
    };

    // Start the worker threads.
    for (int i = 0; i < numThreads; ++i) {
        threads[i] = std::thread{work, i};
    }

    // Wait for the worker threads to finish.
    for (auto& thread : threads) {
        thread.join();
    }

    // Close the input file.
    inputFile.close();

    // Process the output buffers.
    int totalLines = 0;
    std::vector<std::shared_ptr<char>> processedBuffers;
    {
        std::lock_guard<std::mutex> lock(outputMutex);
        processedBuffers = std::move(outputQueue);
    }
    for (auto& buffer : processedBuffers) {
        // Process the data in the buffer.
        int numLines = 0;
        for (char* line = buffer->get(); line < buffer->get() + buffer->size(); ++line) {
            if (*line == '\n') {
                numLines++;
            }
        }
        totalLines += numLines;

        // Add the buffer to the pool.
        std::lock_guard<std::mutex> lock(bufferMutex);
        bufferPool.push_back(buffer);
        bufferCondVar.notify_one();
    }

    // Log the total number of lines processed.
    if (logger) {
        logger->log("Total lines: " + std::to_string(totalLines));
    }

    return 0;
}
