#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <assert.h>
#include <openssl/aes.h>
#include <openssl/des.h>
#include <openssl/modes.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>

#define MODE_NONE 0
#define MODE_ENCRYPT 1
#define MODE_DECRYPT 2

#define BUFFER_SIZE 4096
#define KEY_SIZE 32 // bytes

struct cipher {
    char *name;
    int keylen;
    unsigned long flags;
};

static struct cipher supported_ciphers[] = {
    {"aes-128-cbc",  16, MODE_ENCRYPT | MODE_DECRYPT},
    {"aes-192-cbc",  24, MODE_ENCRYPT | MODE_DECRYPT},
    {"aes-256-cbc",  32, MODE_ENCRYPT | MODE_DECRYPT},
    {"des-ede3-cbc", 24, MODE_ENCRYPT | MODE_DECRYPT},
    {"des-ede-cbc",  16, MODE_ENCRYPT | MODE_DECRYPT},
};

static struct cipher *get_cipher(const char *name) {
    for (int i = 0; i < sizeof(supported_ciphers) / sizeof(struct cipher); ++i) {
        if (!strcmp(supported_ciphers[i].name, name)) {
            return &supported_ciphers[i];
        }
    }
    return NULL;
}

// Returns true if the given cipher is supported by this library.
static bool is_cipher_supported(const char *name) {
    return get_cipher(name) != NULL;
}

// Generates a random key of the specified length (in bytes).
static void generate_key(unsigned char *key, int len) {
    RAND_bytes(key, len);
}

// Initializes a cipher context with the given name and key.
static EVP_CIPHER_CTX *init_cipher(const char *name, const unsigned char *key) {
    struct cipher *cipher = get_cipher(name);
    if (!cipher) {
        return NULL;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "EVP_CIPHER_CTX_new() failed\n");
        return NULL;
    }

    int ret = EVP_EncryptInit_ex(ctx, cipher->name, NULL, key, NULL);
    if (ret != 1) {
        fprintf(stderr, "EVP_EncryptInit_ex() failed\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}

// Frees a cipher context.
static void free_cipher(EVP_CIPHER_CTX *ctx) {
    if (ctx != NULL) {
        EVP_CIPHER_CTX_free(ctx);
    }
}

// Encrypts the given data with the specified cipher and returns the result.
static unsigned char *encrypt(const struct cipher *cipher, const unsigned char *data, int len) {
    EVP_CIPHER_CTX *ctx = init_cipher(cipher->name, cipher->key);
    if (!ctx) {
        return NULL;
    }

    // Set the encrypt mode.
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, NULL, NULL) != 1) {
        fprintf(stderr, "EVP_EncryptInit_ex() failed\n");
        free_cipher(ctx);
        return NULL;
    }

    // Determine the buffer size.
    int buflen = len + EVP_CIPHER_CTX_block_size(ctx);

    // Allocate memory for the result.
    unsigned char *result = malloc(buflen);
    if (result == NULL) {
        fprintf(stderr, "malloc() failed\n");
        free_cipher(ctx);
        return NULL;
    }

    // Encrypt the data.
    int outlen = 0;
    if (EVP_EncryptUpdate(ctx, result, &outlen, data, len) != 1) {
        fprintf(stderr, "EVP_EncryptUpdate() failed\n");
        free_cipher(ctx);
        free(result);
        return NULL;
    }

    // Finalize the encryption.
    if (EVP_EncryptFinal_ex(ctx, result + outlen, &outlen) != 1) {
        fprintf(stderr, "EVP_EncryptFinal_ex() failed\n");
        free_cipher(ctx);
        free(result);
        return NULL;
    }

    // Store the length of the result.
    buflen = outlen + EVP_CIPHER_CTX_block_size(ctx);

    // Free the cipher context.
    free_cipher(ctx);

    return result;
}

// Decrypts the given data with the specified cipher and returns the result.
static unsigned char *decrypt(const struct cipher *cipher, const unsigned char *data, int len) {
    EVP_CIPHER_CTX *ctx = init_cipher(cipher->name, cipher->key);
    if (!ctx) {
        return NULL;
    }

    // Set the decrypt mode.
    if (EVP_DecryptInit_ex(ctx, NULL, NULL, NULL, NULL) != 1) {
        fprintf(stderr, "EVP_DecryptInit_ex() failed\n");
        free_cipher(ctx);
        return NULL;
    }

    // Determine the buffer size.
    int buflen = len + EVP_CIPHER_CTX_block_size(ctx);

    // Allocate memory for the result.
    unsigned char *result = malloc(buflen);
    if (result == NULL) {
        fprintf(stderr, "malloc() failed\n");
        free_cipher(ctx);
        return NULL;
    }

    // Decrypt the data.
    int outlen = 0;
    if (EVP_DecryptUpdate(ctx, result, &outlen, data, len) != 1) {
        fprintf(stderr, "EVP_DecryptUpdate() failed\n");
        free_cipher(ctx);
        free(result);
        return NULL;
    }

    // Finalize the decryption.
    if (EVP_DecryptFinal_ex(ctx, result + outlen, &outlen) != 1) {
        fprintf(stderr, "EVP_DecryptFinal_ex() failed\n");
        free_cipher(ctx);
        free(result);
        return NULL;
    }

    // Store the length of the result.
    buflen = outlen + EVP_CIPHER_CTX_block_size(ctx);

    // Free the cipher context.
    free_cipher(ctx);

    return result;
}

int main() {
    const char *name = "aes-128-cbc";
    unsigned char key[16];
    generate_key(key, sizeof(key));

    struct cipher *cipher = get_cipher(name);
    if (!cipher) {
        printf("Cipher '%s' is not supported\n", name);
        return 1;
    }

    unsigned char *data = "Hello, World!";
    int len = strlen((char *) data);

    // Encrypt the data.
    unsigned char *encrypted = encrypt(cipher, data, len);
    if (encrypted == NULL) {
        printf("Encryption failed\n");
        return 1;
    }

    // Decrypt the data.
    unsigned char *decrypted = decrypt(cipher, encrypted, len);
    if (decrypted == NULL) {
        printf("Decryption failed\n");
        free(encrypted);
        return 1;
    }

    // Print the result.
    printf("%s -> %s\n", data, decrypted);

    // Free the memory.
    free(encrypted);
    free(decrypted);

    return 0;
}']

