// Header file for the cryptographic service
#ifndef CRYPTO_SERVICE_H
#define CRYPTO_SERVICE_H

#include <openssl/crypto.h>
#include <stdbool.h>
#include <stdint.h>

// Define the error codes for the cryptographic service
enum ErrorCode {
    SUCCESS = 0,
    INVALID_ARGUMENTS = 1,
    OPENSSL_ERROR = 2,
    MEMORY_ALLOCATION_FAILURE = 3
};

// Define the supported cryptographic operations
enum OperationType {
    ENCRYPTION = 0,
    DECRYPTION = 1,
    SIGNING = 2,
    VERIFICATION = 3
};

// Structure to represent a cipher object
struct CipherObject {
    enum OperationType type;
    void* data;
};

// Function to initialize the cryptographic service
int cryptoServiceInit(void);

// Function to release resources allocated by the cryptographic service
void cryptoServiceRelease(void);

// Function to perform a cryptographic operation (encryption, decryption, signing, or verification)
struct CipherObject* cryptoOperation(enum OperationType type, const void* data, size_t length);

// Function to free the memory allocated by the cipher object
void cryptoFreeCipherObject(struct CipherObject* cipherObj);

#endif // CRYPTO_SERVICE_H

// Implementation file for the cryptographic service

#include "cryptoservice.h"
#include <openssl/evp.h>
#include <string.h>
#include <stdio.h>

static EVP_CIPHER_CTX* ctx = NULL; // Context for the current cryptographic operation
static struct CipherObject* cipherObj = NULL; // Resulting cipher object for the current operation

// Initialize the cryptographic service
int cryptoServiceInit(void) {
    // Allocate memory for the context and set it to NULL
    ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        printf("Error: Failed to allocate memory for the OpenSSL context\n");
        return MEMORY_ALLOCATION_FAILURE;
    }

    return SUCCESS;
}

// Release resources allocated by the cryptographic service
void cryptoServiceRelease(void) {
    // Release the OpenSSL context
    EVP_CIPHER_CTX_free(ctx);
}

// Perform a cryptographic operation (encryption, decryption, signing, or verification)
struct CipherObject* cryptoOperation(enum OperationType type, const void* data, size_t length) {
    // Validate the input arguments
    if (data == NULL || length == 0) {
        printf("Error: Invalid arguments passed to cryptoOperation\n");
        return NULL;
    }

    // Allocate memory for the cipher object
    cipherObj = malloc(sizeof(struct CipherObject));
    if (cipherObj == NULL) {
        printf("Error: Failed to allocate memory for the cipher object\n");
        return NULL;
    }

    // Initialize the OpenSSL context with the appropriate algorithm and key
    switch (type) {
        case ENCRYPTION:
            if (!EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
                printf("Error: Failed to initialize the OpenSSL context for encryption\n");
                return NULL;
            }
            break;
        case DECRYPTION:
            if (!EVP_DecryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, NULL, NULL)) {
                printf("Error: Failed to initialize the OpenSSL context for decryption\n");
                return NULL;
            }
            break;
        case SIGNING:
            if (!EVP_SignInit_ex(ctx, EVP_sha256(), NULL)) {
                printf("Error: Failed to initialize the OpenSSL context for signing\n");
                return NULL;
            }
            break;
        case VERIFICATION:
            if (!EVP_VerifyInit_ex(ctx, EVP_sha256(), NULL)) {
                printf("Error: Failed to initialize the OpenSSL context for verification\n");
                return NULL;
            }
            break;
        default:
            printf("Error: Unsupported cryptographic operation\n");
            return NULL;
    }

    // Set the input data and length for the cipher object
    cipherObj->type = type;
    cipherObj->data = malloc(length);
    if (cipherObj->data == NULL) {
        printf("Error: Failed to allocate memory for the cipher object\n");
        return NULL;
    }
    memcpy(cipherObj->data, data, length);

    // Perform the cryptographic operation and handle any errors
    switch (type) {
        case ENCRYPTION:
            if (!EVP_EncryptUpdate(ctx, cipherObj->data, &length, data, length)) {
                printf("Error: Failed to encrypt the input data\n");
                return NULL;
            }
            break;
        case DECRYPTION:
            if (!EVP_DecryptUpdate(ctx, cipherObj->data, &length, data, length)) {
                printf("Error: Failed to decrypt the input data\n");
                return NULL;
            }
            break;
        case SIGNING:
            if (!EVP_SignUpdate(ctx, data, length)) {
                printf("Error: Failed to update the signing context with the input data\n");
                return NULL;
            }
            break;
        case VERIFICATION:
            if (!EVP_VerifyUpdate(ctx, data, length)) {
                printf("Error: Failed to update the verification context with the input data\n");
                return NULL;
            }
            break;
        default:
            printf("Error: Unsupported cryptographic operation\n");
            return NULL;
    }

    return cipherObj;
}

// Release memory for the cipher object
void cryptoFree(struct CipherObject* obj) {
    // Validate the input argument
    if (obj == NULL) {
        printf("Error: Invalid arguments passed to cryptoFree\n");
        return;
    }

    // Release memory for the cipher object data and the cipher object itself
    free(obj->data);
    free(obj);
}']

