using namespace std;

// Structure to represent a session in the list
struct Session {
    string id;
    string data;
    Session* next;
    Session* prev;
};

// Global variables for the doubly linked list and logging service
mutex g_listMutex;
Session* g_listHead = nullptr;
mutex g_logMutex;
atomic<int> g_logCount {0};
condition_variable g_logCondVar;

// Function to append or insert a session in the list
void appendOrInsertInList(string id, string data) {
    // Lock the mutex to prevent concurrent modifications
    lock_guard<mutex> guard(g_listMutex);

    // Check if the session ID is already present in the list
    Session* curr = g_listHead;
    while (curr != nullptr) {
        if (id == curr->id) {
            // If the ID is found, insert the new session data after it
            auto* newSession = new Session();
            newSession->id = id;
            newSession->data = data;
            newSession->next = curr->next;
            if (curr->next != nullptr) {
                curr->next->prev = newSession;
            }
            curr->next = newSession;
            break;
        }
        curr = curr->next;
    }

    // If the ID is not found, append it to the end of the list
    if (curr == nullptr) {
        auto* newSession = new Session();
        newSession->id = id;
        newSession->data = data;
        newSession->prev = curr;
        if (g_listHead != nullptr) {
            g_listTail->next = newSession;
        } else {
            g_listHead = newSession;
        }
        g_listTail = newSession;
    }

    // Asynchronously log the operation details using the logging service
    auto loggerTask = [id, data]() {
        lock_guard<mutex> guard(g_logMutex);
        string logMessage = "Appended or inserted session with ID: " + id;
        if (!data.empty()) {
            logMessage += " and data: " + data;
        }
        g_logCount++;
        cout << logMessage << endl;
    };
    future<void> fut = async(launch::async, loggerTask);
}

// Function to split a long log message into multiple entries if necessary
void splitLogMessage(string& logMessage) {
    int maxPayloadSize = 1024; // Maximum payload size for structured logging
    int currSize = 0;
    string currEntry;
    while (currSize < logMessage.size()) {
        if (currSize + maxPayloadSize > logMessage.size()) {
            // If the current entry is too long, split it into multiple entries
            currEntry = logMessage.substr(currSize);
            logMessage = logMessage.substr(0, currSize);
            break;
        } else {
            // Add the next chunk of the message to the current entry
            currEntry += logMessage[currSize];
            currSize++;
        }
    }
    // Log the current entry and recurse if there are more chunks left
    lock_guard<mutex> guard(g_logMutex);
    cout << "Logging: " << currEntry << endl;
    if (currSize < logMessage.size()) {
        splitLogMessage(logMessage);
    }
}
```
This code defines a `Session` structure to represent the session data in the doubly linked list, and global variables for the mutex, head of the list, and logging service. The `appendOrInsertInList` function takes a string representing the ID of the session to be inserted or appended, and a string representing the session data. It first checks if the ID is already present in the list using a linear search, and inserts the new session data after it if found. If not found, it appends the session at the end of the list.

The function then asynchronously logs the operation details using the logging service by creating a `future` object for the `loggerTask`, which takes the ID and data of the session to be logged. The `splitLogMessage` function is used to split long log messages into multiple entries if necessary, to avoid exceeding the maximum payload size of 1KB for structured logging.

To ensure thread safety, the mutex `g_listMutex` is locked before any modifications are made to the list or its elements. The logging service also uses a separate mutex `g_logMutex` to avoid concurrent access to the log message and counter variables. Finally, the function uses an atomic variable `g_logCount` to track the number of log messages generated, and condition variable `g_logCondVar` to signal when new log messages are available for processing.']

