TEST(FileConfigManagerTest, Load) {
    FileConfigManager configManager("path/to/config/file");
    std::string configData = configManager.load();
    EXPECT_EQ(configData, "{\n  \"key\": \"value\"\n}");
}

TEST(FileConfigManagerTest, Update) {
    FileConfigManager configManager("path/to/config/file");
    std::string newConfigData = "{\n  \"key\": \"new_value\"\n}";
    configManager.update(newConfigData);
    std::string updatedConfigData = configManager.load();
    EXPECT_EQ(updatedConfigData, newConfigData);
}
```
### 4. Using the implementation

Once you have tested your `FileConfigManager` class, you can use it in your application to read and update configuration data from a file. Here is an example of how you can use the `FileConfigManager` class:
```c++
#include <iostream>
