double RandomEngine::generateDouble() {
    std::lock_guard<std::mutex> lock(mutex_);
    return distDouble_(engine_);
}

bool RandomEngine::generateBool() {
    std::lock_guard<std::mutex> lock(mutex_);
    return distBool_(engine_);
}

void RandomEngine::setDistribution(std::function<int()> func) {
    std::lock_guard<std::mutex> lock(mutex_);
    distInt_ = std::uniform_int_distribution<int>(func());
}
