import java.util.Base64;
import javax.ws.rs.GET;
import javax.ws.rs.POST;
import javax.ws.rs.PUT;
import javax.ws.rs.DELETE;
import javax.ws.rs.Path;
import javax.ws.rs.Produces;
import javax.ws.rs.Consumes;
import javax.ws.rs.core.Response;
import org.json.JSONObject;
import com.mysql.jdbc.Connection;
import com.rabbitmq.client.Channel;
import com.rabbitmq.client.Envelope;
import com.rabbitmq.client.MessageProperties;
import com.sun.jersey.api.client.Client;
import com.sun.jersey.api.client.WebResource;
import com.sun.jersey.api.client.config.DefaultClientConfig;
import com.sun.jersey.core.header.FormDataContentDisposition;

@Path("/resource")
public class ResourceService {
  @POST
  @Consumes("application/json")
  @Produces("application/json")
  public Response createResource(JSONObject json) {
    // Validate input data and handle errors gracefully
    if (json == null || !json.has("data")) {
      return Response.status(Response.Status.BAD_REQUEST).entity("Invalid request body").build();
    }

    // Connect to database and enqueue message for notification
    Connection dbConnection = new Connection();
    Channel rabbitChannel = new Channel();
    String queueName = "resource-notification";

    try {
      JSONObject resource = json.getJSONObject("data");
      String id = resource.getString("id");
      String name = resource.getString("name");
      int age = resource.getInt("age");

      // Insert resource into database
      dbConnection.insertResource(id, name, age);

      // Enqueue message for notification
      rabbitChannel.basicPublish("", queueName, null, id.getBytes());

      return Response.ok().entity("Resource created successfully").build();
    } catch (Exception e) {
      // Log error and return appropriate HTTP status code
      e.printStackTrace();
      return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error creating resource").build();
    } finally {
      // Close database connection and RabbitMQ channel
      dbConnection.close();
      rabbitChannel.close();
    }
  }

  @GET
  @Produces("application/json")
  public Response retrieveResource(@QueryParam("id") String id) {
    // Validate input data and handle errors gracefully
    if (id == null || id.isEmpty()) {
      return Response.status(Response.Status.BAD_REQUEST).entity("Invalid ID").build();
    }

    // Connect to database and retrieve resource
    Connection dbConnection = new Connection();
    try {
      JSONObject resource = dbConnection.retrieveResource(id);

      return Response.ok().entity(resource).build();
    } catch (Exception e) {
      // Log error and return appropriate HTTP status code
      e.printStackTrace();
      return Response.status(Response.Status.NOT_FOUND).entity("Resource not found").build();
    } finally {
      // Close database connection
      dbConnection.close();
    }
  }

  @PUT
  @Consumes("application/json")
  @Produces("application/json")
  public Response updateResource(@QueryParam("id") String id, JSONObject json) {
    // Validate input data and handle errors gracefully
    if (id == null || id.isEmpty() || json == null || !json.has("data")) {
      return Response.status(Response.Status.BAD_REQUEST).entity("Invalid request body").build();
    }

    // Connect to database and update resource
    Connection dbConnection = new Connection();
    try {
      JSONObject resource = json.getJSONObject("data");
      String name = resource.getString("name");
      int age = resource.getInt("age");

      // Update resource in database
      dbConnection.updateResource(id, name, age);

      return Response.ok().entity("Resource updated successfully").build();
    } catch (Exception e) {
      // Log error and return appropriate HTTP status code
      e.printStackTrace();
      return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error updating resource").build();
    } finally {
      // Close database connection
      dbConnection.close();
    }
  }

  @DELETE
  @Consumes("application/json")
  @Produces("application/json")
  public Response deleteResource(@QueryParam("id") String id) {
    // Validate input data and handle errors gracefully
    if (id == null || id.isEmpty()) {
      return Response.status(Response.Status.BAD_REQUEST).entity("Invalid ID").build();
    }

    // Connect to database and delete resource
    Connection dbConnection = new Connection();
    try {
      JSONObject resource = dbConnection.retrieveResource(id);

      if (resource != null) {
        // Delete resource from database
        dbConnection.deleteResource(id);

        // Notify all subscribed services via RabbitMQ message queue
        Channel rabbitChannel = new Channel();
        String queueName = "resource-notification";
        rabbitChannel.basicPublish("", queueName, null, id.getBytes());
      } else {
        return Response.status(Response.Status.NOT_FOUND).entity("Resource not found").build();
      }

      return Response.ok().entity("Resource deleted successfully").build();
    } catch (Exception e) {
      // Log error and return appropriate HTTP status code
      e.printStackTrace();
      return Response.status(Response.Status.INTERNAL_SERVER_ERROR).entity("Error deleting resource").build();
    } finally {
      // Close database connection and RabbitMQ channel
      dbConnection.close();
      rabbitChannel.close();
    }
  }

  @GET
