        _httpClient = httpClient;
    }

    public async Task<bool> UpdateElementAsync(int elementId, string content)
    {
        try
        {
            // Validate input
            if (string.IsNullOrEmpty(content))
                throw new ArgumentException("Content is required", nameof(content));

            // Check if the element exists in the octree
            if (!_octree.ContainsKey(elementId))
                return false;

            // Retrieve element from cache or API
            object cachedElement = null;
            if (_cache.TryGetValue(elementId, out cachedElement))
            {
                var currentContent = (string)cachedElement;
                if (currentContent == content)
                    return true; // No need to update
            }

            var request = new HttpRequestMessage(HttpMethod.Post, $"https://api.example.com/elements/{elementId}");
            request.Headers.Add("Accept", "application/json");
            request.Content = new StringContent(content, Encoding.UTF8, "application/json");

            var response = await _httpClient.SendAsync(request);
            if (response.StatusCode == HttpStatusCode.OK)
            {
                // Update element in octree and cache
                var updatedElement = JsonConvert.DeserializeObject<OctreeElement>(await response.Content.ReadAsStringAsync());
                _octree[elementId] = updatedElement;
                _cache[elementId] = updatedElement.Content;
                return true;
            }
            else if (response.StatusCode == HttpStatusCode.BadRequest)
            {
                throw new ArgumentException("Invalid content", nameof(content));
            }
            else
