```javascript
const fs = require('fs');
const path = require('path');

// Configurable options
const API_URL = 'https://api.example.com/validate-file';
const MAX_ATTEMPTS = 3;
const RETRY_INTERVAL = 5000; // in milliseconds
const CONCURRENCY_LIMIT = 10; // maximum number of parallel file processing operations

// File extension whitelist and blacklist for supported/unsupported files
const SUPPORTED_EXTENSIONS = ['.pdf', '.txt'];
const UNSUPPORTED_EXTENSIONS = ['.exe', '.bin'];

// Function to validate file metadata and apply transformations based on the file type and content size limits imposed by the API
async function processFile(filePath) {
  const extension = path.extname(filePath);
  if (UNSUPPORTED_EXTENSIONS.includes(extension)) {
    return; // skip unsupported files
  }

  const fileStats = await fs.stat(filePath);
  const fileSize = fileStats.size;

  try {
    const response = await fetch(`${API_URL}/validate-file?path=${encodeURIComponent(filePath)}&size=${fileSize}`);
    if (response.ok) {
      // Apply transformations based on the file type and content size limits
      // ...
    } else {
      console.error(`Failed to validate file ${filePath}:`, response.statusText);
    }
  } catch (error) {
    console.error('Error validating file:', error);
  }
}

// Function to manage concurrency and retry failed API calls
async function processFiles(files) {
  const queue = new Map(); // map of files to process
  let inProgress = 0; // number of files currently being processed
  let successes = 0; // number of successful file validations
  let failures = 0; // number of failed file validations

  for (const filePath of files) {
    queue.set(filePath, { inProgress: false });
  }

  while (queue.size > 0) {
    const filePath = Array.from(queue.keys())[0];
    const { inProgress } = queue.get(filePath);

    if (!inProgress) {
      // Start processing the next file in the queue
      queue.set(filePath, { inProgress: true });
      try {
        await processFile(filePath);
        successes++;
      } catch (error) {
        failures++;
      } finally {
        // Update the state of the file in the queue and move on to the next one
        const state = queue.get(filePath);
        state.inProgress = false;
        queue.set(filePath, state);
        inProgress--;
      }
    } else {
      // Wait for the current file to be processed before moving on to the next one
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }

  console.log(`Processed ${successes} files successfully`);
  console.log(`Failed to process ${failures} files due to API errors`);
}

// Main function to handle the file processing pipeline
async function run() {
  const dirs = ['/path/to/dir1', '/path/to/dir2']; // list of directories containing supported and unsupported files
  const files = [];

  for (const dir of dirs) {
    const dirEntries = await fs.readdir(dir, { withFileTypes: true });
    for (const entry of dirEntries) {
      if (entry.isFile()) {
        files.push(path.join(dir, entry.name));
      }
    }
  }

  // Apply concurrency limit and retry logic to file processing operations
  const results = await processFiles(files);
  console.log(`Processed ${results.length} files in total`);
}
```
In this code, we define a `processFile` function that takes a file path as an argument and validates its metadata using the external API. If the validation is successful, we apply any necessary transformations based on the file type and content size limits. If the validation fails or there's an error during processing, we log the error message.

We also define a `processFiles` function that takes a list of files as an argument and manages concurrency and retry logic for failed API calls. It creates a queue of files to be processed, updates its state when file processing starts or finishes, and relies on the `fetch` module to handle HTTP requests.

Finally, we define a `run` function that handles the file processing pipeline. It reads the directories containing supported and unsupported files, applies concurrency limit and retry logic to file processing operations, and logs the number of successfully processed files and failed file validations.

This code implements the asynchronous file processing pipeline with configurable options for tuning performance and error handling strategies. It also provides a flexible configuration mechanism for adding new file types and transformation rules while maintaining code clarity and ease of maintenance."]

