    let result;
    try {
      result = testCase.f();
    } catch (error) {
      console.log(`Failed to execute test case ${testCase.label}: ${error}`);
    }

    // Execute the teardown function if provided
    try {
      testCase.teardown ? testCase.teardown() : null;
    } catch (error) {
      console.log(`Failed to execute teardown for test case ${testCase.label}: ${error}`);
    }

