    resetBlueslip();

    // Handle errors gracefully
    if (result instanceof Error) {
      console.log(`Test case ${testCase.label} failed with error: ${result}`);
      failed++;
    } else {
      passed++;
    }
  }

  // Track test success rate
  const total = passed + failed;
  console.log(`Total tests run: ${total}, passed: ${passed}, failed: ${failed}`);
  console.log(`Average test duration: ${averageDuration(testCases)}`);

  // Optimize for performance and scalability
  function averageDuration(testCases) {
    let totalDuration = 0;
    for (let i = 0; i < testCases.length; i++) {
      const testCase = testCases[i];
      totalDuration += testCase.duration;
    }
    return totalDuration / testCases.length;
  }
}

