function renderFooterScripts() {
  const scriptList = [
    { id: 'script1', src: 'https://cdn.example.com/script1.js' },
    { id: 'script2', src: 'https://cdn.example.com/script2.js' },
    { id: 'script3', src: 'https://cdn.example.com/script3.js' }
  ];

  return new Promise((resolve, reject) => {
    let scriptTags = '';
    let failedScripts = [];
    let pendingRequests = scriptList.length;

    for (const script of scriptList) {
      fetch(script.src)
        .then(response => response.text())
        .then(scriptContent => {
          scriptTags += `<script id="${script.id}">${scriptContent}</script>`;
          pendingRequests--;
          if (pendingRequests === 0) {
            resolve(`<body>${scriptTags}</body>`);
          }
        })
        .catch(error => {
          failedScripts.push(script);
          pendingRequests--;
          if (pendingRequests === 0) {
            reject(new Error(`Failed to load scripts: ${failedScripts.map(s => s.id).join(', ')}`));
          }
        });
    }
  });
}
```
