// Define a class to represent the DOM tree traversal state
class DomState {
  private nodes: DomNode[] = [];
  private nodeIndex: number = 0;

  // Method to traverse and filter the DOM tree asynchronously
  async filterDomTree(rootNode: DomNode, filterCriteria: any) {
