<?php

namespace SecurityKit;

class TokenGenerator {
    /**
     * Generates a secure random token of varying lengths.
     *
     * @param int $length The length of the generated token (in bytes).
     * @return string The generated token.
     */
    public static function generateToken($length = 128) {
        // Use a secure random source, such as /dev/urandom or openssl_random_pseudo_bytes().
        $token = bin2hex(openssl_random_pseudo_bytes($length));

        // Hash the token to make it more difficult for attackers to predict.
        return hash('sha256', $token);
    }
}

class EmailValidator {
    /**
     * Checks if an email address is valid and exists according to RFC 5322.
     *
     * @param string $email The email address to validate.
     * @return bool True if the email address is valid, false otherwise.
     */
    public static function isValidEmail($email) {
        // Use a DNS lookup service, such as checkdnsrr(), to verify domain existence.
        return filter_var($email, FILTER_VALIDATE_EMAIL) !== false && checkdnsrr(explode('@', $email)[1]);
    }
}

class PasswordHasher {
    /**
     * Hashes a password using the Argon2 algorithm with configurable parameters.
     *
     * @param string $password The plaintext password to hash.
     * @param array $config Optional configuration options for Argon2.
     * @return string The hashed password.
     */
    public static function hashPassword($password, $config = []) {
        // Use the latest Argon2 algorithm with configurable parameters.
        return password_hash($password, PASSWORD_ARGON2I, $config);
    }
}

class AuthenticationManager {
    /**
     * Verifies a user's credentials and generates a token if valid.
     *
     * @param string $username The username to verify.
     * @param string $password The plaintext password to verify.
     * @return string|null The generated token on success, null otherwise.
     */
    public static function authenticate($username, $password) {
        // Connect to a database and retrieve the user's hashed password.
        $hashedPassword = DB::fetch(DB::SELECT, 'SELECT password FROM users WHERE username = ?', [$username]);

        // Verify the password against the stored hash.
        if (password_verify($password, $hashedPassword)) {
            // Generate a new token and store it in the database.
            $token = TokenGenerator::generateToken();
            DB::query('UPDATE users SET token = ? WHERE username = ?', [$token, $username]);

            return $token;
        }

        return null;
    }
}
