    if error.is_some() {
        return Err(error.unwrap());
    }

    // Read the private key file and certificate file.
    let private_key_file = fs::File::open(&private_key_path).map_err(|e| e.to_string())?;
    let certificate_file = fs::File::open(&certificate_path).map_err(|e| e.to_string())?;

    // Combine the private key and certificate files into a single PEM file.
    let mut pem_data = Vec::new();
    io::copy(&mut private_key_file, &mut pem_data).map_err(|e| e.to_string())?;
    pem_data.extend(io::copy(&mut certificate_file, &mut Vec::new()));

    // Verify the signatures of the PEM file.
