#include <string>
#include <thread>
#include <mutex>
#include <chrono>
#include <iostream>
#include <fstream>
#include <vector>
#include <unordered_set>

using namespace std;

class DAO {
public:
    virtual int updateUserPassword(string userId, string newPassword) = 0;
};

class UserDAO : public DAO {
private:
    mutex mtx_;
    ofstream outfile_;

public:
    UserDAO() {
        outfile_.open("user_passwords.txt", ios::app);
    }

    int updateUserPassword(string userId, string newPassword) override {
        lock_guard<mutex> lck(mtx_);
        if (newPassword.size() < 8 || !isalpha(newPassword[0]) || !isupper(newPassword[0])) {
            cerr << "Invalid password: must be at least 8 characters long, starting with a letter and containing a digit" << endl;
            return 0;
        }

        unordered_set<char> uniqueChars;
        for (const char& c : newPassword) {
            if (!isalnum(c)) {
                cerr << "Invalid password: must contain only letters and digits" << endl;
                return 0;
            }
            uniqueChars.insert(c);
        }
        if (uniqueChars.size() < newPassword.size()) {
            cerr << "Invalid password: must not contain repeated characters" << endl;
            return 0;
        }

        thread t([this, userId, newPassword] {
            this->updateUserPasswordInBackground(userId, newPassword);
        });
        t.detach();

        outfile_ << userId << " " << newPassword << endl;

        return 1;
    }

private:
    void updateUserPasswordInBackground(string userId, string newPassword) {
        // Do some background processing here...
        cout << "Processing password for user " << userId << " in the background" << endl;
        this_thread::sleep_for(chrono::seconds(1));
    }
};
