        for log in self.log_entries:
            if log.error_code in error_codes:
                filtered_logs.append(log)
        self.log_entries = filtered_logs

    def get_service_counts(self, service_ids: List[str]) -> Dict[str, int]:
        counts = {}
        for log in self.log_entries:
            if log.service_id in service_ids:
