// C++ code for the high-performance octree data structure

#include <iostream>
#include <vector>
#include <map>
#include <set>
#include <chrono>
#include <cstdlib>
#include <string>
#include <fstream>
#include <sstream>

// Define constants for octree properties
const int OCTREE_GRID_SIZE = 16; // grid size of each node in the octree
const int LEAF_NODE_CAPACITY = 8; // maximum number of points per leaf node

// Define data structures for storing spatial information
struct Point {
    float x, y, z; // coordinates of a point
};

struct Node {
    Point center; // center coordinate of the node
    int size; // size of the node (number of points it contains)
    int level; // level of the node in the octree
    bool isLeaf; // whether the node is a leaf node or not
};

// Define data structures for storing external database information
struct Database {
    std::vector<Point> points; // list of all points in the database
    std::map<int, Node> nodes; // mapping from node IDs to nodes
    std::set<int> leafNodes; // set of all leaf node IDs
};

// Define functions for managing memory and performing operations on the octree
void insertPoint(Database &db, Point p) {
    // Insert a point into the database and update the corresponding node in the octree
    int nodeID = getNodeID(p);
    db.points.push_back(p);
    Node node;
    node.center = p;
    node.size = 1;
    node.level = getLevel(nodeID);
    node.isLeaf = true;
    db.nodes[nodeID] = node;
    db.leafNodes.insert(nodeID);
}

void deletePoint(Database &db, Point p) {
    // Delete a point from the database and update the corresponding node in the octree
    int nodeID = getNodeID(p);
    auto it = db.points.begin();
    while (it != db.points.end() && *it != p) ++it;
    if (it == db.points.end()) return; // point not found
    db.points.erase(it);
    Node node = db.nodes[nodeID];
    node.size--;
    if (node.size == 0) {
        db.leafNodes.erase(nodeID);
    } else {
        db.nodes[nodeID] = node;
    }
}

void updatePoint(Database &db, Point oldP, Point newP) {
    // Update a point in the database and update the corresponding node in the octree
    int oldNodeID = getNodeID(oldP);
    int newNodeID = getNodeID(newP);
    if (oldNodeID == newNodeID) {
        db.points[getPointIndex(db, oldP)] = newP;
        Node node = db.nodes[oldNodeID];
        node.center = newP;
        db.nodes[oldNodeID] = node;
    } else {
        deletePoint(db, oldP);
        insertPoint(db, newP);
    }
}

int getLevel(int nodeID) {
    // Get the level of a node in the octree given its ID
    int level = 0;
    while (nodeID > 1) {
        nodeID /= 8;
        level++;
    }
    return level;
}

int getNodeID(Point p) {
    // Get the ID of a node in the octree given its center coordinate
    int nodeID = 0;
    for (int i = 0; i < OCTREE_GRID_SIZE; i++) {
        if (p.x > (float)(i * OCTREE_GRID_SIZE) / OCTREE_GRID_SIZE && p.x <= ((float)(i + 1) * OCTREE_GRID_SIZE) / OCTREE_GRID_SIZE) {
            nodeID += pow(2, getLevel(nodeID) - 1);
        }
    }
    for (int i = 0; i < OCTREE_GRID_SIZE; i++) {
        if (p.y > (float)(i * OCTREE_GRID_SIZE) / OCTREE_GRID_SIZE && p.y <= ((float)(i + 1) * OCTREE_GRID_SIZE) / OCTREE_GRID_SIZE) {
            nodeID += pow(2, getLevel(nodeID));
        }
    }
    for (int i = 0; i < OCTREE_GRID_SIZE; i++) {
        if (p.z > (float)(i * OCTREE_GRID_SIZE) / OCTREE_GRID_SIZE && p.z <= ((float)(i + 1) * OCTREE_GRID_SIZE) / OCTREE_GRID_SIZE) {
            nodeID += pow(2, getLevel(nodeID) + 1);
        }
    }
    return nodeID;
}

int getPointIndex(Database &db, Point p) {
    // Get the index of a point in the database given its coordinates
    int index = -1;
    for (int i = 0; i < db.points.size(); i++) {
        if (p == db.points[i]) {
            index = i;
            break;
        }
    }
    return index;
}

void readPoints(std::string filename, Database &db) {
    // Read points from a file and insert them into the database
    std::ifstream file(filename);
    std::string line;
    while (getline(file, line)) {
        std::stringstream ss(line);
        float x, y, z;
        ss >> x >> y >> z;
        Point p;
        p.x = x;
        p.y = y;
        p.z = z;
        insertPoint(db, p);
    }
}

void writePoints(std::string filename, Database &db) {
    // Write points from the database to a file
    std::ofstream file(filename);
    for (int i = 0; i < db.points.size(); i++) {
        Point p = db.points[i];
        file << p.x << " " << p.y << " " << p.z << "\n";
    }
}

void batchInsert(Database &db, std::vector<Point> points) {
    // Insert a list of points into the database
    for (int i = 0; i < points.size(); i++) {
        insertPoint(db, points[i]);
    }
}

void batchDelete(Database &db, std::vector<Point> points) {
    // Delete a list of points from the database
    for (int i = 0; i < points.size(); i++) {
        deletePoint(db, points[i]);
    }
}

void batchUpdate(Database &db, std::vector<Point> oldPoints, std::vector<Point> newPoints) {
    // Update a list of points in the database
    for (int i = 0; i < oldPoints.size(); i++) {
        updatePoint(db, oldPoints[i], newPoints[i]);
    }
}

void queryRange(Database &db, Point p1, Point p2) {
    // Query all points within a range
    int level = getLevel(getNodeID(p1));
    std::vector<Point> points;
    for (int i = 0; i < db.points.size(); i++) {
        Point p = db.points[i];
        if (p == p1 || p == p2) {
            continue;
        }
        int distX = abs(p.x - p1.x);
        int distY = abs(p.y - p1.y);
        int distZ = abs(p.z - p1.z);
        if (distX <= OCTREE_GRID_SIZE / 2 && distY <= OCTREE_GRID_SIZE / 2 && distZ <= OCTREE_GRID_SIZE / 2) {
            points.push_back(p);
        } else if (getLevel(getNodeID(p)) == level - 1) {
            if (distX <= OCTREE_GRID_SIZE / 4 && distY <= OCTREE_GRID_SIZE / 4 && distZ <= OCTREE_GRID_SIZE / 4) {
                points.push_back(p);
            } else {
                continue;
            }
        }
    }
}

void queryKNN(Database &db, Point p, int k) {
    // Query the K nearest neighbors of a point
    int level = getLevel(getNodeID(p));
    std::vector<Point> points;
    for (int i = 0; i < db.points.size(); i++) {
        Point p = db.points[i];
        if (p == p1) {
            continue;
        }
        int distX = abs(p.x - p1.x);
        int distY = abs(p.y - p1.y);
        int distZ = abs(p.z - p1.z);
        if (distX <= OCTREE_GRID_SIZE / 2 && distY <= OCTREE_GRID_SIZE / 2 && distZ <= OCTREE_GRID_SIZE / 2) {
            points.push_back(p);
        } else if (getLevel(getNodeID(p)) == level - 1) {
            if (distX <= OCTREE_GRID_SIZE / 4 && distY <= OCTREE_GRID_SIZE / 4 && distZ <= OCTREE_GRID_SIZE / 4) {
                points.push_back(p);
            } else {
                continue;
            }
        }
    }
}
