    // Parse the JSON string and extract the numeric items.
    int num_items = 0;
    Json::Value json_obj = Json::parse(json_str, NULL, false);
    if (!json_obj["items"].isArray()) {
        free(bundle);
        return NULL;
    }

    for (int i = 0; i < json_obj["items"].size(); ++i) {
        item_t *item = malloc(sizeof(item_t));
        memset(item, 0, sizeof(item_t));
        item->id = json_obj["items"][i]["id"];
        item->value = json_obj["items"][i]["value"];
        bundle->items[num_items++] = *item;
    }

    // Apply the asynchronous reduction operation on the numeric items using the `reduce` method.
    pthread_mutex_lock(&mutex);
    bundle->num_items = num_items;
    reduce(bundle->items, num_items, &bundle->total_value);
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);

    // Clean up.
    free(json_str);
    return bundle;
}

void reduce(item_t *items, int num_items, double *total_value) {
