    //Filter packets based on the specified time interval and IP address
    logDataManager.filterPackets();

    //Export processed data in CSV or JSON format
    string outputFilePath = "output.csv";
    string fileFormat = "CSV";
    logDataManager.exportData(outputFilePath, fileFormat);

    return 0;
