// File Renaming Module

import hashlib
import os
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from typing import List, Optional

class FileRenamer:
    def __init__(self, directory_path: str, max_filename_length: int = 255):
        self.directory_path = directory_path
        self.max_filename_length = max_filename_length

    def rename_files(self) -> None:
        files = os.listdir(self.directory_path)
        with ThreadPoolExecutor() as executor:
            for file in files:
                filename = Path(file).name
                if len(filename) > self.max_filename_length:
                    continue
                new_filename = f"{hashlib.sha256(filename.encode('utf-8')).hexdigest()}_{time.strftime('%Y%m%d-%H%M%S')}"
                if len(new_filename) > self.max_filename_length:
                    continue
                file_path = os.path.join(self.directory_path, filename)
                new_file_path = os.path.join(self.directory_path, new_filename)
                try:
                    os.rename(file_path, new_file_path)
                except OSError as e:
                    print(f"Error renaming file {file_path}: {e}")

// External Metadata Service

import json
import requests
from typing import Dict

class ExternalMetadataService:
    def __init__(self, url: str):
        self.url = url

    def store_metadata(self, filename: str, metadata: Dict[str, str]) -> None:
        data = json.dumps(metadata)
        headers = {"Content-Type": "application/json"}
        response = requests.post(f"{self.url}/{filename}", data=data, headers=headers)
        if not response.ok:
            print(f"Error storing metadata for {filename}: {response.status_code}")

// Logging Infrastructure

import logging
from typing import List

class FileLogger:
    def __init__(self, log_level: int = logging.INFO):
        self.log_level = log_level

    def log_files(self, files: List[str]) -> None:
        for file in files:
            logger = logging.getLogger(__name__)
            logger.log(self.log_level, f"Renamed {file}")

// Integration

from typing import Optional

class FileRenamerWithMetadataService:
    def __init__(self, directory_path: str, metadata_service_url: Optional[str] = None):
        self.directory_path = directory_path
        self.metadata_service_url = metadata_service_url

    def rename_files(self) -> None:
        files = os.listdir(self.directory_path)
        with ThreadPoolExecutor() as executor:
            for file in files:
                filename = Path(file).name
                new_filename = f"{hashlib.sha256(filename.encode('utf-8')).hexdigest()}_{time.strftime('%Y%m%d-%H%M%S')}"
                file_path = os.path.join(self.directory_path, filename)
                new_file_path = os.path.join(self.directory_path, new_filename)
                try:
                    os.rename(file_path, new_file_path)
                    metadata = {"hash": hashlib.sha256(filename.encode('utf-8')).hexdigest(), "timestamp": time.strftime("%Y%m%d-%H%M%S")}
                    if self.metadata_service_url:
                        ExternalMetadataService(self.metadata_service_url).store_metadata(new_filename, metadata)
                except OSError as e:
                    print(f"Error renaming file {file_path}: {e}")

if __name__ == "__main__":
    FileRenamerWithMetadataService(".").rename_files()
