public class CryptographicLibrary {
    private static final Map<String, String> AES_CIPHERS = new HashMap<>();
    private static final Map<String, String> CAMELLIA_CIPHERS = new HashMap<>();
    private static final Map<String, String> MD5_DIGESTS = new HashMap<>();
    private static final Map<String, String> SHA1_DIGESTS = new HashMap<>();
    private static final Map<String, String> RSA_SIGNATURES = new HashMap<>();

    static {
        AES_CIPHERS.put("AES-128", "AES/ECB/PKCS5Padding");
        AES_CIPHERS.put("AES-192", "AES/ECB/PKCS5Padding");
        AES_CIPHERS.put("AES-256", "AES/ECB/PKCS5Padding");
        CAMELLIA_CIPHERS.put("CAMELLIA-128", "Camellia/ECB/PKCS5Padding");
        CAMELLIA_CIPHERS.put("CAMELLIA-192", "Camellia/ECB/PKCS5Padding");
        CAMELLIA_CIPHERS.put("CAMELLIA-256", "Camellia/ECB/PKCS5Padding");
        MD5_DIGESTS.put("MD5", "MD5");
        SHA1_DIGESTS.put("SHA-1", "SHA-1");
        RSA_SIGNATURES.put("RSA", "RSA");
    }

    private static final String KEY_SERVICE_URL = "https://key-management-service/keys";

    public static void init() {
        RestTemplate restTemplate = new RestTemplate();
        ResponseEntity<String> response = restTemplate.getForEntity(KEY_SERVICE_URL, String.class);
        JSONObject jsonObject = new JSONObject(response.getBody());
        SecretKeySpec aesKey = new SecretKeySpec(jsonObject.getString("AES-128"), "AES");
        AES_CIPHERS.put("AES-128", new Cipher(aesKey).toString());
        SecretKeySpec camelliaKey = new SecretKeySpec(jsonObject.getString("CAMELLIA-128"), "Camellia");
        CAMELLIA_CIPHERS.put("CAMELLIA-128", new Cipher(camelliaKey).toString());
    }

    public static String encrypt(String plaintext, String algorithm) throws Exception {
        return Base64.getEncoder().encodeToString(encryptBytes(plaintext.getBytes(), algorithm));
    }

    private static byte[] encryptBytes(byte[] plaintext, String algorithm) throws Exception {
        Cipher cipher = Cipher.getInstance(AES_CIPHERS.getOrDefault(algorithm, ""));
        SecretKeySpec secretKeySpec = new SecretKeySpec(plaintext, "AES");
        cipher.init(Cipher.ENCRYPT_MODE, secretKeySpec);
        return cipher.doFinal(plaintext);
    }

    public static String decrypt(String ciphertext, String algorithm) throws Exception {
        return new String(decryptBytes(ciphertext, algorithm));
    }

    private static byte[] decryptBytes(String ciphertext, String algorithm) throws Exception {
        Cipher cipher = Cipher.getInstance(AES_CIPHERS.getOrDefault(algorithm, ""));
        SecretKeySpec secretKeySpec = new SecretKeySpec(ciphertext, "AES");
        cipher.init(Cipher.DECRYPT_MODE, secretKeySpec);
        return cipher.doFinal(ciphertext);
    }

    public static String sign(String data, String algorithm) throws Exception {
        return Base64.getEncoder().encodeToString(signBytes(data, algorithm));
    }

    private static byte[] signBytes(String data, String algorithm) throws Exception {
        Signature signature = Signature.getInstance(RSA_SIGNATURES.getOrDefault(algorithm, ""));
        PrivateKey privateKey = getPrivateKey();
        signature.initSign(privateKey);
        signature.update(data.getBytes());
        return signature.sign();
    }

    public static boolean verify(String data, String signature, String algorithm) throws Exception {
        Signature signatureObj = Signature.getInstance(RSA_SIGNATURES.getOrDefault(algorithm, ""));
        PublicKey publicKey = getPublicKey();
        signatureObj.initVerify(publicKey);
        signatureObj.update(data.getBytes());
        return signatureObj.verify(signatureBytes(signature));
    }

    private static byte[] signetureBytes(String signature) throws Exception {
        Signature signature = Signature.getInstance(RSA_SIGNATURES.getOrDefault(algorithm, ""));
        PublicKey publicKey = getPublicKey();
        signature.initVerify(publicKey);
        signature.update(data.getBytes());
        return signature.verify(signatureBytes(signature));
    }

