const char* HELP_OPT = "-h";
const int DEFAULT_COMPRESSION_LEVEL = 6;
const int DEFAULT_LOG_VERBOSITY = 2;
const std::string DEFAULT_STORAGE_PROVIDER = "local";

// Define the structure for input file data
struct InputFile {
    std::string filename;
    std::string targetDir;
};

// Define the structure for compressed archive data
struct CompressedArchive {
    std::string filename;
    std::vector<unsigned char> data;
};

// Define a function to compress a file into an archive
CompressedArchive compressFile(const InputFile& inputFile) {
    // Open the input file for reading
    std::ifstream inFile(inputFile.filename, std::ios::binary);
    if (!inFile.is_open()) {
        throw std::runtime_error("Failed to open input file");
    }

    // Create a new archive object
    CompressedArchive archive;

    // Set the compression level based on the command-line option
    int compressionLevel = DEFAULT_COMPRESSION_LEVEL;
    if (compressionLevel < 0 || compressionLevel > 9) {
        throw std::runtime_error("Invalid compression level");
    }

    // Compress the input file data into the archive object
    archive.filename = inputFile.filename + ".tar";
    try {
        archive.data = compress(inFile, compressionLevel);
    } catch (const std::runtime_error& e) {
        throw std::runtime_error("Failed to compress file: " + inputFile.filename);
    }

    // Close the input file
    inFile.close();

    return archive;
}

// Define a function to save an archive to storage
void saveArchive(const CompressedArchive& archive, const std::string& targetDir) {
    // Open the output file for writing
    std::ofstream outFile(targetDir + "/" + archive.filename, std::ios::binary);
    if (!outFile.is_open()) {
        throw std::runtime_error("Failed to open output file");
    }

    // Write the compressed data to the output file
    try {
        outFile.write(reinterpret_cast<const char*>(&archive.data[0]), archive.data.size());
    } catch (const std::runtime_error& e) {
        throw std::runtime_error("Failed to write compressed data to output file");
    }

    // Close the output file
    outFile.close();
}

// Define a function to log an error message and exit with failure code
void logErrorAndExit(const std::string& msg) {
    std::cerr << "ERROR: " << msg << std::endl;
    exit(1);
}

// Define the main function for the application
int main(int argc, char* argv[]) {
    // Initialize variables for input files and target directories
    std::vector<InputFile> inputFiles;
    std::string targetDir;

    // Parse command-line options
    if (argc == 1) {
        logErrorAndExit("Missing arguments");
    } else if (argc > 1 && argv[1] == HELP_OPT) {
        std::cout << "Usage: tar [options] <input files>" << std::endl;
        std::cout << "Options:" << std::endl;
        std::cout << "\t-c <compression level>  (default: 6)" << std::endl;
        std::cout << "\t-l <log verbosity>      (default: 2)" << std::endl;
        std::cout << "\t-s <storage provider>   (default: local)" << std::endl;
        std::cout << "\thelp                    (display this message)" << std::endl;
        return 0;
    } else {
        for (int i = 1; i < argc; ++i) {
            if (!strcmp(argv[i], COMPRESSION_LEVEL_OPT)) {
                // Set the compression level based on the command-line option
                if (++i >= argc || !isdigit(argv[i][0])) {
                    logErrorAndExit("Invalid compression level");
                } else {
                    int compressionLevel = atoi(argv[i]);
                    if (compressionLevel < 0 || compressionLevel > 9) {
                        logErrorAndExit("Invalid compression level");
                    } else {
                        // Set the compression level and move on to the next argument
                        DEFAULT_COMPRESSION_LEVEL = compressionLevel;
                        continue;
                    }
                }
            } else if (!strcmp(argv[i], LOG_VERBOSITY_OPT)) {
                // Set the log verbosity based on the command-line option
                if (++i >= argc || !isdigit(argv[i][0])) {
                    logErrorAndExit("Invalid log verbosity");
                } else {
                    int logVerbosity = atoi(argv[i]);
                    if (logVerbosity < 0 || logVerbosity > 3) {
                        logErrorAndExit("Invalid log verbosity");
                    } else {
                        // Set the log verbosity and move on to the next argument
                        DEFAULT_LOG_VERBOSITY = logVerbosity;
                        continue;
                    }
                }
            } else if (!strcmp(argv[i], STORAGE_PROVIDER_OPT)) {
                // Set the storage provider based on the command-line option
                if (++i >= argc) {
                    logErrorAndExit("Invalid storage provider");
                } else {
                    std::string storageProvider = argv[i];
                    // Validate the storage provider and set it
                    if (storageProvider == "local") {
                        DEFAULT_STORAGE_PROVIDER = storageProvider;
                    } else {
                        logErrorAndExit("Invalid storage provider");
                    }
                    continue;
                }
            } else {
                // Add the input file to the list of input files
                InputFile inputFile;
                inputFile.filename = argv[i];
                inputFiles.push_back(inputFile);
            }
        }
    }

    // Validate that at least one input file was specified
    if (inputFiles.empty()) {
        logErrorAndExit("Missing input files");
    }

    // Set the target directory to the current working directory
    targetDir = ".";

    // Process the input files in parallel using a thread pool
    std::vector<std::future<void>> futures;
    for (const auto& inputFile : inputFiles) {
        futures.push_back(std::async(std::launch::async, [inputFile, targetDir]() {
            // Create the output file name by appending ".tar" to the input file name
            std::string outputFileName = inputFile.filename + ".tar";
            // Create a tar file from the input file and write it to the target directory
            saveTarFile(inputFile.filename, outputFileName, targetDir);
        }));
    }

    // Wait for all tasks to complete before returning
    std::for_each(futures.begin(), futures.end(), [](std::future<void>& f) { f.get(); });

    return 0;
}']

