// Command Execution Utility

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <time.h>
#include <pthread.h>
#include <semaphore.h>
#include <errno.h>

// Define constants for log levels and command execution statuses
#define LOG_LEVEL_INFO 1
#define LOG_LEVEL_WARNING 2
#define LOG_LEVEL_ERROR 3
#define COMMAND_STATUS_SUCCESS 0
#define COMMAND_STATUS_FAILURE 1

// Define the structure to hold command execution metadata
typedef struct CommandMetadata {
    int pid;
    int status;
    char *command;
} CommandMetadata;

// Define the queue data structure for storing pending commands
#define QUEUE_SIZE 10000
typedef struct QueueItem {
    int key;
    CommandMetadata metadata;
} QueueItem;

// Define the command execution function
void executeCommand(char *command) {
    // Fork a new process to run the command
    pid_t pid = fork();

    if (pid == 0) {
        // Child process: Execute the command and exit
        system(command);
        _exit(COMMAND_STATUS_SUCCESS);
    } else if (pid > 0) {
        // Parent process: Wait for the command to finish and store metadata
        int status;
        wait(&status);

        CommandMetadata *metadata = malloc(sizeof(CommandMetadata));
        metadata->pid = pid;
        metadata->status = WEXITSTATUS(status);
        metadata->command = command;

        // Store the metadata in the queue
        pthread_mutex_lock(&queueMutex);
        queue[tail].key = pid;
        memcpy(&queue[tail].metadata, metadata, sizeof(CommandMetadata));
        tail = (tail + 1) % QUEUE_SIZE;
        pthread_cond_signal(&queueCondition);
        pthread_mutex_unlock(&queueMutex);

        free(metadata);
    } else {
        // Fork failed: Log the error and exit
        perror("fork");
        _exit(COMMAND_STATUS_FAILURE);
    }
}

// Define the logging function
void logCommand(char *command, int level) {
    if (level == LOG_LEVEL_INFO) {
        printf("[INFO] Command executed: %s\n", command);
    } else if (level == LOG_LEVEL_WARNING) {
        printf("[WARN] Command execution failed: %s\n", command);
    } else if (level == LOG_LEVEL_ERROR) {
        printf("[ERR ] Command execution error: %s\n", command);
    }
}

// Define the thread function for consuming commands from the queue
void *consumerThread(void *args) {
    // Loop until the end of time
    while (1) {
        // Wait for a new item in the queue
        pthread_mutex_lock(&queueMutex);
        while (head == tail) {
            pthread_cond_wait(&queueCondition, &queueMutex);
        }

        // Consume the next command in the queue
        CommandMetadata metadata = queue[head].metadata;
        head = (head + 1) % QUEUE_SIZE;
        pthread_mutex_unlock(&queueMutex);

        // Execute the command and log the results
        executeCommand(metadata.command);
        logCommand(metadata.command, metadata.status == COMMAND_STATUS_SUCCESS ? LOG_LEVEL_INFO : LOG_LEVEL_ERROR);
    }
}

// Define the thread function for consuming logs from the logging service
void *loggerThread(void *args) {
    // Loop until the end of time
    while (1) {
        // Fetch a new log message from the logging service
        LogMessage message = fetchLogMessage();

        // Print the log message to stdout
        printf("[LOG] %s\n", message.text);
    }
}

// Define the main function for launching the threads and starting the command execution loop
int main(int argc, char **argv) {
    // Initialize the queue, mutex, and condition variables
    head = 0;
    tail = 0;
    pthread_mutex_init(&queueMutex, NULL);
    pthread_cond_init(&queueCondition, NULL);

    // Launch the consumer thread to consume commands from the queue
    pthread_create(&consumerThread, NULL);

    // Launch the logger thread to consume logs from the logging service and print them to stdout
    pthread_create(&loggerThread, NULL);

    // Start the command execution loop
    while (1) {
        char *command = readline("$ ");
        executeCommand(command);
    }

    return 0;
}']

