```java
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.logging.Logger;

import com.jcraft.jsch.JSch;
import com.jcraft.jsch.JSchException;
import com.jcraft.jsch.Session;
import com.jcraft.jsch.UserInfo;

public class CommandExecutionUtility {
    private static final Logger logger = Logger.getLogger(CommandExecutionUtility.class.getName());

    private ExecutorService executor;
    private int numThreads;
    private JSch jsch;

    public CommandExecutionUtility(int numThreads) {
        this.numThreads = numThreads;
        this.executor = Executors.newFixedThreadPool(numThreads);
        this.jsch = new JSch();
    }

    public void executeCommand(String host, String command, int timeout, int logLevel) {
        Session session = null;
        try {
            UserInfo userInfo = new UserInfo() {
                @Override
                public String getPassphrase() {
                    return null;
                }

                @Override
                public String getPassword() {
                    return "password";
                }

                @Override
                public boolean promptYesNo(String message) {
                    return true;
                }

                @Override
                public void showMessage(String message) {
                    logger.log(Level.INFO, message);
                }
            };

            jsch.addIdentity("~/.ssh/id_rsa");
            session = jsch.getSession(userInfo, host, 22);
            session.setConfig("StrictHostKeyChecking", "no");
            session.connect();

            ChannelExec channel = (ChannelExec) session.openChannel("exec");
            channel.setCommand(command);
            channel.setInputStream(null);

            Future<Integer> future = executor.submit(() -> {
                try {
                    channel.connect();
                    return channel.getExitStatus();
                } catch (JSchException e) {
                    logger.log(Level.WARNING, "Failed to execute command", e);
                    return -1;
                } finally {
                    session.disconnect();
                    executor.shutdownNow();
                }
            });

            Integer exitStatus = future.get(timeout, TimeUnit.SECONDS);
            if (exitStatus != 0) {
                logger.log(Level.WARNING, "Command execution failed with exit status: " + exitStatus);
            } else {
                logger.log(Level.INFO, "Command executed successfully");
            }
        } catch (JSchException | InterruptedException | ExecutionException e) {
            logger.log(Level.SEVERE, "Failed to execute command", e);
        } finally {
            if (session != null) {
                session.disconnect();
            }
        }
    }
}
```
