// Function to parse incoming JSON strings representing access tokens into an internal structure
void parse_access_token(char* json, struct access_token* token) {
    // Check for valid JSON structure
    if (!json || !*json) {
        // Invalid JSON structure: return NULL
        printf("Invalid JSON structure\n");
        return;
    }

    // Initialize token fields to default values
    token->access_token = NULL;
    token->expires_in = -1;
    token->token_type = NULL;
    token->refresh_token = NULL;

    // Parse JSON string and populate internal structure
    json = strtok(json, "\"");
    while (json) {
        if (!strcmp(json, "access_token")) {
            token->access_token = strdup(strtok(NULL, ",\""));
        } else if (!strcmp(json, "expires_in")) {
            token->expires_in = atoi(strtok(NULL, ",\""));
        } else if (!strcmp(json, "token_type")) {
            token->token_type = strdup(strtok(NULL, "\",\""));
        } else if (!strcmp(json, "refresh_token")) {
            token->refresh_token = strdup(strtok(NULL, ",\""));
        }
        json = strtok(NULL, "\"");
    }

    // Validate mandatory fields and optional fields against strict criteria
    if (!token->access_token || !*token->access_token) {
        printf("Invalid access token\n");
        return;
    } else if (token->expires_in <= 0) {
        printf("Invalid expiry time\n");
        return;
    } else if (strcmp(token->token_type, "Bearer")) {
        printf("Invalid token type\n");
        return;
    } else if (token->refresh_token && !is_valid_base64_encoded_string(token->refresh_token)) {
        printf("Invalid refresh token\n");
        return;
    }
}

// Function to validate a base64-encoded string against strict criteria
bool is_valid_base64_encoded_string(char* str) {
    // Check for valid base64 encoding
    if (!str || !*str) {
        return false;
    }

    // Initialize variables
    int len = strlen(str);
    char* buf = malloc(len * 3 / 4 + 1);
    int i, j;

    // Decode base64-encoded string and validate length
    if (base64_decode(str, len, buf) < 0) {
        return false;
    } else if (len % 4 != 0 || len > 128) {
        return false;
    }

    // Validate characters in buffer against strict criteria
    for (i = j = 0; i < len; i++) {
        char c = buf[i];
        if (!(isalpha(c) || isdigit(c) || c == '+' || c == '-' || c == '_')) {
            break;
        }
        if (++j > 128) {
            break;
        }
    }

    // Clean up and return validation result
    free(buf);
    return i == j && i == len;
}

