```csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

namespace EncryptionDecryptionService
{
    public class InputHandlingModule
    {
        private readonly string _inputFilePath;
        private readonly object _lockObject = new object();
        private readonly int[] _validInputs = new int[0];

        public InputHandlingModule(string inputFilePath)
        {
            _inputFilePath = inputFilePath;
        }

        public async Task<int> GetLargestIntegerAsync()
        {
            var largestInteger = 0;

            using (var reader = new StreamReader(_inputFilePath))
            {
                while (!reader.EndOfStream)
                {
                    var input = await reader.ReadLineAsync().ConfigureAwait(false);

                    if (int.TryParse(input, out int parsedInput))
                    {
                        lock (_lockObject)
                        {
                            _validInputs = _validInputs.Append(parsedInput).ToArray();
                        }

                        if (parsedInput > largestInteger)
                        {
                            largestInteger = parsedInput;
                        }
                    }
                }
            }

            return largestInteger;
        }

        public async Task<int[]> GetValidInputsAsync()
        {
            lock (_lockObject)
            {
                return _validInputs.ToArray();
            }
        }
    }

    public class EncryptionDecryptionService
    {
        private readonly TripleDESCryptoServiceProvider _des;
        private readonly byte[] _key;
        private readonly byte[] _iv;

        public EncryptionDecryptionService(int seed, byte[] iv)
        {
            _des = new TripleDESCryptoServiceProvider();
            _key = GetKey(seed);
            _iv = iv;
        }

        public byte[] Encrypt(byte[] data)
        {
            using (var encryptor = _des.CreateEncryptor(_key, _iv))
            {
                return encryptor.TransformFinalBlock(data, 0, data.Length);
            }
        }

        public byte[] Decrypt(byte[] encryptedData)
        {
            using (var decryptor = _des.CreateDecryptor(_key, _iv))
            {
                return decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);
            }
        }

        private byte[] GetKey(int seed)
        {
            using (var provider = new RNGCryptoServiceProvider())
            {
                var keyBytes = new byte[8];
                provider.GetNonZeroBytes(keyBytes);
                return BitConverter.ToInt64(keyBytes, 0).ToString().PadLeft(16, '0').ToCharArray();
            }
        }
    }

    class Program
    {
        static async Task Main()
        {
            var inputHandlingModule = new InputHandlingModule("input.txt");
            var largestInteger = await inputHandlingModule.GetLargestIntegerAsync();
            var iv = Encoding.UTF8.GetBytes("ABCDEFGHIJKLMNOPQRSTUVWXYZ");
            var encryptionDecryptionService = new EncryptionDecryptionService(largestInteger, iv);

            // Get valid inputs from input handling module
            var validInputs = await inputHandlingModule.GetValidInputsAsync();

            foreach (var input in validInputs)
            {
                Console.WriteLine("Encrypting input: {0}", input);

                var encryptedData = encryptionDecryptionService.Encrypt(BitConverter.GetBytes(input));
                var decryptedData = encryptionDecryptionService.Decrypt(encryptedData);

                Console.WriteLine("Decrypted data: {0}", BitConverter.ToInt32(decryptedData, 0));
            }
