    public static class FileHelper
    {
        public static async Task<string> GetHashAsync(string filePath, HashAlgorithm algorithm)
        {
            using (var stream = File.OpenRead(filePath))
            {
                byte[] hash = await HashFileAsync(stream, algorithm);
                return BitConverter.ToString(hash).Replace("-", string.Empty);
            }
        }

        private static async Task<byte[]> HashFileAsync(Stream stream, HashAlgorithm algorithm)
        {
            byte[] buffer = new byte[8192];
            int read;
            while ((read = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
            {
                algorithm.TransformBlock(buffer, 0, read, null, 0);
            }
            algorithm.TransformFinalBlock(buffer, 0, 0);
            return algorithm.Hash;
        }
    }
