use std::env;
use std::path::PathBuf;
use std::fs::{create_dir, create_dir_all};
use std::io::ErrorKind;
use std::sync::Arc;
use std::sync::Mutex;
use std::thread;
use std::time::Duration;
use log::{info, warn};

// Define the maximum number of concurrent threads to use for directory creation
const MAX_CONCURRENCY: usize = 10;

// Define the maximum number of directories that can be created in a single batch
const BATCH_SIZE: usize = 50;

// Define the interval at which the function will log information about its progress
const LOGGING_INTERVAL: u64 = 10; // seconds

// Define the maximum number of errors that can be encountered before the function exits
const MAX_ERRORS: usize = 5;

fn main() {
    // Parse command-line arguments and validate input
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} DIRECTORY...", args[0]);
        return;
    }

    // Create a vector of directory names to be created
    let dirs: Vec<PathBuf> = args[1..].iter().map(|dir| PathBuf::from(dir)).collect();

    // Initialize the logging service and set up rate-limiting mechanisms
    let logger = Arc::new(Mutex::new(create_logger()));
    let mut error_count: usize = 0;

    // Create a vector of threads to handle directory creation in parallel
    let threads: Vec<thread::JoinHandle<()>> = dirs.chunks(BATCH_SIZE)
        .enumerate()
        .map(|(i, batch)| {
            thread::spawn(move || {
                // Create directories in batches, with rate-limiting and error handling
                for (j, dir) in batch.iter().enumerate() {
                    if error_count >= MAX_ERRORS {
                        return;
                    }

                    match create_dir(&dir) {
                        Ok(_) => info!(logger, "Created directory {}", dir.display()),
                        Err(e) => match e.kind() {
                            ErrorKind::AlreadyExists => warn!(logger, "Directory already exists: {}", dir.display()),
                            _ => {
                                error_count += 1;
                                warn!(logger, "Error creating directory {}: {}", dir.display(), e);
                            }
                        },
                    };

                    if i % LOGGING_INTERVAL == 0 {
                        info!(logger, "Processed {} directories so far...", i * BATCH_SIZE + j);
                    }
                }
            })
        })
        .collect();

    // Wait for all threads to complete and print a final summary of the results
    let mut success: usize = 0;
    let mut error: usize = 0;
    let start_time = std::time::Instant::now();
    for thread in threads {
        match thread.join() {
            Ok(_) => success += 1,
            Err(e) => {
                error_count += 1;
                warn!(logger, "Error creating directories: {}", e);
            },
        };
    }
    let end_time = std::time::Instant::now();
    info!(logger, "Processed a total of {} directories in {:.2} seconds.", success + error, end_time - start_time);
    if error > 0 {
        warn!(logger, "Encountered {} errors creating directories.", error);
    }
}

fn create_logger() -> Logger {
    // Initialize the logging service and set up rate-limiting mechanisms
    let mut logger = Logger::new();
    let log_level: usize = 3;
    logger.set_log_level(log_level);
    logger.set_rate_limit(LOGGING_INTERVAL);
    return logger;
}
