using System.Net.Http;
using Newtonsoft.Json;
using OAuth2TokenValidator.Configuration;
using OAuth2TokenValidator.Validation;

namespace OAuth2TokenValidator
{
    public class TokenValidator
    {
        private readonly HttpClient _httpClient;
        private readonly ISchemaRegistry _schemaRegistry;
        private readonly IValidationRuleRegistry _validationRuleRegistry;
        private readonly ILogger _logger;

        public TokenValidator(HttpClient httpClient, ISchemaRegistry schemaRegistry, IValidationRuleRegistry validationRuleRegistry, ILogger logger)
        {
            _httpClient = httpClient;
            _schemaRegistry = schemaRegistry;
            _validationRuleRegistry = validationRuleRegistry;
            _logger = logger;
        }

        public async Task<bool> ValidateToken(string token, string apiVersion)
        {
            var response = await _httpClient.GetAsync($"https://api.example.com/oauth2/validate?token={token}&version={apiVersion}");

            if (response.StatusCode == HttpStatusCode.OK)
            {
                try
                {
                    var jsonResponse = JsonConvert.DeserializeObject<JsonResponse>(await response.Content.ReadAsStringAsync());

                    if (jsonResponse.IsValid)
                    {
                        return true;
                    }
                    else
                    {
                        _logger.LogError($"Token validation failed: {string.Join(", ", jsonResponse.Errors)}");
                        return false;
                    }
                }
                catch (JsonException ex)
                {
                    _logger.LogError(ex, "Failed to parse JSON response.");
                    return false;
                }
            }
            else if (response.StatusCode == HttpStatusCode.NotFound)
            {
                _logger.LogWarning($"Token validation failed: API endpoint not found.");
                return false;
            }
            else
            {
                _logger.LogError($"Token validation failed with status code {(int)response.StatusCode} and reason phrase {response.ReasonPhrase}");
                return false;
            }
        }
    }

    public class JsonResponse
    {
        [JsonProperty("isValid")]
        public bool IsValid { get; set; }

        [JsonProperty("errors")]
        public List<string> Errors { get; set; }
    }
}
