import json
from datetime import datetime

class GraphDatabase:
    def __init__(self, schema):
        self.schema = schema
        self.vertices = {}
        self.edges = {}
        self.user_data = {}

    def add_vertex(self, vertex_id, properties={}):
        if vertex_id in self.vertices:
            raise ValueError("Vertex already exists")
        self.vertices[vertex_id] = properties

    def add_edge(self, edge_id, source_vertex, target_vertex, properties={}):
        if source_vertex not in self.vertices:
            raise ValueError("Source vertex does not exist")
        if target_vertex not in self.vertices:
            raise ValueError("Target vertex does not exist")
        self.edges[edge_id] = (source_vertex, target_vertex, properties)

    def get_vertex(self, vertex_id):
        return self.vertices.get(vertex_id)

    def get_neighbors(self, vertex_id):
        if vertex_id not in self.vertices:
            raise ValueError("Vertex does not exist")
        return [e[1] for e in self.edges if e[0] == vertex_id]

    def get_all_vertices(self):
        return list(self.vertices)

    def get_all_edges(self):
        return list(self.edges)
```
