// Modular C++ library for a distributed cache system

#include <iostream>
#include <vector>
#include <map>
#include <set>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <cstdlib>
#include <algorithm>
#include <iterator>

// In-memory store for speed and a disk-based persistent store for reliability
class Cache {
public:
    Cache() {}
    ~Cache() {}

    // Add key-value pair to cache
    void add(const std::string& key, const std::string& value) {
        std::lock_guard<std::mutex> lock(_mutex);
        _cache[key] = value;
    }

    // Get value from cache by key
    bool get(const std::string& key, std::string& value) {
        std::lock_guard<std::mutex> lock(_mutex);
        auto it = _cache.find(key);
        if (it == _cache.end()) {
            return false;
        }
        value = it->second;
        return true;
    }

    // Remove key-value pair from cache
    void remove(const std::string& key) {
        std::lock_guard<std::mutex> lock(_mutex);
        _cache.erase(key);
    }

private:
    std::map<std::string, std::string> _cache;
    std::mutex _mutex;
};

// Advanced caching strategies like LRU or TTL to optimize memory usage while minimizing cache pollution
class CacheStrategy {
public:
    virtual ~CacheStrategy() {}
    virtual void add(const std::string& key, const std::string& value) = 0;
    virtual bool get(const std::string& key, std::string& value) = 0;
    virtual void remove(const std::string& key) = 0;
};

// LRU caching strategy
class LRUStrategy : public CacheStrategy {
public:
    LRUStrategy() {}
    ~LRUStrategy() {}

    void add(const std::string& key, const std::string& value) override {
        std::lock_guard<std::mutex> lock(_mutex);
        _cache[key] = value;
        updateLRUList(key);
    }

    bool get(const std::string& key, std::string& value) override {
        std::lock_guard<std::mutex> lock(_mutex);
        auto it = _cache.find(key);
        if (it == _cache.end()) {
            return false;
        }
        value = it->second;
        updateLRUList(key);
        return true;
    }

    void remove(const std::string& key) override {
        std::lock_guard<std::mutex> lock(_mutex);
        _cache.erase(key);
    }

private:
    std::map<std::string, std::string> _cache;
    std::list<std::string> _lruList;
    std::mutex _mutex;

    void updateLRUList(const std::string& key) {
        auto it = _cache.find(key);
        if (it == _cache.end()) {
            return;
        }
        _lruList.remove(key);
        _lruList.push_front(key);
    }
};

// TTL caching strategy
class TTLStrategy : public CacheStrategy {
public:
    TTLStrategy() {}
    ~TTLStrategy() {}

    void add(const std::string& key, const std::string& value) override {
        std::lock_guard<std::mutex> lock(_mutex);
        _cache[key] = value;
        updateTTLList(key);
    }

    bool get(const std::string& key, std::string& value) override {
        std::lock_guard<std::mutex> lock(_mutex);
        auto it = _cache.find(key);
        if (it == _cache.end()) {
            return false;
        }
        value = it->second;
        updateTTLList(key);
        return true;
    }

    void remove(const std::string& key) override {
        std::lock_guard<std::mutex> lock(_mutex);
        _cache.erase(key);
    }

private:
    std::map<std::string, std::string> _cache;
    std::list<std::pair<std::string, std::chrono::time_point<std::chrono::steady_clock>>> _ttlList;
    std::mutex _mutex;

    void updateTTLList(const std::string& key) {
        auto it = _cache.find(key);
        if (it == _cache.end()) {
            return;
        }
        _ttlList.remove_if([&](const auto& item) { return item.first == key; });
        _ttlList.push_front(std::make_pair(key, std::chrono::steady_clock::now()));
    }
};

