// Function to add a new request to the queue
void addRequest(const RequestData& data) {
    // Lock the mutex and add the request to the vector
    std::unique_lock<std::mutex> lock(request_lock);
    requests.push_back(data);
    request_cv.notify_all();
}

// Function to process a single request
void processRequest(const RequestData& data) {
    // Initialize the API object with the configuration path and output directory
    ExternalAPI api(data.api);

    // Open the input file stream
    std::ifstream in_file(data.input_file);
    if (!in_file) {
        throw std::runtime_error("Failed to open input file");
    }

    // Create a new output file stream
    std::ofstream out_file;
    if (data.output_dir.empty()) {
        out_file.open(api.getFileName(), std::ios::out | std::ios::binary);
    } else {
        out_file.open(data.output_dir + "/" + api.getFileName(), std::ios::out | std::ios::binary);
    }

    // Parse the JSON configuration file and set the API parameters
    api.setParameters(in_file);

    // Loop over the input text and perform the desired processing steps
    while (!in_file.eof()) {
        // Read a chunk of data from the input file
        std::string chunk = readChunk(in_file);

        // Pass the chunk to the API for processing
        api.process(chunk, out_file);

        // Check if we have reached the end of the input file
        if (in_file.eof()) {
            break;
        }
    }

    // Close the output file stream
    out_file.close();
}

// Function to read a chunk of data from an input file
std::string readChunk(std::ifstream& in_file) {
    // Initialize the buffer with enough space to hold the entire file
    std::string buffer;
    buffer.resize(in_file.seekg(0, std::ios::end).tellg());
    in_file.seekg(0, std::ios::beg);
    in_file.read(&buffer[0], buffer.size());

    // Split the buffer into chunks of size CHUNK_SIZE
    const int CHUNK_SIZE = 1024; // 1KB
    std::vector<std::string> chunks;
    for (int i = 0; i < buffer.size(); i += CHUNK_SIZE) {
        chunks.push_back(buffer.substr(i, CHUNK_SIZE));
    }

    // Join the chunks with '\n' to form a single string
    std::string result;
    for (const auto& chunk : chunks) {
        result += chunk + '\n';
    }

    return result;
}

// Function to copy specified byte ranges from a list of buffered data chunks into a new buffer without modifying the original data
void copyBytes(const std::vector<std::string>& buffers, const std::vector<int>& ranges, std::string& output) {
    // Calculate the total number of bytes to be copied
    int num_bytes = 0;
    for (auto range : ranges) {
        num_bytes += range;
    }

    // Create a new buffer with enough space to hold the copied data
    output.resize(num_bytes);

    // Copy the specified byte ranges from each buffer into the output buffer
    int pos = 0;
    for (int i = 0; i < buffers.size(); ++i) {
        const auto& buffer = buffers[i];
        const auto& range = ranges[i];
        std::memcpy(&output[pos], &buffer[0], range);
        pos += range;
    }
}

