#include <iostream>
#include <vector>
#include <map>
#include <unordered_map>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <future>
#include <algorithm>

// Third-party libraries
#include "cdn_api.h"
#include "image_processor.h"

using namespace std;

struct ImageTask {
  string image_id;
  string url;
  int priority;
};

class ImagePipeline {
 private:
  // CDN API client
  CdnApi* cdn_api_;

  // Map of image IDs to task metadata
  unordered_map<string, shared_ptr<ImageTask>> tasks_;

  // Mutex for protecting concurrent access to the task map
  mutex task_mutex_;

  // Condition variable for notifying threads when a new task is added
  condition_variable task_added_cv_;

  // Thread pool for processing image tasks
  vector<shared_ptr<thread>> thread_pool_;

  // Number of active worker threads
  int num_active_workers_;

  // Map of image IDs to results
  unordered_map<string, shared_ptr<ImageResult>> results_;

  // Mutex for protecting concurrent access to the result map
  mutex result_mutex_;

  // Condition variable for notifying threads when a new result is available
  condition_variable result_available_cv_;

  // Function for processing image tasks
  void processTask(shared_ptr<ImageTask> task) {
    auto& cdn = cdn_api_->getCdn();
    ImageResult* result;

    try {
      // Download the image from the CDN
      const string& url = cdn.getImageUrl(task->image_id);

      // Process the image using the provided processor
      auto& processor = getImageProcessor();
      result = new ImageResult(processor.processImage(url));
    } catch (CdnError& e) {
      // Handle CDN errors and retry if necessary
      tryAgain:
      cerr << "CDN error: " << e.what() << endl;

      // Check for transient failures and retry if appropriate
      if (e.isTransient()) {
        this_thread::sleep_for(chrono::seconds(10));
        goto tryAgain;
      }

      // If the error is not transient, propagate it up
      throw e;
    } catch (ImageError& e) {
      // Handle image errors and retry if necessary
      tryAgain:
      cerr << "Image error: " << e.what() << endl;

      // Check for transient failures and retry if appropriate
      if (e.isTransient()) {
        this_thread::sleep_for(chrono::seconds(10));
        goto tryAgain;
      }

      // If the error is not transient, propagate it up
      throw e;
    } catch (...) {
      cerr << "Unknown error occurred" << endl;
      result = new ImageResult();
    }

    // Update the result map and notify any waiting threads
    unique_lock<mutex> lock(result_mutex_);
    results_.insert({task->image_id, shared_ptr<ImageResult>(result)});
    result_available_cv_.notify_all();
  }

  // Function for fetching image tasks from the CDN API
  void fetchTask() {
    while (true) {
      try {
        // Fetch a new task from the CDN API
        auto task = cdn_api_->getNextTask();

        // Add the task to the task map
        unique_lock<mutex> lock(task_mutex_);
        tasks_.insert({task.image_id, shared_ptr<ImageTask>(new ImageTask(task))});

        // Notify any waiting threads
        task_added_cv_.notify_all();
      } catch (CdnError& e) {
        // Handle CDN errors and retry if necessary
        tryAgain:
        cerr << "CDN error: " << e.what() << endl;

        // Check for transient failures and retry if appropriate
        if (e.isTransient()) {
          this_thread::sleep_for(chrono::seconds(10));
          goto tryAgain;
        }

        // If the error is not transient, propagate it up
        throw e;
      }
    }
  }

  // Function for processing image tasks in parallel
  void processTasks() {
    while (true) {
      try {
        unique_lock<mutex> lock(task_mutex_);

        // Wait until a new task is added to the map
        task_added_cv_.wait(lock, [this](){ return !tasks_.empty(); });

        // Sort tasks by priority and iterate through them
        vector<shared_ptr<ImageTask>> sorted_tasks = sortTasks(tasks_);
        for (auto& task : sorted_tasks) {
          // If the task is already in progress, wait until it completes
          if (results_.find(task->image_id) != results_.end()) {
            unique_lock<mutex> result_lock(result_mutex_);
            result_available_cv_.wait(result_lock, [this, task](){ return !results_.count(task->image_id); });
          }

          // Process the task in a separate thread
          thread t(processTask, task);
          t.detach();
        }
      } catch (CdnError& e) {
        // Handle CDN errors and retry if necessary
        tryAgain:
        cerr << "CDN error: " << e.what() << endl;

        // Check for transient failures and retry if appropriate
        if (e.isTransient()) {
          this_thread::sleep_for(chrono::seconds(10));
          goto tryAgain;
        }

        // If the error is not transient, propagate it up
        throw e;
      } catch (...) {
        cerr << "Unknown error occurred" << endl;
      }
    }
  }

  // Function for sorting tasks by priority
  vector<shared_ptr<ImageTask>> sortTasks(map<string, shared_ptr<ImageTask>>& tasks) {
    vector<shared_ptr<ImageTask>> sorted_tasks = vector<shared_ptr<ImageTask>>(tasks.begin(), tasks.end());

    // Sort the tasks by priority
    sort(sorted_tasks.begin(), sorted_tasks.end(), [](const shared_ptr<ImageTask>& a, const shared_ptr<ImageTask>& b) {
      return a->priority < b->priority;
    });

    return sorted_tasks;
  }

 public:
  // Constructor for the image processing pipeline
  ImagePipeline(CdnApi& cdn_api, shared_ptr<ImageProcessor> processor) {
    this->cdn_api = &cdn_api;
    this->processor = processor;

    // Start the fetch task and process tasks in parallel
    thread t1(fetchTask);
    thread t2(processTasks);
    t1.detach();
    t2.detach();
  }

  // Function for getting an image result from the pipeline
  shared_ptr<ImageResult> getResult(const string& image_id) {
    unique_lock<mutex> lock(result_mutex_);

    // Wait until the result is available or a timeout occurs
    const chrono::time_point<chrono::system_clock> start = chrono::system_clock::now();
    while (!results_.count(image_id) && (chrono::duration<double>(chrono::system_clock::now() - start).count() < 30.0)) {
      result_available_cv_.wait_for(lock, chrono::seconds(1), [this](){ return !results_.empty(); });
    }

    // Return the result if it is available, or a null pointer if a timeout occurs
    shared_ptr<ImageResult> result = results_.find(image_id) != results_.end() ? results_.at(image_id) : shared_ptr<ImageResult>();
    return result;
  }
};
```

The `ImagePipeline` class is responsible for fetching image tasks from the CDN API and processing them in parallel using a separate thread. It maintains two maps, one for storing the tasks in progress and another for storing the results once they are available. The `getResult()` function waits until a result is available or a timeout occurs before returning the result.

The `ImagePipeline` class also takes a reference to an `ImageProcessor` object as an argument in its constructor, which is used to process each image task in the pipeline. This allows for easy extension and customization of the processing behavior for different types of images.']

