// RandomEngine.h

#ifndef RANDOM_ENGINE_H
#define RANDOM_ENGINE_H

#include <random>

class RandomEngine {
public:
    virtual ~RandomEngine() = default;
    virtual int generateInt(int min, int max) = 0;
    virtual double generateDouble(double min, double max) = 0;
    virtual void setSeed(unsigned long seed) = 0;
};

#endif // RANDOM_ENGINE_H

// RandomEngine.cpp

#include "RandomEngine.h"
#include <random>

class RandomEngineImpl : public RandomEngine {
public:
    int generateInt(int min, int max) override {
        std::uniform_int_distribution<int> distribution(min, max);
        return distribution(m_engine);
    }

    double generateDouble(double min, double max) override {
        std::uniform_real_distribution<double> distribution(min, max);
        return distribution(m_engine);
    }

    void setSeed(unsigned long seed) override {
        m_engine.seed(seed);
    }

private:
    std::mt19937 m_engine;
};

// RNGService.h

#ifndef RNG_SERVICE_H
#define RNG_SERVICE_H

#include <map>
#include <mutex>
#include <string>

class RNGService {
public:
    virtual ~RNGService() = default;
    virtual int generateInt(const std::string& engineName, int min, int max) = 0;
    virtual double generateDouble(const std::string& engineName, double min, double max) = 0;
    virtual void setSeed(const std::string& engineName, unsigned long seed) = 0;
};

#endif // RNG_SERVICE_H

// RNGService.cpp

#include "RNGService.h"
#include <map>
#include <mutex>
#include <string>

class RNGServiceImpl : public RNGService {
public:
    int generateInt(const std::string& engineName, int min, int max) override {
        std::unique_lock<std::mutex> lock(m_mutex);
        auto iter = m_engines.find(engineName);
        if (iter == m_engines.end()) {
            throw std::invalid_argument("Invalid engine name");
        }
        return iter->second->generateInt(min, max);
    }

    double generateDouble(const std::string& engineName, double min, double max) override {
        std::unique_lock<std::mutex> lock(m_mutex);
        auto iter = m_engines.find(engineName);
        if (iter == m_engines.end()) {
            throw std::invalid_argument("Invalid engine name");
        }
        return iter->second->generateDouble(min, max);
    }

    void setSeed(const std::string& engineName, unsigned long seed) override {
        std::unique_lock<std::mutex> lock(m_mutex);
        auto iter = m_engines.find(engineName);
        if (iter == m_engines.end()) {
            throw std::invalid_argument("Invalid engine name");
        }
        iter->second->setSeed(seed);
    }

private:
    std::map<std::string, RandomEngine*> m_engines;
    std::mutex m_mutex;
};

// main.cpp

#include <iostream>
#include "RNGService.h"

int main() {
    RNGService service;
    service.generateInt("engine1", 0, 10);
    return 0;
}']

