Here is an example of how you could implement the modular JavaScript application using AJAX requests to dynamically retrieve and display employee details from a relational database:
```
// Define a function to fetch and display employee details
function fetchAndDisplayEmployeeDetails(supervisorId) {
  // Create a new XMLHttpRequest object
  var xhr = new XMLHttpRequest();

  // Set up the request parameters
  xhr.open("GET", "http://example.com/api/employees?supervisor_id=" + supervisorId, true);

  // Set up the response type and headers
  xhr.responseType = "json";
  xhr.setRequestHeader("Content-Type", "application/json");

  // Handle the response when it arrives
  xhr.onreadystatechange = function() {
    if (xhr.readyState === 4 && xhr.status === 200) {
      // Parse the JSON response
      var employees = JSON.parse(xhr.responseText);

      // Display the employee details in a table
      var table = document.createElement("table");
      table.classList.add("employee-details");

      // Loop through each employee and add their details to the table
      employees.forEach(function(employee) {
        var row = table.insertRow();

        // Add a cell for the employee name
        var nameCell = row.insertCell();
        nameCell.innerHTML = employee.name;

        // Add a cell for the employee email
        var emailCell = row.insertCell();
        emailCell.innerHTML = employee.email;
      });

      // Append the table to the DOM
      document.body.appendChild(table);
    } else if (xhr.readyState === 4 && xhr.status !== 200) {
      // Handle any errors that may occur during the request
      console.log("Error: " + xhr.statusText);
    }
  };

  // Send the request to retrieve the employee details
  xhr.send();
}

// Define a function to handle paginated results
function handlePagination(page) {
  var pageSize = 10; // The number of employees per page

  // Fetch the employee details for the current page
  fetchAndDisplayEmployeeDetails(page * pageSize);
}

// Define a function to handle filtering by supervisor ID
function filterBySupervisorId(supervisorId) {
  // Fetch the employee details for the specified supervisor ID
  fetchAndDisplayEmployeeDetails(supervisorId);
}
```
This code defines three functions: `fetchAndDisplayEmployeeDetails`, which retrieves and displays employee details from a relational database using AJAX requests; `handlePagination`, which handles paginated results by fetching the employee details for the current page; and `filterBySupervisorId`, which filters employee details by supervisor ID.

To use these functions, you can call `fetchAndDisplayEmployeeDetails` with no arguments to retrieve all employee details, or you can pass a supervisor ID as an argument to filter the results by supervisor. You can also use `handlePagination` to handle paginated results. For example:
```
// Retrieve all employee details
fetchAndDisplayEmployeeDetails();

// Filter the results by supervisor ID
filterBySupervisorId(123);

// Handle paginated results for page 2
handlePagination(2);
```
This code would retrieve and display all employee details, filter the results by supervisor ID 123, and handle paginated results for page 2.

