import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;

public class GraphDatabase {
    private ConcurrentMap<Node, Node> nodes;
    private Map<String, DataFeed> dataFeeds;

    public GraphDatabase() {
        this.nodes = new ConcurrentHashMap<>();
        this.dataFeeds = new HashMap<>();
    }

    public void addNode(Node node) {
        this.nodes.putIfAbsent(node, node);
    }

    public Node getNode(int id) {
        return this.nodes.get(id);
    }

    public void addDataFeed(String name, DataFeed feed) {
        this.dataFeeds.put(name, feed);
    }

    public Map<Node, Integer> getWeightedConnections() {
        // Compute the weighted connections between all nodes in the graph
        Map<Node, Integer> weightedConnections = new HashMap<>();
        for (Node node : this.nodes.keySet()) {
            Node neighbor = null;
            int weight = 0;
            while ((neighbor = feed.getNextNeighbor(node)) != null) {
                weight += feed.getWeight(node, neighbor);
            }
            weightedConnections.put(node, weight);
        }
        return weightedConnections;
    }
}
