use std::{env, path::PathBuf};

fn build_system_status(project_dir: PathBuf, resource_bundle: String) -> Result<BuildStatus> {
    // Validate project directory and resource bundle
    if !project_dir.is_dir() || !resource_bundle.ends_with(".json") {
        return Err(BuildError::InvalidInput);
    }

    // Integrate with external dependency management tools and CI/CD system to automate builds
    let mut build = Build::new(project_dir, resource_bundle)?;
    build.set_dependency_manager(DependencyManager::Cargo);
    build.set_ci_system(CISystem::GitLab);
    build.build()?;

    // Update Rust compiler if necessary
    let rustc_version = get_rustc_version();
    if rustc_version < LATEST_RUSTC_VERSION {
        update_rustc()?;
    }

    // Monitor and log system CPU and memory usage
    let mut cpu_usage: f32 = 0.0;
    let mut mem_usage: u64 = 0;
    for _ in 1..=5 {
        thread::sleep(Duration::from_secs(1));
        cpu_usage += get_cpu_usage();
        mem_usage += get_mem_usage();
    }

    // Implement custom logging hook to capture detailed metrics
    log_build_metrics(BuildMetrics {
        compilation_time: build.get_compilation_time(),
        memory_usage: mem_usage,
        cpu_load: cpu_usage / 5.0,
    });

    // Handle compilation tasks asynchronously
    let mut compile_tasks = Vec::new();
    for dep in build.get_dependencies() {
        compile_tasks.push(DependencyCompileTask::new(&dep));
    }
    let mut threads = Vec::new();
    for task in compile_tasks {
        threads.push(thread::spawn(move || {
            task.compile().unwrap();
        }));
    }
    for thread in threads {
        thread.join();
    }

    // Implement caching mechanism to store compiled dependencies and intermediate build products
    let mut cached_dependencies = HashMap::new();
    for dep in build.get_dependencies() {
        if !cached_dependencies.contains_key(&dep.name) {
            cached_dependencies.insert(dep.name, dep);
        }
    }

    // Handle compilation errors and warnings
    let mut exit_code = 0;
    for (index, warning) in build.get_warnings().iter().enumerate() {
        println!("Warning {}: {}", index + 1, warning);
        exit_code = 1;
    }
    for (index, error) in build.get_errors().iter().enumerate() {
        eprintln!("Error {}: {}", index + 1, error);
        exit_code = 2;
    }

    // Return structured BuildStatus with fields for exit code, warnings, errors, and metrics
    Ok(BuildStatus::new(exit_code, build.get_warnings(), build.get_errors(), cpu_usage, mem_usage))
}

struct BuildStatus {
    exit_code: i32,
    warnings: Vec<String>,
    errors: Vec<String>,
    compilation_time: f64,
    memory_usage: u64,
    cpu_load: f32,
}

impl BuildStatus {
    fn new(exit_code: i32, warnings: Vec<String>, errors: Vec<String>, compilation_time: f64, memory_usage: u64) -> Self {
        Self {
            exit_code,
            warnings,
            errors,
            compilation_time,
            memory_usage,
            cpu_load: 0.0,
        }
    }
}
```
