Here is a sample code for the dynamic, multi-threaded octree data structure in C++:
```c++
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <condition_variable>

// Octree node struct
struct OctreeNode {
    int level; // Level of the node (0 for root)
    float x, y, z; // Coordinates of the center of the node
    std::vector<OctreeNode*> children; // Pointers to child nodes
    void insert(float x, float y, float z); // Insert a point into the node
    void remove(float x, float y, float z); // Remove a point from the node
    void query(float x1, float y1, float z1, float x2, float y2, float z2); // Query points within a bounding box
};

// Octree struct
struct Octree {
    std::mutex mutex; // Mutex to protect the octree data structure
    std::condition_variable cv; // Condition variable for waiting for threads to finish
    int maxLevel; // Maximum level of the octree (e.g., 3 for a 3D octree)
    float minSize; // Minimum size of a node (e.g., 0.1 for a node that is 0.1 x 0.1 x 0.1 meters)
    int numNodes; // Number of nodes in the octree
    std::vector<OctreeNode*> nodes; // Pointers to the nodes in the octree
    OctreeNode* root; // Root node of the octree
    void insert(float x, float y, float z); // Insert a point into the octree
    void remove(float x, float y, float z); // Remove a point from the octree
    void query(float x1, float y1, float z1, float x2, float y2, float z2); // Query points within a bounding box
};

// Implementation of the OctreeNode struct
void OctreeNode::insert(float x, float y, float z) {
    // Check if this node is a leaf node (i.e., it has no children)
    if (level == maxLevel || numNodes < 4) {
        // Insert the point into the node and return
        points.push_back(std::make_pair(x, y, z));
        return;
    }

    // Check which child nodes are in the bounding box of the point
    int x1 = (int) std::floor((x - minSize / 2) / minSize);
    int y1 = (int) std::floor((y - minSize / 2) / minSize);
    int z1 = (int) std::floor((z - minSize / 2) / minSize);
    int x2 = (int) std::ceil((x + minSize / 2) / minSize);
    int y2 = (int) std::ceil((y + minSize / 2) / minSize);
    int z2 = (int) std::ceil((z + minSize / 2) / minSize);

    // Insert the point into the child nodes that are in the bounding box of the point
    for (int i = x1; i <= x2; ++i) {
        for (int j = y1; j <= y2; ++j) {
            for (int k = z1; k <= z2; ++k) {
                if (children[i][j][k] != nullptr) {
                    children[i][j][k]->insert(x, y, z);
                }
            }
        }
    }
}

void OctreeNode::remove(float x, float y, float z) {
    // Check if this node is a leaf node (i.e., it has no children)
    if (level == maxLevel || numNodes < 4) {
        // Remove the point from the node and return
        points.erase(std::remove(points.begin(), points.end(), std::make_pair(x, y, z)), points.end());
        return;
    }

    // Check which child nodes are in the bounding box of the point
    int x1 = (int) std::floor((x - minSize / 2) / minSize);
    int y1 = (int) std::floor((y - minSize / 2) / minSize);
    int z1 = (int) std::floor((z - minSize / 2) / minSize);
    int x2 = (int) std::ceil((x + minSize / 2) / minSize);
    int y2 = (int) std::ceil((y + minSize / 2) / minSize);
    int z2 = (int) std::ceil((z + minSize / 2) / minSize);

    // Remove the point from the child nodes that are in the bounding box of the point
    for (int i = x1; i <= x2; ++i) {
        for (int j = y1; j <= y2; ++j) {
            for (int k = z1; k <= z2; ++k) {
                if (children[i][j][k] != nullptr) {
                    children[i][j][k]->remove(x, y, z);
                }
            }
        }
    }
}

void OctreeNode::query(float x1, float y1, float z1, float x2, float y2, float z2) {
    // Check if this node is a leaf node (i.e., it has no children)
    if (level == maxLevel || numNodes < 4) {
        // Query the points in the node that are within the bounding box and return
        for (auto point : points) {
            float x = point.first;
            float y = point.second;
            float z = point.third;
            if (x >= x1 && x <= x2 && y >= y1 && y <= y2 && z >= z1 && z <= z2) {
                std::cout << "Point (" << x << ", " << y << ", " << z << ") is within the bounding box." << std::endl;
            }
        }
        return;
    }

    // Check which child nodes are in the bounding box of the query box
    int x1 = (int) std::floor((x1 - minSize / 2) / minSize);
    int y1 = (int) std::floor((y1 - minSize / 2) / minSize);
    int z1 = (int) std::floor((z1 - minSize / 2) / minSize);
    int x2 = (int) std::ceil((x2 + minSize / 2) / minSize);
    int y2 = (int) std::ceil((y2 + minSize / 2) / minSize);
    int z2 = (int) std::ceil((z2 + minSize / 2) / minSize);

    // Query the points in the child nodes that are within the bounding box of the query box
    for (int i = x1; i <= x2; ++i) {
        for (int j = y1; j <= y2; ++j) {
            for (int k = z1; k <= z2; ++k) {
                if (children[i][j][k] != nullptr) {
                    children[i][j][k]->query(x1, y1, z1, x2, y2, z2);
                }
            }
        }
    }
}

void Octree::insert(float x, float y, float z) {
    root.insert(x, y, z);
}

void Octree::remove(float x, float y, float z) {
    root.remove(x, y, z);
}

void Octree::query(float x1, float y1, float z1, float x2, float y2, float z2) {
    root.query(x1, y1, z1, x2, y2, z2);
}
```

### 4. Spatial Hashing

Spatial hashing is a technique used to improve the performance of collision detection in games and simulations by dividing the game world into large cells and only checking for collisions within those cells that are likely to intersect with an object. This can significantly reduce the number of collisions that need to be checked, making the simulation faster and more efficient.

The basic idea behind spatial hashing is to divide the game world into a grid of cells, where each cell represents a small region of space. When an object is inserted into the hash table, its position is used to determine which cell it belongs to. The collision detection algorithm then only needs to check for collisions within that cell and any neighboring cells that are likely to intersect with the object.

Here's an example of how this might work in a 2D game:
```
// Create a grid of cells
grid = new Cell[10][10];

// Insert an object into the hash table
hash_table.insert(object, x, y);

// Check for collisions with other objects in the same cell and neighboring cells
for (int i = -1; i <= 1; i++) {
    for (int j = -1; j <= 1; j++) {
        Cell cell = hash_table.getCell(x + i, y + j);
        if (cell != null) {
            List<Object> objects = cell.getObjects();
            for (Object other : objects) {
                if (other == object || other.intersects(object)) {
                    collision = true;
                    break;
                }
            }
        }
    }
}
```
This is just a basic example of how spatial hashing can be used, and the specific implementation will depend on the game or simulation being developed. The key idea is to divide the game world into a grid of cells, and only check for collisions within those cells that are likely to intersect with an object.']

