#include "NetworkResourceManager.h"
#include <chrono>
#include <future>
#include <thread>
#include <iostream>
#include <sstream>

NetworkResourceManager::NetworkResourceManager() {
    stopped_ = false;
}

NetworkResourceManager::~NetworkResourceManager() {
    stop();
}

void NetworkResourceManager::addResource(const std::string& name, const std::shared_ptr<NetworkResource>& resource) {
    mutex_.lock();
    resources_.emplace(name, resource);
    mutex_.unlock();
}

std::shared_ptr<NetworkResource> NetworkResourceManager::getResource(const std::string& name) {
    mutex_.lock();
    auto it = resources_.find(name);
    if (it != resources_.end()) {
        return it->second;
    } else {
        return nullptr;
    }
    mutex_.unlock();
}

void NetworkResourceManager::removeResource(const std::string& name) {
    mutex_.lock();
    auto it = resources_.find(name);
    if (it != resources_.end()) {
        resources_.erase(it);
    }
    mutex_.unlock();
}

bool NetworkResourceManager::isStopped() const {
    return stopped_;
}

void NetworkResourceManager::start() {
    workers_ = std::vector<std::thread>(resourceMonitorThreads_);
    for (int i = 0; i < resourceMonitorThreads_; ++i) {
        workers_[i] = std::thread(&NetworkResourceManager::monitorResources, this);
    }
}

void NetworkResourceManager::stop() {
    if (!stopped_) {
        stopped_ = true;
        for (int i = 0; i < resourceMonitorThreads_; ++i) {
            workers_[i].join();
        }
    }
}

void NetworkResourceManager::monitorResources() {
    while (!isStopped()) {
        std::vector<std::future<bool>> futures;
        for (auto& resource : resources_) {
            futures.emplace_back(resource->monitor());
        }
        for (auto& future : futures) {
            bool success = future.get();
            if (!success) {
                // Handle resource breach and trigger alerts
            }
        }
    }
}
