    worker_ = std::thread(&NetworkResource::monitor, this);
}

void NetworkResource::stop() {
    if (!stopped_) {
        stopped_ = true;
        worker_.join();
    }
}

bool NetworkResource::isStopped() const {
    return stopped_;
}

void NetworkResource::monitor() {
    while (!isStopped()) {
        // Monitor resource usage and handle breaches as needed
        std::this_thread::sleep_for(std::chrono::seconds(10));
    }
