#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/aes.h>
#include <openssl/camellia.h>
#include <openssl/md5.h>
#include <openssl/sha.h>
#include <openssl/rsa.h>
#include <openssl/pem.h>
#include <openssl/err.h>

// Constants for different encryption algorithms and key sizes
#define AES_KEY_SIZE 128
#define CAMELLIA_KEY_SIZE 256
#define MD5_HASH_SIZE 16
#define SHA_HASH_SIZE 20
#define RSA_KEY_SIZE 2048

// Struct to store key information for each algorithm
typedef struct {
    int type; // Type of encryption (AES, Camellia, MD5, SHA, RSA)
    char *key; // Encryption key
} KeyInfo;

// Global variables for the service
KeyInfo *keys = NULL;
int num_keys = 0;

// Function to initialize OpenSSL libraries and load keys from a file
void initOpenSSL() {
    // Initialize AES, Camellia, MD5, SHA, and RSA encryption libraries
    AES_set_encrypt_key(NULL);
    CAMELLIA_set_encrypt_key(NULL);
    MD5_Init(NULL);
    SHA1_Init(NULL);
    RSA_new();

    // Load keys from a file
    FILE *file = fopen("keys.txt", "r");
    if (file != NULL) {
        char line[256];
        while (fgets(line, sizeof(line), file)) {
            int type;
            char key[256];
            sscanf(line, "%d %s", &type, key);
            addKey(type, key);
        }
    }
}

// Function to finalize OpenSSL libraries and free memory
void finOpenSSL() {
    // Finalize AES, Camellia, MD5, SHA, and RSA encryption libraries
    AES_set_decrypt_key(NULL);
    CAMELLIA_set_decrypt_key(NULL);
    MD5_Final(NULL);
    SHA1_Final(NULL);
    RSA_free();
}

// Function to add a key to the list of keys
void addKey(int type, char *key) {
    // Allocate memory for the new key
    KeyInfo *new_key = (KeyInfo *)malloc(sizeof(KeyInfo));
    new_key->type = type;
    new_key->key = strdup(key);

    // Add the new key to the list of keys
    keys = (KeyInfo *)realloc(keys, (num_keys + 1) * sizeof(KeyInfo));
    keys[num_keys] = new_key;
    num_keys++;
}

// Function to encrypt a message using AES, Camellia, MD5, SHA, or RSA
void encrypt(char *plaintext, char **ciphertext) {
    // Find the key for the appropriate encryption algorithm
    int i;
    for (i = 0; i < num_keys; i++) {
        if (keys[i].type == AES || keys[i].type == CAMELLIA) {
            break;
        }
    }
    KeyInfo *key = &keys[i];

    // Encrypt the message using the appropriate algorithm
    int size = strlen(plaintext);
    char *buffer = (char *)malloc(size);
    if (key->type == AES) {
        AES_encrypt(plaintext, buffer, key->key);
    } else if (key->type == CAMELLIA) {
        Camellia_encrypt(plaintext, buffer, key->key);
    } else if (key->type == MD5) {
        MD5_Update((unsigned char *)buffer, plaintext, size);
        MD5_Final((unsigned char *)buffer, NULL);
    } else if (key->type == SHA) {
        SHA1_Update((unsigned char *)buffer, plaintext, size);
        SHA1_Final((unsigned char *)buffer, NULL);
    } else if (key->type == RSA) {
        // Use the public key to encrypt the message
        RSA_public_encrypt(size, (unsigned char *)plaintext, (unsigned char *)buffer, key->key);
    }
    *ciphertext = buffer;
}

// Function to decrypt a message using AES, Camellia, MD5, SHA, or RSA
void decrypt(char *ciphertext, char **plaintext) {
    // Find the key for the appropriate encryption algorithm
    int i;
    for (i = 0; i < num_keys; i++) {
        if (keys[i].type == AES || keys[i].type == CAMELLIA) {
            break;
        }
    }
    KeyInfo *key = &keys[i];

    // Decrypt the message using the appropriate algorithm
    int size = strlen(ciphertext);
    char *buffer = (char *)malloc(size);
    if (key->type == AES) {
        AES_decrypt(ciphertext, buffer, key->key);
    } else if (key->type == CAMELLIA) {
        Camellia_decrypt(ciphertext, buffer, key->key);
    } else if (key->type == MD5) {
        // Use the private key to decrypt the message
        RSA_private_decrypt(size, (unsigned char *)ciphertext, (unsigned char *)buffer, key->key);
    } else if (key->type == SHA) {
        // Use the public key to encrypt the message
        SHA1_Update((unsigned char *)buffer, ciphertext, size);
        SHA1_Final((unsigned char *)buffer, NULL);
    }
    *plaintext = buffer;
}

// Function to handle errors and log them appropriately
void error(char *message) {
    // Log the error message
    FILE *file = fopen("error.log", "a");
    if (file != NULL) {
        fprintf(file, "%s\n", message);
    }
}

// Main function for the service
int main(int argc, char **argv) {
    // Initialize OpenSSL libraries and load keys from a file
    fini();

    // Encrypt or decrypt the message based on the command-line arguments
    if (strcmp(argv[1], "encrypt") == 0) {
        char *plaintext = argv[2];
        char *ciphertext;
        encrypt(plaintext, &ciphertext);
        printf("%s\n", ciphertext);
    } else if (strcmp(argv[1], "decrypt") == 0) {
        char *ciphertext = argv[2];
        char *plaintext;
        decrypt(ciphertext, &plaintext);
        printf("%s\n", plaintext);
    } else {
        error("Invalid command-line argument");
    }

    // Clean up and exit the program
    fini();
    return 0;
}
