    PreparedStatement *stmt = prepareStatement(db, "INSERT INTO encryption_metadata (salt, iv, key) VALUES(?, ?, ?)");
    if (stmt == NULL) {
        printf("Error preparing statement\n");
        exit(1);
    }

    // Bind the parameters for the prepared statement and execute it
    bindParameter(stmt, 0, salt, 32);
    bindParameter(stmt, 1, iv, 32);
    bindParameter(stmt, 2, key, 32);
    executeStatement(stmt);
}

// Function to retrieve encryption metadata from a relational database
void retrieveEncryptionMetadata(uint8_t salt[], uint8_t iv[], uint8_t key[]) {
    // Initialize the connection to the relational database using appropriate API calls
    DBConnection *db = openDatabase();
