def generate_random_salt(length):
    return os.urandom(length)

def derive_encryption_key(password, salt, rounds=100000):
    kdf = PBKDF2(
        hashes=['sha384'],
        length=32,
        salt=salt,
        iterations=rounds,
        backend=default_backend()
    )
    return kdf.derive(password)

def encrypt(plaintext, key):
    cipher = Cipher(algorithms.AES(key), modes.GCM(aad_bytes=None), backend=default_backend())
    encryptor = cipher.encryptor()
    ciphertext = encryptor.update(plaintext.encode('utf-8')) + encryptor.finalize()
    return base64.b64encode(ciphertext)

def decrypt(ciphertext, key):
    cipher = Cipher(algorithms.AES(key), modes.GCM(aad_bytes=None), backend=default_backend())
    decryptor = cipher.decryptor()
    plaintext = decryptor.update(base64.b64decode(ciphertext)) + decryptor.finalize()
    return plaintext.decode('utf-8')

def main():
    password = input("Enter the password: ")
    salt = generate_random_salt(16)
    key = derive_encryption_key(password, salt)
    ciphertext = encrypt("Hello, World!", key)
    plaintext = decrypt(ciphertext, key)
    print("Plaintext: {}".format(plaintext))

if __name__ == "__main__":
    main()
