Here is an example of a distributed C++/C# hybrid library that efficiently manages a dynamic collection of `TX_POWER_REPORT` structures:
```c++
// Define the structure for the TX power report
struct TX_POWER_REPORT {
    uint64_t rnti;
    double timestamp;
    double power_level;
};

// Define a class to manage the collection of reports
class PowerReportManager {
public:
    // Add a new report to the collection
    void addReport(const TX_POWER_REPORT& report) {
        std::unique_lock<std::mutex> lock(_mutex);
        _reports.push_back(report);
    }

    // Remove all reports for a given RNTI
    void removeReports(uint64_t rnti) {
        std::unique_lock<std::mutex> lock(_mutex);
        auto it = std::remove_if(_reports.begin(), _reports.end(), [rnti](const TX_POWER_REPORT& report) {
            return report.rnti == rnti;
        });
        _reports.erase(it, _reports.end());
    }

    // Get all reports for a given RNTI
    std::vector<TX_POWER_REPORT> getReports(uint64_t rnti) {
        std::unique_lock<std::mutex> lock(_mutex);
        auto it = std::find_if(_reports.begin(), _reports.end(), [rnti](const TX_POWER_REPORT& report) {
            return report.rnti == rnti;
        });
        if (it != _reports.end()) {
            std::vector<TX_POWER_REPORT> reports;
            reports.push_back(*it);
            return reports;
        }
        return {};
    }

private:
    // Mutex to protect the collection of reports
    std::mutex _mutex;

    // Collection of reports
    std::vector<TX_POWER_REPORT> _reports;
};
