    }

    // Enumerate all files in input directory and compress them using specified compression level
    vector<FileMetadata> metadataList;
    while (infile.good()) {
        FileMetadata metadata;
        string filename;
        infile >> filename;
        metadata.filename = filename;
        struct stat fileStat;
        int status = fstat(fileno(infile), &fileStat);
        if (status != 0) {
