        }
        metadata.timestamp = fileStat.st_mtime;
        metadata.filesize = fileStat.st_size;
        metadataList.push_back(metadata);
    }

    for (FileMetadata metadata : metadataList) {
        string inputFilename = inputDirname + "/" + metadata.filename;
        ifstream infile(inputFilename.c_str());
        if (!infile.is_open()) {
            throw runtime_error("Error opening file for compression: " + inputFilename);
        }
        string outputFilename = outputDirname + "/" + metadata.filename;
        ofstream outfile(outputFilename.c_str());
        if (!outfile.is_open()) {
            throw runtime_error("Error opening file for compression: " + outputFilename);
        }
        compressFile(infile, outfile, compressionLevel);
    }
