```java
public class CommandExecutionUtility {
  private static final int MAX_THREADS = 50;
  private static final int MIN_THREADS = 10;

  private ExecutorService threadPool;
  private List<String> commandQueue;
  private Map<String, String> dependencyCache;

  public CommandExecutionUtility() {
    this.threadPool = new ThreadPoolExecutor(MIN_THREADS, MAX_THREADS, 0L, TimeUnit.MILLISECONDS, new LinkedBlockingDeque<>());
    this.commandQueue = new ArrayList<>();
    this.dependencyCache = new HashMap<>();
  }

  public void executeCommand(String command) {
    this.threadPool.execute(() -> {
      try {
        // Execute the command locally
        Process process = Runtime.getRuntime().exec(command);
        int exitCode = process.waitFor();

        if (exitCode != 0) {
          throw new Exception("Command failed with exit code: " + exitCode);
        }
      } catch (Exception e) {
        // Handle exception
      } finally {
        this.threadPool.execute(() -> {
          try {
            // Execute the command remotely using SSH
            Process process = Runtime.getRuntime().exec("ssh user@remote-host " + command);
            int exitCode = process.waitFor();

            if (exitCode != 0) {
              throw new Exception("Command failed with exit code: " + exitCode);
            }
