// C# Service

using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.IO;
using System.Linq;
using System.Net.Http;
using System.Security.Claims;
using System.Text;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Newtonsoft.Json;
using Serilog;

namespace BinaryDataService
{
    [ApiController]
    [Authorize(AuthenticationSchemes = "Bearer")]
    [Route("[controller]")]
    public class DataProcessingController : ControllerBase
    {
        private readonly ILogger _logger;
        private readonly string _connectionString;
        private readonly int _batchSize;
        private readonly List<int> _retryCounts = new List<int>();

        public DataProcessingController(ILogger logger, IConfiguration config)
        {
            _logger = logger.ForContext<DataProcessingController>();
            _connectionString = config["ConnectionString"];
            _batchSize = int.Parse(config["BatchSize"]);
        }

        [HttpPost("[action]")]
        public async Task ProcessDataAsync([FromBody] List<BinaryData> data)
        {
            if (!IsTokenValid())
            {
                return;
            }

            try
            {
                using (var connection = new SqlConnection(_connectionString))
                {
                    await connection.OpenAsync();
                    var command = connection.CreateCommand();

                    var transactions = data.Batch(_batchSize);
                    foreach (var transaction in transactions)
                    {
                        command.Parameters.Clear();
                        command.CommandText = "INSERT INTO [dbo].[BinaryData] (Data) VALUES (@data)";
                        command.Parameters.Add(new SqlParameter("@data", SqlDbType.VarBinary, -1) { Value = transaction });
                        await command.ExecuteNonQueryAsync();
                    }
                }
            }
            catch (Exception ex)
            {
                _logger.Error(ex, "Error processing data");
            }
        }

        [HttpGet("[action]")]
        public async Task<IEnumerable<BinaryData>> GetDataAsync([FromQuery] string id = null)
        {
            if (!IsTokenValid())
            {
                return Enumerable.Empty<BinaryData>();
            }

            using (var connection = new SqlConnection(_connectionString))
            {
                await connection.OpenAsync();
                var command = connection.CreateCommand();

                if (id != null)
                {
                    command.CommandText = $"SELECT * FROM [dbo].[BinaryData] WHERE Id = @id";
                    command.Parameters.Add(new SqlParameter("@id", id));
                    return await ReadAsync<BinaryData>(command);
                }
                else
                {
                    command.CommandText = "SELECT * FROM [dbo].[BinaryData]";
                    return await ReadAsync<List<BinaryData>>(command);
                }
            }
        }

        private async Task<IEnumerable<T>> ReadAsync<T>(SqlCommand command)
        {
            var reader = await command.ExecuteReaderAsync();
            var results = new List<T>();
            while (await reader.ReadAsync())
            {
                results.Add(reader.GetFieldValue<T>(0));
            }

            return results;
        }

        private bool IsTokenValid()
        {
            if (!User.Identity.IsAuthenticated)
            {
                _logger.Warning("Unauthenticated request");
                return false;
            }

            var accessToken = User.Claims.FirstOrDefault(c => c.Type == "access_token");
            if (accessToken == null)
            {
                _logger.Warning("Missing access token claim");
                return false;
            }

            if (!int.TryParse(User.Claims.FirstOrDefault(c => c.Type == "expires_in")?.Value, out var expiresIn))
            {
                _logger.Warning("Missing or invalid expires_in claim");
                return false;
            }

            if (accessToken.Value.Length < 10)
            {
                _logger.Warning("Access token is too short");
                return false;
            }

            var tokenType = User.Claims.FirstOrDefault(c => c.Type == "token_type")?.Value;
            if (tokenType != "Bearer")
            {
                _logger.Warning("Invalid token type");
                return false;
            }

            var tokenExpiry = DateTimeOffset.Now + TimeSpan.FromSeconds(expiresIn);
            if (DateTimeOffset.Now > tokenExpiry)
            {
                _logger.Warning("Token has expired");
                return false;
            }

            return true;
        }
    }
}

// BinaryData class

using System;
using System.IO;

namespace BinaryDataService
{
    public class BinaryData : IEquatable<BinaryData>
    {
        public string Id { get; set; }
        public byte[] Data { get; set; }

        public override bool Equals(object obj)
        {
            return base.Equals(obj as BinaryData);
        }

        public bool Equals(BinaryData other)
        {
            if (other == null)
                return false;

            return Id == other.Id && Data.SequenceEqual(other.Data);
        }

        public override int GetHashCode()
        {
            unchecked
            {
                var hash = 17;
                hash = hash * 23 + (Id?.GetHashCode() ?? 0);
                foreach (var b in Data)
                    hash = hash * 23 + b.GetHashCode();
                return hash;
            }
        }
    }
}']

