package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"

	"github.com/pkg/errors"
)

// CommandLineArguments represents the command-line arguments passed to the utility
type CommandLineArguments struct {
	Directories []string `json:"directories"`
}

// JSONProcessingComponent is a component for parsing and creating JSON objects
type JSONProcessingComponent struct {
	Factories map[string]FactoryFunc
	Mu       sync.RWMutex
}

// FactoryFunc represents a factory function for creating instances of subclasses
type FactoryFunc func() interface{}

// NewJSONProcessingComponent creates a new instance of the JSONProcessingComponent
func NewJSONProcessingComponent() *JSONProcessingComponent {
	return &JSONProcessingComponent{
		Factories: make(map[string]FactoryFunc),
	}
}

// AddFactory adds a factory function to the registry
func (jpc *JSONProcessingComponent) AddFactory(id string, ff FactoryFunc) error {
	if _, ok := jpc.Factories[id]; ok {
		return fmt.Errorf("factory with id %s already exists", id)
	}

	jpc.Mu.Lock()
	defer jpc.Mu.Unlock()

	jpc.Factories[id] = ff

	return nil
}

// CreateInstance creates an instance of a subclass using the appropriate factory function
func (jpc *JSONProcessingComponent) CreateInstance(id string) (interface{}, error) {
	jpc.Mu.RLock()
	defer jpc.Mu.RUnlock()

	if ff, ok := jpc.Factories[id]; ok {
		return ff(), nil
	}

	return nil, fmt.Errorf("factory with id %s does not exist", id)
}

// ErrorHandler represents a function for handling errors
type ErrorHandler func(error) error

// HandleError handles an error by logging it and returning the original error
func (eh ErrorHandler) HandleError(err error) error {
	log.Println("Error occurred:", err)
	return err
}

// CreateDirectories creates directories in a multi-threaded environment, ensuring thread-safe operations and efficient resource management
func CreateDirectories(directories []string, timeout time.Duration, logger Logger, handler ErrorHandler) {
	if len(directories) == 0 {
		logger.Info("No directories to create")
		return
	}

	var wg sync.WaitGroup
	wg.Add(len(directories))

	for _, directory := range directories {
		go func(directory string) {
			defer wg.Done()

			if err := createDirectory(directory, timeout, logger, handler); err != nil {
				handler.HandleError(err)
			}
		}(directory)
	}

	wg.Wait()
}

// Logger represents a function for logging messages
type Logger interface {
	Info(string, ...interface{})
}

// LogFunc is a basic implementation of the Logger interface
func LogFunc(format string, v ...interface{}) {
	log.Printf(format, v...)
}

// createDirectory creates a directory with the specified name, retrying on errors
func createDirectory(name string, timeout time.Duration, logger Logger, handler ErrorHandler) error {
	logger.Info("Creating directory: %s", name)

	start := time.Now()

	for {
		if err := os.MkdirAll(name, 0755); err == nil {
			return nil
		} else if !strings.Contains(err.Error(), "no such file or directory") && !os.IsNotExist(err) {
			logger.Info("Encountered error creating directory %s: %v", name, err)
			return handler.HandleError(errors.Wrapf(err, "error creating directory %s", name))
		}

		if time.Since(start) >= timeout {
			logger.Info("Timed out creating directory %s", name)
			return handler.HandleError(fmt.Errorf("timed out creating directory %s", name))
		}

		time.Sleep(10 * time.Millisecond)
	}
}

func main() {
	flag.Parse()

	args := flag.Args()
	if len(args) == 0 {
		fmt.Println("No directories specified")
		return
	}

	// Set up the JSON processing component
	jpc := NewJSONProcessingComponent()
	jsonFactories, err := jsonFactories()
	if err != nil {
		log.Fatal(err)
	}

	for _, ff := range jsonFactories {
		if err := jpc.AddFactory("json", ff); err != nil {
			log.Fatal(err)
		}
	}

	// Set up the logger and error handler
	logger := LogFunc
	handler := ErrorHandler(func(err error) error {
		return err
	})

	// Create directories in a multi-threaded environment, ensuring thread-safe operations and efficient resource management
	CreateDirectories(args, 1*time.Minute, logger, handler)
}

func jsonFactories() ([]FactoryFunc, error) {
	ffs := []FactoryFunc{
		func() interface{} {
			return &CommandLineArguments{}
		},
	}

	return ffs, nil
}']

