  if (!(ctx = EVP_CIPHER_CTX_new())) {
    fprintf(stderr, "Failed to create encryption context\n");
    return;
  }

  // Set the encryption algorithm and mode
  if (1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
    fprintf(stderr, "Failed to initialize encryption\n");
    return;
  }

  // Process the plaintext in chunks
  while (plaintext_size > 0) {
    len = EVP_EncryptUpdate(ctx, ciphertext, &outlen, plaintext, plaintext_size);
    if (len < 0) {
      fprintf(stderr, "Failed to encrypt data\n");
      return;
    }
    plaintext += len;
    plaintext_size -= len;
  }

  // Finalize the encryption
  len = EVP_EncryptFinal_ex(ctx, ciphertext + outlen, &outlen);
  if (len < 0) {
    fprintf(stderr, "Failed to finalize encryption\n");
    return;
