    ciphertext += len;
    ciphertext_size -= len;
  }

  // Finalize the decryption
  len = EVP_DecryptFinal_ex(ctx, plaintext + outlen, &outlen);
  if (len < 0) {
    fprintf(stderr, "Failed to finalize decryption\n");
    return;
  }
  outlen += len;

