#include <boost/asio.hpp>
#include <boost/thread.hpp>
#include <iostream>
#include <string>
#include <vector>

using boost::asio::ip::tcp;
using boost::system::error_code;

class CustomSandeshClient {
 public:
  CustomSandeshClient(const std::string& host, const std::string& port)
      : io_service(),
        resolver(io_service),
        socket(io_service),
        remote_endpoint(tcp::endpoint(boost::asio::ip::address::from_string(host),
                                      boost::lexical_cast<std::uint16_t>(port))),
        in_buffer(),
        out_buffer() {}

  void connect() {
    socket.async_connect(remote_endpoint, [this](error_code ec) {
      if (ec) {
        std::cout << "Error connecting to remote monitoring service: " << ec.message() << std::endl;
        return;
      }

      std::cout << "Connected to remote monitoring service" << std::endl;
    });
  }

  void disconnect() {
    socket.close();
  }

  void sendGetRequest(const std::string& path, const std::vector<std::string>& query_params) {
    out_buffer = "GET " + path + "?" + boost::algorithm::join(query_params, "&") + "\r\n";
    socket.async_send(boost::asio::buffer(out_buffer), [this](error_code ec, std::size_t bytes) {
      if (ec) {
        std::cout << "Error sending GET request to remote monitoring service: " << ec.message() << std::endl;
        return;
      }

      in_buffer += boost::asio::buffer(out_buffer);
    });
  }

 private:
  boost::asio::io_service io_service;
  tcp::resolver resolver;
  tcp::socket socket;
  tcp::endpoint remote_endpoint;
  std::string in_buffer, out_buffer;
};
```
