Here is an example implementation of a resilient, modular, and extensible encryption and decryption service in C#, leveraging AES-256-CBC encryption with PBKDF2 key derivation, SHA-256 for key hashing, and Key Management Service (KMS) for secure key storage and retrieval:
```csharp
using System;
using System.Security.Cryptography;
using System.IO;
using System.Text;

// Define a class to handle encryption and decryption using AES-256-CBC with PBKDF2 key derivation
public class EncryptionService
{
    // Define the size of the initialization vector (IV) in bytes
    private const int IV_SIZE = 16;

    // Define the size of the salt for PBKDF2 in bytes
    private const int SALT_SIZE = 32;

    // Define the number of iterations for PBKDF2 key derivation
    private const int ITERATIONS = 10000;

    // Define a static class variable to store the KMS client instance
    private static KmsClient kmsClient;

    // Define a method to initialize the KMS client
    public static void InitializeKmsClient(string region)
    {
        if (kmsClient == null)
        {
            kmsClient = new KmsClient(region);
        }
    }

    // Define a method to get the key from the KMS
    private static async Task<byte[]> GetKeyAsync(string keyId)
    {
        return await kmsClient.GetKeyAsync(keyId).ConfigureAwait(false);
    }

    // Define a method to compute the MD5 hash of a string using a standard library cryptographic hash function
    private static byte[] ComputeMd5Hash(string input)
    {
        using (MD5 md5 = MD5.Create())
        {
            return md5.ComputeHash(Encoding.UTF8.GetBytes(input));
        }
    }

    // Define a method to generate a random initialization vector (IV)
    private static byte[] GenerateIv()
    {
        using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
        {
            byte[] iv = new byte[IV_SIZE];
            rng.GetBytes(iv);
            return iv;
        }
    }

    // Define a method to generate a random salt for PBKDF2 key derivation
    private static byte[] GenerateSalt()
    {
        using (RNGCryptoServiceProvider rng = new RNGCryptoServiceProvider())
        {
            byte[] salt = new byte[SALT_SIZE];
            rng.GetBytes(salt);
            return salt;
        }
    }

    // Define a method to derive the encryption key using PBKDF2 and AES-256-CBC
    private static async Task<byte[]> DeriveKeyAsync(string password, byte[] iv)
    {
        var pbkdf2 = new PBKDF2();
        var aes = new AesCryptoServiceProvider();

        // Set the key size to 256 bits
        aes.KeySize = 256;

        // Set the block size to 128 bits
        aes.BlockSize = 128;

        // Create an initialization vector (IV) for AES-256-CBC
        byte[] ivBytes = GenerateIv();

        // Create a salt for PBKDF2 key derivation
        byte[] salt = GenerateSalt();

        // Derive the encryption key using PBKDF2 and AES-256-CBC
        byte[] key = await pbkdf2.DeriveKeyAsync(password, salt, ITERATIONS, aes.KeySize, ivBytes).ConfigureAwait(false);

        return key;
    }

    // Define a method to encrypt a string using AES-256-CBC and PBKDF2 key derivation
    public static async Task<byte[]> EncryptAsync(string input, string password)
    {
        try
        {
            // Get the encryption key from the KMS
            byte[] key = await DeriveKeyAsync(password, GenerateIv());

            // Create an AES-256-CBC encryptor
            var aes = new AesCryptoServiceProvider();
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;
            aes.KeySize = 256;
            aes.BlockSize = 128;
            aes.IV = GenerateIv();
            aes.Key = key;

            // Encrypt the input string using AES-256-CBC
            byte[] encryptedBytes = await aes.EncryptAsync(Encoding.UTF8.GetBytes(input)).ConfigureAwait(false);

            return encryptedBytes;
        }
        catch (Exception ex)
        {
            throw new EncryptionException("Failed to encrypt input string", ex);
        }
    }

    // Define a method to decrypt a string using AES-256-CBC and PBKDF2 key derivation
    public static async Task<string> DecryptAsync(byte[] encryptedBytes, string password)
    {
        try
        {
            // Get the encryption key from the KMS
            byte[] key = await DeriveKeyAsync(password, GenerateIv());

            // Create an AES-256-CBC decryptor
            var aes = new AesCryptoServiceProvider();
            aes.Mode = CipherMode.CBC;
            aes.Padding = PaddingMode.PKCS7;
            aes.KeySize = 256;
            aes.BlockSize = 128;
            aes.IV = GenerateIv();
            aes.Key = key;

            // Decrypt the input string using AES-256-CBC
            byte[] decryptedBytes = await aes.DecryptAsync(encryptedBytes).ConfigureAwait(false);

            return Encoding.UTF8.GetString(decryptedBytes);
        }
        catch (Exception ex)
        {
            throw new DecryptionException("Failed to decrypt input string", ex);
        }
    }
}
```

This class provides methods for encrypting and decrypting strings using AES-256-CBC and PBKDF2 key derivation. The encryption method takes a password as an argument and returns the encrypted string. The decryption method takes the encrypted string and password as arguments and returns the original plaintext string.

The `DeriveKeyAsync` method is used to derive the encryption key from the password using PBKDF2 and AES-256-CBC. This method creates an instance of the `PBKDF2` class and uses it to derive the encryption key from the password. The `AesCryptoServiceProvider` class is then used to create an instance of the AES-256-CBC algorithm and set its properties.

The `EncryptAsync` method is used to encrypt a plaintext string using AES-256-CBC and PBKDF2 key derivation. This method first gets the encryption key from the KMS using the `DeriveKeyAsync` method, then creates an instance of the `AesCryptoServiceProvider` class and sets its properties using the derived key. The input string is then encrypted using the `EncryptAsync` method of the `AesCryptoServiceProvider` class.

The `DecryptAsync` method is used to decrypt a ciphertext string using AES-256-CBC and PBKDF2 key derivation. This method first gets the encryption key from the KMS using the `DeriveKeyAsync` method, then creates an instance of the `AesCryptoServiceProvider` class and sets its properties using the derived key. The input string is then decrypted using the `DecryptAsync` method of the `AesCryptoServiceProvider` class.

