void* thread_func(void* arg);
int execute_command(const char* command, const char* args[]);
void handle_sigchild();
void handle_sigterm();
void cleanup();
void print_error(const char* message);
void log_info(const char* message);
void log_warn(const char* message);
void log_err(const char* message);

int main() {
  // Initialize semaphore and mutex
  sem = sem_open("command_sem", O_CREAT, 0644, 1);
  if (sem == SEM_FAILED) {
    print_error("Failed to create semaphore");
    return 1;
  }
  pthread_mutex_init(&mutex, NULL);
  pthread_cond_init(&cond, NULL);

  // Create pipes for communication with child process
  if (pipe(read_pipe) == -1 || pipe(write_pipe) == -1) {
    print_error("Failed to create pipes");
    return 1;
  }

  // Fork a child process to handle command execution
  pid_t child_pid = fork();
  if (child_pid == -1) {
    print_error("Failed to fork child process");
    return 1;
  } else if (child_pid == 0) { // Child process
    close(read_pipe[WRITE_END]);
    close(write_pipe[READ_END]);
    int child_pipe[2];
    if (pipe(child_pipe) == -1) {
      print_error("Failed to create pipes");
      return 1;
    }
    dup2(read_pipe[READ_END], STDIN_FILENO);
    dup2(write_pipe[WRITE_END], STDOUT_FILENO);
    close(read_pipe[READ_END]);
    close(write_pipe[WRITE_END]);
    execvp("bash", args);
  } else { // Parent process
    close(read_pipe[READ_END]);
    close(write_pipe[WRITE_END]);
  }

  // Start a thread to handle command execution and logging
  pthread_t thread;
  if (pthread_create(&thread, NULL, thread_func, NULL) != 0) {
    print_error("Failed to create thread");
    return 1;
  }

  // Wait for user input
  char* input = readline("Enter a command: ");
  if (input == NULL) {
    print_error("Failed to read input");
    return 1;
  }

  // Parse and execute the command
  const char* args[MAX_PARAMS];
  int num_args = parse_arguments(input, args);
  if (num_args == -1) {
    print_error("Failed to parse arguments");
    return 1;
  } else if (num_args > 0) {
    int exit_status = execute_command(args[0], args + 1);
    printf("%d\n", exit_status);
  }

  // Clean up and exit
  cleanup();
  return 0;
}

void* thread_func(void* arg) {
  while (true) {
    sem_wait(sem);
    if (!is_running) {
      break;
    }
    char* command = commands[cur_command];
    const char* args[MAX_PARAMS];
    int num_args = parse_arguments(command, args);
    if (num_args == -1) {
      log_err("Failed to parse arguments");
      continue;
    } else if (num_args > 0) {
      // Execute the command in a separate process
      pid_t child_pid = fork();
      if (child_pid == -1) {
        print_error("Failed to fork child process");
        return NULL;
      } else if (child_pid == 0) {
        // Child process
        close(read_pipe[WRITE_END]);
        close(write_pipe[READ_END]);
        dup2(read_pipe[READ_END], STDIN_FILENO);
        dup2(write_pipe[WRITE_END], STDOUT_FILENO);
        close(read_pipe[READ_END]);
        close(write_pipe[WRITE_END]);
        execvp("bash", args);
      } else {
        // Parent process
        close(read_pipe[READ_END]);
        close(write_pipe[WRITE_END]);
      }
    }
  }
  return NULL;
}

int execute_command(const char* command, const char* args[]) {
  // Start the timer
  start_time = time(NULL);

  // Execute the command in a separate process
  pid_t child_pid = fork();
  if (child_pid == -1) {
    print_error("Failed to fork child process");
    return 1;
  } else if (child_pid == 0) {
    // Child process
    close(read_pipe[WRITE_END]);
    close(write_pipe[READ_END]);
    dup2(read_pipe[READ_END], STDIN_FILENO);
    dup2(write_pipe[WRITE_END], STDOUT_FILENO);
    close(read_pipe[READ_END]);
    close(write_pipe[WRITE_END]);
    execvp("bash", args);
  } else {
    // Parent process
    close(read_pipe[READ_END]);
    close(write_pipe[READ_END]);
    int status;
    if (waitpid(child_pid, &status, WNOHANG) == child_pid) {
      // Command timed out
      is_timed_out = true;
    } else {
      // Command exited normally
      is_timed_out = false;
    }
  }

  return 0;
}

void handle_sigchild() {
  pid_t child_pid;
  int status;
  while ((child_pid = waitpid(-1, &status, WNOHANG)) > 0) {
    if (is_running && child_pid == this->child_pid) {
      is_running = false;
    }
  }
}

void handle_sigterm() {
  cleanup();
  exit(1);
}

void cleanup() {
  // Clean up pipes and semaphore
  close(read_pipe[READ_END]);
  close(write_pipe[WRITE_END]);
  sem_close(sem);

  // Exit the program
  exit(0);
}

void print_error(const char* message) {
  fprintf(stderr, "%s\n", message);
}

void log_info(const char* message) {
  printf("%s%d - %s\n", "[INFO] ", (int)time(NULL), message);
}

void log_warn(const char* message) {
  printf("%s%d - %s\n", "[WARN] ", (int)time(NULL), message);
}

void log_err(const char* message) {
  printf("%s%d - %s\n", "[ERR ] ", (int)time(NULL), message);
}
```

The `main` function creates a semaphore and mutex to synchronize access to the shared data between threads. It then creates pipes for communication with the child process, and starts a thread to handle command execution and logging. The user is prompted to enter a command, which is parsed and executed using the `execute_command` function. If the command times out, the `is_timed_out` variable is set to true, and the program continues to run indefinitely until it receives another signal.

The `thread_func` function is called by the thread started in the `main` function. It waits for a semaphore signal, which indicates that there is a new command to execute. It then retrieves the next command from the `commands` array and executes it using the `execute_command` function. If the command times out, the `is_timed_out` variable is set to true, and the program continues to run indefinitely until it receives another signal.

The `execute_command` function starts a new process by calling the `fork` system call. The child process reads input from the pipe connected to the parent process's read end, executes the command using the `execvp` system call, and writes output to the pipe connected to the parent process's write end. If the command times out, it sets the `is_timed_out` variable to true and exits the program.

The `handle_sigchild` function is called by the signal handler when a child process exits or terminates abnormally. It retrieves the status of the child process using the `waitpid` system call, and sets the `is_running` variable to false if it was the child process that was executing a command.

The `handle_sigterm` function is called by the signal handler when the program receives a SIGTERM signal. It cleans up the pipes and semaphore, and exits the program with an exit code of 1.

The `cleanup` function is called by the signal handler when the program receives a SIGINT signal or receives a SIGTERM signal. It cleans up the pipes and semaphore, and exits the program with an exit code of 0.']

