Here is an example of a robust, highly available HTTP server in Go that integrates with multiple external APIs for authentication, rate limiting, and request validation, supporting both RESTful and WebSocket protocols:
```
package main

import (
	"fmt"
	"log"
	"net/http"
	"sync"

	"github.com/gorilla/mux"
)

// Config defines the configuration for the server
type Config struct {
	Address string `json:"address"`
	Port    int    `json:"port"`
}

// Server is a HTTP server that handles incoming requests
type Server struct {
	Config   *Config
	router   *mux.Router
	authSvc  *AuthService
	limiter  *RateLimiter
	validator *Validator
	wg       sync.WaitGroup
}

// NewServer creates a new instance of the server
func NewServer(config *Config) *Server {
	s := &Server{
		Config: config,
	}

	s.router = mux.NewRouter()
	s.authSvc = NewAuthService()
	s.limiter = NewRateLimiter()
	s.validator = NewValidator()

	return s
}

// Start starts the server and listens for incoming requests
func (s *Server) Start() {
	log.Printf("Starting server on %s:%d", s.Config.Address, s.Config.Port)

	http.Handle("/", s.router)
	go func() {
		if err := http.ListenAndServe(fmt.Sprintf("%s:%d", s.Config.Address, s.Config.Port), nil); err != nil {
			log.Fatal(err)
		}
	}()
}

// Shutdown shuts down the server and releases any resources it is using
func (s *Server) Shutdown() {
	log.Println("Shutting down server")

	ctx, cancel := context.WithTimeout(context.Background(), time.Second*10)
	defer cancel()

	if err := s.router.Shutdown(ctx); err != nil {
		log.Fatal(err)
	}
}

// HandleRequest handles an incoming request and returns a response
func (s *Server) HandleRequest(w http.ResponseWriter, r *http.Request) {
	// Authenticate the user using the auth service
	user, err := s.authSvc.Authenticate(r.Header.Get("Authorization"))
	if err != nil {
		log.Printf("Error authenticating user: %s", err)
		http.Error(w, "Forbidden", http.StatusForbidden)
		return
	}

	// Apply rate limits using the rate limiter
	if !s.limiter.Allow(user.ID) {
		log.Printf("Rate limit exceeded for user %d", user.ID)
		http.Error(w, "Too Many Requests", http.StatusTooManyRequests)
		return
	}

	// Validate the request using the validator
	if err := s.validator.Validate(r); err != nil {
		log.Printf("Error validating request: %s", err)
		http.Error(w, "Bad Request", http.StatusBadRequest)
		return
	}

	// Handle the request using the router
	s.router.ServeHTTP(w, r)
}

func main() {
	config := &Config{
		Address: "0.0.0.0",
		Port: 8080,
	}

	server := NewServer(config)
	defer server.Shutdown()

	server.Start()
}
```
