char* renameFileWithDynamicExt(const char* originalFilename) {
    // Parse the original filename to determine its current extension and base name
    const char* extension = strrchr(originalFilename, '.');
    if (extension == NULL) {
        return NULL; // Invalid file path
    }

    int extLength = strlen(extension);
    if (extLength < 5) {
        // Append a numeric sequence to the extension
        char* newExtension = malloc(sizeof(char) * (extLength + 6));
        snprintf(newExtension, extLength + 6, "%s%04d", extension, getNextSequence());
        return newExtension;
    } else {
        // Replace the current extension with "custom_ext"
        char* newExtension = malloc(sizeof(char) * (strlen("custom_ext") + 1));
        strcpy(newExtension, "custom_ext");
        return newExtension;
    }
}
```
