#define ERR_DELETE_SEMAPHORE 3
#define ERR_INITIALIZE_SEMAPHORE 4
#define ERR_UPDATE_SEMAPHORE 5
#define ERR_WAIT_SEMAPHORE 6
#define ERR_SIGNAL_SEMAPHORE 7
#define LOG_ERROR(err) fprintf(stderr, "Error %d: %s\n", err, strerror(err))

// Struct for semaphore state data
typedef struct {
    int value;
    pthread_mutex_t mutex;
} semaphore_state_t;

// Function to initialize the semaphore with a specified initial value
int init_semaphore(semaphore_state_t *state, int value) {
    state->value = value;
    if (pthread_mutex_init(&state->mutex, NULL)) {
        LOG_ERROR(ERR_CREATE_SEMAPHORE);
        return ERR_CREATE_SEMAPHORE;
    }
    return 0;
}

// Function to delete the semaphore
int delete_semaphore(semaphore_state_t *state) {
    pthread_mutex_destroy(&state->mutex);
    free(state);
    return 0;
}

// Function to initialize the semaphore with a specified initial value from persistent storage
int init_semaphore_from_storage(semaphore_state_t *state, int value) {
    // Read the state from persistent storage and assign it to the semaphore
    if (read_state_from_storage(&state->value)) {
        LOG_ERROR(ERR_INITIALIZE_SEMAPHORE);
        return ERR_INITIALIZE_SEMAPHORE;
    }
    if (pthread_mutex_init(&state->mutex, NULL)) {
        LOG_ERROR(ERR_CREATE_SEMAPHORE);
        return ERR_CREATE_SEMAPHORE;
    }
    return 0;
}

// Function to update the semaphore state from persistent storage
int update_semaphore_from_storage(semaphore_state_t *state) {
    // Read the state from persistent storage and assign it to the semaphore
    if (read_state_from_storage(&state->value)) {
        LOG_ERROR(ERR_UPDATE_SEMAPHORE);
        return ERR_UPDATE_SEMAPHORE;
    }
    return 0;
}

// Function to wait for the semaphore
int wait_semaphore(semaphore_state_t *state) {
    pthread_mutex_lock(&state->mutex);
    while (state->value <= 0) {
        pthread_cond_wait(&state->cond, &state->mutex);
    }
    state->value--;
    pthread_mutex_unlock(&state->mutex);
    return 0;
}

// Function to signal the semaphore
int signal_semaphore(semaphore_state_t *state) {
    pthread_mutex_lock(&state->mutex);
    state->value++;
    pthread_cond_signal(&state->cond);
    pthread_mutex_unlock(&state->mutex);
    return 0;
}

// Function to delete the semaphore from persistent storage
int delete_semaphore_from_storage(semaphore_state_t *state) {
    // Delete the state from persistent storage
    if (delete_state_from_storage(&state->value)) {
        LOG_ERROR(ERR_DELETE_SEMAPHORE);
        return ERR_DELETE_SEMAPHORE;
    }
    return 0;
}
