using System;
using System.Threading;
using System.Threading.Tasks;
using Newtonsoft.Json;

namespace OAuth2TokenValidator
{
    public class TokenValidator
    {
        private readonly Dictionary<string, GraphQLSchema> _schemas = new();
        private readonly List<OAuth2ApiClient> _apiClients = new();

        public async Task ValidateAsync(OAuth2Token token)
        {
            var apiClient = GetApiClient(token);
            var schema = await apiClient.GetSchemaAsync().ConfigureAwait(false);
            var validationResult = ValidateToken(schema, token);

            if (!validationResult.IsValid)
            {
                throw new Exception("Invalid token");
            }
        }

        private GraphQLSchema GetApiClient(OAuth2Token token)
        {
            // Use a dictionary to cache the schema for each API client,
            // so that we don't have to fetch it every time.
            var apiClient = _apiClients.Find(c => c.Name == token.ApiName);

            if (apiClient is null)
            {
                throw new Exception("Unknown API client");
            }

            return _schemas.GetOrAdd(token.ApiName, schema => apiClient.FetchSchema());
        }

        private bool ValidateToken(GraphQLSchema schema, OAuth2Token token)
        {
            // Use the schema to validate the token fields.
            var validationResult = schema.Validate(token);

            if (!validationResult.IsValid)
            {
                return false;
            }

            return true;
        }
    }
}
```
