// Define the supported symmetric and asymmetric encryption algorithms
typedef enum {
  AES_128_CBC,
  AES_192_CBC,
  AES_256_CBC,
  AES_128_GCM,
  AES_192_GCM,
  AES_256_GCM,
  DES_CBC,
