  ECDH_SHA1,
  ECDSA_SHA256,
  ECDH_SHA256,
  ECDSA_SHA384,
  ECDH_SHA384,
  ECDSA_SHA512,
  ECDH_SHA512
} cipher_type;

// Define the supported key management services (KMS)
typedef enum {
  INTERNAL_KMS,
  AWS_KMS,
  AZURE_KEY_VAULT
} kms_service;

// Define the fallback options for null encryption and secure key management
typedef enum {
  NULL_ENCRYPTION,
  SECURE_KEY_MANAGEMENT
} fallback_option;

// Define the error codes for the library
typedef enum {
  SUCCESS,
  ERROR_INVALID_ARGUMENT,
  ERROR_UNSUPPORTED_ALGORITHM,
  ERROR_KEY_NOT_FOUND,
  ERROR_KEY_GENERATION,
  ERROR_DECRYPTION,
  ERROR_ENCRYPTION,
  ERROR_INVALID_SIGNATURE,
  ERROR_SIGNING,
  ERROR_VERIFICATION,
  ERROR_KEY_MANAGEMENT
} error_code;

// Define the library configuration and initialization
struct library_config {
  bool enable_logging; // Enable logging for debugging purposes
  kms_service default_kms; // Default KMS service to use for key management
};

// Define the encryption context structure
struct encryption_context {
  cipher_type algorithm; // Encryption algorithm used
  char *key; // Encryption key
  unsigned int key_length; // Length of the encryption key in bytes
  bool enable_padding; // Enable padding for block sizes less than the symmetric key length
};

// Define the decryption context structure
struct decryption_context {
  cipher_type algorithm; // Decryption algorithm used
  char *key; // Decryption key
  unsigned int key_length; // Length of the decryption key in bytes
  bool enable_padding; // Enable padding for block sizes less than the symmetric key length
};

// Define the signing context structure
struct signing_context {
  cipher_type algorithm; // Signing algorithm used
  char *key; // Signing key
  unsigned int key_length; // Length of the signing key in bytes
  bool enable_padding; // Enable padding for block sizes less than the symmetric key length
};

// Define the verification context structure
struct verifying_context {
  cipher_type algorithm; // Verifying algorithm used
  char *key; // Verifying key
  unsigned int key_length; // Length of the verifying key in bytes
  bool enable_padding; // Enable padding for block sizes less than the symmetric key length
};

// Define the KMS context structure
struct kms_context {
  kms_service service; // KMS service used for key management
  char *key; // Encryption key used by the KMS
  unsigned int key_length; // Length of the encryption key in bytes
};

// Define the library function prototypes
error_code encrypt(encryption_context ctx, const char *plaintext, size_t plaintext_length, char **ciphertext, size_t *ciphertext_length);
error_code decrypt(decryption_context ctx, const char *ciphertext, size_t ciphertext_length, char **plaintext, size_t *plaintext_length);
error_code sign(signing_context ctx, const char *message, size_t message_length, char **signature, size_t *signature_length);
error_code verify(verifying_context ctx, const char *message, size_t message_length, const char *signature, size_t signature_length);
error_code generate_key(kms_context ctx, char **key, unsigned int key_length);
error_code manage_key(kms_context ctx, bool enable);

// Define the library error message functions
const char *get_error_message(error_code code);
void print_error(error_code code, const char *msg);

// Define the main function for testing purposes
int main() {
  encryption_context enc_ctx;
  decryption_context dec_ctx;
  signing_context sign_ctx;
  verifying_context verify_ctx;
  kms_context kms_ctx;

  // Initialize the library configuration and contexts
  struct library_config config = {true, INTERNAL_KMS};
  enc_ctx.algorithm = AES_256_CBC;
  enc_ctx.key = "my_secret_key";
  enc_ctx.key_length = strlen(enc_ctx.key);
  dec_ctx.algorithm = AES_256_CBC;
  dec_ctx.key = "my_decryption_key";
  dec_ctx.key_length = strlen(dec_ctx.key);
  sign_ctx.algorithm = RSA_PKCS1_V1_5;
  sign_ctx.key = "my_signing_key";
  sign_ctx.key_length = strlen(sign_ctx.key);
  verify_ctx.algorithm = RSA_OAEP;
  verify_ctx.key = "my_verifying_key";
  verify_ctx.key_length = strlen(verify_ctx.key);
  kms_ctx.service = AWS_KMS;
  kms_ctx.key = NULL;

  // Encrypt the plaintext using AES-256-CBC with a randomly generated key
  char *ciphertext = NULL;
  size_t ciphertext_length = 0;
  error_code err = encrypt(enc_ctx, "plaintext", strlen("plaintext"), &ciphertext, &ciphertext_length);

  // Decrypt the ciphertext using AES-256-CBC with a randomly generated key
  char *plaintext = NULL;
  size_t plaintext_length = 0;
  err = decrypt(dec_ctx, ciphertext, ciphertext_length, &plaintext, &plaintext_length);

  // Sign the message using RSA-PKCS1-V1.5 with a randomly generated key
  char *signature = NULL;
  size_t signature_length = 0;
  err = sign(sign_ctx, "message", strlen("message"), &signature, &signature_length);

  // Verify the signature using RSA-OAEP with a randomly generated key
  err = verify(verify_ctx, "message", strlen("message"), signature, signature_length);

  // Generate an encryption key for use with the KMS service
  char *key = NULL;
  unsigned int key_length = 0;
  err = generate_key(kms_ctx, &key, key_length);

  // Manage the encryption key for use with the KMS service
  bool enable = true;
  err = manage_key(kms_ctx, enable);

  return 0;
}
