import java.util.concurrent.ConcurrentHashMap;

class StreamDataProcessor {
    private static final int MAX_CACHE_SIZE = 1000000; // maximum cache size in MB
    private static final long CACHE_EXPIRY_TIME = 3600000; // cache expiry time in milliseconds (1 hour)
    private static final int MAX_CONCURRENT_REQUESTS = 5; // maximum number of concurrent requests per client

    private ConcurrentHashMap<String, Object> cache; // cache for frequently accessed data points
    private List<StreamingClient> clients; // list of streaming clients
    private Map<String, StreamingDataProcessor> processingStages; // map of processing stages
    private long totalEventsProcessed = 0; // total number of events processed

    public StreamDataProcessor() {
        cache = new ConcurrentHashMap<>();
        clients = new ArrayList<>();
        processingStages = new HashMap<>();
    }

    /**
     * Adds a streaming client to the pipeline.
     */
    public void addClient(StreamingClient client) {
        clients.add(client);
    }

    /**
     * Removes a streaming client from the pipeline.
     */
    public void removeClient(StreamingClient client) {
        clients.remove(client);
    }

    /**
     * Adds a processing stage to the pipeline.
     */
    public void addProcessingStage(String name, StreamingDataProcessor processor) {
        processingStages.put(name, processor);
    }

    /**
     * Removes a processing stage from the pipeline.
     */
    public void removeProcessingStage(String name) {
        processingStages.remove(name);
    }

    /**
     * Processes a data point from a streaming client.
     */
    public void processDataPoint(StreamingClient client, Object dataPoint) {
        // check if the cache is full
        if (cache.size() >= MAX_CACHE_SIZE) {
            // evict the oldest entries first to make room for new ones
            Iterator<Map.Entry<String, Object>> it = cache.entrySet().iterator();
            while (it.hasNext()) {
                Map.Entry<String, Object> entry = it.next();
                if (System.currentTimeMillis() - entry.getValue().getTimestamp() > CACHE_EXPIRY_TIME) {
                    it.remove();
                }
            }
        }

        // add the data point to the cache
        cache.put(dataPoint.getId(), dataPoint);

        // process the data point through all processing stages
        for (StreamingDataProcessor processor : processingStages.values()) {
            processor.processDataPoint(client, dataPoint);
        }
    }

    /**
     * Processes a batch of data points from a streaming client.
     */
    public void processBatch(StreamingClient client, List<Object> dataPoints) {
        // check if the cache is full
        if (cache.size() + dataPoints.size() >= MAX_CACHE_SIZE) {
            // evict the oldest entries first to make room for new ones
            Iterator<Map.Entry<String, Object>> it = cache.entrySet().iterator();
            while (it.hasNext()) {
                Map.Entry<String, Object> entry = it.next();
                if (System.currentTimeMillis() - entry.getValue().getTimestamp() > CACHE_EXPIRY_TIME) {
                    it.remove();
                }
            }
        }

        // add the data points to the cache
        for (Object dataPoint : dataPoints) {
            cache.put(dataPoint.getId(), dataPoint);
        }

        // process the data points through all processing stages
        for (StreamingDataProcessor processor : processingStages.values()) {
            processor.processBatch(client, dataPoints);
        }
    }

    /**
     * Returns the total number of events processed by the pipeline.
     */
    public long getTotalEventsProcessed() {
        return totalEventsProcessed;
    }
}']

