class TxPowerReport {
    private:
        int id; // UE identifier (RNTI)
        long timestamp; // timestamp of the power report
        float powerLevel; // power level value
        static std::unordered_map<int, TxPowerReport> reports; // map of UE identifiers to power reports
        static std::mutex reportsMutex; // mutex for protecting concurrent access to reports map

    public:
        TxPowerReport(int id, long timestamp, float powerLevel) {
            this->id = id;
            this->timestamp = timestamp;
            this->powerLevel = powerLevel;
        }

        void addToReports() {
            std::lock_guard<std::mutex> lock(reportsMutex);
            reports[id] = *this;
        }

        static TxPowerReport* getTxPowerReport(int id) {
            std::lock_guard<std::mutex> lock(reportsMutex);
            auto it = reports.find(id);
            if (it != reports.end()) {
                return &(it->second);
            } else {
                return nullptr;
            }
        }
};
