["```javascript
import { readFileSync } from 'fs';
import { join } from 'path';

interface ThemeCache {
  [key: string]: Buffer;
}

class ProcessThemeData {
  private themeCache: ThemeCache = {};
  private paused = false;

  constructor(private apiEndpoint: string) {}

  public async processThemeData(): Promise<void> {
    try {
      const response = await fetch(this.apiEndpoint);
      const data = await response.json();

      if (this.paused) {
        this.resume();
      } else {
        for (const theme of data.themes) {
          await this.handleTheme(theme);
        }
      }
    } catch (error) {
      console.error('Error processing theme data', error);
    } finally {
      if (!this.paused) {
        setTimeout(() => this.processThemeData(), 1000); // retry after 1s
      }
    }
  }

  private async handleTheme(theme: any): Promise<void> {
    const buffer = await readFileSync(join('cache', theme.id + '.png'));
    this.themeCache[theme.id] = buffer;
  }

  public pause(): void {
    this.paused = true;
  }

  public resume(): void {
    this.paused = false;
    this.processThemeData();
  }

  public getThemes(): ThemeCache {
    return this.themeCache;
  }
}
```
