        while ((entry = readdir(dir)) != NULL) {
            if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;
            // Check if resource bundle is already loaded
            CacheEntry *cacheEntry = getCacheEntry(entry->d_name);
            if (cacheEntry) {
