}

// Remove a cache entry from the cache
bool removeCacheEntry(const void *data, int size) {
    // Find cache entry that matches data and size
    CacheEntry *entry = findCacheEntry(data, size);
    if (!entry) {
        return false;
    }
    // Remove cache entry from cache
    memcpy(entry->data, NULL, entry->size);
    entry->size = 0;
    entry->timestamp = 0;
    return true;
}

// Evict cache entries that have expired
void evictCacheEntries() {
    // Find oldest cache entry
    CacheEntry *entry = findOldestCacheEntry();
    if (!entry) {
        perror("Failed to evict cache entries");
        exit(1);
