### 1.2.4 패키지와의 상호작용

이 시스템은 `ExternalMemoryPool`과 `DynamicArray`가 상호작용을 하는 것을 보장해야 한다. 따라서, 아래의 주요 기능을 제공해야 한다.

- `DynamicArray`가 `ExternalMemoryPool`에 할당된 모든 메모리를 관리하는 기능
- `DynamicArray`의 사이즈가 `ExternalMemoryPool`의 남은 용량을 벗어나지 않도록 유지해야 하는 기능
- `DynamicArray`가 메모리를 `ExternalMemoryPool`에서 할당받아 사용할 수 있도록 하는 기능
- `DynamicArray`가 사용하고 있는 메모리를 `ExternalMemoryPool`에 다시 반환해주어야 하는 기능
- `DynamicArray`의 사이즈가 0인지 아닌지에 대한 기능

아래의 코드는 위의 기능들을 구현한 것이다.

```scss
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// ExternalMemoryPool

typedef struct {
    void **memory;
    size_t size;
} ExternalMemoryPool;

ExternalMemoryPool *ExternalMemoryPool_create(size_t size) {
    ExternalMemoryPool *pool = (ExternalMemoryPool *)malloc(sizeof(ExternalMemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->memory = (void **)malloc(sizeof(void *) * size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }
    pool->size = size;
    return pool;
}

bool ExternalMemoryPool_destroy(ExternalMemoryPool *pool) {
    if (!pool) {
        return false;
    }
    free(pool->memory);
    free(pool);
    return true;
}

void *ExternalMemoryPool_allocate(ExternalMemoryPool *pool, size_t size) {
    if (size > pool->size || !pool->memory[0]) {
        return NULL;
    }
    for (int i = 0; i < pool->size - size + 1; i++) {
        if (!pool->memory[i]) {
            continue;
        }
        void *p = &pool->memory[i];
        memmove(&pool->memory[i + size], p, sizeof(void *) * (pool->size - i));
        return p;
    }
    return NULL;
}

bool ExternalMemoryPool_free(ExternalMemoryPool *pool, void *p) {
    if (!pool || !p) {
        return false;
    }
    int index = ((char *)p - (char *)pool->memory) / sizeof(void *);
    pool->memory[index] = NULL;
    return true;
}

// DynamicArray

typedef struct {
    void **elements;
    size_t capacity;
    size_t size;
    ExternalMemoryPool *pool;
} DynamicArray;

DynamicArray *DynamicArray_create(size_t capacity, ExternalMemoryPool *pool) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) {
        return NULL;
    }
    array->elements = (void **)malloc(sizeof(void *) * capacity);
    if (!array->elements) {
        free(array);
        return NULL;
    }
    array->capacity = capacity;
    array->size = 0;
    array->pool = pool;
    return array;
}

bool DynamicArray_destroy(DynamicArray *array) {
    if (!array) {
        return false;
    }
    free(array->elements);
    free(array);
    return true;
}

bool DynamicArray_add(DynamicArray *array, void *p) {
    if (!array || !p) {
        return false;
    }
    if (array->size == array->capacity) {
        // 메모리가 꽉 찼다면 확장
        array->capacity *= 2;
        void **elements = realloc(array->elements, sizeof(void *) * array->capacity);
        if (!elements) {
            return false;
        }
        array->elements = elements;
    }
    array->elements[array->size++] = p;
    return true;
}

bool DynamicArray_remove(DynamicArray *array, int index) {
    if (!array || index < 0 || index >= array->size) {
        return false;
    }
    void **p = &array->elements[index];
    memmove(&array->elements[index], &array->elements[index + 1], sizeof(void *) * (array->size - index));
    // 메모리를 다시 확장하지 않도록 한다.
    array->capacity = array->size;
    return ExternalMemoryPool_free(array->pool, p);
}

bool DynamicArray_get(DynamicArray *array, int index, void **p) {
    if (!array || index < 0 || index >= array->size) {
        return false;
    }
    *p = array->elements[index];
    return true;
}

bool DynamicArray_clear(DynamicArray *array) {
    if (!array) {
        return false;
    }
    array->size = 0;
    // 메모리를 다시 확장하지 않도록 한다.
    array->capacity = 0;
    return true;
}

bool DynamicArray_resize(DynamicArray *array, size_t capacity) {
    if (!array || capacity < array->size) {
        return false;
    }
    void **elements = realloc(array->elements, sizeof(void *) * capacity);
    if (!elements) {
        return false;
    }
    array->capacity = capacity;
    array->elements = elements;
    return true;
}

bool DynamicArray_is_empty(DynamicArray *array) {
    if (!array) {
        return false;
    }
    return array->size == 0;
}
```

### 구현한 코드의 문제점

위에서 구현한 코드는 DynamicArray를 사용하는 작성자가 아무리 주의해도 내부의 흩어진 메모리가 다 쓸데없이 잡아먹을 수 있다. 그러므로 내부에서 사용하는 DynamicArray의 사이즈를 잘못 설정해서 쓰던 메모리가 다 없어지는 일을 피하기 위해서는 주의해야한다.

### 개선한 코드

내부에서 사용하는 DynamicArray의 사이즈를 잘못 설정해도 그것을 통제할 수 있다면, 문제점은 해결될 가능성이 높아진다.

```scss
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// ExternalMemoryPool

typedef struct {
    void **memory;
    size_t size;
} ExternalMemoryPool;

ExternalMemoryPool *ExternalMemoryPool_create(size_t size) {
    ExternalMemoryPool *pool = (ExternalMemoryPool *)malloc(sizeof(ExternalMemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->memory = (void **)malloc(sizeof(void *) * size);
    if (!pool->memory) {
        free(pool);
        return NULL;
    }
    pool->size = 0;
    return pool;
}

bool ExternalMemoryPool_destroy(ExternalMemoryPool *pool) {
    if (!pool) {
        return false;
    }
    free(pool->memory);
    free(pool);
    return true;
}

void *ExternalMemoryPool_allocate(ExternalMemoryPool *pool, size_t size) {
    if (size > pool->size || !pool->memory[0]) {
        return NULL;
    }
    void **p = &pool->memory[pool->size];
    pool->size += size;
    return p;
}

bool ExternalMemoryPool_free(ExternalMemoryPool *pool, void *ptr) {
    if (!pool || !ptr) {
        return false;
    }
    size_t index = (char *)ptr - (char *)pool->memory;
    if (index >= pool->size) {
        return false;
    }
    for (int i = 0; i < pool->size - index; i++) {
        pool->memory[i] = pool->memory[i + index];
    }
    pool->size -= index;
    return true;
}

// DynamicArray

typedef struct {
    void **data;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray *DynamicArray_create(size_t capacity) {
    DynamicArray *array = (DynamicArray *)malloc(sizeof(DynamicArray));
    if (!array) {
        return NULL;
    }
    array->data = (void **)ExternalMemoryPool_allocate((void *)array, sizeof(void *) * capacity);
    if (!array->data) {
        free(array);
        return NULL;
    }
    array->capacity = capacity;
    array->size = 0;
    return array;
}

bool DynamicArray_destroy(DynamicArray *array) {
    if (!array) {
        return false;
    }
    for (int i = 0; i < array->size; i++) {
        void **p = &array->data[i];
        ExternalMemoryPool_free((void *)array, p);
    }
    free(array->data);
    free(array);
    return true;
}

bool DynamicArray_add(DynamicArray *array, void *value) {
    if (!array) {
        return false;
    }
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        void **new_data = (void **)ExternalMemoryPool_allocate((void *)array, sizeof(void *) * new_capacity);
        if (!new_data) {
            return false;
        }
        for (int i = 0; i < array->size; i++) {
            void **p = &array->data[i];
            new_data[i] = *p;
        }
        ExternalMemoryPool_free((void *)array, array->data);
        array->data = new_data;
        array->capacity = new_capacity;
    }
    void **p = &array->data[array->size++];
    *p = value;
    return true;
}

bool DynamicArray_remove(DynamicArray *array, int index) {
    if (!array || index < 0 || index >= array->size) {
        return false;
    }
    for (int i = index + 1; i < array->size; i++) {
        void **p = &array->data[i - 1];
        array->data[i] = *p;
    }
    array->size--;
    return true;
}

bool DynamicArray_get(DynamicArray *array, int index, void **value) {
    if (!array || index < 0 || index >= array->size) {
        return false;
    }
    *value = array->data[index];
    return true;
}

bool DynamicArray_clear(DynamicArray *array) {
    if (!array) {
        return false;
    }
    for (int i = 0; i < array->size; i++) {
        void **p = &array->data[i];
        ExternalMemoryPool_free((void *)array, p);
    }
    array->size = 0;
    return true;
}

bool DynamicArray_resize(DynamicArray *array, size_t capacity) {
    if (!array || capacity < array->size) {
        return false;
    }
    void **new_data = (void **)ExternalMemoryPool_allocate((void *)array, sizeof(void *) * capacity);
    if (!new_data) {
        return false;
    }
    for (int i = 0; i < array->size; i++) {
        void **p = &array->data[i];
        new_data[i] = *p;
    }
    ExternalMemoryPool_free((void *)array, array->data);
    array->data = new_data;
    array->capacity = capacity;
    return true;
}
```

In this implementation, we define a `DynamicArray` structure that contains three fields: `data`, `capacity`, and `size`. The `data` field is a pointer to an array of pointers, which will be used to store the elements of the dynamic array. The `capacity` field is the maximum number of elements that can be stored in the dynamic array, and the `size` field is the current number of elements stored in the dynamic array.

The `DynamicArray_create` function allocates memory for a new `DynamicArray` structure and initializes its fields. The `capacity` field is initialized to the requested capacity, and the `data` field is set to an empty array. The `size` field is initialized to 0.

The `DynamicArray_destroy` function frees all memory allocated for a given dynamic array. It first calls `ExternalMemoryPool_free` on each element in the dynamic array's data array, and then frees the memory allocated for the dynamic array structure itself.

The `DynamicArray_add` function adds a new element to the end of the dynamic array. If the current size of the dynamic array is equal to its capacity, it reallocates the memory for the data array and doubles its capacity. It then copies the given value into the new slot in the data array and increments the `size` field.

The `DynamicArray_remove` function removes an element from a given position in the dynamic array. It shifts all elements after the removed element to the left by one position, and then decrements the `size` field.

The `DynamicArray_get` function retrieves the value of an element at a given position in the dynamic array. It returns the value of that element if it exists, or NULL otherwise.

The `DynamicArray_clear` function frees all memory allocated for a given dynamic array's elements and resets the `size` field to 0.

The `DynamicArray_resize` function reallocates the memory for a given dynamic array's data array to a new capacity. It copies each element from the old array to the new array, and then frees the memory allocated for the old array.']

