#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>

struct Transaction {
    int transaction_id;
    double weighted_sum;
};

// Function to filter transactions based on their age and weighted sum
struct Transaction* filter_transactions(int num_transactions, struct Transaction* transactions) {
    // Declare variables
    int i, j;
    int age = 3;
    double weighted_sum = 0.0;
    struct Transaction* filtered_transactions;

    // Initialize filtered transactions
    filtered_transactions = (struct Transaction*)malloc(num_transactions * sizeof(struct Transaction));
    memset(filtered_transactions, 0, num_transactions * sizeof(struct Transaction));

    // Loop through transactions and filter based on age and weighted sum
    for (i = 0; i < num_transactions; i++) {
        if ((transactions[i].transaction_id - time(NULL)) <= age) {
            weighted_sum += transactions[i].weighted_sum;
            filtered_transactions[j++] = transactions[i];
        }
    }

    // Return filtered transactions and maximum weighted sum
    return filtered_transactions;
}

// Function to update metrics and provide comprehensive error reporting and logging mechanisms
void update_metrics(int num_filtered_transactions, struct Transaction* filtered_transactions) {
    // Declare variables
    int i;
    double maximum_weighted_sum = 0.0;
    int maximum_transaction_id = -1;
    char error_message[256];

    // Loop through filtered transactions and update metrics
    for (i = 0; i < num_filtered_transactions; i++) {
        if (filtered_transactions[i].weighted_sum > maximum_weighted_sum) {
            maximum_weighted_sum = filtered_transactions[i].weighted_sum;
            maximum_transaction_id = filtered_transactions[i].transaction_id;
        }
    }

    // Log and report error message if any
    if (maximum_transaction_id == -1) {
        sprintf(error_message, "No transactions found with age <= %d", age);
        printf("Error: %s\n", error_message);
    } else {
        printf("Maximum weighted sum: %.2f (Transaction ID: %d)\n", maximum_weighted_sum, maximum_transaction_id);
    }
}
