package deployments

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"strconv"
	"strings"
	"time"

	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/rest"
)

type DeploymentStatus int

const (
	DeploySuccess = iota
	DeployFailure
	ScaleSuccess
	ScaleFailure
)

type Result struct {
	Status   DeploymentStatus
	ErrorMsg string
	Details  string
}

// DeployMicroservice deploys a microservice in a multi-cluster Kubernetes environment.
func DeployMicroservice(ctx context.Context, clusterConfig ClusterConfig, deploymentSpec DeploymentSpec, override ClusterOverride) (Result, error) {
	clientset, err := getClientSet(clusterConfig.Name, override)
	if err != nil {
		return Result{}, err
	}

	err = validateDeployment(deploymentSpec)
	if err != nil {
		return Result{}, err
	}

	err = createOrUpdateService(ctx, clientset, deploymentSpec.ServiceName, deploymentSpec.ImageName, override)
	if err != nil {
		return Result{}, err
	}

	err = createOrUpdateDeployment(ctx, clientset, deploymentSpec, override)
	if err != nil {
		return Result{}, err
	}

	err = createOrUpdateIngress(ctx, clientset, deploymentSpec.ServiceName, deploymentSpec.IngressName, override)
	if err != nil {
		return Result{}, err
	}

	deploymentStatus := DeploySuccess
	details := ""

	// Check readiness and liveness of the microservice.
	for i := 0; i < deploymentSpec.Replicas; i++ {
		podName := fmt.Sprintf("%s-%d", deploymentSpec.ServiceName, i)
		err = waitForPodReadiness(ctx, clientset, podName, override)
		if err != nil {
			deploymentStatus = DeployFailure
			details += fmt.Sprintf("Error waiting for pod %s to be ready: %v\n", podName, err)
		}

		err = waitForPodLiveness(ctx, clientset, podName, override)
		if err != nil {
			deploymentStatus = DeployFailure
			details += fmt.Sprintf("Error waiting for pod %s to be alive: %v\n", podName, err)
		}
	}

	// Scale the deployment if necessary.
	if deploymentSpec.Scale {
		err = scaleDeployment(ctx, clientset, deploymentSpec.ServiceName, deploymentSpec.Replicas, override)
		if err != nil {
			deploymentStatus = ScaleFailure
			details += fmt.Sprintf("Error scaling deployment %s: %v\n", deploymentSpec.ServiceName, err)
		}
	}

	return Result{deploymentStatus, "", details}, nil
}

func getClientSet(clusterName string, override ClusterOverride) (*kubernetes.Clientset, error) {
	config := rest.Config{}
	if len(override.URL) > 0 {
		config.Host = override.URL
	}
	return kubernetes.NewForConfig(&config)
}

func validateDeployment(deploymentSpec DeploymentSpec) error {
	// Validate the deployment spec fields.
	if len(deploymentSpec.ServiceName) == 0 {
		return errors.New("service name must be provided")
	}
	if len(deploymentSpec.ImageName) == 0 {
		return errors.New("image name must be provided")
	}
	if deploymentSpec.Replicas <= 0 {
		return errors.New("replica count must be greater than 0")
	}

	// Validate the cluster config fields.
	if len(override.Name) == 0 {
		return errors.New("cluster name must be provided")
	}
	if len(override.URL) == 0 {
		return errors.New("cluster URL must be provided")
	}

	return nil
}

func createOrUpdateService(ctx context.Context, clientset *kubernetes.Clientset, serviceName string, imageName string, override ClusterOverride) error {
	// Create a new service if it doesn't exist.
	service := &v1.Service{
		TypeMeta: metav1.TypeMeta{
			Kind:       "Service",
			APIVersion: "v1",
		},
		ObjectMeta: metav1.ObjectMeta{
			Name: serviceName,
		},
	}
	_, err := clientset.CoreV1().Services(override.Namespace).Create(ctx, service, metav1.CreateOptions{})
	if err != nil {
		// If the service already exists, update it instead.
		service, err = clientset.CoreV1().Services(override.Namespace).Get(ctx, serviceName, metav1.GetOptions{})
		if err != nil {
			return fmt.Errorf("error getting service %s: %v", serviceName, err)
		}
		service.Spec.Type = v1.ServiceTypeClusterIP
		service.Spec.Selector = map[string]string{
			"app": serviceName,
		}
		service.Spec.Ports = []v1.ServicePort{
			{
				Protocol:   "TCP",
				Port:       80,
				TargetPort: intstr.FromInt(80),
			},
		}
		_, err = clientset.CoreV1().Services(override.Namespace).Update(ctx, service, metav1.UpdateOptions{})
		if err != nil {
			return fmt.Errorf("error updating service %s: %v", serviceName, err)
		}
	}

	// Create a new deployment if it doesn't exist.
	deployment := &appsv1.Deployment{
		TypeMeta: metav1.TypeMeta{
			Kind:       "Deployment",
			APIVersion: "apps/v1",
		},
		ObjectMeta: metav1.ObjectMeta{
			Name: serviceName,
		},
	}
	_, err = clientset.AppsV1().Deployments(override.Namespace).Create(ctx, deployment, metav1.CreateOptions{})
	if err != nil {
		// If the deployment already exists, update it instead.
		deployment, err = clientset.AppsV1().Deployments(override.Namespace).Get(ctx, serviceName, metav1.GetOptions{})
		if err != nil {
			return fmt.Errorf("error getting deployment %s: %v", serviceName, err)
		}
		deployment.Spec.Replicas = &deploymentSpec.Replicas
		deployment.Spec.Selector = &metav1.LabelSelector{
			MatchLabels: map[string]string{
				"app": serviceName,
			},
		}
		deployment.Spec.Template.ObjectMeta.Labels = map[string]string{
			"app": serviceName,
		}
		deployment.Spec.Template.ObjectMeta.Annotations = map[string]string{
			"sidecar.istio.io/inject": "true",
		}
		deployment.Spec.Template.Spec.Containers = []v1.Container{
			{
				Name:  serviceName,
				Image: imageName,
				Ports: []v1.ContainerPort{
					{
						Protocol: v1.ProtocolTCP,
						ContainerPort: 80,
					},
				},
			},
		}
		_, err = clientset.AppsV1().Deployments(override.Namespace).Update(ctx, deployment, metav1.UpdateOptions{})
		if err != nil {
			return fmt.Errorf("error updating deployment %s: %v", serviceName, err)
		}
	}

	// Create a new ingress if it doesn't exist.
	ingress := &extensionsv1beta1.Ingress{
		TypeMeta: metav1.TypeMeta{
			Kind:       "Ingress",
			APIVersion: "networking.k8s.io/v1beta1",
		},
		ObjectMeta: metav1.ObjectMeta{
			Name: serviceName,
		},
	}
	_, err = clientset.ExtensionsV1beta1().Ingresses(override.Namespace).Create(ctx, ingress, metav1.CreateOptions{})
	if err != nil {
		// If the ingress already exists, update it instead.
		ingress, err = clientset.ExtensionsV1beta1().Ingresses(override.Namespace).Get(ctx, serviceName, metav1.GetOptions{})
		if err != nil {
			return fmt.Errorf("error getting ingress %s: %v", serviceName, err)
		}
		ingress.Spec.Rules = []extensionsv1beta1.IngressRule{
			{
				Host: deploymentSpec.IngressHost,
			},
		}
		ingress.Spec.TLS = []extensionsv1beta1.IngressTLS{
			{
				Hosts: []string{deploymentSpec.IngressHost},
			},
		}
		_, err = clientset.ExtensionsV1beta1().Ingresses(override.Namespace).Update(ctx, ingress, metav1.UpdateOptions{})
		if err != nil {
			return fmt.Errorf("error updating ingress %s: %v", serviceName, err)
		}
	}

	return nil
}

func waitForPod(ctx context.Context, clientset *kubernetes.Clientset, name string, namespace string, ready bool, timeout time.Duration) error {
	timeoutChan := time.After(timeout)
	ticker := time.NewTicker(500 * time.Millisecond)

	for {
		select {
		case <-timeoutChan:
			return errors.New("timed out waiting for pod to become ready")
		case <-ticker.C:
			pod, err := clientset.CoreV1().Pods(namespace).Get(ctx, name, metav1.GetOptions{})
			if err != nil {
				return err
			}

			if ready && podReady(*pod) || !ready && !podReady(*pod) {
				return nil
			}
		}
	}
}

func waitForService(ctx context.Context, clientset *kubernetes.Clientset, name string, namespace string, timeout time.Duration) error {
	timeoutChan := time.After(timeout)
	ticker := time.NewTicker(500 * time.Millisecond)

	for {
		select {
		case <-timeoutChan:
			return errors.New("timed out waiting for service to become ready")
		case <-ticker.C:
			svc, err := clientset.CoreV1().Services(namespace).Get(ctx, name, metav1.GetOptions{})
			if err != nil {
				return err
			}

			if svcReady(*svc) {
				return nil
			}
		}
	}
}

func podReady(pod v1.Pod) bool {
	for _, cond := range pod.Status.Conditions {
		if cond.Type == "Ready" && cond.Status == "True" {
			return true
		}
	}
	return false
}

func svcReady(svc v1.Service) bool {
	for _, cond := range svc.Status.Conditions {
		if cond.Type == "Available" && cond.Status == "True" {
			return true
		}
	}
	return false
}`']

