import logging
from datetime import datetime
from typing import Dict, List
from log_processor import LogProcessor

class LogProcessor:
    def __init__(self):
        self.log_entries = []

    @staticmethod
    def read_logs(log_file_path: str) -> List[Dict]:
        with open(log_file_path, "r") as log_file:
            return [json.loads(line) for line in log_file]

    @staticmethod
    def parse_logs(logs: List[Dict]) -> List[Dict]:
        return [LogProcessor.parse_log(log) for log in logs]

    @staticmethod
    def parse_log(log: Dict) -> Dict:
        parsed_log = {}
        try:
            parsed_log["timestamp"] = datetime.strptime(log["timestamp"], "%Y-%m-%d %H:%M:%S")
            parsed_log["error_code"] = log["errorCode"]
        except KeyError as e:
            logging.warning("Unable to parse log due to missing key: {}".format(e))
        return parsed_log

    def sort_logs(self) -> List[Dict]:
        self.log_entries = sorted(self.log_entries, key=lambda x: x["timestamp"])
        return self.log_entries

    def extract_error_codes(self) -> List[int]:
        error_codes = []
        for log in self.log_entries:
            if "errorCode" in log:
                error_codes.append(log["errorCode"])
        return error_codes

if __name__ == "__main__":
    log_processor = LogProcessor()
    logs = LogProcessor.read_logs("path/to/log/file")
    parsed_logs = LogProcessor.parse_logs(logs)
    sorted_logs = log_processor.sort_logs()
    error_codes = log_processor.extract_error_codes()

