            var aes = new AesCryptoServiceProvider();
            aes.GenerateIV();
            aes.GenerateKey();
            return aes.Key;
        }

        public byte[] RotateEncryptionKey() {
            // Rotate encryption key based on predefined schedule or detected anomalies
            lock (_lockObject) {
                _encryptionKeys.Add(_encryptionKeys[_encryptionKeys.Count - 1]);
                _encryptionKeys.RemoveAt(0);
            }
            return _encryptionKeys[_encryptionKeys.Count - 1];
        }

        public async Task<byte[]> GetEncryptionKeyAsync() {
            // Retrieve encryption key from distributed cache for rapid retrieval
            try {
                string response = await _httpClient.GetStringAsync(_keyDatabaseUrl);
                byte[] encryptionKey = Convert.FromBase64String(response);
                return encryptionKey;
            } catch (Exception e) {
                Console.WriteLine("Error occurred: " + e.Message);
                throw new Exception("Failed to retrieve encryption key from distributed cache");
            }
        }
