2. Secure Data Storage: Implement robust encryption mechanisms, leveraging a hardware security module (HSM) for key management. Encrypt all stored files, allowing users to define encryption policies at the file or directory level. Ensure seamless integration with third-party data processing and storage services.
```java
import java.security.Key;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import org.apache.hadoop.fs.FileSystem;
import org.apache.hadoop.fs.Path;

public class SecureStorage {
  private Key key;

  public SecureStorage() {}

  public void setKey(String key) {
    this.key = new SecretKeySpec(key.getBytes(), "AES");
  }

  public byte[] encrypt(byte[] data) throws Exception {
    Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
    cipher.init(Cipher.ENCRYPT_MODE, key);
    return cipher.doFinal(data);
  }

  public byte[] decrypt(byte[] data) throws Exception {
    Cipher cipher = Cipher.getInstance("AES/ECB/PKCS5Padding");
    cipher.init(Cipher.DECRYPT_MODE, key);
    return cipher.doFinal(data);
  }

  public void writeToFileSystem(byte[] data) throws Exception {
    FileSystem fs = FileSystem.get(new Path("/path/to/file"), new Configuration());
    fs.createNewFile("/path/to/file");
    FSDataOutputStream out = fs.append(new Path("/path/to/file"));
    out.write(encrypt(data));
    out.close();
  }

  public byte[] readFromFileSystem() throws Exception {
    FileSystem fs = FileSystem.get(new Path("/path/to/file"), new Configuration());
    FSDataInputStream in = fs.open(new Path("/path/to/file"));
    byte[] data = in.readAll();
    in.close();
    return decrypt(data);
  }
}
