#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for holding RX information
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the doubly linked list structure for holding the RX information
typedef struct NFAPI_CRC_INDICATION_LIST {
    struct NFAPI_CRC_INDICATION_PDU_T *head;
    struct NFAPI_CRC_INDICATION_PDU_T *tail;
} NFAPI_CRC_INDICATION_LIST;

// Define the lock for protecting the doubly linked list
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Define the semaphore for signaling between threads
static semaphore_t sem;

// Define the memory pool for allocating and deallocating NFAPI_CRC_INDICATION_PDU_T structures
static void *pool = NULL;

// Define the function for initializing the library
void nfapi_crc_indication_init(NFAPI_CRC_INDICATION_LIST *list) {
    list->head = NULL;
    list->tail = NULL;
}

// Define the function for adding a new element to the doubly linked list
void nfapi_crc_indication_add(NFAPI_CRC_INDICATION_LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&lock);

    // Allocate memory for the new element
    if (pool == NULL) {
        pool = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    memcpy(pool, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Add the new element to the end of the doubly linked list
    if (list->tail == NULL) {
        list->head = pool;
        list->tail = pool;
    } else {
        list->tail->next = pool;
        list->tail = pool;
    }

    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&lock);
}

// Define the function for removing an element from the doubly linked list
void nfapi_crc_indication_remove(NFAPI_CRC_INDICATION_LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&lock);

    // Find the element in the doubly linked list and remove it
    struct NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current == pdu) {
            break;
        }
        current = current->next;
    }
    if (current == NULL) {
        // The element was not found in the doubly linked list
        return;
    }

    // Remove the element from the doubly linked list
    if (list->head == pdu) {
        list->head = current->next;
    } else {
        struct NFAPI_CRC_INDICATION_PDU_T *previous = list->head;
        while (previous->next != pdu) {
            previous = previous->next;
        }
        previous->next = current->next;
    }
    if (list->tail == pdu) {
        list->tail = previous;
    }

    // Free the memory allocated for the element
    free(pdu);

    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&lock);
}

// Define the function for querying an element from the doubly linked list
NFAPI_CRC_INDICATION_PDU_T *nfapi_crc_indication_query(NFAPI_CRC_INDICATION_LIST *list, uint16_t RX_UE_INFORMATION_TAG) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&lock);

    // Find the element in the doubly linked list and return it
    struct NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            break;
        }
        current = current->next;
    }
    if (current == NULL) {
        // The element was not found in the doubly linked list
        return NULL;
    }

    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&lock);

    // Return a copy of the found element
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(pdu, current, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    return pdu;
}

// Define the function for removing all elements from the doubly linked list
void nfapi_crc_indication_remove_all(NFAPI_CRC_INDICATION_LIST *list) {
    // Lock the list to prevent concurrent modifications
    pthread_mutex_lock(&lock);

    // Free all memory allocated for the elements in the doubly linked list
    struct NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        free(current);
        current = current->next;
    }
    list->head = NULL;
    list->tail = NULL;

    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&lock);
}
```

This code implements a doubly linked list data structure for storing NFAPI CRC Indication PDUs. The `nfapi_crc_indication_init` function initializes the library by setting the head and tail pointers of the doubly linked list to NULL. The `nfapi_crc_indication_add` function adds a new element to the end of the doubly linked list, and the `nfapi_crc_indication_remove` function removes an element from the doubly linked list by finding it using the RX UE Information Tag. The `nfapi_crc_indication_query` function returns a copy of the found element, and the `nfapi_crc_indication_remove_all` function frees all memory allocated for the elements in the doubly linked list.

This code uses a separate pool of memory for allocating new elements, which is allocated using the `malloc` function. The pool is used to allocate memory for each element that is added to the doubly linked list, and it is freed when the library is initialized or when all elements are removed from the doubly linked list. This allows the library to dynamically allocate memory as needed without causing a memory leak.

The code also uses a mutex to prevent concurrent modifications to the doubly linked list while an element is being added, removed, or queried. This ensures that multiple threads can safely access the library at the same time without causing data corruption or other errors.']

