namespace EncryptionService
{
    public class EncryptionManager
    {
        private readonly Dictionary<string, Aes> _keyMap = new Dictionary<string, Aes>();
        private readonly List<Aes> _rotationQueue = new List<Aes>();
        private readonly object _lockObject = new object();

        public EncryptionManager() {}

        public void Initialize(int keySize)
        {
            // Generate the initial keys for each user session
            for (var i = 0; i < keySize; i++)
            {
                var key = CreateKey();
                _keyMap.Add(key, Aes.Create());
            }
        }

        public void Encrypt(string plaintext, string username)
        {
            // Get the corresponding AES instance for this user session
            var aesInstance = _keyMap[username];

            // Generate a new initialization vector (IV) and encrypt the plaintext
            using (var iv = CreateIv())
            {
                using (var encryptedPlaintext = Encrypt(plaintext, aesInstance, iv))
                {
                    // Add the encrypted plaintext to the rotation queue
                    _rotationQueue.Add(encryptedPlaintext);
                }
            }
        }

        public void Decrypt(string ciphertext, string username)
        {
            // Get the corresponding AES instance for this user session
            var aesInstance = _keyMap[username];

            // Decrypt the ciphertext using the appropriate initialization vector (IV)
            using (var iv = CreateIv())
            {
                using (var decryptedCiphertext = Decrypt(ciphertext, aesInstance, iv))
                {
                    // Return the decrypted plaintext
                    return decryptedCiphertext;
                }
            }
        }

        private Aes CreateKey()
        {
            var key = new Aes();
            key.GenerateKey();
            key.GenerateIV();
            return key;
        }

        private byte[] CreateIv()
        {
            // Generate a random initialization vector (IV) using the AES class
            var iv = new Aes().IV;
            return iv;
        }

        private byte[] Encrypt(string plaintext, Aes aesInstance, byte[] iv)
        {
            // Create a new memory stream for the encrypted plaintext
            using (var memoryStream = new MemoryStream())
            {
                // Write the initialization vector (IV) to the memory stream
                memoryStream.Write(iv);

                // Encrypt the plaintext using the AES instance and write it to the memory stream
                using (var encryptor = aesInstance.CreateEncryptor())
                {
                    var ciphertext = encryptor.TransformFinalBlock(Encoding.UTF8.GetBytes(plaintext), 0, plaintext.Length);
                    memoryStream.Write(ciphertext);
                }

                // Return the encrypted plaintext as a byte array
                return memoryStream.ToArray();
            }
        }

        private byte[] Decrypt(string ciphertext, Aes aesInstance, byte[] iv)
        {
            // Create a new memory stream for the decrypted plaintext
            using (var memoryStream = new MemoryStream())
            {
                // Read the initialization vector (IV) from the memory stream
                var ivBytes = memoryStream.Read(iv);

                // Decrypt the ciphertext using the AES instance and write it to the memory stream
                using (var decryptor = aesInstance.CreateDecryptor())
                {
                    var plaintext = decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);
                    memoryStream.Write(plaintext);
                }

                // Return the decrypted plaintext as a byte array
                return memoryStream.ToArray();
            }
        }

        private void RotateKeys()
        {
            // Create a new AES instance for each key in the rotation queue
            foreach (var encryptedPlaintext in _rotationQueue)
            {
                var aesInstance = Aes.Create();
                aesInstance.GenerateKey();
                aesInstance.GenerateIV();

                // Update the corresponding key map entry with the new AES instance
                _keyMap[encryptedPlaintext] = aesInstance;
            }

            // Clear the rotation queue
            _rotationQueue.Clear();
        }
    }
}
