import java.util.concurrent.TimeUnit;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import com.datastax.driver.core.Cluster;
import com.datastax.driver.core.Session;
import com.rabbitmq.client.Channel;
import com.rabbitmq.client.ConnectionFactory;
import com.rabbitmq.client.MessageProperties;
import org.json.JSONObject;

@RestController
public class MyAPI {

    private static final String DATABASE_HOST = "localhost";
    private static final int DATABASE_PORT = 9042;
    private static final String MESSAGE_BROKER_HOST = "localhost";
    private static final int MESSAGE_BROKER_PORT = 5672;
    private static final String API_KEY = "YOUR_API_KEY";

    @GetMapping("/users")
    public ResponseEntity<String> getUsers() {
        Cluster cluster = null;
        Session session = null;
        try {
            cluster = new Cluster.Builder().addContactPoint(DATABASE_HOST).withPort(DATABASE_PORT).build();
            session = cluster.connect();
            String query = "SELECT * FROM users";
            ResultSet results = session.execute(query);
            JSONArray jsonArray = new JSONArray();
            for (Row row : results) {
                JSONObject jsonObject = new JSONObject();
                jsonObject.put("id", row.getInt("id"));
                jsonObject.put("name", row.getString("name"));
                jsonArray.add(jsonObject);
            }
            return ResponseEntity.ok(jsonArray.toString());
        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.badRequest().body(e.getMessage());
        } finally {
            if (session != null) session.close();
            cluster.close();
        }
    }

    @PostMapping("/users")
    public ResponseEntity<String> createUser(@RequestBody String requestBody) {
        Cluster cluster = null;
        Session session = null;
        try {
            cluster = new Cluster.Builder().addContactPoint(DATABASE_HOST).withPort(DATABASE_PORT).build();
            session = cluster.connect();
            JSONObject jsonObject = new JSONObject(requestBody);
            String name = jsonObject.getString("name");
            int age = jsonObject.getInt("age");
            String query = "INSERT INTO users (name, age) VALUES (" + name + ", " + age + ")";
            session.execute(query);
            return ResponseEntity.ok().body("User created successfully.");
        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.badRequest().body(e.getMessage());
        } finally {
            if (session != null) session.close();
            cluster.close();
        }
    }

    @PutMapping("/users/{id}")
    public ResponseEntity<String> updateUser(@PathVariable String id, @RequestBody String requestBody) {
        Cluster cluster = null;
        Session session = null;
        try {
            cluster = new Cluster.Builder().addContactPoint(DATABASE_HOST).withPort(DATABASE_PORT).build();
            session = cluster.connect();
            JSONObject jsonObject = new JSONObject(requestBody);
            String name = jsonObject.getString("name");
            int age = jsonObject.getInt("age");
            String query = "UPDATE users SET name=" + name + ", age=" + age + " WHERE id=" + id;
            session.execute(query);
            return ResponseEntity.ok().body("User updated successfully.");
        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.badRequest().body(e.getMessage());
        } finally {
            if (session != null) session.close();
            cluster.close();
        }
    }

    @DeleteMapping("/users/{id}")
    public ResponseEntity<String> deleteUser(@PathVariable String id) {
        Cluster cluster = null;
        Session session = null;
        try {
            cluster = new Cluster.Builder().addContactPoint(DATABASE_HOST).withPort(DATABASE_PORT).build();
            session = cluster.connect();
            String query = "DELETE FROM users WHERE id=" + id;
            session.execute(query);
            return ResponseEntity.ok().body("User deleted successfully.");
        } catch (Exception e) {
            e.printStackTrace();
            return ResponseEntity.badRequest().body(e.getMessage());
        } finally {
            if (session != null) session.close();
            cluster.close();
        }
    }

    private void sendMessageToRabbitMQ(String message) {
        ConnectionFactory factory = new ConnectionFactory();
        factory.setHost(MESSAGE_BROKER_HOST);
        factory.setPort(MESSAGE_BROKER_PORT);
        Channel channel = null;
        try {
            Connection connection = factory.newConnection();
            channel = connection.createChannel();
            String exchangeName = "my_exchange";
            String routingKey = "my_routing_key";
            channel.basicPublish(exchangeName, routingKey, MessageProperties.PERSISTENT_TEXT_PLAIN, message.getBytes("UTF-8"));
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            if (channel != null) try { channel.close(); } catch (IOException ignore) {}
        }
    }

}
