// Define the structure for an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the function to initialize an array of NFAPI_CRC_INDICATION_PDU_T structures
void init_nfapi_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu, size_t num_elements, uint32_t seed, void* memory_pool) {
    // Check if the input parameters are valid
    if (pdu == NULL || num_elements == 0 || seed == 0 || memory_pool == NULL) {
        fprintf(stderr, "Invalid input parameter(s).\n");
        return;
    }

    // Generate a random number within the given range using the provided seed
    srand(seed);
    uint8_t rand_num = (uint8_t)rand() % 256;

    // Initialize the structures with valid values
    for (size_t i = 0; i < num_elements; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = rand_num++;
        pdu[i].RNTI = rand_num++;
        pdu[i].CRC_INDICATION_REL8_TAG = rand_num++;
        pdu[i].CRCFLAG = (rand_num % 2 == 0) ? true : false;
    }
}

// Test the function with a small number of elements
int main(void) {
    const size_t num_elements = 10;
    NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        fprintf(stderr, "Failed to allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures.\n");
        return 1;
    }

    // Initialize the array with random values using a seed of 42
    init_nfapi_crc_indication(pdu, num_elements, 42, NULL);

    // Print the initialized structures
    for (size_t i = 0; i < num_elements; i++) {
        printf("Structure %zu:\n", i + 1);
