// Custom data structures and functions for efficient geolocation processing
class Geolocation {
public:
    double latitude;
    double longitude;
    int timestamp;
    std::string device_id;
    std::string event_type;
};

class EventProcessor {
private:
    // Map of IoT devices and their associated event types
    std::unordered_map<std::string, std::set<std::string>> device_event_types_;

    // Map of device IDs and their associated geolocation data
    std::unordered_map<std::string, Geolocation> device_geolocations_;

    // Function for processing events from IoT devices
    void processEvent(const std::string& event) {
        // Parse the event data and extract relevant information
        std::stringstream ss;
        ss << event;
        double latitude, longitude;
        int timestamp;
        std::string device_id, event_type;
        ss >> latitude >> longitude >> timestamp >> device_id >> event_type;

        // Add the geolocation data to the map of device IDs and their associated data
        Geolocation new_geolocation = {latitude, longitude, timestamp, device_id, event_type};
        device_geolocations_[device_id] = new_geolocation;

        // Update the set of event types for the current IoT device
        if (device_event_types_.find(device_id) != device_event_types_.end()) {
            device_event_types_[device_id].insert(event_type);
        } else {
            std::set<std::string> new_set = {event_type};
            device_event_types_[device_id] = new_set;
        }
    }

public:
    // Function for processing events from IoT devices and updating the geolocation data map
    void processEvents(const std::vector<std::string>& events) {
        for (auto event : events) {
            processEvent(event);
        }
    }

    // Function for retrieving the geolocation data for a given IoT device
    const Geolocation& getGeolocationData(const std::string& device_id) const {
        return device_geolocations_.at(device_id);
    }
};

// Custom data structures and functions for efficient geolocation processing (parallel version)
class ParallelEventProcessor {
private:
    // Map of IoT devices and their associated event types
    std::unordered_map<std::string, std::set<std::string>> device_event_types_;

    // Map of device IDs and their associated geolocation data
    std::unordered_map<std::string, Geolocation> device_geolocations_;

    // Vector of futures for processing events in parallel
    std::vector<std::future<void>> event_processors_;

    // Function for processing events from IoT devices (parallel version)
    void processEvent(const std::string& event) {
        // Parse the event data and extract relevant information
        std::stringstream ss;
        ss << event;
        double latitude, longitude;
        int timestamp;
        std::string device_id, event_type;
        ss >> latitude >> longitude >> timestamp >> device_id >> event_type;

        // Add the geolocation data to the map of device IDs and their associated data (parallel version)
        Geolocation new_geolocation = {latitude, longitude, timestamp, device_id, event_type};
        std::lock_guard<std::mutex> lock(mutex_);
        device_geolocations_[device_id] = new_geolocation;

        // Update the set of event types for the current IoT device (parallel version)
        if (device_event_types_.find(device_id) != device_event_types_.end()) {
            std::lock_guard<std::mutex> lock(mutex_);
            device_event_types_[device_id].insert(event_type);
        } else {
            std::set<std::string> new_set = {event_type};
            std::lock_guard<std::mutex> lock(mutex_);
            device_event_types_[device_id] = new_set;
        }
    }

public:
    // Function for processing events from IoT devices and updating the geolocation data map (parallel version)
    void processEvents(const std::vector<std::string>& events) {
        // Create a vector of futures for processing events in parallel
        event_processors_.resize(events.size());
        for (size_t i = 0; i < events.size(); ++i) {
            event_processors_[i] = std::async(std::launch::async, &ParallelEventProcessor::processEvent, this, events[i]);
        }

        // Wait for all events to be processed in parallel
        for (auto& future : event_processors_) {
            future.get();
        }
    }

    // Function for retrieving the geolocation data for a given IoT device
    const Geolocation& getGeolocationData(const std::string& device_id) const {
        return device_geolocations_.at(device_id);
    }
};

