// Define the structure to hold the access token information
struct access_token {
    char* access_token;
    int expires_in;
    char* token_type;
    char* refresh_token;
};

// Function to validate an OAuth2 access token response against predefined criteria
int validate_access_token(const struct json_object* response) {
    // Check if the required fields are present and correctly formatted
    const struct json_object* access_token = json_object_get_string(response, "access_token");
    if (!access_token) {
        return 0;
    }
    int expires_in = json_object_get_int(response, "expires_in");
    if (expires_in < 0) {
        return 0;
    }
    const char* token_type = json_object_get_string(response, "token_type");
    if (!token_type || strcmp(token_type, "Bearer") != 0) {
        return 0;
    }
    // Check for optional fields and handle potential errors gracefully
    const char* refresh_token = json_object_get_string(response, "refresh_token");
    if (refresh_token && strlen(refresh_token) > 0) {
        return 1;
    }
    return 1;
}

// Function to handle memory allocation and initialization of internal data structures
struct access_token* init_access_token() {
    struct access_token* token = malloc(sizeof(struct access_token));
    if (!token) {
        return NULL;
    }
    token->access_token = NULL;
    token->expires_in = 0;
    token->token_type = NULL;
    token->refresh_token = NULL;
    return token;
}

// Function to populate the access token structure with random integer values within a specified range
void populate_access_token(struct access_token* token) {
    assert(token);
    // Generate a random integer within the specified range
    int random_int = rand() % 10;
    // Assign the random integer to the access token structure
    token->access_token = "random_int";
}

// Function to validate an OAuth2 access token response and populate the access token structure with validated values
struct access_token* validate_and_populate(const struct json_object* response) {
    // Validate the access token response against predefined criteria
    if (validate_access_token(response)) {
        // Initialize the access token structure and populate it with random integer values within a specified range
        struct access_token* token = init_access_token();
        populate_access_token(token);
        return token;
    }
    return NULL;
}
```
