// Load config file and initialize data structures
void init(void) {
    // Load token cache from Redis
    redisContext *redis = redisConnect(REDIS_HOST, REDIS_PORT);
    if (redis == NULL || redis->err) {
        printf("Error connecting to Redis: %s\n", redis->errstr);
        return;
    }
    redisReply *reply = redisCommand(redis, "GET token-cache");
    if (reply != NULL && reply->type == REDIS_REPLY_STRING) {
        char *token_cache = reply->str;
        int token_count = 0;
        while (*token_cache) {
            // Parse token from cache
            token_t *token = (token_t *)malloc(sizeof(token_t));
            memset(token, 0, sizeof(token_t));
            char *cur_token = token_cache;
            while (*cur_token != '\n') {
                if (*cur_token == ' ') {
                    cur_token++;
                } else {
                    token->token = cur_token;
                    cur_token += strlen(token->token);
                }
            }
            // Parse expiry time from cache
            char *expires_in = cur_token + 1;
            while (*cur_token != '\n') {
                if (*cur_token == ' ') {
                    cur_token++;
                } else {
                    token->expires_in = atoi(expires_in);
                    cur_token += strlen(expires_in);
                }
            }
            // Add to token cache
            token_count++;
        }
        free(reply);
    } else {
        printf("Error loading token cache: %s\n", redis->errstr);
        return;
    }
    // Load client credentials from file
    FILE *file = fopen("client-credentials.json", "r");
    if (file != NULL) {
        char line[1024];
        while (fgets(line, 1024, file)) {
            if (strncmp(line, "\"client_id\": ", 13) == 0) {
                char *client_id = line + 13;
                client_t *client = (client_t *)malloc(sizeof(client_t));
                memset(client, 0, sizeof(client_t));
                client->client_id = strdup(client_id);
            } else if (strncmp(line, "\"client_secret\": ", 16) == 0) {
                char *client_secret = line + 16;
                client_t *client = (client_t *)malloc(sizeof(client_t));
                memset(client, 0, sizeof(client_t));
                client->client_secret = strdup(client_secret);
            }
        }
        fclose(file);
    } else {
        printf("Error loading client credentials: %s\n", strerror(errno));
        return;
    }
}

