    // Add data to the buffer
    {
        std::lock_guard<std::mutex> lock(mutex);
        buffer.push_back(data);
    }

    // Notify the thread that is waiting for new data
    conditionVariable.notify_one();
}

bool DynamicDataFlowProcessor::store(const std::string& data) {
    return storage->store(data);
}

void DynamicDataFlowProcessor::run() {
    while (!stopProcessing) {
        // Wait for new data to arrive
        std::unique_lock<std::mutex> lock(mutex);
        conditionVariable.wait(lock, [this] { return hasNewData || stopProcessing; });

        if (hasNewData) {
            // Process the buffered data
            for (const auto& data : buffer) {
                processor->process(data);
            }

            // Clear the buffer
            buffer.clear();
        }
    }
}
