#include <stdbool.h>
#include <stdio.h>
#include <time.h>

int getDisjointPairs(int* arr, int size) {
    // Initialize Union-Find data structure with size of array
    int* uf = (int*)malloc(sizeof(int)*size);
    for (int i = 0; i < size; i++) {
        uf[i] = i;
    }

    // Loop through each pair of elements in the array
    int pairs = 0;
    for (int i = 0; i < size - 1; i++) {
        for (int j = i + 1; j < size; j++) {
            // If elements are not disjoint, merge them
            if (!areDisjoint(arr[i], arr[j])) {
                merge(uf, i, j);
                pairs++;
            }
        }
    }

    return pairs;
}

bool areDisjoint(int x, int y) {
    // If elements are in different sets, they are disjoint
    if (find(uf, x) != find(uf, y)) {
        return true;
    } else {
        return false;
    }
}

void merge(int* uf, int x, int y) {
    // Merge elements into the same set
    int rootX = find(uf, x);
    int rootY = find(uf, y);
    if (rootX != rootY) {
        uf[rootX] = rootY;
    }
}

int find(int* uf, int i) {
    // Find the root of the set that element i belongs to
    while (uf[i] != i) {
        i = uf[i];
    }
    return i;
}
