#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <dlfcn.h>
#include <stdint.h>

// Define the maximum number of plugins that can be loaded
#define MAX_PLUGINS 50

// Define the structure to hold information about each plugin
typedef struct {
    void* handle; // Handle to the shared library for this plugin
    char* name; // Name of the plugin
} PluginInfo;

// Define a global array to store information about all plugins
PluginInfo plugins[MAX_PLUGINS];

// Define a mutex to protect access to the plugin array
pthread_mutex_t pluginMutex = PTHREAD_MUTEX_INITIALIZER;

// Define a function to load a new plugin
int loadPlugin(char* filename) {
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(&pluginMutex);

    // Check if there is space in the plugins array for this new plugin
    if (plugins[0].name == NULL) {
        // If no slots are available, return an error
        printf("No more room in plugins array\n");
        pthread_mutex_unlock(&pluginMutex);
        return -1;
    }

    // Open the shared library for this plugin
    void* handle = dlopen(filename, RTLD_NOW | RTLD_GLOBAL);
    if (!handle) {
        printf("Failed to open shared library %s: %s\n", filename, dlerror());
        pthread_mutex_unlock(&pluginMutex);
        return -1;
    }

    // Get the name of the plugin from the shared library
    char* name = dlsym(handle, "getPluginName");
    if (!name) {
        printf("Failed to get plugin name: %s\n", dlerror());
        pthread_mutex_unlock(&pluginMutex);
        return -1;
    }

    // Check if this plugin is already loaded
    for (int i = 0; i < MAX_PLUGINS; i++) {
        if (plugins[i].name && strcmp(plugins[i].name, name) == 0) {
            printf("Plugin %s is already loaded\n", name);
            pthread_mutex_unlock(&pluginMutex);
            return -1;
        }
    }

    // Add the new plugin to the plugins array
    for (int i = 0; i < MAX_PLUGINS; i++) {
        if (plugins[i].name == NULL) {
            plugins[i].handle = handle;
            plugins[i].name = name;
            break;
        }
    }

    // Release the mutex and return success
    pthread_mutex_unlock(&pluginMutex);
    return 0;
}

// Define a function to unload a plugin
int unloadPlugin(char* name) {
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(&pluginMutex);

    // Find the plugin in the plugins array and remove it
    for (int i = 0; i < MAX_PLUGINS; i++) {
        if (plugins[i].name && strcmp(plugins[i].name, name) == 0) {
            dlclose(plugins[i].handle);
            plugins[i].name = NULL;
            break;
        }
    }

    // Release the mutex and return success
    pthread_mutex_unlock(&pluginMutex);
    return 0;
}

// Define a function to call a plugin's method
int callPluginMethod(char* name, char* methodName, void** args) {
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(&pluginMutex);

    // Find the plugin in the plugins array and get its handle
    for (int i = 0; i < MAX_PLUGINS; i++) {
        if (plugins[i].name && strcmp(plugins[i].name, name) == 0) {
            void* handle = plugins[i].handle;
            pthread_mutex_unlock(&pluginMutex);
            // Call the plugin's method using the handle and args
            return callPluginMethod(handle, methodName, args);
        }
    }

    // Release the mutex and return error
    pthread_mutex_unlock(&pluginMutex);
    printf("Plugin %s is not loaded\n", name);
    return -1;
}

// Define a function to get the names of all plugins
int getPluginNames(char** names) {
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(&pluginMutex);

    // Copy the plugin names into the output array
    for (int i = 0; i < MAX_PLUGINS; i++) {
        if (plugins[i].name) {
            strcpy(names[i], plugins[i].name);
        } else {
            break;
        }
    }

    // Release the mutex and return success
    pthread_mutex_unlock(&pluginMutex);
    return 0;
}

// Define a function to get the number of plugins loaded
int getNumPlugins() {
    int numPlugins = 0;
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(&pluginMutex);

    // Count the number of non-null plugin names in the array
    for (int i = 0; i < MAX_PLUGINS; i++) {
        if (plugins[i].name) {
            numPlugins++;
        } else {
            break;
        }
    }

    // Release the mutex and return success
    pthread_mutex_unlock(&pluginMutex);
    return numPlugins;
}

// Define a function to get the number of plugin loads/unloads in progress
int getNumLoadsInProgress() {
    int numLoads = 0;
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(&pluginMutex);

    // Count the number of non-null handles in the array
    for (int i = 0; i < MAX_PLUGINS; i++) {
        if (plugins[i].handle) {
            numLoads++;
        } else {
            break;
        }
    }

    // Release the mutex and return success
    pthread_mutex_unlock(&pluginMutex);
    return numLoads;
}

// Define a function to get the number of plugin loads/unloads completed
int getNumLoadsCompleted() {
    int numLoads = 0;
    // Acquire the mutex to prevent race conditions
    pthread_mutex_lock(&pluginMutex);

    // Count the number of non-null handles in the array
    for (int i = 0; i < MAX_PLUGINS; i++) {
        if (plugins[i].name && plugins[i].handle) {
            numLoads++;
        } else {
            break;
        }
    }

    // Release the mutex and return success
    pthread_mutex_unlock(&pluginMutex);
    return numLoads;
}']

