            return -1;
        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    // Parse the JSON data in the buffer and update the resource bundle
    update_resource_bundle();

    return 0;
}

// Function to update the resource bundle with new data from an in-memory structure
int update_in_memory() {
    // Read the in-memory data structure and parse it into JSON format
    struct json_object* json = json_parse_string(in_memory_data);
    if (json == NULL) {
        printf("Error parsing JSON data from file %s\n", filename);
        return -1;
    }

    // Update the resource bundle with the new data
    update_resource_bundle(json);

    json_object_put(json);

    return 0;
}

// Function to write the resource bundle to a local file
int write_local_file(const char* filename) {
    // Open the file and write the JSON data in it
    int fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd < 0) {
        printf("Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    struct json_object* json = get_resource_bundle();
    char* buffer = json_serialize_to_string(json);
    if (buffer == NULL) {
        printf("Error serializing JSON data to file %s\n", filename);
        return -1;
    }

    ssize_t bytes_written = write(fd, buffer, strlen(buffer));
    if (bytes_written < 0) {
        printf("Error writing to file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    close(fd);

    free(buffer);
    json_object_put(json);

    return 0;
}

// Function to write the resource bundle to a remote API
int write_remote_api() {
    char* api_url = "https://example.com/api/data";
    struct curl_slist *headers = NULL;
