        }
    }

    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);

    return 0;
}

// Function to write the resource bundle to an in-memory structure
int write_in_memory() {
    // Read the in-memory data structure and parse it into JSON format
    struct json_object* json = get_resource_bundle();
    char* buffer = json_serialize_to_string(json);
    if (buffer == NULL) {
        printf("Error serializing JSON data to file %s\n", filename);
        return -1;
    }

    // Update the in-memory data structure with the new data
    update_in_memory(buffer);

    json_object_put(json);

    free(buffer);

    return 0;
}

int main() {
