import time
import threading
import queue
from concurrent.futures import ThreadPoolExecutor

class DataIngestionFramework:
    def __init__(self, data_sources, tenants):
        self.data_sources = data_sources
        self.tenants = tenants
        self.data_queue = queue.Queue()
        self.executor = ThreadPoolExecutor(max_workers=10)
        self.start_time = time.time()

    def run(self):
        # Start data ingestion threads
        for source in self.data_sources:
            t = threading.Thread(target=self.ingest_data, args=(source,))
            t.daemon = True
            t.start()

        # Start data processing threads
        for tenant in self.tenants:
            t = threading.Thread(target=self.process_data, args=(tenant,))
            t.daemon = True
            t.start()

    def ingest_data(self, source):
        # Connect to data source and retrieve data
        while True:
            try:
                data = self.connect_to_source(source)
                if data is None:
                    continue
                self.data_queue.put((source, data))
            except Exception as e:
                print(f"Error ingesting data from {source}: {e}")

    def process_data(self, tenant):
        # Process data for given tenant
        while True:
            try:
                source, data = self.data_queue.get()
                processed_data = self.process_data_(data)
                if processed_data is None:
                    continue
                self.write_to_destination(processed_data, tenant)
            except Exception as e:
                print(f"Error processing data for {tenant}: {e}")

