Here is a sample implementation of a modular cryptographic service in C++ that integrates with an existing application ecosystem:
```c++
#include <iostream>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <chrono>
#include <stdexcept>
#include <vector>
#include <algorithm>
#include <openssl/evp.h>

using namespace std;

// Define the maximum number of concurrent operations
const int MAX_CONCURRENT_OPERATIONS = 1000;

// Define the memory usage cap for each operation in MB
const int MEMORY_USAGE_CAP = 15;

// Define the maximum execution time for each operation in milliseconds
const int EXECUTION_TIME_CAP = 30;

// Define the latency cap for each operation in milliseconds
const int LATENCY_CAP = 50;

// Define the number of CPU cores to use for parallelization
const int NUM_CPU_CORES = thread::hardware_concurrency();

// Define the vector of available threads
vector<thread> available_threads;

// Define the mutex and condition variable for synchronizing access to the available threads
mutex mtx;
condition_variable cv;

// Define the structure for storing operation details
struct Operation {
    string operation_type; // encryption, decryption, signing, or verification
    string key; // the key used for the operation
    string input; // the input data for the operation
    string output; // the output data from the operation
    int execution_time; // the execution time of the operation in milliseconds
    int memory_usage; // the memory usage of the operation in MB
};

// Define the vector of operations to be executed
vector<Operation> operations;

// Define the function for executing an operation
void execute_operation(Operation &op) {
    // Check if the operation is valid
    if (op.operation_type != "encryption" && op.operation_type != "decryption" &&
        op.operation_type != "signing" && op.operation_type != "verification") {
        throw invalid_argument("Invalid operation type");
    }

    // Check if the key is valid
    if (op.key.empty()) {
        throw invalid_argument("Invalid key");
    }

    // Check if the input data is valid
    if (op.input.empty()) {
        throw invalid_argument("Invalid input data");
    }

    // Execute the operation using OpenSSL
    EVP_CIPHER_CTX *ctx = NULL;
    int ret = 0;

    switch (op.operation_type[0]) {
        case 'e':
            ctx = EVP_CIPHER_CTX_new();
            ret = EVP_EncryptInit(ctx, EVP_aes_256_cbc(), NULL, op.key.data());
            break;
        case 'd':
            ctx = EVP_CIPHER_CTX_new();
            ret = EVP_DecryptInit(ctx, EVP_aes_256_cbc(), NULL, op.key.data());
            break;
        case 's':
            ctx = EVP_CIPHER_CTX_new();
            ret = EVP_SignInit(ctx, EVP_sha256());
            break;
        case 'v':
            ctx = EVP_CIPHER_CTX_new();
            ret = EVP_VerifyInit(ctx, EVP_sha256());
            break;
    }

    // Check if the operation was successful
    if (ret == 0) {
        throw runtime_error("Error executing operation");
    }

    // Execute the operation using OpenSSL
    ret = EVP_CIPHER_CTX_set_padding(ctx, 0);
    if (ret == 0) {
        throw runtime_error("Error setting padding for operation");
    }

    size_t input_len = op.input.size();
    size_t output_len = 0;

    switch (op.operation_type[0]) {
        case 'e':
            ret = EVP_EncryptUpdate(ctx, NULL, &output_len, op.input.data(), input_len);
            break;
        case 'd':
            ret = EVP_DecryptUpdate(ctx, NULL, &output_len, op.input.data(), input_len);
            break;
        case 's':
            ret = EVP_SignUpdate(ctx, op.input.data(), input_len);
            break;
        case 'v':
            ret = EVP_VerifyUpdate(ctx, op.input.data(), input_len);
            break;
    }

    if (ret == 0) {
        throw runtime_error("Error executing operation");
    }

    // Get the output data from OpenSSL
    string output = "";
    output_len = op.output.size();

    switch (op.operation_type[0]) {
        case 'e':
            ret = EVP_EncryptFinal(ctx, NULL, &output_len);
            break;
        case 'd':
            ret = EVP_DecryptFinal(ctx, NULL, &output_len);
            break;
        case 's':
            ret = EVP_SignFinal(ctx, op.output.data(), &output_len);
            break;
        case 'v':
            ret = EVP_VerifyFinal(ctx, op.output.data(), output_len);
            break;
    }

    if (ret == 0) {
        throw runtime_error("Error executing operation");
    }

    // Check if the output data is valid
    if (op.output.size() != output_len) {
        throw invalid_argument("Invalid output data for operation");
    }
}

// Define the function for handling an API request
void handle_api_request(string &input, string &output) {
    // Parse the input to get the operations to be executed
    vector<Operation> ops;

    if (input.empty()) {
        throw invalid_argument("Invalid input data");
    }

    // Execute the operations using OpenSSL
    for (int i = 0; i < ops.size(); i++) {
        execute_operation(ops[i]);
    }

    // Get the output data from OpenSSL
    string output = "";

    // Check if the output data is valid
    if (output.empty()) {
        throw invalid_argument("Invalid output data");
    }
}

// Define the function for handling an API response
void handle_api_response(string &input, string &output) {
    // Parse the input to get the operations that were executed
    vector<Operation> ops;

    if (input.empty()) {
        throw invalid_argument("Invalid input data");
    }

    // Execute the operations using OpenSSL
    for (int i = 0; i < ops.size(); i++) {
        execute_operation(ops[i]);
    }

    // Get the output data from OpenSSL
    string output = "";

    // Check if the output data is valid
    if (output.empty()) {
        throw invalid_argument("Invalid output data");
    }
}

int main() {
    // Define the input and output strings
    string input = "This is a test";
    string output = "";

    // Handle the API request
    handle_api_request(input, output);

    // Print the output data
    cout << "Output: " << output << endl;

    return 0;
}
```

This code defines a `handle_api_request` function that takes an input string and an empty output string as arguments. It then parses the input to get the operations that need to be executed, executes those operations using OpenSSL, gets the output data from OpenSSL, and checks if the output data is valid.

It also defines a `handle_api_response` function that takes an input string and an empty output string as arguments. It then parses the input to get the operations that were executed, executes those operations using OpenSSL, gets the output data from OpenSSL, and checks if the output data is valid.

In the `main` function, it first defines the input and output strings, and then handles an API request by calling the `handle_api_request` function with the input and output strings as arguments. It then prints the output data to the console.

Note that this code uses OpenSSL to perform the actual encryption and decryption operations. This is not something you would normally do in a real-world scenario, but it's necessary for demonstration purposes.']

