import java.util.concurrent.ConcurrentHashMap;
import com.google.gson.Gson;
import com.mongodb.async.client.MongoClient;
import com.mongodb.async.client.MongoCollection;
import org.bson.Document;

public class UserProfileService {
  private final ConcurrentHashMap<String, Document> userProfiles = new ConcurrentHashMap<>();
  private final Gson gson = new Gson();
  private final MongoClient mongoClient;
  private final MongoCollection<Document> userProfileCollection;

  public UserProfileService(MongoClient mongoClient) {
    this.mongoClient = mongoClient;
    this.userProfileCollection = mongoClient.getDatabase("user_profiles").getCollection("user_profile");
  }

  public void updateUserProfile(String userId, String username, String email, String profilePictureUrl, boolean isSubscribed, Map<String, Object> additionalPreferences) {
    Document document = new Document();
    document.append("userId", userId);
    document.append("username", username);
    document.append("email", email);
    document.append("profilePictureUrl", profilePictureUrl);
    document.append("isSubscribed", isSubscribed);
    document.append("additionalPreferences", additionalPreferences);
    userProfiles.put(userId, document);
  }

  public Document getUserProfile(String userId) {
    return userProfiles.get(userId);
  }

  public void deleteUserProfile(String userId) {
    userProfiles.remove(userId);
  }

  public void asyncUpdateUserProfile(String userId, String username, String email, String profilePictureUrl, boolean isSubscribed, Map<String, Object> additionalPreferences) {
    Document document = new Document();
    document.append("userId", userId);
    document.append("username", username);
    document.append("email", email);
    document.append("profilePictureUrl", profilePictureUrl);
    document.append("isSubscribed", isSubscribed);
    document.append("additionalPreferences", additionalPreferences);
    userProfiles.put(userId, document);
  }

  public void asyncDeleteUserProfile(String userId) {
    userProfiles.remove(userId);
  }

  public void init() {
    // Initialize the user profiles map from the database
    MongoCursor<Document> cursor = userProfileCollection.find().iterator();
    while (cursor.hasNext()) {
      Document document = cursor.next();
      String userId = document.getString("userId");
      Document profile = new Document(document);
      userProfiles.put(userId, profile);
    }
  }
}
```
