// Define struct for plugin metadata
typedef struct {
    char *name;
    void *handle;
} Plugin;

// Define struct for state management
typedef struct {
    Plugin *plugins[100];
    int num_plugins;
    int current_plugin;
} State;

// Define function pointers for plugin functions
typedef void (*PluginFunc)(void);

// Declare global variables
State state;
int plugin_loaded = 0;
pthread_mutex_t lock;

/*
 * Function to load a plugin.
 * @param name The name of the plugin to load.
 */
void load_plugin(char *name) {
    // Check if plugin is already loaded
    for (int i = 0; i < state.num_plugins; i++) {
        if (!strcmp(state.plugins[i]->name, name)) {
            return;
        }
    }

    // Load the plugin
    void *handle = dlopen(name, RTLD_NOW | RTLD_GLOBAL);
    if (!handle) {
        printf("Error loading plugin: %s\n", dlerror());
        return;
    }

    // Get the function pointer for the plugin's init function
    PluginFunc init = dlsym(handle, "init");
    if (!init) {
        printf("Error getting init function for plugin: %s\n", dlerror());
        return;
    }

    // Call the init function to initialize the plugin
    init();

    // Add the plugin to the list of loaded plugins
    state.plugins[state.num_plugins++] = (Plugin *) malloc(sizeof(Plugin));
    strcpy(state.plugins[state.num_plugins-1]->name, name);
    state.plugins[state.num_plugins-1]->handle = handle;

    plugin_loaded = 1;
}

/*
 * Function to unload a plugin.
 * @param index The index of the plugin to unload.
 */
void unload_plugin(int index) {
    // Check if plugin is loaded
    if (state.plugins[index] == NULL || state.num_plugins <= 0) {
        return;
    }

    // Unload the plugin
    dlclose(state.plugins[index]->handle);
    free(state.plugins[index]);

    // Remove the plugin from the list of loaded plugins
    for (int i = index; i < state.num_plugins-1; i++) {
        memcpy(&state.plugins[i], &state.plugins[i+1], sizeof(Plugin));
    }
    state.num_plugins--;
}

/*
 * Function to call a plugin's function.
 * @param index The index of the plugin to call.
 * @param name The name of the function in the plugin to call.
 */
void call_plugin(int index, char *name) {
    // Check if plugin is loaded
    if (state.plugins[index] == NULL || state.num_plugins <= 0) {
        return;
    }

    // Get the function pointer for the plugin's function
    PluginFunc func = dlsym(state.plugins[index]->handle, name);
    if (!func) {
        printf("Error getting function %s from plugin: %s\n", name, dlerror());
        return;
    }

    // Call the plugin's function
    func();
}

/*
 * Function to get a list of all loaded plugins.
 * @return A list of strings containing the names of all loaded plugins.
 */
char **get_loaded_plugins() {
    char **plugins = (char **) malloc(sizeof(char *) * state.num_plugins);

    for (int i = 0; i < state.num_plugins; i++) {
        plugins[i] = strdup(state.plugins[i]->name);
    }

    return plugins;
}

/*
 * Function to get the number of loaded plugins.
 * @return The number of loaded plugins.
 */
int num_loaded_plugins() {
    return state.num_plugins;
}

/*
 * Function to get a list of all available plugins.
 * @param dir The directory containing the plugin files.
 * @return A list of strings containing the names of all available plugins.
 */
char **get_available_plugins(char *dir) {
    char **plugins = (char **) malloc(sizeof(char *) * 100);
    int num_plugins = 0;

    DIR *d;
    struct dirent *dirent;
    d = opendir(dir);
    if (!d) {
        return NULL;
    }

    while ((dirent = readdir(d)) != NULL) {
        if (strstr(dirent->d_name, ".so") != NULL) {
            plugins[num_plugins++] = strdup(dirent->d_name);
        }
    }

    closedir(d);

    return plugins;
}

/*
 * Function to initialize the state management.
 */
void init_state() {
    memset(&state, 0, sizeof(State));
    pthread_mutex_init(&lock, NULL);
}

/*
 * Function to destroy the state management.
 */
void destroy_state() {
    for (int i = 0; i < state.num_plugins; i++) {
        dlclose(state.plugins[i]->handle);
        free(state.plugins[i]);
    }
    pthread_mutex_destroy(&lock);
}

/*
 * Function to get the current plugin.
 * @return The index of the currently loaded plugin, or -1 if no plugin is loaded.
 */
int get_current_plugin() {
    return state.current_plugin;
}

/*
 * Function to set the current plugin.
 * @param index The index of the new plugin to load.
 */
void set_current_plugin(int index) {
    if (index < 0 || index >= state.num_plugins) {
        return;
    }

    // Lock the mutex before accessing the global state
    pthread_mutex_lock(&lock);

    // Unload any existing plugins
    for (int i = 0; i < state.num_plugins; i++) {
        if (state.plugins[i] != NULL) {
            unload_plugin(i);
        }
    }

    // Load the new plugin
    load_plugin(index);

    // Set the current plugin index
    state.current_plugin = index;

    pthread_mutex_unlock(&lock);
}

/*
 * Function to load a plugin.
 * @param index The index of the plugin to load.
 */
void load_plugin(int index) {
    // Check if the plugin is already loaded
    if (state.plugins[index] != NULL) {
