    void* handle;
    int refCount;
} PluginRef;

typedef struct {
    sem_t *semaphore;
    pthread_mutex_t mutex;
} LoadLock;

// Global variables
PluginInfo plugins[MAX_PLUGINS];
PluginRef* pluginRefs[MAX_PLUGINS];
LoadLock loadLock;
int numPlugins = 0;
int numLoaded = 0;

void initLoadLock() {
    sem_init(&loadLock.semaphore, PTHREAD_PROCESS_SHARED, 1);
    pthread_mutex_init(&loadLock.mutex, NULL);
}

void destroyLoadLock() {
    sem_destroy(&loadLock.semaphore);
    pthread_mutex_destroy(&loadLock.mutex);
}

void acquireLoadLock() {
    sem_wait(&loadLock.semaphore);
    pthread_mutex_lock(&loadLock.mutex);
}

void releaseLoadLock() {
    pthread_mutex_unlock(&loadLock.mutex);
    sem_post(&loadLock.semaphore);
}

int loadPlugin(const char* name, const char* version) {
    int i;
    for (i = 0; i < numPlugins; ++i) {
        if (strcmp(plugins[i].name, name) == 0 && strcmp(plugins[i].version, version) == 0) {
            return i;
        }
    }
    return -1;
}

void* loadPluginDynamicLib(const char* name, const char* version) {
    int index = loadPlugin(name, version);
    if (index < 0) {
        // Not found, load it from disk
        void* handle = dlopen(name, RTLD_NOW | RTLD_GLOBAL);
        if (!handle) {
            return NULL;
        }
        PluginInfo info;
        info.name = name;
        info.version = version;
        pluginRefs[numPlugins] = (PluginRef*)mmap(NULL, sizeof(PluginRef), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
        if (!pluginRefs[numPlugins]) {
            dlclose(handle);
            return NULL;
        }
        pluginRefs[numPlugins]->plugin = handle;
        pluginRefs[numPlugins]->refCount = 1;
        plugins[numPlugins] = info;
        numPlugins++;
    } else {
        // Found, increase ref count
        pluginRefs[index]->refCount++;
    }
    return pluginRefs[index];
}

void* getPluginSymbol(const char* name) {
    void* handle = loadPluginDynamicLib(name);
    if (!handle) {
        return NULL;
    }
    return dlsym(handle, name);
}

int releasePlugin(const char* name, const char* version) {
    int index = loadPlugin(name, version);
    if (index < 0) {
        // Not found, ignore
        return -1;
    }
    pluginRefs[index]->refCount--;
    if (pluginRefs[index]->refCount == 0) {
        // Unload the plugin
        dlclose(pluginRefs[index]->handle);
        munmap((void*)pluginRefs[index], sizeof(PluginRef));
        for (int i = index; i < numPlugins - 1; ++i) {
            plugins[i] = plugins[i + 1];
            pluginRefs[i] = pluginRefs[i + 1];
        }
        numPlugins--;
    }
    return 0;
}

void* createPluginInstance(const char* name, const char* version) {
    void* handle = loadPluginDynamicLib(name, version);
    if (!handle) {
        return NULL;
    }
    // Create instance using the "create" function
    void (*createFunction)(void**) = (void(*)())dlsym(handle, "create");
    void* instance = NULL;
    if (createFunction != NULL) {
        createFunction(&instance);
    }
    return instance;
}

int destroyPluginInstance(const char* name, const char* version) {
    int index = loadPlugin(name, version);
    if (index < 0) {
        // Not found, ignore
        return -1;
    }
    // Destroy instance using the "destroy" function
    void (*destroyFunction)(void**) = (void(*)())dlsym(pluginRefs[index]->handle, "destroy");
    if (destroyFunction != NULL) {
        destroyFunction(&instance);
    }
    return releasePlugin(name, version);
}

int addMetric(const char* name, const char* type, void* instance, void* context) {
    // Add the metric to the plugin's metric list
    if (instance == NULL) {
        // Instance not found, ignore
        return -1;
    }
    // Create a new metric entry
    MetricEntry* entry = (MetricEntry*)malloc(sizeof(MetricEntry));
    if (entry == NULL) {
        // Memory allocation failed, ignore
        return -1;
    }
    entry->name = name;
    entry->type = type;
    entry->instance = instance;
    entry->context = context;
    // Add the entry to the plugin's metric list
    if (pluginRefs[index]->metrics == NULL) {
        pluginRefs[index]->metrics = (MetricList*)malloc(sizeof(MetricList));
        pluginRefs[index]->metrics->numEntries = 0;
    }
    pluginRefs[index]->metrics->entries[pluginRefs[index]->metrics->numEntries++] = entry;
    return 0;
}

int removeMetric(const char* name, const char* type) {
    int index = loadPlugin(name, version);
    if (index < 0) {
        // Not found, ignore
        return -1;
    }
    // Remove the metric from the plugin's metric list
    if (pluginRefs[index]->metrics != NULL && pluginRefs[index]->metrics->numEntries > 0) {
        MetricEntry* entries = pluginRefs[index]->metrics->entries;
        int numEntries = pluginRefs[index]->metrics->numEntries;
        for (int i = 0; i < numEntries; ++i) {
            if (strcmp(entries[i].name, name) == 0 && strcmp(entries[i].type, type) == 0) {
                // Found the metric, remove it from the list
                MetricEntry* entry = entries + i;
                pluginRefs[index]->metrics->numEntries--;
                free(entry);
                return 0;
            }
        }
    }
    // Not found, ignore
