package main

import (
	"fmt"
	"log"
	"os"
	"strings"
	"time"
)

// LogManager is a highly reliable and scalable error logging and alerting system
type LogManager struct {
	LogLevel   string    // dynamic log level configuration
	Output     string    // output format for logs (e.g., json, text)
	FilePath   string    // file path for logging (e.g., /var/log/myservice.log)
	External   bool      // enable external alerting system integration
	PagerDuty  string    // PagerDuty integration URL (e.g., https://events.pagerduty.com/integration/abc123)
	Slack      string    // Slack integration URL (e.g., https://hooks.slack.com/services/ABC123)
	RetryDelay time.Duration   // retry delay for failed alerts
}

// NewLogManager creates a new LogManager instance with default configuration
func NewLogManager() *LogManager {
	return &LogManager{
		LogLevel: "info",
		Output: "text",
		FilePath: "/var/log/myservice.log",
		External: false,
		PagerDuty: "",
		Slack: "",
		RetryDelay: time.Second * 30,
	}
}

// Log logs a message with the specified level and args
func (lm *LogManager) Log(level string, args ...interface{}) {
	// filter log messages based on level
	if !strings.HasPrefix(level, "info") {
		return
	}

	// format log message
	var msg string
	switch lm.Output {
	case "text":
		msg = fmt.Sprint(args...)
	case "json":
		msg = fmt.Sprintf("%s", args...)
	default:
		return
	}

	// log message to file and external alerting systems (if configured)
	lm.logToFile(level, msg)
	lm.alert(level, msg)
}

func (lm *LogManager) logToFile(level string, msg string) {
	// open or create log file
	f, err := os.OpenFile(lm.FilePath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0644)
	if err != nil {
		log.Println("failed to open log file:", err)
		return
	}
	defer f.Close()

	// write log message to file
	_, err = fmt.Fprintln(f, msg)
	if err != nil {
		log.Println("failed to write to log file:", err)
		return
	}
}

func (lm *LogManager) alert(level string, msg string) {
	// check if external alerting system is enabled
	if !lm.External {
		return
	}

	// format and send alert to PagerDuty or Slack
	var url string
	switch lm.Output {
	case "text":
		url = fmt.Sprintf("%s?d=%s", lm.PagerDuty, msg)
	case "json":
		url = fmt.Sprintf("%s?d=%s", lm.Slack, url.QueryEscape(msg))
	default:
		return
	}

	// send alert and retry if failed
	resp, err := http.Get(url)
	if err != nil {
		log.Println("failed to send alert:", err)
		time.Sleep(lm.RetryDelay)
		return
	}
	defer resp.Body.Close()

	// check if alert was delivered successfully
	if resp.StatusCode != http.StatusOK {
		log.Println("alert delivery failed:", resp.Status)
	}
}
```']

