class streamDataProcessor {
  private ConcurrentHashMap<String, Object> cache = new ConcurrentHashMap<>();
  private ExecutorService executor = Executors.newFixedThreadPool(10);

  public void processStream(String data) {
    // Parse the data and extract the relevant information
    JSONObject jsonData = new JSONObject(data);
    String symbol = jsonData.getString("symbol");
    double price = jsonData.getDouble("price");
    long timestamp = jsonData.getLong("timestamp");

    // Check if the data is already in the cache, and if not, add it
    Object cachedData = cache.get(symbol);
    if (cachedData == null) {
      cache.put(symbol, new CachedSymbol(price, timestamp));
    } else {
      // Update the cached data with the new price and timestamp
      CachedSymbol cachedSymbol = (CachedSymbol) cachedData;
      cachedSymbol.updatePrice(price);
      cachedSymbol.updateTimestamp(timestamp);
    }

    // Process the data asynchronously
    Future<?> future = executor.submit(() -> {
      // Perform any additional processing or analysis on the data
      System.out.println("Processing data for symbol " + symbol);
      // ...
    });
  }

  public void shutdown() {
    executor.shutdown();
    cache.clear();
  }
}

class CachedSymbol {
  private double price;
  private long timestamp;

  public CachedSymbol(double price, long timestamp) {
    this.price = price;
    this.timestamp = timestamp;
  }

  public void updatePrice(double price) {
    this.price = price;
  }

  public void updateTimestamp(long timestamp) {
    this.timestamp = timestamp;
  }
}
