```csharp
// Configuration Management
using System.Xml;
using System.Json;
using Amazon.S3;
using Microsoft.Azure.Storage.Blobs;

public class ConfigurationManager {
    private const int MAX_RETRY_ATTEMPTS = 5;
    private const string DEFAULT_CONFIG_PATH = "config.xml";

    // Fetch and parse XML and JSON configuration files from multiple cloud services
    public static void InitializeConfiguration(string configPath) {
        if (string.IsNullOrEmpty(configPath)) {
            configPath = DEFAULT_CONFIG_PATH;
        }

        var xmlConfig = new XmlDocument();
        try {
            using (var reader = File.OpenText(configPath)) {
                xmlConfig.Load(reader);
            }
        } catch (Exception e) {
            // Handle exception and retry failed downloads if possible
            if (MaxRetryAttempts > 0) {
                RetryDownloadConfiguration(configPath, MaxRetryAttempts - 1);
            } else {
                throw new Exception("Failed to download configuration file", e);
            }
        }

        var jsonConfig = JsonConvert.DeserializeObject<Configuration>(xmlConfig.InnerText);
        // Apply configuration changes and update version control
    }

    public static void RetryDownloadConfiguration(string configPath, int retryAttempts) {
        try {
            InitializeConfiguration(configPath);
        } catch (Exception e) {
            if (retryAttempts > 0) {
                Thread.Sleep(1000 * Math.Pow(2, retryAttempts)); // Exponential backoff
                RetryDownloadConfiguration(configPath, retryAttempts - 1);
            } else {
                throw new Exception("Failed to download configuration file", e);
            }
        }
    }

    // Version control for configurations
    public class ConfigurationVersionControl {
        private const string CONFIG_HISTORY_PATH = "config-history";

        public static void UpdateConfiguration(string configPath, string newConfig) {
            var historyFile = Path.Combine(CONFIG_HISTORY_PATH, Path.GetFileNameWithoutExtension(configPath) + "-" + DateTime.Now.ToString("yyyy-MM-ddTHH-mm-ss") + ".xml");
            if (!File.Exists(historyFile)) {
                File.Move(configPath, historyFile);
            } else {
                var oldConfig = File.ReadAllText(historyFile);
                if (newConfig != oldConfig) {
                    File.WriteAllText(historyFile, newConfig);
                }
            }
        }

        public static void RestoreConfiguration(string configPath) {
            var historyFiles = Directory.EnumerateFiles(CONFIG_HISTORY_PATH).Where(f => f.StartsWith(configPath)).OrderByDescending(f => f).Take(1);
            if (historyFiles.Any()) {
                var historyFile = historyFiles.First();
                File.Move(historyFile, configPath);
            }
        }
    }
}

// Grid Initialization and Dynamic Resizing
using System.Linq;

public class GameWorld {
    private const int TILE_SIZE = 128;
    private readonly List<Tile> _tiles = new List<Tile>();

    public void InitializeGrid(int width, int height) {
        for (int x = 0; x < width; x++) {
            for (int y = 0; y < height; y++) {
                var tile = new Tile(x, y);
                _tiles.Add(tile);
            }
        }
    }

    public void DynamicResizeGrid(int width, int height) {
        // Remove tiles that are no longer needed
        var toRemove = _tiles.Where(t => !IsTileVisible(t.X, t.Y, width, height)).ToList();
        foreach (var tile in toRemove) {
            _tiles.Remove(tile);
        }

        // Add new tiles if needed
        for (int x = 0; x < width; x++) {
            for (int y = 0; y < height; y++) {
                var tile = GetTileAt(x, y);
                if (tile == null) {
                    tile = new Tile(x, y);
                    _tiles.Add(tile);
                }
            }
        }
    }

    public bool IsTileVisible(int x, int y, int width, int height) {
        return x >= 0 && x < width && y >= 0 && y < height;
    }

    public Tile GetTileAt(int x, int y) {
        return _tiles.FirstOrDefault(t => t.X == x && t.Y == y);
    }
}

