using System.Numerics;
using UnityEngine;

public class CameraController : MonoBehaviour {
    private const float DEFAULT_ZOOM = 10f;
    private const float MIN_ZOOM = 5f;
    private const float MAX_ZOOM = 20f;
    private const float MOUSE_SENSITIVITY = 3f;
    private const float CAMERA_POSITION_OFFSET = 1.5f;
    private const float FOCUS_DISTANCE = 10f;
    private const float ROLLING_SPEED = 1f;
    private const float MAX_FIELD_OF_VIEW = 90f;
    private const float MIN_FIELD_OF_VIEW = 30f;
    private const float FOCUS_DISTANCE_THRESHOLD = 1.5f;

    public Transform Target { get; set; }

    private Vector3 _initialPosition;
    private Quaternion _initialRotation;
    private float _zoom = DEFAULT_ZOOM;
    private float _lastX;
    private float _lastY;
    private float _focusDistance;

    void Start() {
        _initialPosition = transform.position;
        _initialRotation = transform.rotation;
    }

    void LateUpdate() {
        // Update zoom
        if (_zoom < MIN_ZOOM) {
            _zoom = MIN_ZOOM;
        } else if (_zoom > MAX_ZOOM) {
            _zoom = MAX_ZOOM;
        }

        // Update focus distance
        var delta = Target.position - transform.position;
        _focusDistance = Mathf.Clamp(delta.magnitude, FOCUS_DISTANCE, FOCUS_DISTANCE + FOCUS_DISTANCE_THRESHOLD);

        // Update camera position and rotation
        var newPosition = Target.position - _focusDistance * transform.forward;
        var newRotation = Quaternion.LookRotation(Target.position - newPosition, Vector3.up);
        transform.rotation = newRotation;
        transform.position = newPosition;

        // Update camera position offset
        if (Input.GetKeyDown("space")) {
            _lastX = Input.mousePosition.x;
            _lastY = Input.mousePosition.y;
        } else if (Input.GetMouseButton(0) && Input.GetKey(KeyCode.LeftShift)) {
            var offsetX = Input.mousePosition.x - _lastX;
            var offsetY = Input.mousePosition.y - _lastY;
            transform.position += new Vector3(-offsetX, -offsetY, 0) * CAMERA_POSITION_OFFSET * Time.deltaTime;
            _lastX = Input.mousePosition.x;
            _lastY = Input.mousePosition.y;
        }
    }
}
