#include <sys/stat.h>

// Record structure with key, offset, and additional metadata
struct record {
    int key;
    long offset;
    char* metadata;
};

// Initialize records with random values within specified ranges
void initialize_records(int num_records, int min_key, int max_key, long min_offset, long max_offset, const char* metadata) {
    // Allocate and initialize memory for the record structures and supporting data arrays
    struct record** records = (struct record**)malloc(sizeof(struct record*) * num_records);
    for (int i = 0; i < num_records; i++) {
        records[i] = (struct record*)malloc(sizeof(struct record));
        records[i]->key = min_key + rand() % (max_key - min_key + 1);
        records[i]->offset = min_offset + rand() % (max_offset - min_offset + 1);
        records[i]->metadata = strdup(metadata);
    }

    // Persist the initialized records to a file system using JSON format
    char* filename = "records.json";
    FILE* fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Error: unable to open file %s for writing\n", filename);
        return;
    }
    for (int i = 0; i < num_records; i++) {
        fprintf(fp, "{\"key\":%d, \"offset\":%ld, \"metadata\":\"%s\"}\n", records[i]->key, records[i]->offset, records[i]->metadata);
    }
    fclose(fp);

    // Log initialization statistics and errors
    printf("Initialized %d records with keys between %d and %d, offsets between %ld and %ld, and metadata of length %d\n", num_records, min_key, max_key, min_offset, max_offset, strlen(metadata));
}
```
