use std::sync::Arc;
use std::thread;
use std::time::Duration;

struct DataProcessingPipeline {
    sources: Vec<DataSource>,
    workers: Vec<Worker>,
    cache: Arc<Cache>,
}

impl DataProcessingPipeline {
    fn new(sources: &[&str], workers: usize) -> Self {
        let mut pipeline = Self {
            sources: vec![],
            workers: vec![],
            cache: Arc::new(Cache::default()),
        };

        for source in sources.iter() {
            pipeline.sources.push(DataSource::new(source));
        }

        for _ in 0..workers {
            let cache = pipeline.cache.clone();
            let worker = Worker::new(cache);
            pipeline.workers.push(worker);
        }

        pipeline
    }

    fn run(&mut self) {
        for source in &self.sources {
            // Spawn a thread to process the data from each source
            let cache = self.cache.clone();
            thread::spawn(move || {
                loop {
                    // Fetch data from the source
                    let data = source.fetch_data()?;

                    // Validate and transform the data
                    let transformed_data = cache.validate_and_transform(&data);

                    // Store the transformed data in the cache
                    cache.store(transformed_data)?;
                }
            });
        }

        for worker in &self.workers {
            // Spawn a thread to process the data from each worker
            let cache = self.cache.clone();
            thread::spawn(move || loop {
                // Fetch data from the cache
                let data = cache.fetch_data()?;

                // Process the data
                worker.process(&data);

                // Store the processed data in the cache
                cache.store(&data)?;
            });
        }
    }
}

