using System;
using System.Collections.Generic;
using System.Linq;
using System.Web;
using Microsoft.AspNetCore.Mvc;
using OAuth2.Client;
using ThirdParty.BiometricAuthentication;

namespace MyFinancialInstitution.WebApplication
{
    public class AuthController : Controller
    {
        [HttpPost]
        public async Task<IActionResult> Login(string username, string password)
        {
            var user = await UserService.AuthenticateUserAsync(username, password);
            if (user == null)
                return Unauthorized();

            await Request.GetOwinContext().Authentication.SignInAsync(
                new AuthenticationProperties()
                {
                    IsPersistent = true,
                    AllowRefresh = true,
                    ExpiresUtc = DateTimeOffset.UtcNow.AddMinutes(30)
                },
                new ClaimsIdentity(new[] { new Claim("username", username), new Claim("role", user.Role) }, "MyFinancialInstitutionAuth")
            );

            return RedirectToAction("Index", "Home");
        }
    }

    public class HomeController : Controller
    {
        private readonly UserService _userService;

        public HomeController(UserService userService)
        {
            _userService = userService;
        }

        [HttpGet]
        public IActionResult Index()
        {
            var username = User.FindFirstValue("username");
            var role = User.FindFirstValue("role");

            if (string.IsNullOrEmpty(username))
                return Unauthorized();

            ViewBag.Username = username;
            ViewBag.Role = role;

            return View();
        }
    }
}
