      this.setState({ employees: response.data });
    } catch (error) {
      console.log(error);
    }
  }

  // Filter employee data based on search filters and update the state with the results
  async filterEmployees(searchFilter) {
    try {
      const employees = await this.state.employees;
      const filteredEmployees = employees.filter((employee) => {
        return (
          employee.supervisorId === searchFilter.supervisorId &&
          employee.department === searchFilter.department &&
          employee.jobTitle === searchFilter.jobTitle
        );
      });
      this.setState({ employees: filteredEmployees });
    } catch (error) {
      console.log(error);
    }
  }

  // Export employee data to a CSV file and download it
  async exportToCsv() {
    try {
      const response = await fileStorageClient.post('export', { params: FILE_STORAGE_PARAMS });
      const blob = new Blob([response.data], { type: 'text/csv' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `employees_${new Date().toISOString()}.csv`;
      document.body.appendChild(a);
      a.click();
    } catch (error) {
      console.log(error);
    }
  }

