import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

class DataCenterManager {
  private static final int MAX_CONNECTIONS = 10000;
  private List<DataCenter> dataCenters = new ArrayList<>();
  private Lock connectionsLock = new ReentrantLock();

  public void addDataCenter(String hostname, int port) {
    // Acquire the lock to prevent concurrent modifications
    connectionsLock.lock();

    try {
      DataCenter dataCenter = new DataCenter(hostname, port);
      dataCenters.add(dataCenter);

      // Update the synchronization policies for all existing data centers
      for (DataCenter existingDataCenter : dataCenters) {
        existingDataCenter.updateSynchronizationPolicies();
      }
    } finally {
      connectionsLock.unlock();
    }
  }

  public void removeDataCenter(String hostname, int port) {
    // Acquire the lock to prevent concurrent modifications
    connectionsLock.lock();

    try {
      DataCenter dataCenter = findDataCenter(hostname, port);
      if (dataCenter == null) {
        return;
      }

      dataCenters.remove(dataCenter);

      // Update the synchronization policies for all existing data centers
      for (DataCenter existingDataCenter : dataCenters) {
        existingDataCenter.updateSynchronizationPolicies();
      }
    } finally {
      connectionsLock.unlock();
    }
  }

  private DataCenter findDataCenter(String hostname, int port) {
    for (DataCenter dataCenter : dataCenters) {
      if (dataCenter.getHostname().equals(hostname) && dataCenter.getPort() == port) {
        return dataCenter;
      }
    }

    return null;
  }
}

class DataSynchronizer {
  private static final int MAX_CONNECTIONS = 10000;
  private List<DataCenter> dataCenters = new ArrayList<>();
  private Lock connectionsLock = new ReentrantLock();

  public void synchronize(String hostname, int port) {
    // Acquire the lock to prevent concurrent modifications
    connectionsLock.lock();

    try {
      DataCenter dataCenter = findDataCenter(hostname, port);
      if (dataCenter == null) {
        return;
      }

      // Synchronize with the remote data center
      for (DataCenter existingDataCenter : dataCenters) {
        if (!existingDataCenter.equals(dataCenter)) {
          synchronizeWith(dataCenter, existingDataCenter);
        }
      }
    } finally {
      connectionsLock.unlock();
    }
  }

  private void synchronizeWith(DataCenter dataCenter1, DataCenter dataCenter2) {
    // Implement the logic for synchronizing with a remote data center
  }

  private DataCenter findDataCenter(String hostname, int port) {
    for (DataCenter dataCenter : dataCenters) {
      if (dataCenter.getHostname().equals(hostname) && dataCenter.getPort() == port) {
        return dataCenter;
      }
    }

    return null;
  }
}

class DataMonitor {
  private static final int MAX_CONNECTIONS = 10000;
  private List<DataCenter> dataCenters = new ArrayList<>();
  private Lock connectionsLock = new ReentrantLock();

  public void monitor() {
    // Acquire the lock to prevent concurrent modifications
    connectionsLock.lock();

    try {
      for (DataCenter dataCenter : dataCenters) {
        monitorDataCenter(dataCenter);
      }
    } finally {
      connectionsLock.unlock();
    }
  }

  private void monitorDataCenter(DataCenter dataCenter) {
