import org.apache.kafka.streams.kstream.KStreamBuilder;
import org.apache.kafka.streams.kstream.Predicate;
import org.apache.kafka.streams.kstream.Transformer;
import org.apache.kafka.streams.kstream.ValueMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.util.Map;
import java.util.Properties;
import java.util.concurrent.TimeUnit;

public class RealTimeDataProcessor {
    private static final Logger logger = LoggerFactory.getLogger(RealTimeDataProcessor.class);

    public static void main(String[] args) throws Exception {
        Properties props = new Properties();
        // Kafka consumer properties
        props.put("bootstrap.servers", "localhost:9092");
        props.put("group.id", "my-consumer-group");
        props.put("key.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        props.put("value.deserializer", "org.apache.kafka.common.serialization.StringDeserializer");
        // Kafka producer properties
        props.put("bootstrap.servers", "localhost:9092");
        props.put("key.serializer", "org.apache.kafka.common.serialization.StringSerializer");
        props.put("value.serializer", "org.apache.kafka.common.serialization.StringSerializer");

        KafkaStreams streams = new KafkaStreams(createTopology(), props);
        streams.start();

        Runtime.getRuntime().addShutdownHook(new Thread(streams::close));
    }

    private static KStreamBuilder createTopology() {
        KStreamBuilder builder = new KStreamBuilder();

        // Define a stream of incoming data from Kafka topic "my-input-topic"
        KStream<String, String> inputStream = builder.stream("my-input-topic");

        // Filter out messages that do not contain the word "alert"
        Predicate<String, String> filterPredicate = (key, value) -> value.contains("alert");
        KStream<String, String> filteredStream = inputStream.filter(filterPredicate);

        // Transform the data to add a new field with the current timestamp
        ValueMapper<String, String> timestampMapper = (value) -> {
            Map<String, Object> jsonObj = (Map<String, Object>) JSONValue.parseWithException(value);
            jsonObj.put("timestamp", System.currentTimeMillis());
            return JSONValue.toJSONString(jsonObj);
        };
        KStream<String, String> transformedStream = filteredStream.transformValues(timestampMapper);

        // Send the transformed data to a new Kafka topic "my-output-topic"
        ProducerRecord<String, String> outputRecord = new ProducerRecord<>("my-output-topic", transformedStream);
        KStream<String, String> outputStream = builder.stream(outputRecord);

        // Define a custom load balancing algorithm that dynamically adjusts based on observed latency and error rates
        LoadBalancer loadBalancer = new LoadBalancer();
        outputStream.foreach((key, value) -> {
            Map<String, Object> jsonObj = (Map<String, Object>) JSONValue.parseWithException(value);
            String serviceName = (String) jsonObj.get("service");
            loadBalancer.selectService(serviceName).sendMessage(jsonObj);
        });

        return builder;
    }
}
