<?php

namespace SecurityKit;

use Symfony\Component\HttpFoundation\Request;

class SecurityKit {
    /**
     * Generates a cryptographically secure random token.
     *
     * @param int $length The length of the token to generate
     * @return string The generated token
     */
    public static function generateToken(int $length = 32): string
    {
        return bin2hex(random_bytes($length));
    }

    /**
     * Validates an email address using the RFC 5322 standard.
     *
     * @param string $email The email address to validate
     * @return bool True if the email is valid, false otherwise
     */
    public static function validateEmail(string $email): bool
    {
        return preg_match("/^([a-z0-9]+)(\.[a-z0-9]+)*@[a-z0-9-.]+(\.[a-z]{2,})$/i", $email);
    }

    /**
     * Hashes a password using the Bcrypt algorithm with a configurable cost factor.
     *
     * @param string $password The password to hash
     * @param int $costFactor The cost factor for the Bcrypt algorithm
     * @return string The hashed password
     */
    public static function hashPassword(string $password, int $costFactor = 10): string
    {
        return password_hash($password, PASSWORD_BCRYPT, ['cost' => $costFactor]);
    }

    /**
     * Verifies a password against a stored hash.
     *
     * @param string $password The plaintext password to verify
     * @param string $hash The hashed password to compare with
     * @return bool True if the password matches, false otherwise
     */
    public static function verifyPassword(string $password, string $hash): bool
    {
        return password_verify($password, $hash);
    }

    /**
     * Generates a cryptographically secure random token using the OpenSSL library.
     *
     * @param int $length The length of the token to generate
     * @return string The generated token
     */
    public static function generateOpenSSLToken(int $length = 32): string
    {
        return openssl_random_pseudo_bytes($length);
    }

    /**
     * Generates a cryptographically secure random IV using the OpenSSL library.
     *
     * @param int $length The length of the IV to generate
     * @return string The generated IV
     */
    public static function generateOpenSSLIV(int $length = 16): string
    {
        return openssl_random_pseudo_bytes($length);
    }
}
