using namespace std;

// Forward declarations for helper functions
void monitorTenant(const string& tenantName, const vector<string>& resourceNames);
void adjustResourceAllocation(const unordered_map<string, int>& resourceUtilizationMap);
bool isServiceDisrupted();

class NetworkResourceManager {
public:
    // Constructor and destructor
    NetworkResourceManager() {}
    ~NetworkResourceManager() {}

    // Add a new tenant to the system
    void addTenant(const string& tenantName, const vector<string>& resourceNames) {
        // Check if the tenant already exists in the system
        if (tenants_.find(tenantName) != tenants_.end()) {
            throw runtime_error("Tenant already exists");
        }

        // Add a new entry for the tenant to the map
        tenants_[tenantName] = resourceNames;

        // Monitor the tenant's resources
        monitorTenant(tenantName, resourceNames);
    }

    // Remove a tenant from the system
    void removeTenant(const string& tenantName) {
        // Check if the tenant exists in the system
        auto it = tenants_.find(tenantName);
        if (it == tenants_.end()) {
            throw runtime_error("Tenant not found");
        }

        // Remove the entry for the tenant from the map
        tenants_.erase(it);
    }

    // Update the resources assigned to a tenant
    void updateTenantResources(const string& tenantName, const vector<string>& resourceNames) {
        // Check if the tenant exists in the system
        auto it = tenants_.find(tenantName);
        if (it == tenants_.end()) {
            throw runtime_error("Tenant not found");
        }

        // Update the resources for the tenant
        it->second = resourceNames;
    }

    // Get the utilization of a resource for all tenants
    unordered_map<string, int> getResourceUtilization(const string& resourceName) {
        unordered_map<string, int> utilizationMap;

        // Loop through each tenant and calculate the utilization of the resource
        for (auto it = tenants_.begin(); it != tenants_.end(); ++it) {
            const auto& resources = it->second;
            for (const auto& resource : resources) {
                if (resource == resourceName) {
                    utilizationMap[it->first] += 1;
                    break;
                }
            }
        }

        return utilizationMap;
    }

private:
    // Map of tenants and their assigned resources
    unordered_map<string, vector<string>> tenants_;
};

void monitorTenant(const string& tenantName, const vector<string>& resourceNames) {
    while (true) {
        // Check if the service is disrupted
        if (isServiceDisrupted()) {
            cout << "Service disruption detected. Pausing monitoring." << endl;
            sleep(10);  // Sleep for 10 seconds before continuing
        } else {
            // Calculate the utilization of each resource for the tenant
            unordered_map<string, int> utilizationMap = getResourceUtilization(resourceNames);

            // Check if any resources exceed their SLAs
            bool slaViolated = false;
            for (const auto& entry : utilizationMap) {
                if (entry.second > 90) {  // 90% SLA for each resource
                    cout << "SLA violation detected for tenant: " << tenantName << endl;
                    slaViolated = true;
                    break;
                }
            }

            // If the SLA is not violated, adjust the allocation of resources
            if (!slaViolated) {
                adjustResourceAllocation(utilizationMap);
            }
        }

        // Sleep for 1 second before continuing monitoring
        sleep(1);
    }
}

void adjustResourceAllocation(const unordered_map<string, int>& resourceUtilizationMap) {
    // Implement algorithm to adjust resource allocation based on utilization map
}

bool isServiceDisrupted() {
    // Check if the service is disrupted by performing checks against external APIs and services
    return false;  // Return true if disrupted, else return false
}
