package com.filemanagement;

import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;
import com.filemanagement.models.File;
import com.filemanagement.services.FileService;
import com.filemanagement.utils.PollingStrategy;
import com.filemanagement.utils.StoragePolicy;
import com.google.gson.JsonObject;

@RestController
public class FileManagementController {
    @Autowired
    private FileService fileService;

    @GetMapping("/files/{fileId}")
    public ResponseEntity<File> getFile(@PathVariable("fileId") String fileId) {
        return new ResponseEntity<>(fileService.getFile(fileId), HttpStatus.OK);
    }

    @PostMapping("/files")
    public ResponseEntity<Void> createFile(@RequestBody File file) {
        try {
            fileService.createFile(file);
            return new ResponseEntity<>(HttpStatus.CREATED);
        } catch (Exception e) {
            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
        }
    }

    @GetMapping("/files")
    public ResponseEntity<List<File>> getFiles() {
        return new ResponseEntity<>(fileService.getFiles(), HttpStatus.OK);
    }

    // Polling strategy for checking file status
    private ScheduledExecutorService pollingExecutor = Executors.newScheduledThreadPool(10);
    private static final int POLLING_INTERVAL = 30; // seconds

    @PostMapping("/files/{fileId}/polling")
    public ResponseEntity<JsonObject> pollFileStatus(@PathVariable("fileId") String fileId) {
        JsonObject response = new JsonObject();
        File file = fileService.getFile(fileId);
        if (file == null || !StoragePolicy.isAvailable(file.getStorage())) {
            response.addProperty("status", "NOT_FOUND");
            return new ResponseEntity<>(response, HttpStatus.OK);
        } else {
            PollingStrategy pollingStrategy = new PollingStrategy(POLLING_INTERVAL, fileId);
            pollingExecutor.scheduleAtFixedRate(pollingStrategy, 0, POLLING_INTERVAL, TimeUnit.SECONDS);
            response.addProperty("status", "OK");
            return new ResponseEntity<>(response, HttpStatus.OK);
        }
    }
}
