    _cache.Set("config-data", deserializedData, new MemoryCacheEntryOptions
    {
        Size = 1024 * 1024 // Set cache size limit
    });

    return deserializedData;
}

// Integration and Reliability
public static async Task<T> LoadAndDeserializeConfigurationDataAsync<T>(string version)
{
    try
    {
        var data = await LoadConfigurationDataAsync();
        if (!data.Any())
        {
            return default(T);
        }

        // Deserialize configuration data and cache it in memory
        var deserializedData = Deserialize<T>(data);
        _cache.Set("config-data", deserializedData, new MemoryCacheEntryOptions
        {
            Size = 1024 * 1024 // Set cache size limit
        });

        return deserializedData;
    }
    catch (Exception ex)
    {
        _logger.LogError(ex, "Failed to load configuration data");
        throw new Exception("Failed to load configuration data", ex);
    }
}
