import os
import json
import requests
from ratelimit import RateLimit
from alerting_service import AlertService

class MonitoringClient(object):
    def __init__(self, environment_vars, secrets_manager):
        self.environment_vars = environment_vars
        self.secrets_manager = secrets_manager
        self.api_url = "https://cloud-monitoring.com/api"
        self.rate_limit = RateLimit(10, 5) # 10 requests per 5 seconds
        self.alert_service = AlertService()

    def get_metrics(self):
        try:
            url = f"{self.api_url}/metrics?app={os.environ['APP_NAME']}"
            headers = {
                "Authorization": f"Bearer {self.secrets_manager.get('API_TOKEN')}",
                "Content-Type": "application/json"
            }
            response = requests.get(url, headers=headers)
            if response.status_code == 200:
                return json.loads(response.content)
            else:
                raise Exception("Error fetching metrics")
        except Exception as e:
            self.alert_service.send_alert("Error fetching metrics", str(e))
            raise e

    def report_metrics(self, metrics):
        try:
            url = f"{self.api_url}/metrics?app={os.environ['APP_NAME']}"
            headers = {
                "Authorization": f"Bearer {self.secrets_manager.get('API_TOKEN')}",
                "Content-Type": "application/json"
            }
            response = requests.post(url, json=metrics, headers=headers)
            if response.status_code == 201:
                return response.content
            else:
                raise Exception("Error reporting metrics")
        except Exception as e:
            self.alert_service.send_alert("Error reporting metrics", str(e))
            raise e

    def get_alerts(self):
        try:
            url = f"{self.api_url}/alerts?app={os.environ['APP_NAME']}"
            headers = {
                "Authorization": f"Bearer {self.secrets_manager.get('API_TOKEN')}",
                "Content-Type": "application/json"
            }
            response = requests.get(url, headers=headers)
            if response.status_code == 200:
                return json.loads(response.content)
            else:
                raise Exception("Error fetching alerts")
        except Exception as e:
            self.alert_service.send_alert("Error fetching alerts", str(e))
            raise e

    def report_alert(self, alert):
        try:
            url = f"{self.api_url}/alerts?app={os.environ['APP_NAME']}"
            headers = {
                "Authorization": f"Bearer {self.secrets_manager.get('API_TOKEN')}",
                "Content-Type": "application/json"
            }
            response = requests.post(url, json=alert, headers=headers)
            if response.status_code == 201:
                return response.content
            else:
                raise Exception("Error reporting alert")
        except Exception as e:
            self.alert_service.send_alert("Error reporting alert", str(e))
            raise e
```
