```
To ensure that the buffer's operations are idempotent and that any partial updates are handled gracefully, the `Buffer` class can be modified to use an `std::atomic<size_t>` for the size and capacity of the buffer, and to use a `std::condition_variable` to signal when new items are available in the buffer.
```c++
#include <iostream>
#include <thread>

class Buffer {
 public:
  // Constructor.
  Buffer(size_t initial_size) : size_(initial_size), capacity_(initial_size * 2) {}

  // Adds an item to the buffer. Returns true if successful, false otherwise.
  bool add(int item) {
    std::unique_lock<std::mutex> lock(mutex_);
    if (full()) {
      // Dynamic resizing: double the buffer size if it's full.
      resize();
    }
    items_.push(item);
    return true;
  }

  // Removes an item from the buffer. Returns true if successful, false otherwise.
  bool remove(int& item) {
    std::unique_lock<std::mutex> lock(mutex_);
    if (empty()) {
      return false;
    }
    item = items_.front();
    items_.pop();
    return true;
  }

 private:
  // Resize the buffer.
  void resize() {
    std::unique_lock<std::mutex> lock(mutex_);
    size_ *= 2;
    capacity_ = size_;
    items_.resize(size_);
  }

  // Returns true if the buffer is full, false otherwise.
  bool full() { return size_ == capacity_; }

  // Returns true if the buffer is empty, false otherwise.
  bool empty() { return size_ == 0; }

  // The current size of the buffer.
  std::atomic<size_t> size_;

  // The maximum size of the buffer.
  const size_t capacity_;

  // The queue of items in the buffer.
  std::queue<int> items_;

  // The mutex for synchronizing access to the buffer.
  std::mutex mutex_;

  // The condition variable for signaling when new items are available in the buffer.
  std::condition_variable condVar_;
};

class MessageHandler {
 public:
  // Constructor.
  MessageHandler(Buffer& buffer) : buffer_(buffer), thread_(&MessageHandler::handleMessages, this) {}

  ~MessageHandler() {
    stop();
  }

  void start() {
    thread_.join();
  }

  void stop() {
    if (thread_.joinable()) {
      thread_.detach();
    }
  }

 private:
  void handleMessages() {
    while (true) {
      // Receive a message from the messaging queue service.
      int item;
      bool received = receiveMessage(item);
      if (!received) {
        break;
      }

      // Add the item to the buffer.
      buffer_.add(item);
    }
  }

  bool receiveMessage(int& item) {
    std::unique_lock<std::mutex> lock(buffer_.mutex_);
    if (buffer_.empty()) {
      return false;
    }
    item = buffer_.items_.front();
    buffer_.items_.pop();
    // Signal that a new item is available in the buffer.
    buffer_.condVar_.notify_one();
    return true;
  }

  Buffer& buffer_;
  std::thread thread_;
};
```
This approach ensures that the buffer's operations are idempotent and that any partial updates are handled gracefully, while also providing a way to handle potential delays and failures by using a timeout for message reception and retrying on failure."]

