            this.id = id;
            this.name = name;
            this.x = x;
            this.y = y;
        }

        // Function to get the entity's ID
        public string GetId()
        {
            return id;
        }

        // Function to get the entity's name
        public string GetName()
        {
            return name;
        }

        // Function to get the entity's position
        public (int, int) GetPosition()
        {
            return (x, y);
        }
    }

