    {
        private World world;
        private WorldDimensions dimensions;
        private SpecialEntitiesManager entitiesManager;
        private UserInteractionsManager usersManager;
        private ApiManager apiManager;

        // Constructor for initializing the game manager's dependencies
        public GameManager(World world, WorldDimensions dimensions, SpecialEntitiesManager entitiesManager, UserInteractionsManager usersManager, ApiManager apiManager)
        {
            this.world = world;
            this.dimensions = dimensions;
            this.entitiesManager = entitiesManager;
            this.usersManager = usersManager;
            this.apiManager = apiManager;
        }

        // Function to fetch tile data from the API and update the game state
        public async Task UpdateStateAsync()
        {
            var tiles = await apiManager.GetTilesAsync();
            if (tiles != null)
            {
                world.UpdateTiles(tiles);
            }
        }
    }
}
