    char *command;
    pid_t pid;
    int status;
    bool running;
};

// Command queue
struct command_queue {
    struct command commands[MAX_CONCURRENT];
    size_t count;
};

// Initialize the signal handler struct
static void init_signal_handler(struct signal_handler *handler) {
    handler->signal = 0;
    handler->handler = NULL;
}

// Set a custom environment variable for each command execution
static int set_env_var(char *command) {
    char *env_var = "MY_ENV_VAR";
    size_t env_var_len = strlen(env_var);
    size_t command_len = strlen(command);
    char *new_command = (char *)malloc((env_var_len + command_len + 3) * sizeof(char));
    snprintf(new_command, env_var_len + command_len + 3, "%s=%s %s", env_var, MY_ENV_VAR, command);
    return new_command;
}

// Fork and execute a shell command
static pid_t fork_exec(char *command) {
    // Set the custom environment variable for this command
    char *env_var = set_env_var(command);

    // Fork a child process to execute the command
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork");
        return -1;
    } else if (pid == 0) {
        // Execute the shell command in the forked child process
        execl("/bin/sh", "sh", "-c", env_var, NULL);
        exit(EXIT_FAILURE);
    }

    return pid;
}

// Wait for a child process to finish and update its status
static int waitpid_update_status(pid_t pid) {
    int status = -1;
    if (waitpid(pid, &status, 0) < 0) {
        perror("waitpid");
        return -1;
    }
    return status;
}

// Handle a SIGINT signal by canceling the current command execution
static void handle_sigint(int signal) {
    // Cancel the current command execution
    struct command *current_command = &backgroundExecutor->commands[backgroundExecutor->count - 1];
    if (current_command->running) {
        kill(current_command->pid, SIGINT);
        current_command->status = -1;
        current_command->running = false;
    }
}

// Handle a SIGTERM signal by terminating the entire command execution queue
static void handle_sigterm(int signal) {
    // Terminate all running commands and flush any partially written logs or files
    for (size_t i = 0; i < backgroundExecutor->count; i++) {
        struct command *command = &backgroundExecutor->commands[i];
        if (command->running) {
            kill(command->pid, SIGTERM);
            command->status = -1;
            command->running = false;
        }
    }
}

// Handle a SIGQUIT signal by terminating the entire command execution queue and flushing any partially written logs or files
static void handle_sigquit(int signal) {
    // Terminate all running commands, flush any partially written logs or files, and exit the process
    for (size_t i = 0; i < backgroundExecutor->count; i++) {
        struct command *command = &backgroundExecutor->commands[i];
        if (command->running) {
            kill(command->pid, SIGQUIT);
            command->status = -1;
            command->running = false;
        }
    }
}

// Add a new command to the execution queue
static int add_command(char *command) {
    // Check if the queue is full
    if (backgroundExecutor->count >= MAX_CONCURRENT) {
        return -1;
    }

    // Fork and execute the shell command in a child process
    pid_t pid = fork_exec(command);
    if (pid < 0) {
        return -1;
    }

    // Update the status of the new command
    struct command *new_command = &backgroundExecutor->commands[backgroundExecutor->count];
    new_command->command = command;
    new_command->pid = pid;
    new_command->status = -1;
    new_command->running = true;
    backgroundExecutor->count++;

    return 0;
}

// Remove a finished command from the execution queue
static int remove_finished_command() {
    // Check if there are any finished commands to remove
    for (size_t i = 0; i < backgroundExecutor->count; i++) {
        struct command *command = &backgroundExecutor->commands[i];
        if (!command->running) {
            // Update the status of the removed command
            int status = waitpid_update_status(command->pid);
            if (status < 0) {
                return -1;
            }

            // Remove the finished command from the queue
            memmove(&backgroundExecutor->commands[i], &backgroundExecutor->commands[i + 1], sizeof(struct command) * (backgroundExecutor->count - i));
            backgroundExecutor->count--;
            return 0;
        }
    }

    // No finished commands found, nothing to remove
    return 0;
}

// Gracefully terminate the entire command execution queue
static int terminate_all() {
    // Terminate all running commands, flush any partially written logs or files, and exit the process
    for (size_t i = 0; i < backgroundExecutor->count; i++) {
        struct command *command = &backgroundExecutor->commands[i];
        if (command->running) {
            kill(command->pid, SIGTERM);
            command->status = -1;
            command->running = false;
        }
    }
}

// The main function for the backgroundExecutor utility
int main() {
    // Initialize the backgroundExecutor struct and set up signal handlers
    backgroundExecutor = calloc(1, sizeof(struct backgroundExecutor));
    if (!backgroundExecutor) {
        fprintf(stderr, "Error: failed to allocate memory for the backgroundExecutor struct\n");
        return -1;
    }

    // Add a SIGINT signal handler
    struct sigaction sa_int = { .sa_handler = handle_sigint };
    if (sigaction(SIGINT, &sa_int, NULL) < 0) {
        fprintf(stderr, "Error: failed to set up the SIGINT signal handler\n");
        return -1;
    }

    // Add a SIGTERM signal handler
    struct sigaction sa_term = { .sa_handler = handle_sigterm };
    if (sigaction(SIGTERM, &sa_term, NULL) < 0) {
        fprintf(stderr, "Error: failed to set up the SIGTERM signal handler\n");
        return -1;
    }

    // Add a SIGQUIT signal handler
    struct sigaction sa_quit = { .sa_handler = handle_sigquit };
    if (sigaction(SIGQUIT, &sa_quit, NULL) < 0) {
        fprintf(stderr, "Error: failed to set up the SIGQUIT signal handler\n");
        return -1;
    }

    // Run the main loop until a signal is received or an error occurs
    while (1) {
        // Check if there are any finished commands to remove
        remove_finished_command();

        // Add new commands to the execution queue as necessary
        add_command("New command");

        // Check for any pending signals and handle them accordingly
        pause();
    }

    return 0;
}
```

This program uses a `struct backgroundExecutor` to keep track of the current status of each command in the execution queue. The main loop constantly checks if there are any finished commands to remove, adds new commands as necessary, and handles any pending signals that may have been received. If an error occurs during the execution of a command, it is immediately terminated.

Here are some tips for using this program:

* You can add new commands by providing the `add_command()` function with a string representing the command to execute. For example, you could call `add_command("ls -l")` to execute the `ls` command with the `-l` option.
* You can remove finished commands from the execution queue by using the `remove_finished_command()` function.
* If you want to terminate all running commands and exit the process, you can use the `terminate_all()` function.
* The program uses a `pause()` system call to handle any pending signals that may have been received while it was waiting for a command to finish or adding new commands. This means that if you press Ctrl+C (or send the SIGINT signal) while the program is running, it will immediately cancel all currently executing commands and exit the process.
* If you want to gracefully terminate all running commands and flush any partially written logs or files, you can use the `terminate_all()` function followed by a system call such as `exit(0)`.

This program provides a simple way to execute multiple shell commands in parallel while handling signals and error conditions. You can use it to run a series of long-running commands that may take several minutes or even hours to complete, while still being able to terminate the process quickly if necessary.']

