public class RealTimeDataIngestion {
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final List<NFAPI_CRC_INDICATION_PDU_T> crcIndications = new LinkedBlockingQueue<>();
    private final AtomicInteger sequenceNumber = new AtomicInteger(0);

    public void ingestData(List<RX_UE_INFORMATION_TAG> rxUeInformationTags) {
        for (RX_UE_INFORMATION_TAG tag : rxUeInformationTags) {
            executor.submit(() -> handleCrcIndication(tag));
        }
    }

    private void handleCrcIndication(RX_UE_INFORMATION_TAG tag) {
        NFAPI_CRC_INDICATION_PDU_T crcIndication = new NFAPI_CRC_INDICATION_PDU_T();
        crcIndication.setRxUeInformationTag(tag);
        crcIndication.setCrcIndicationRel8Tag(new CRC_INDICATION_REL8_TAG());
        if (sequenceNumber.getAndIncrement() % 2 == 0) {
            crcIndication.getCrcIndicationRel8Tag().setCrcFlag(true);
        } else {
            crcIndication.getCrcIndicationRel8Tag().setCrcFlag(false);
        }
        crcIndications.add(crcIndication);
    }

    public void startProcessing() {
        executor.submit(() -> processCrcIndications());
    }

    private void processCrcIndications() {
        while (!crcIndications.isEmpty()) {
            NFAPI_CRC_INDICATION_PDU_T crcIndication = crcIndications.poll();
            // Process the CRC indication here
        }
    }

    public void stopProcessing() {
        executor.shutdownNow();
        try {
            executor.awaitTermination(10, TimeUnit.SECONDS);
        } catch (InterruptedException e) {
            // Handle interruption
        }
    }
}
