        exit(1);
    }

    // Fetch the results of the MySQL query statement
    MYSQL_BIND result[3];
    memset(&result, 0, sizeof(MYSQL_BIND) * 3);
    if (mysql_stmt_bind_result(stmt, result)) {
        fprintf(stderr, "mysql_stmt_bind_result: %s\n", mysql_error(db));
        exit(1);
