    while (mysql_stmt_fetch(stmt) == 0) {
        printf("Employee Name: %s\n", result[0].buffer.char_value);
        printf("Employee City: %s\n", result[1].buffer.char_value);
        printf("Employee Address: %s\n", result[2].buffer.char_value);
