    private List<IdentityProvider> identityProviders = new ArrayList<>();

    // Define the configuration file for the authentication service
    private AuthenticationConfig config;

    public AuthenticationService(AuthenticationConfig config) {
        this.config = config;
        initIdentityProviders();
    }

    /**
     * Initialize the list of supported identity providers
     */
    private void initIdentityProviders() {
        // Load the identity provider configuration from the file
        Map<String, IdentityProviderConfig> idpConfigs = config.getIdpConfigs();

        // Create an instance of each identity provider and add it to the list
        for (Map.Entry<String, IdentityProviderConfig> entry : idpConfigs.entrySet()) {
            String idpName = entry.getKey();
            IdentityProviderConfig idpConfig = entry.getValue();

            // Create an instance of the identity provider and add it to the list
            IdentityProvider idp;
            if (idpConfig.getType().equals("saml")) {
                idp = new SamlIdentityProvider(idpName, idpConfig);
            } else if (idpConfig.getType().equals("jwt")) {
                idp = new JwtIdentityProvider(idpName, idpConfig);
            } else if (idpConfig.getType().equals("oauth2")) {
                idp = new OAuth2IdentityProvider(idpName, idpConfig);
            } else {
                throw new RuntimeException("Unsupported identity provider type: " + idpConfig.getType());
            }
            identityProviders.add(idp);
        }
    }

    /**
     * Authenticate the user using the specified credentials and return a JWT token
     * @param username The username of the user to authenticate
     * @param password The password of the user to authenticate
     * @return A JWT token that can be used for authorization
     */
    public String authenticate(String username, String password) {
        // Check if the user is allowed to access the system
        boolean isAllowed = config.isUserAllowed(username);
        if (!isAllowed) {
            throw new RuntimeException("User not allowed: " + username);
        }

        // Create a JWT token for the user
        return createJwtToken(username, password);
    }

    /**
