     * @param username The username of the user to authenticate
     * @param password The password of the user to authenticate
     * @return A JWT token that can be used for authorization
     */
    private String createJwtToken(String username, String password) {
        // Check if the user is allowed to access the system
        boolean isAllowed = config.isUserAllowed(username);
        if (!isAllowed) {
            throw new RuntimeException("User not allowed: " + username);
        }

        // Create a JWT token for the user
        return createJwtToken(username, password, null);
