mutex stream_lock;

// Condition variable to signal changes in the vector of streams
condition_variable stream_cv;

// Function to add a new stream to the vector of streams
void add_stream(int id, string name, int resolution, float bitrate) {
  // Acquire the lock on the vector of streams
  unique_lock<mutex> lock(stream_lock);

  // Create a new Stream object and populate its metadata
  Stream s;
  s.id = id;
  s.name = name;
  s.resolution = resolution;
  s.bitrate = bitrate;
  s.active = true;

  // Add the new stream to the vector of streams
  streams.push_back(s);

  // Notify all waiting threads that the vector has changed
  stream_cv.notify_all();
}

