    streamsConfig.put(ProducerConfig.ACKS_CONFIG, "-1");
    streamsConfig.put(StreamsConfig.DEFAULT_KEY_SERDE_CLASS_CONFIG, Serdes.String().getClass());
    streamsConfig.put(StreamsConfig.DEFAULT_VALUE_SERDE_CLASS_CONFIG, Serdes.String().getClass());

    KafkaStreams.StateListener stateListener = (newState, oldState) -> {
      System.out.println("New state: " + newState);
    };
    this.streams = new KafkaStreams(createTopology(), streamsConfig);
    this.streams.setStateListener(stateListener);
    this.streams.start();

    // Set up the state table
    storeBuilder = Stores.keyValueStoreBuilder(Stores.persistentKeyValueStore("my-store"), Serdes.String(), Serdes.String());
    KTable<String, String> stateTable = streams.builder().addStateStore(storeBuilder).globalTable("state-topic", "state-store");

    // Set up the input stream
    this.inputStream = streams.builder().stream("input-topic");

    // Process messages from the input stream and update the state table
    KStream<String, String> processedStream = inputStream.process(() -> new Processor() {
      private KeyValueStore<String, String> store;

      @Override
      public void init(ProcessorContext context) {
        this.store = (KeyValueStore<String, String>)context.getStateStore("state-store");
      }

      @Override
      public void process(String key, String value) {
        // Update the state table with the current event
        store.put(key, value);

        // Process the event and update the output topic
        // ...
      }
    });

    // Write the processed stream to the output topic
    processedStream.to("output-topic");

    // Start the streams
    this.streams.start();
  }

  private Topology createTopology() {
    return new Topology()
      .addSource(null, "input-topic")
      .addSink(null, "output-topic");
  }
}
