#include <openssl/aes.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <openssl/conf.h>
#include <openssl/err.h>

// Structure to hold the encryption context
typedef struct {
    AES_KEY aes; // AES key structure
    HMAC_CTX *hmac; // HMAC context
} EncryptionContext;

// Function to initialize an encryption context
int initEncryptionContext(EncryptionContext *ctx) {
    // Initialize the AES and HMAC structures
    if (AES_set_encrypt_key(&ctx->aes, EVP_CIPHER_CTX_key_length(&ctx->aes), NULL)) {
        return 0;
    }
    if (!HMAC_Init_ex(ctx->hmac, NULL, 0, NULL, NULL)) {
        return 0;
    }

    // Generate a random IV and set it in the HMAC context
    uint8_t iv[16];
    RAND_bytes(iv, sizeof(iv));
    if (!HMAC_Init_ex(ctx->hmac, NULL, 0, NULL, NULL)) {
        return 0;
    }
    HMAC_Update(ctx->hmac, iv, sizeof(iv));

    // Set the encryption mode and key length
    EVP_CIPHER_CTX_set_key_length(&ctx->aes, 16);
    EVP_CIPHER_CTX_set_padding(&ctx->aes, 0);

    return 1;
}

// Function to encrypt data using an encryption context
int encrypt(EncryptionContext *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext, size_t ciphertext_len) {
    // Check if the encryption context is initialized
    if (!ctx || !initEncryptionContext(ctx)) {
        return 0;
    }

    // Generate a random IV and set it in the HMAC context
    uint8_t iv[16];
    RAND_bytes(iv, sizeof(iv));
    if (!HMAC_Init_ex(ctx->hmac, NULL, 0, NULL, NULL)) {
        return 0;
    }
    HMAC_Update(ctx->hmac, iv, sizeof(iv));

    // Set the encryption mode and key length
    EVP_CIPHER_CTX_set_key_length(&ctx->aes, 16);
    EVP_CIPHER_CTX_set_padding(&ctx->aes, 0);

    // Encrypt the plaintext using AES-256-CBC and HMAC-SHA-256
    if (!EVP_EncryptInit_ex(ctx->aes, EVP_aes_256_cbc(), NULL, NULL)) {
        return 0;
    }
    if (!HMAC_Update(ctx->hmac, plaintext, plaintext_len)) {
        return 0;
    }
    if (!EVP_EncryptFinal_ex(ctx->aes, ciphertext, &ciphertext_len)) {
        return 0;
    }
    HMAC_Update(ctx->hmac, ciphertext, ciphertext_len);

    // Set the IV and HMAC in the ciphertext buffer
    memcpy(ciphertext + sizeof(iv), iv, sizeof(iv));
    memcpy(ciphertext + sizeof(iv) + 16, ctx->hmac, SHA256_DIGEST_LENGTH);

    return 1;
}

// Function to decrypt data using an encryption context
int decrypt(EncryptionContext *ctx, const unsigned char *ciphertext, size_t ciphertext_len, unsigned char *plaintext, size_t plaintext_len) {
    // Check if the encryption context is initialized
    if (!ctx || !initEncryptionContext(ctx)) {
        return 0;
    }

    // Extract the IV and HMAC from the ciphertext buffer
    uint8_t iv[16];
    unsigned char hmac[SHA256_DIGEST_LENGTH];
    memcpy(iv, ciphertext + sizeof(iv), sizeof(iv));
    memcpy(hmac, ciphertext + sizeof(iv) + 16, SHA256_DIGEST_LENGTH);

    // Set the encryption mode and key length
    EVP_CIPHER_CTX_set_key_length(&ctx->aes, 16);
    EVP_CIPHER_CTX_set_padding(&ctx->aes, 0);

    // Decrypt the ciphertext using AES-256-CBC and HMAC-SHA-256
    if (!EVP_DecryptInit_ex(ctx->aes, EVP_aes_256_cbc(), NULL, NULL)) {
        return 0;
    }
    if (!HMAC_Update(ctx->hmac, ciphertext, ciphertext_len - SHA256_DIGEST_LENGTH)) {
        return 0;
    }
    if (!EVP_DecryptFinal_ex(ctx->aes, plaintext, &plaintext_len)) {
        return 0;
    }
    HMAC_Update(ctx->hmac, plaintext, plaintext_len);

    // Verify the HMAC
    unsigned char calculated_hmac[SHA256_DIGEST_LENGTH];
    HMAC_Final(ctx->hmac, calculated_hmac, NULL);
    if (memcmp(calculated_hmac, hmac, SHA256_DIGEST_LENGTH) != 0) {
        return 0;
    }

    return 1;
}
