class CombatStrategyManager {
public:
    CombatStrategyManager() {}

    void selectAttackStrategy(int playerId) {
        // Generate a random number between 1 and 3 to select an attack strategy
        int strategyIndex = rand() % 3 + 1;

        // Print the selected attack strategy to the console
        std::cout << "Player " << playerId << " has chosen attack strategy " << strategyIndex << std::endl;

        // Update the player's cooldown period
        updateCooldownPeriod(playerId);
    }

    void updateCooldownPeriod(int playerId) {
        // Add 7 seconds to the current time
        time_t newTime = time(0) + 7;

        // Check if the cooldown period has expired
        if (newTime > cooldownTimes[playerId]) {
            // Reset the cooldown period
            cooldownTimes[playerId] = newTime;
        } else {
            // If the cooldown period is still active, log an error message and return
            std::cerr << "Player " << playerId << " cannot select another attack strategy until their cooldown period expires." << std::endl;
            return;
        }
    }

private:
    // Map of player IDs to their current cooldown periods
    std::map<int, time_t> cooldownTimes;
};
