#include <condition_variable>
#include <chrono>

using namespace std;

// Struct for storing socket information
struct TcpSocketConnection {
    int descriptor;
    string remote_ip;
    uint16_t port;
};

// Vector to store all open connections
vector<TcpSocketConnection> connections;

// Mutex and condition variable for protecting concurrent access to the connection vector
mutex conn_mtx;
condition_variable conn_cv;

void establish_connection(const string& remote_ip, uint16_t port) {
    // Create a new socket descriptor
    int sock = socket(AF_INET, SOCK_STREAM, 0);

    // Establish the connection
    connect(sock, (struct sockaddr *)&remote_ip, sizeof(remote_ip));

    // Lock the mutex and add the new connection to the vector
    unique_lock<mutex> lock(conn_mtx);
    connections.push_back({ sock, remote_ip, port });
    conn_cv.notify_all();
}

void close_connection(int descriptor) {
    // Lock the mutex and find the connection with the matching socket descriptor
    unique_lock<mutex> lock(conn_mtx);
    for (auto it = connections.begin(); it != connections.end(); ++it) {
        if (it->descriptor == descriptor) {
            // Close the connection and remove it from the vector
            close(it->descriptor);
            connections.erase(it);
            break;
        }
    }
}

void read_data(int descriptor, char* buffer, size_t size) {
    // Lock the mutex and find the connection with the matching socket descriptor
    unique_lock<mutex> lock(conn_mtx);
    for (auto it = connections.begin(); it != connections.end(); ++it) {
        if (it->descriptor == descriptor) {
            // Read data from the socket and copy it to the buffer
            read(it->descriptor, buffer, size);
            break;
        }
    }
}

void write_data(int descriptor, const char* buffer, size_t size) {
    // Lock the mutex and find the connection with the matching socket descriptor
    unique_lock<mutex> lock(conn_mtx);
    for (auto it = connections.begin(); it != connections.end(); ++it) {
        if (it->descriptor == descriptor) {
            // Write data to the socket
            write(it->descriptor, buffer, size);
            break;
        }
    }
}
```
This implementation uses a vector to store all open connections, and employs mutexes and condition variables for protecting concurrent access to the connection vector. It also provides functions for establishing new connections, closing existing connections, reading data from connections, and writing data to connections.']

