// A structure to represent a TX power report.
struct TXPowerReport {
    uint64_t rnti;  // The unique UE identifier (RNTI)
    int64_t timestamp;  // The timestamp of the report
    double powerLevel;  // The power level value
};

// A container class to manage a collection of TX power reports.
class TXPowerReportContainer {
public:
    // Adds a new TX power report to the container.
    void add(const TXPowerReport& report) {
        std::lock_guard<std::mutex> lock(_mutex);
        _reports.push_back(report);
    }

    // Retrieves a TX power report with the specified RNTI.
    optional<TXPowerReport> get(uint64_t rnti) {
        std::lock_guard<std::mutex> lock(_mutex);
        for (const auto& report : _reports) {
            if (report.rnti == rnti) {
                return report;
            }
        }
        return {};
    }

    // Updates a TX power report with the specified RNTI.
    void update(const TXPowerReport& report) {
        std::lock_guard<std::mutex> lock(_mutex);
        for (auto it = _reports.begin(); it != _reports.end(); ++it) {
            if (it->rnti == report.rnti) {
                *it = report;
                break;
            }
        }
    }

    // Deletes a TX power report with the specified RNTI.
    void delete(uint64_t rnti) {
        std::lock_guard<std::mutex> lock(_mutex);
        for (auto it = _reports.begin(); it != _reports.end(); ++it) {
            if (it->rnti == rnti) {
                _reports.erase(it);
                break;
            }
        }
    }

private:
    std::mutex _mutex;  // A mutex to protect the reports container from concurrent access.
    std::vector<TXPowerReport> _reports;  // A vector of TX power reports.
};
```
