using System;
using System.Collections.Generic;
using System.Data;
using System.Threading.Tasks;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using MySqlConnector;
using Npgsql;
using Oracle.ManagedDataAccess.Client;

namespace DataRetrievalFramework
{
    public class DataRetrievalService
    {
        private readonly ILogger<DataRetrievalService> _logger;
        private readonly IConfiguration _configuration;
        private readonly IDictionary<string, DbConnection> _connections;

        public DataRetrievalService(ILogger<DataRetrievalService> logger, IConfiguration configuration)
        {
            _logger = logger;
            _configuration = configuration;
            _connections = new Dictionary<string, DbConnection>();
        }

        public async Task<TResult> ExecuteAsync<TResult>(Func<DbConnection, Task<TResult>> action, string connectionString)
        {
            try
            {
                var connection = GetOrCreateConnection(connectionString);
                return await action(connection).ConfigureAwait(false);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error executing data retrieval task");
                throw;
            }
        }

        public async Task<TResult> ExecuteAsync<TResult>(string connectionString, Func<DbDataReader, TResult> readerAction)
        {
            try
            {
                var connection = GetOrCreateConnection(connectionString);
                using (var command = connection.CreateCommand())
                {
                    return await ExecuteAsync(async () =>
                    {
                        using (var reader = await command.ExecuteReaderAsync().ConfigureAwait(false))
                        {
                            while (await reader.ReadAsync().ConfigureAwait(false))
                            {
                                var result = readerAction(reader);
                                if (!Equals(result, default(TResult)))
                                {
                                    return result;
                                }
                            }
                        }
                        return default(TResult);
                    }, connection).ConfigureAwait(false);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error executing data retrieval task");
                throw;
            }
        }

        public async Task<IEnumerable<TResult>> ExecuteAsync<TResult>(string connectionString, Func<DbDataReader, TResult> readerAction)
        {
            try
            {
                var connection = GetOrCreateConnection(connectionString);
                using (var command = connection.CreateCommand())
                {
                    return await ExecuteAsync(async () =>
                    {
                        var results = new List<TResult>();
                        using (var reader = await command.ExecuteReaderAsync().ConfigureAwait(false))
                        {
                            while (await reader.ReadAsync().ConfigureAwait(false))
                            {
                                var result = readerAction(reader);
                                if (!Equals(result, default(TResult)))
                                {
                                    results.Add(result);
                                }
                            }
                        }
                        return results;
                    }, connection).ConfigureAwait(false);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error executing data retrieval task");
                throw;
            }
        }

        public async Task<IEnumerable<TResult>> ExecuteAsync<TResult>(string connectionString, string sqlQuery)
        {
            try
            {
                var connection = GetOrCreateConnection(connectionString);
                using (var command = connection.CreateCommand())
                {
                    return await ExecuteAsync(async () =>
                    {
                        var results = new List<TResult>();
                        using (var reader = await command.ExecuteReaderAsync().ConfigureAwait(false))
                        {
                            while (await reader.ReadAsync().ConfigureAwait(false))
                            {
                                var result = GetValue<TResult>(reader, 0);
                                if (!Equals(result, default(TResult)))
                                {
                                    results.Add(result);
                                }
                            }
                        }
                        return results;
                    }, connection).ConfigureAwait(false);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error executing data retrieval task");
                throw;
            }
        }

        public async Task<TResult> ExecuteScalarAsync<TResult>(string connectionString, string sqlQuery)
        {
            try
            {
                var connection = GetOrCreateConnection(connectionString);
                using (var command = connection.CreateCommand())
                {
                    return await ExecuteAsync(async () =>
                    {
                        var result = default(TResult);
                        using (var reader = await command.ExecuteReaderAsync().ConfigureAwait(false))
                        {
                            while (await reader.ReadAsync().ConfigureAwait(false))
                            {
                                result = GetValue<TResult>(reader, 0);
                            }
                        }
                        return result;
                    }, connection).ConfigureAwait(false);
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error executing data retrieval task");
                throw;
            }
        }

        private DbConnection GetOrCreateConnection(string connectionString)
        {
            if (_connections.ContainsKey(connectionString))
            {
                return _connections[connectionString];
            }

            var connection = CreateDbConnection(connectionString);
            _connections.Add(connectionString, connection);
            return connection;
        }

        private DbConnection CreateDbConnection(string connectionString)
        {
            switch (GetDatabaseType(connectionString))
            {
                case DatabaseType.MySql:
                    return new MySqlConnection(connectionString);
                case DatabaseType.PostgreSql:
                    return new NpgsqlConnection(connectionString);
                case DatabaseType.Oracle:
                    return new OracleConnection(connectionString);
            }

            throw new Exception("Unsupported database type");
        }

        private static T GetValue<T>(DbDataReader reader, int ordinal)
        {
            if (reader.IsDBNull(ordinal))
            {
                return default(T);
            }

            var value = reader[ordinal];
            if (value is T)
            {
                return (T)value;
            }

            if (typeof(T) == typeof(string))
            {
                return (T)(object)value.ToString();
            }

            throw new Exception($"Cannot convert type '{value.GetType().Name}' to '{typeof(T).Name}'");
        }

        private enum DatabaseType
        {
            MySql,
            PostgreSql,
            Oracle
        }

        private static DatabaseType GetDatabaseType(string connectionString)
        {
            if (connectionString.StartsWith("Server=MySQL"))
            {
                return DatabaseType.MySql;
            }
            else if (connectionString.StartsWith("Server=PostgreSql"))
            {
                return DatabaseType.PostgreSql;
            }
            else if (connectionString.StartsWith("Server=Oracle"))
            {
                return DatabaseType.Oracle;
            }

            throw new Exception("Unsupported database type");
        }
    }
}
```

#### Using the `DbContext` class

The `DbContext` class is a lightweight, high-performance ORM for .NET that makes it easy to work with databases. It provides a simple and intuitive API for querying data, as well as an extensible framework for building custom database providers.

Here's an example of how you can use the `DbContext` class to interact with a SQL Server database:
```csharp
using System;
using System.Data.SqlClient;
using Microsoft.EntityFrameworkCore;

namespace DbContextExample
{
    public class BlogContext : DbContext
    {
        public BlogContext(DbContextOptions<BlogContext> options)
            : base(options)
        { }

        public DbSet<Blog> Blogs { get; set; }
        public DbSet<Post> Posts { get; set; }
    }

    public class Blog
    {
        public int Id { get; set; }
        public string Name { get; set; }
        public string Url { get; set; }
    }

    public class Post
    {
        public int Id { get; set; }
        public string Title { get; set; }
        public string Content { get; set; }
        public Blog Blog { get; set; }
    }
}
```
This example shows a `BlogContext` class that inherits from the `DbContext` class. The `BlogContext` class is used to interact with a SQL Server database, and it defines two `DbSet<T>` properties (`Blogs` and `Posts`) that represent the `Blog` and `Post` tables in the database.

Here's an example of how you can use the `BlogContext` class to query data from the database:
```csharp
using (var context = new BlogContext(options))
{
    var blog = context.Blogs.FirstOrDefault();
    Console.WriteLine($"Blog ID: {blog.Id}");
    Console.WriteLine($"Blog Name: {blog.Name}");
    Console.WriteLine($"Blog Url: {blog.Url}");
}
```
This example creates an instance of the `BlogContext` class and uses it to query data from the database. The `DbSet<T>` properties (`Blogs` and `Posts`) are used to retrieve a single `Blog` or `Post` object, based on its primary key value. The `FirstOrDefault()` method is used to retrieve the first matching `Blog` or `Post` object, or null if no match was found.

Here's an example of how you can use the `BlogContext` class to add new data to the database:
```csharp
using (var context = new BlogContext(options))
{
    var blog = new Blog { Name = "My Blog", Url = "https://myblog.com" };
    context.Blogs.Add(blog);
    context.SaveChanges();
}
```
This example creates an instance of the `BlogContext` class and uses it to add a new `Blog` object to the database. The `Add()` method is used to mark the `Blog` object as added, and the `SaveChanges()` method is used to persist the changes to the database.

Here's an example of how you can use the `BlogContext` class to update existing data in the database:
```csharp
using (var context = new BlogContext(options))
{
    var blog = new Blog { Id = 1, Name = "My Blog", Url = "https://myblog.com" };
    context.Blogs.Update(blog);
    context.SaveChanges();
}
```
This example creates an instance of the `BlogContext` class and uses it to update an existing `Blog` object in the database. The `Update()` method is used to mark the `Blog` object as updated, and the `SaveChanges()` method is used to persist the changes to the database.

Here's an example of how you can use the `BlogContext` class to delete existing data from the database:
```csharp
using (var context = new BlogContext(options))
{
    var blog = new Blog { Id = 1 };
    context.Blogs.Remove(blog);
    context.SaveChanges();
}
```
This example creates an instance of the `BlogContext` class and uses it to delete an existing `Blog` object from the database. The `Remove()` method is used to mark the `Blog` object as deleted, and the `SaveChanges()` method is used to persist the changes to the database.

#### Using the `DbSet<T>` class

