// Define the Union-Find data structure to manage disjoint sets of nodes
class UnionFind {
  // Initialize the map for storing nodes and their representative elements
  Map<Integer, Integer> nodeMap = new HashMap<>();

  // Initialize the map for storing the number of elements in each set
  Map<Integer, Integer> setSizes = new HashMap<>();

  // Define a method to find the representative element of a given node
  public int find(int node) {
    if (!nodeMap.containsKey(node)) return -1;
    if (node == nodeMap.get(node)) return node;
    else {
      int rep = find(nodeMap.get(node));
      nodeMap.put(node, rep);
      return rep;
    }
  }

  // Define a method to merge two nodes into the same set
  public void union(int node1, int node2) {
    int rep1 = find(node1), rep2 = find(node2);
    if (rep1 == -1 || rep2 == -1) return;
    else if (rep1 != rep2) {
      setSizes.put(rep1, setSizes.get(rep1) + setSizes.get(rep2));
      nodeMap.put(rep2, rep1);
    }
  }
}

