#include <iostream>
#include <string>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <vector>
#include <map>
#include <future>
#include <functional>

// Define data structures to store incoming financial market data and callback functions
struct DataRecord {
  std::string symbol;
  double price;
  int volume;
};

class CallbackFunction {
public:
  virtual void onDataReceived(const DataRecord& record) = 0;
};

// Define a class to handle incoming data from multiple sources
class DataProcessor {
private:
  std::mutex mtx_;
  std::condition_variable cv_;
  std::vector<CallbackFunction*> callbacks_;
  std::map<std::string, DataRecord> data_;
  bool running_;

public:
  DataProcessor(std::initializer_list<CallbackFunction*> callbacks) {
    for (auto cb : callbacks) {
      callbacks_.push_back(cb);
    }
    running_ = true;
  }

  ~DataProcessor() {
    running_ = false;
    cv_.notify_all();
  }

  // Add a new data source and attach the given callback function
  void addDataSource(const std::string& url, CallbackFunction* cb) {
    std::lock_guard<std::mutex> lock(mtx_);
    callbacks_.push_back(cb);
    data_.emplace(url, DataRecord{});
  }

  // Remove a data source and detach the given callback function
  void removeDataSource(const std::string& url) {
    std::lock_guard<std::mutex> lock(mtx_);
    callbacks_.erase(std::remove_if(callbacks_.begin(), callbacks_.end(), [url](CallbackFunction* cb){ return cb->getUrl() == url; }), callbacks_.end());
    data_.erase(url);
  }

  // Process incoming data from the given URL and pass it to the attached callback function
  void processData(const std::string& url, const DataRecord& record) {
    std::lock_guard<std::mutex> lock(mtx_);
    auto it = data_.find(url);
    if (it != data_.end()) {
      // Update the data record with the latest price and volume
      it->second.price = record.price;
      it->second.volume = record.volume;
      // Notify all attached callback functions
      for (auto cb : callbacks_) {
        if (cb->getUrl() == url) {
          cb->onDataReceived(it->second);
        }
      }
    } else {
      // Add the new data source and initialize its record
      data_.emplace(url, record);
      for (auto cb : callbacks_) {
        if (cb->getUrl() == url) {
          cb->onDataReceived(record);
        }
      }
    }
  }
};

// Define a class to manage the data processing pipeline
class DataPipeline {
private:
  std::mutex mtx_;
  std::condition_variable cv_;
  std::vector<CallbackFunction*> callbacks_;
  std::map<std::string, DataRecord> data_;
  bool running_;

public:
  DataPipeline(std::initializer_list<CallbackFunction*> callbacks) {
    for (auto cb : callbacks) {
      callbacks_.push_back(cb);
    }
    running_ = true;
  }

  ~DataPipeline() {
    running_ = false;
    cv_.notify_all();
  }

  // Add a new data source and attach the given callback function
  void addDataSource(const std::string& url, CallbackFunction* cb) {
    std::lock_guard<std::mutex> lock(mtx_);
    callbacks_.push_back(cb);
    data_.emplace(url, DataRecord{});
  }

  // Remove a data source and detach the given callback function
  void removeDataSource(const std::string& url) {
    std::lock_guard<std::mutex> lock(mtx_);
    callbacks_.erase(std::remove_if(callbacks_.begin(), callbacks_.end(), [url](CallbackFunction* cb){ return cb->getUrl() == url; }), callbacks_.end());
    data_.erase(url);
  }

  // Process incoming data from the given URL and pass it to the attached callback function
  void processData(const std::string& url, const DataRecord& record) {
    std::lock_guard<std::mutex> lock(mtx_);
    auto it = data_.find(url);
    if (it != data_.end()) {
      // Update the data record with the latest price and volume
      it->second.price = record.price;
      it->second.volume = record.volume;
      // Notify all attached callback functions
      for (auto cb : callbacks_) {
        if (cb->getUrl() == url) {
          cb->onDataReceived(it->second);
        }
      }
    } else {
      // Add the new data source and initialize its record
      data_.emplace(url, record);
      for (auto cb : callbacks_) {
        if (cb->getUrl() == url) {
          cb->onDataReceived(record);
        }
      }
    }
  }
};

// Define a class to handle asynchronous data processing
class AsyncDataProcessor {
private:
  std::mutex mtx_;
