// Define a structure to hold the context for each cryptographic operation
typedef struct {
    EVP_PKEY* pkey;
    SSL_CTX* ctx;
} crypt_ctx_t;

// Define a structure to hold the resource pool for OpenSSL contexts
typedef struct {
    int size;
    int count;
    crypt_ctx_t** contexts;
} ssl_pool_t;

// Initialize the resource pool for OpenSSL contexts
static void ssl_pool_init(ssl_pool_t* pool, int size) {
    pool->size = size;
    pool->count = 0;
    pool->contexts = (crypt_ctx_t**)malloc(sizeof(crypt_ctx_t*) * size);
}

// Create a new OpenSSL context and add it to the resource pool
static void ssl_pool_add(ssl_pool_t* pool, EVP_PKEY* pkey, SSL_CTX* ctx) {
    if (pool->count < pool->size) {
        pool->contexts[pool->count] = (crypt_ctx_t*)malloc(sizeof(crypt_ctx_t));
        pool->contexts[pool->count]->pkey = pkey;
        pool->contexts[pool->count]->ctx = ctx;
        pool->count++;
    } else {
        // Resource pool is full, need to discard an existing context
        ssl_pool_remove(pool, 0);
        ssl_pool_add(pool, pkey, ctx);
    }
}

// Remove a specific OpenSSL context from the resource pool
static void ssl_pool_remove(ssl_pool_t* pool, int index) {
    if (index < pool->count) {
        free(pool->contexts[index]);
        pool->contexts[index] = NULL;
        pool->count--;
    }
}

// Get a OpenSSL context from the resource pool for the specified operation
static crypt_ctx_t* ssl_pool_get(ssl_pool_t* pool, int op) {
    if (op == OP_ENCRYPT || op == OP_DECRYPT) {
        return pool->contexts[0];
    } else if (op == OP_SIGN || op == OP_VERIFY) {
        return pool->contexts[1];
    } else {
        // Invalid operation, need to handle this gracefully
        return NULL;
    }
}

// Release a OpenSSL context back to the resource pool
static void ssl_pool_release(ssl_pool_t* pool, crypt_ctx_t* ctx) {
    int i = 0;
    while (i < pool->count && ctx != pool->contexts[i]) {
        i++;
    }
    if (i == pool->count) {
        // Context not found in the pool, need to handle this gracefully
    } else {
        ssl_pool_remove(pool, i);
    }
}

