class LogService {
  constructor() {
    this.logEvents = [];
    this.externalLoggingAPIs = [new LegacyLoggingAPI(), new CloudLoggingAPI()];
    this.distributedDataStore = new NoSQLDatabase();
  }

  async addLogEvent(event) {
    // Optimistic concurrency control
    const currentEvents = await this.getAllLogEvents();
    if (currentEvents.some((e) => e.eventId === event.eventId)) {
      return false;
    }

    this.logEvents.push(event);
    this.externalLoggingAPIs.forEach((api) => api.logEvent(event));
    this.distributedDataStore.saveEvent(event);
