// DynamicRealtimeDataProcessor.h
#pragma once

#include <string>
#include <memory>
#include <unordered_map>
#include <functional>
#include <future>
#include <mutex>

namespace dynrt {

class DynamicRealtimeDataProcessor {
public:
    using FeedId = std::string;
    using DataPoint = double; // replace with appropriate data type for your use case
    using DataStream = std::unordered_map<FeedId, std::vector<DataPoint>>;
    using ProcessingFunction = std::function<DataStream(const DataStream&)>;
    using FeedConfig = std::pair<std::string, ProcessingFunction>;
    using FeedMap = std::unordered_map<FeedId, FeedConfig>;

    DynamicRealtimeDataProcessor();
    ~DynamicRealtimeDataProcessor();

    void addFeed(const FeedId& feedId, const ProcessingFunction& processingFunction);
    void removeFeed(const FeedId& feedId);
    bool isActive() const;
    void start();
    void stop();

private:
    std::mutex m_mutex;
    std::atomic<bool> m_isRunning;
    FeedMap m_feeds;
    std::vector<std::future<DataStream>> m_processingThreads;
    std::unordered_map<FeedId, DataStream> m_dataStreams;
};

} // namespace dynrt

// DynamicRealtimeDataProcessor.cpp
#include "DynamicRealtimeDataProcessor.h"

namespace dynrt {

DynamicRealtimeDataProcessor::DynamicRealtimeDataProcessor() : m_isRunning(false) {}

DynamicRealtimeDataProcessor::~DynamicRealtimeDataProcessor() {
    if (m_isRunning) {
        stop();
    }
}

void DynamicRealtimeDataProcessor::addFeed(const FeedId& feedId, const ProcessingFunction& processingFunction) {
    std::lock_guard<std::mutex> lock(m_mutex);
    m_feeds[feedId] = { feedId, processingFunction };
}

void DynamicRealtimeDataProcessor::removeFeed(const FeedId& feedId) {
    std::lock_guard<std::mutex> lock(m_mutex);
    m_feeds.erase(feedId);
}

bool DynamicRealtimeDataProcessor::isActive() const {
    return m_isRunning;
}

void DynamicRealtimeDataProcessor::start() {
    std::lock_guard<std::mutex> lock(m_mutex);
    if (m_isRunning) {
        return;
    }

    m_dataStreams.clear();
    for (const auto& feed : m_feeds) {
        const FeedId& feedId = feed.first;
        const ProcessingFunction& processingFunction = feed.second.second;
        m_dataStreams[feedId] = std::vector<DataPoint>();
        m_processingThreads.emplace_back(std::async([=, &m_dataStreams, &m_feeds]() {
            while (true) {
                DataStream dataStream;
                try {
                    // retrieve data from feed
                    auto& feedConfig = m_feeds.at(feedId);
                    const std::string& feedUrl = feedConfig.first;
                    const ProcessingFunction& processingFunction = feedConfig.second;
                    dataStream = processingFunction(dataStream);
                } catch (const std::exception& e) {
                    // handle exception gracefully
                    continue;
                }
                m_dataStreams[feedId] = dataStream;
            }
        }));
    }
    m_isRunning = true;
}

void DynamicRealtimeDataProcessor::stop() {
    std::lock_guard<std::mutex> lock(m_mutex);
    if (!m_isRunning) {
        return;
    }

    for (auto& thread : m_processingThreads) {
        thread.wait();
    }
    m_isRunning = false;
}

} // namespace dynrt']

