// Custom dependencies
#include "dependency_graph.hpp"
#include "resource_manager.hpp"
#include "cache_manager.hpp"
#include "metrics_tracker.hpp"
#include "alert_system.hpp"
#include "notification_service.hpp"

namespace drm {
using json = nlohmann::json;
using namespace std::chrono_literals; // for convenience
using namespace boost::algorithm; // for string manipulation algorithms
using DependencyGraph = drm::DependencyGraph<std::string, int>;
using ResourceManager = drm::ResourceManager<std::string, int>;
using CacheManager = drm::CacheManager<std::string, int>;
using MetricsTracker = drm::MetricsTracker<int>;
using AlertSystem = drm::AlertSystem<int>;
using NotificationService = drm::NotificationService<int>;

// Configuration parameters for the DynamicResourceManager library
constexpr std::size_t kDefaultCacheSize = 1024;
constexpr double kDefaultCacheUtilizationThreshold = 0.8;
constexpr int kDefaultAlertFrequencySecs = 3600; // 1 hour
constexpr int kDefaultNotificationFreqSecs = 600; // 10 minutes
const std::vector<std::string> kSupportedServices = {"Amazon S3", "Amazon Redshift", "Amazon DynamoDB"};
const std::map<std::string, int> kDefaultServiceConfigs = {{"Amazon S3", 1024}, {"Amazon Redshift", 512}, {"Amazon DynamoDB", 256}};
constexpr std::size_t kMaxThreadCount = 8; // maximum number of threads to spawn for parallel processing

// Type definitions
using Service = std::string;
using Dependency = int;
using Task = std::function<void()>;
using ResourceHandle = ResourceManager::ResourceHandle<Service, Dependency>;
using CacheEntry = CacheManager::CacheEntry<std::string>;
using AlertMessage = AlertSystem::AlertMessage<int>;
using NotificationEvent = NotificationService::NotificationEvent<int>;

// Forward declarations
class DynamicResourceManager;
struct ServiceDescriptor;
struct ResourceDescriptor;
struct TaskDescriptor;
struct CacheDescriptor;
struct AlertDescriptor;
struct NotificationDescriptor;
struct DependencyGraphDescriptor;

/*
* struct ServiceDescriptor: Descriptor for a service. Contains information about the service, such as its name, dependencies, and configuration parameters.
*/
struct ServiceDescriptor {
  std::string name; // name of the service (e.g., Amazon S3)
  int config_id; // identifier for the service's configuration parameters in the DependencyGraphDescriptor
  std::vector<std::pair<Service, Dependency>> dependencies; // list of services this service depends on and their respective dependencies
};

/*
* struct ResourceDescriptor: Descriptor for a resource. Contains information about the resource, such as its name, capacity, and current utilization.
*/
struct ResourceDescriptor {
  std::string name; // name of the resource (e.g., an Amazon S3 bucket)
  int capacity; // maximum number of requests that can be processed by the resource at any given time
  double utilization_threshold; // threshold for alerting on utilization (e.g., if >80% utilized, trigger an alert)
  double current_utilization; // current utilization rate of the resource
};

/*
* struct TaskDescriptor: Descriptor for a task. Contains information about the task, such as its name, dependencies, and resource requirements.
*/
struct TaskDescriptor {
  std::string name; // name of the task (e.g., uploading a file to S3)
  int config_id; // identifier for the task's configuration parameters in the DependencyGraphDescriptor
  std::vector<std::pair<Service, Dependency>> dependencies; // list of services this task depends on and their respective dependencies
  int num_resources; // number of resources required to complete the task (e.g., an Amazon S3 bucket)
};

/*
* struct CacheDescriptor: Descriptor for a cache. Contains information about the cache, such as its name, capacity, and current size.
*/
struct CacheDescriptor {
  std::string name; // name of the cache (e.g., data fetched from S3)
  int capacity; // maximum number of entries that can be stored in the cache at any given time
  double utilization_threshold; // threshold for alerting on utilization (e.g., if >80% utilized, trigger an alert)
  std::size_t current_size; // current size of the cache
};

/*
* struct AlertDescriptor: Descriptor for an alert. Contains information about the alert, such as its name and frequency.
*/
struct AlertDescriptor {
  std::string name; // name of the alert (e.g., exceeded capacity)
  int config_id; // identifier for the alert's configuration parameters in the DependencyGraphDescriptor
  int frequency_secs; // frequency at which to send alert messages (e.g., every hour)
};

/*
* struct NotificationDescriptor: Descriptor for a notification event. Contains information about the notification, such as its name and recipients.
*/
struct NotificationDescriptor {
  std::string name; // name of the notification event (e.g., exceeded capacity)
  int config_id; // identifier for the notification's configuration parameters in the DependencyGraphDescriptor
  std::vector<std::string> recipients; // list of recipients to send notifications to
};

/*
* struct DependencyGraphDescriptor: Descriptor for a dependency graph. Contains information about the graph, such as its services, resources, and tasks.
*/
struct DependencyGraphDescriptor {
  std::vector<ServiceDescriptor> services; // list of service descriptors in the graph
  std::vector<ResourceDescriptor> resources; // list of resource descriptors in the graph
  std::vector<TaskDescriptor> tasks; // list of task descriptors in the graph
  std::vector<CacheDescriptor> caches; // list of cache descriptors in the graph
  std::vector<AlertDescriptor> alerts; // list of alert descriptors in the graph
  std::vector<NotificationDescriptor> notifications; // list of notification event descriptors in the graph
};

/*
* class DynamicResourceManager: Class that manages the dynamic allocation and deallocation of resources based on a dependency graph.
*/
class DynamicResourceManager {
public:
  /*
  * DynamicResourceManager(const DependencyGraphDescriptor&): Constructor that initializes the DynamicResourceManager with a dependency graph descriptor.
  */
  DynamicResourceManager(const DependencyGraphDescriptor&);

  /*
  * ~DynamicResourceManager(): Destructor that cleans up any remaining resources.
  */
  ~DynamicResourceManager();

  /*
  * AllocateResources(std::vector<TaskDescriptor>): Allocates resources based on the given task descriptors.
  */
  std::vector<ResourceHandle> AllocateResources(const std::vector<TaskDescriptor>&);

  /*
  * DeallocateResources(std::vector<ResourceHandle>): Deallocates resources based on the given resource handles.
  */
  void DeallocateResources(const std::vector<ResourceHandle>&);

  /*
  * UpdateCacheSize(std::size_t): Updates the cache size to the given value.
  */
  void UpdateCacheSize(std::size_t);

  /*
  * GetCacheCapacity(): Returns the capacity of the cache.
  */
  std::size_t GetCacheCapacity() const;

  /*
  * GetCurrentUtilization(): Returns the current utilization rate of the cache.
  */
  double GetCurrentUtilization() const;

  /*
  * UpdateAlertFrequency(int): Updates the alert frequency to the given value (in seconds).
  */
  void UpdateAlertFrequency(int);

  /*
  * GetAlertFrequency(): Returns the current alert frequency (in seconds).
  */
  int GetAlertFrequency() const;

  /*
  * UpdateNotificationRecipients(std::vector<std::string>): Updates the notification recipients to the given list.
  */
  void UpdateNotificationRecipients(const std::vector<std::string>&);

  /*
  * GetNotificationRecipients(): Returns the current notification recipients.
  */
  const std::vector<std::string>& GetNotificationRecipients() const;

  /*
  * UpdateCacheUtilizationThreshold(double): Updates the cache utilization threshold to the given value.
  */
  void UpdateCacheUtilizationThreshold(double);

  /*
  * GetCacheUtilizationThreshold(): Returns the current cache utilization threshold.
  */
  double GetCacheUtilizationThreshold() const;

private:
  DependencyGraph graph_; // The dependency graph that manages the resources and tasks.
  std::vector<ResourceHandle> allocated_resources_; // A list of all currently allocated resources.
  Cache cache_; // The cache that stores recently accessed tasks and their corresponding resource handles.
  double cache_utilization_threshold_; // The threshold for the cache utilization rate.
  int alert_frequency_secs_; // The frequency at which to send alert messages (in seconds).
  std::vector<std::string> notification_recipients_; // The list of recipients to send notifications to.
};
```

## Task Allocation and Deallocation
The `AllocateResources` and `DeallocateResources` functions are used for allocating and deallocating resources based on the given task descriptors, respectively. These functions use the dependency graph to determine which tasks can be run in parallel, and how many resources each task needs to access. The `AllocateResources` function returns a list of resource handles that can be used to deallocate the allocated resources later using the `DeallocateResources` function.
```cpp
std::vector<ResourceHandle> DynamicResourceManager::AllocateResources(const std::vector<TaskDescriptor>& tasks) {
  // Check if any task is already running in the graph.
  for (const auto& task : tasks) {
    if (graph_.IsTaskRunning(task)) {
      throw std::runtime_error("A task with the same ID is already running.");
    }
  }

  // Allocate resources for each task.
  std::vector<ResourceHandle> allocated_resources;
  for (const auto& task : tasks) {
    allocated_resources.push_back(graph_.AllocateResourcesForTask(task));
  }

  return allocated_resources;
}

void DynamicResourceManager::DeallocateResources(const std::vector<ResourceHandle>& resources) {
  // Check if any resource is already deallocated.
  for (const auto& resource : resources) {
    if (!graph_.IsResourceAllocated(resource)) {
      throw std::runtime_error("A resource with the same ID is already deallocated.");
    }
  }

  // Deallocate each resource.
  for (const auto& resource : resources) {
    graph_.DeallocateResourcesForTask(resource);
  }
}
```

## Cache Management
The `UpdateCacheSize`, `GetCacheCapacity`, `GetCurrentUtilization`, and `UpdateCacheUtilizationThreshold` functions are used for updating the cache size, getting the capacity and current utilization of the cache, and setting the threshold for the cache utilization rate, respectively. The `UpdateNotificationRecipients` function is used for updating the notification recipients list.
```cpp
void DynamicResourceManager::UpdateCacheSize(std::size_t new_cache_size) {
  // Check if the new cache size is smaller than the current cache capacity.
  if (new_cache_size > cache_.GetCapacity()) {
    throw std::runtime_error("The new cache size cannot be larger than the current cache capacity.");
  }

  cache_.SetSize(new_cache_size);
}

std::size_t DynamicResourceManager::GetCacheCapacity() const {
  return cache_.GetCapacity();
}

double DynamicResourceManager::GetCurrentUtilization() const {
  return cache_.GetUtilizationRate();
}

void DynamicResourceManager::UpdateCacheUtilizationThreshold(double new_threshold) {
  // Check if the new threshold is valid.
  if (new_threshold < 0 || new_threshold > 1) {
    throw std::runtime_error("The new cache utilization threshold must be between 0 and 1.");
  }

  cache_.SetUtilizationThreshold(new_threshold);
}

void DynamicResourceManager::UpdateNotificationRecipients(const std::vector<std::string>& recipients) {
  notification_recipients_ = recipients;
}
```

## Alerts and Notifications
The `UpdateAlertFrequency` and `GetAlertFrequency` functions are used for updating the alert frequency (in seconds), and getting the current alert frequency, respectively. The `SendNotification` function is used to send a notification event with the given name and parameters to the recipients specified in the `notification_recipients_` list.
```cpp
void DynamicResourceManager::UpdateAlertFrequency(int new_frequency) {
  // Check if the new frequency is valid.
  if (new_frequency < 0) {
    throw std::runtime_error("The new alert frequency must be positive.");
  }

  alert_frequency_secs_ = new_frequency;
}

int DynamicResourceManager::GetAlertFrequency() const {
  return alert_frequency_secs_;
}

void DynamicResourceManager::SendNotification(const std::string& name, const std::map<std::string, std::string>& parameters) {
  // Check if any recipient is specified.
  if (notification_recipients_.empty()) {
    throw std::runtime_error("No notification recipient is specified.");
  }

  // Send the notification to each recipient.
  for (const auto& recipient : notification_recipients_) {
    Notify(name, parameters, recipient);
  }
}
```

## Resource Handling
The `ResourceHandle` class is used to represent a resource in the system. It contains the ID of the resource and provides functions for checking its availability, allocation, and deallocation. The `IsAvailable`, `Allocate`, and `Deallocate` functions are used to check if a resource is available, allocate it for a task, and deallocate it for a task, respectively.
```cpp
class ResourceHandle {
public:
  ResourceHandle(int id) : id_(id) {}

  bool IsAvailable() const { return graph_.IsResourceAvailable(id_); }
  void Allocate() { graph_.AllocateResourceForTask(id_, task_); }
  void Deallocate() { graph_.DeallocateResourceForTask(id_); }

private:
  int id_;
};
```

## Dependency Graph
The `DependencyGraph` class is used to represent the dependency between tasks and resources in the system. It contains a map of task ID to resource IDs, which specifies what resources are required for each task to run, and a set of available resources, which specifies which resources are currently available in the system. The `AddTask`, `RemoveTask`, `AllocateResourceForTask`, and `DeallocateResourceForTask` functions are used to add, remove, allocate, and deallocate tasks and their corresponding resources, respectively.
```cpp
class DependencyGraph {
public:
  void AddTask(const TaskDescriptor& task) {
    // Check if the task is already added.
    if (tasks_.find(task.id()) != tasks_.end()) {
      throw std::runtime_error("A task with the same ID is already added.");
    }

    // Add the new task to the graph.
    tasks_[task.id()] = task;
  }

  void RemoveTask(int id) {
    // Check if the task is already removed.
    if (tasks_.find(id) == tasks_.end()) {
      throw std::runtime_error("A task with the same ID is not found.");
    }

    // Remove the task from the graph.
    tasks_.erase(id);
  }

  bool IsTaskRunning(const TaskDescriptor& task) const {
    return tasks_.find(task.id()) != tasks_.end();
  }

  bool IsResourceAvailable(int id) const {
    return available_resources_.find(id) != available_resources_.end();
  }

  void AllocateResourceForTask(int task_id, int resource_id) {
    // Check if the resource is already allocated.
    if (IsResourceAllocated(resource_id)) {
      throw std::runtime_error("A resource with the same ID is already allocated.");
    }

    // Add the new allocation to the graph.
    task_allocations_[task_id].push_back(resource_id);
  }

  void DeallocateResourceForTask(int resource_id) {
    // Check if the resource is already deallocated.
    if (!IsResourceAllocated(resource_id)) {
      throw std::runtime_error("A resource with the same ID is not found.");
    }

    // Remove the allocation from the graph.
    task_allocations_.erase(resource_id);
  }

private:
  bool IsResourceAllocated(int id) const {
    return task_allocations_.find(id) != task_allocations_.end();
  }

  std::map<int, TaskDescriptor> tasks_;
  std::set<int> available_resources_;
  std::map<int, std::vector<int>> task_allocations_;
};
```

## System Architecture
The system architecture is shown in the following figure. The system consists of a set of nodes, each node has a resource manager and a task scheduler. The resource manager manages the resources allocated to the tasks on that node, and the task scheduler schedules the tasks on that node. The communication between the nodes is done through the message queue, which ensures the consistency of the system state.

![System Architecture](images/system_architecture.png)

The resource manager maintains a set of available resources, which are the resources allocated to tasks on that node. The task scheduler schedules the tasks by checking the dependencies between tasks and allocating resources accordingly. When a task is scheduled, the resource manager updates its state to reflect the allocation of resources for that task.

The system also has a set of notification mechanisms to ensure the consistency of the system state. The notification mechanism consists of a message queue and a notification service. The message queue is used to send messages between nodes, and the notification service is responsible for handling those messages. When a node changes its state, it sends a notification to all other nodes in the system through the message queue. The notification service then updates its state based on the received notifications.

The system also has a set of monitoring mechanisms to track the usage of resources and tasks. The monitoring mechanism consists of a monitor service and a monitor dashboard. The monitor service tracks the usage of resources and tasks by periodically querying the state of the nodes in the system. The monitor dashboard provides an overview of the usage of resources and tasks for all nodes in the system.

The system also has a set of security mechanisms to ensure the integrity of the system. The security mechanism consists of an access control list (ACL) and encryption. The ACL specifies which users have access to different parts of the system, and encryption is used to protect the communication between nodes.']

