```java
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class CommandExecutor {
  private static final Logger LOGGER = Logger.getLogger(CommandExecutor.class.getName());

  private final ConcurrentHashMap<String, RemoteHost> hosts; // map of host names to remote host objects
  private final ExecutorService executor; // thread pool for executing commands
  private final Config config; // configuration object for command timeouts and logging levels

  public CommandExecutor(Config config) {
    this.config = config;
    this.hosts = new ConcurrentHashMap<>();
    this.executor = Executors.newCachedThreadPool();
  }

  public void addHost(String hostname, String username, String password) throws IOException {
    RemoteHost host = new RemoteHost(hostname, username, password);
    hosts.put(hostname, host);
  }

  public void removeHost(String hostname) {
    hosts.remove(hostname);
  }

  public String executeCommand(String command, List<RemoteHost> hosts) throws IOException {
    return executeCommand(command, hosts, config.getTimeout());
  }

  private String executeCommand(String command, List<RemoteHost> hosts, int timeout) throws IOException {
    // create a new thread pool for the current execution
    ExecutorService executor = Executors.newSingleThreadExecutor();

    // create a list of futures for each host
    List<Future<String>> futures = new ArrayList<>();
    for (RemoteHost host : hosts) {
      futures.add(executor.submit(() -> executeCommandOnHost(command, host)));
    }

    // wait for all futures to complete or timeout
    try {
      executor.shutdown();
      executor.awaitTermination(timeout, TimeUnit.SECONDS);
    } catch (InterruptedException e) {
      LOGGER.log(Level.WARNING, "Command execution timed out", e);
      throw new IOException("Command execution timed out");
    }

    // check for errors and return results
    List<String> results = new ArrayList<>();
    for (Future<String> future : futures) {
      try {
        String result = future.get();
        if (result != null) {
          results.add(result);
        }
      } catch (ExecutionException e) {
        LOGGER.log(Level.WARNING, "Command execution failed", e);
        throw new IOException("Command execution failed");
      }
    }

    // return the combined results of all hosts
    return String.join("\n", results);
  }

  private String executeCommandOnHost(String command, RemoteHost host) throws IOException {
    SSHClient client = new SSHClient();
    try {
      client.connect(host.getHostname(), host.getPort());
      if (client.authenticateWithPassword(host.getUsername(), host.getPassword())) {
        return executeCommandOnSSHClient(command, client);
      } else {
        LOGGER.log(Level.WARNING, "Authentication failed for host " + host.getHostname());
        throw new IOException("Authentication failed");
      }
    } finally {
      client.disconnect();
    }
  }

  private String executeCommandOnSSHClient(String command, SSHClient client) throws IOException {
    SSHConnection connection = client.openConnection();
    try {
      connection.authenticateWithPassword(client.getUsername(), client.getPassword());
      return connection.executeCommand(command);
    } finally {
      connection.close();
    }
  }
}
