// File Format Mapping
var fileFormatMappings = new Dictionary<string, Type>
{
    {"json", typeof(JsonSerializer)},
    {"xml", typeof(XmlSerializer)},
    {"csv", typeof(CsvSerializer)}
};

// Data Source Mapping
var dataSourceMappings = new Dictionary<string, Func<IDataReader>>
{
    {"database", () => new DatabaseDataReader()},
    {"api", () => new ApiDataReader()}
};

// Serializer Factory
public static ISerializer CreateSerializer(FileFormat fileFormat)
{
    if (fileFormatMappings.TryGetValue(fileFormat, out var serializerType))
    {
        return Activator.CreateInstance(serializerType) as ISerializer;
    }
    else
    {
        throw new NotSupportedException($"File format '{fileFormat}' is not supported.");
    }
}

// Data Loader
public static async Task<IEnumerable<T>> LoadDataAsync<T>(string filePath, FileFormat fileFormat)
{
    using var reader = CreateReader(filePath, fileFormat);
    return await reader.ReadAsync<T>().ConfigureAwait(false);
}

// Reader Factory
public static IDataReader CreateReader(string filePath, FileFormat fileFormat)
{
    if (dataSourceMappings.TryGetValue(fileFormat, out var dataSourceFactory))
    {
        return dataSourceFactory();
