using namespace std;

class Semaphore {
    private:
        int value_;
        mutex mtx_;
        condition_variable cv_;
        map<int, bool> clients_; // Map of client IDs to boolean status (true if waiting)

    public:
        Semaphore(int initialValue = 0) : value_(initialValue), clients_() {}

        void initSemaphore(int initialValue) {
            mtx_.lock();
            value_ = initialValue;
            clients_.clear();
            mtx_.unlock();
        }

        bool createSemaphore(int initialValue) {
            try {
                initSemaphore(initialValue);
                return true;
            } catch (...) {
                cout << "Error creating semaphore: " << endl;
                return false;
            }
        }

        bool deleteSemaphore() {
            mtx_.lock();
            clients_.clear();
            mtx_.unlock();

            // Delete the semaphore from the NoSQL database
            try {
                // Insert code to delete the semaphore from the NoSQL database here
                return true;
            } catch (...) {
                cout << "Error deleting semaphore: " << endl;
                return false;
            }
        }

        int getValue() {
            mtx_.lock();
            int value = value_;
            mtx_.unlock();
            return value;
        }

        void setValue(int newValue) {
            mtx_.lock();
            value_ = newValue;
            mtx_.unlock();
        }

        bool waitForSemaphore() {
            unique_lock<mutex> lock(mtx_);

            // If the semaphore is available, decrement its value and return true
            if (value_ > 0) {
                --value_;
                return true;
            }

            // Otherwise, add this client to the map of waiting clients and wait for notification
            auto clientID = getThreadID();
            clients_[clientID] = true;
            cv_.wait(lock);
            return false;
        }

        void notifyAll() {
            unique_lock<mutex> lock(mtx_);

            // Notify all waiting clients and update the map of waiting clients
            for (auto clientID : clients_) {
                cv_.notify_one();
                clients_.erase(clientID);
            }
        }
};
