    std::vector<UEIdentifier> ueIdentifiers(numThreads, {0});

    // Run the simulation in parallel using multiple threads
    std::thread threads[numThreads];
    for (unsigned int i = 0; i < numThreads; ++i) {
        threads[i] = std::thread([&collection, &ueIdentifiers, logger, i]() {
            // Simulate the arrival of power reports from multiple users
            while (true) {
                UEIdentifier id = ueIdentifiers[i];
                TXPowerReport report;
                report.RNTI = id;
                report.timestamp = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count();
                report.powerLevel = 10 + (i % 2) * 5;

                // Add the power report to the collection
                collection.add(report);

                logger->info("Power report added: {}", report);
