2. Implement an adaptive memory management strategy that dynamically allocates and deallocates memory as needed, minimizing heap usage and maximizing spatial locality. Evaluate the trade-offs between static and dynamic memory allocation, considering the impact on garbage collection, fragmentation, and cache performance. Optimize for both small-scale and large-scale graphs, ensuring that the library can adapt to varying workloads and environments.
```c++
#include <iostream>
#include <vector>
#include <map>
#include <utility>
#include <algorithm>

using namespace std;

// Define the basic node structure
struct Node {
    int id; // Unique identifier for the node
    string label; // Label for the node (optional)
    vector<pair<int, double>> edges; // List of edge IDs and weights
};

// Define the basic edge structure
struct Edge {
    int id; // Unique identifier for the edge
    pair<int, int> nodes; // Start and end nodes of the edge
    double weight; // Weight of the edge (optional)
};

// Define the graph structure
class Graph {
private:
    vector<Node> nodes_; // Vector of all nodes in the graph
    map<pair<int, int>, Edge> edges_; // Map of all edges in the graph
public:
    void addNode(const Node& node) { nodes_.push_back(node); }
    void addEdge(const Edge& edge) { edges_[make_pair(edge.nodes.first, edge.nodes.second)] = edge; }
    vector<Node> getNodes() const { return nodes_; }
    map<pair<int, int>, Edge> getEdges() const { return edges_; }
};

// Implement an adaptive memory management strategy that dynamically allocates and deallocates memory as needed, minimizing heap usage and maximizing spatial locality.
class MemoryManager {
private:
    size_t maxHeapSize_; // Maximum allowed heap size
    size_t totalAllocatedSize_; // Total amount of memory allocated so far
    vector<void*> allocatedBlocks_; // Vector of all allocated blocks
public:
    MemoryManager(size_t maxHeapSize) : maxHeapSize_(maxHeapSize), totalAllocatedSize_(0), allocatedBlocks_() {}
    void* allocate(size_t size) {
        if (totalAllocatedSize_ + size > maxHeapSize_) {
            return nullptr;
        }
        void* block = malloc(size);
        allocatedBlocks_.push_back(block);
        totalAllocatedSize_ += size;
        return block;
    }
    void deallocate(void* block) {
        for (auto it = allocatedBlocks_.begin(); it != allocatedBlocks_.end(); ++it) {
            if (*it == block) {
                free(*it);
                allocatedBlocks_.erase(it);
                totalAllocatedSize_ -= size;
                break;
            }
        }
    }
};
```
