// Implement a robust, thread-safe graph update mechanism that supports concurrent modifications and queries while maintaining data integrity.
class GraphManager {
private:
    Graph graph_; // The underlying graph structure
    mutex graphMutex_; // Mutex for protecting the graph from concurrent access
public:
    void addNode(const Node& node) {
        lock_guard<mutex> lock(graphMutex_);
        graph_.addNode(node);
    }
    void addEdge(const Edge& edge) {
        lock_guard<mutex> lock(graphMutex_);
        graph_.addEdge(edge);
    }
