#include <map>
#include <utility>
#include <algorithm>
#include <mutex>

using namespace std;

// Define the basic node structure
struct Node {
    int id; // Unique identifier for the node
    string label; // Label for the node (optional)
    vector<pair<int, double>> edges; // List of edge IDs and weights
};

// Define the basic edge structure
struct Edge {
    int id; // Unique identifier for the edge
    pair<int, int> nodes; // Start and end nodes of the edge
    double weight; // Weight of the edge (optional)
};

// Define a hash table for storing edges by their starting node
class HashTable {
private:
    map<int, vector<pair<int, double>>> table_;
public:
    void addEdge(const Edge& edge) {
        auto it = table_.find(edge.nodes.first);
        if (it != table_.end()) {
            it->second.push_back(make_pair(edge.nodes.second, edge.weight));
        } else {
            vector<pair<int, double>> edges;
            edges.push_back(make_pair(edge.nodes.second, edge.weight));
            table_.insert({edge.nodes.first, edges});
        }
    }
};

// Define a graph structure that uses the hash table for efficient edge retrieval
class Graph {
private:
    vector<Node> nodes_; // Vector of all nodes in the graph
    map<pair<int, int>, Edge> edges_; // Map of all edges in the graph
public:
    void addNode(const Node& node) { nodes_.push_back(node); }
    void addEdge(const Edge& edge) { edges_[make_pair(edge.nodes.first, edge.nodes.second)] = edge; }
    vector<Node> getNodes() const { return nodes_; }
    map<pair<int, int>, Edge> getEdges() const { return edges_; }
};

// Implement a graph library that uses the hash table for efficient edge retrieval and avoids unnecessary memory allocation.
class GraphLibrary {
private:
    HashTable table_; // The underlying hash table structure
public:
