// dynamicBackgroundExecutor.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <time.h>
#include <math.h>

// Configuration settings
#define MAX_TASKS 25
#define THRESHOLD 0.75
#define SIGNAL_BUS_SIZE 10
#define LOG_FILE "dynamicBackgroundExecutor.log"
#define ENV_VAR_PREFIX "MY_ENV_VAR="
#define DEFAULT_ENV_VAR_VALUE "TEST=VALUE"
#define MEMORY_PROFILING_TOOL "memprof"

// Global variables
static int numTasks = 0;
static int maxMemory = -1;
static char *envVarValue = NULL;
static pid_t childPids[MAX_TASKS];
static bool childActive[MAX_TASKS];
static bool signalBus[SIGNAL_BUS_SIZE];
static FILE *logFile = NULL;

// Function prototypes
void initEnvVar();
void initLogging();
int getMaxMemory(void);
void memoryProfileUpdate();
void spawnTask(char *command);
void killTask(pid_t pid, int status);
void handleSignals(int signal);
void cleanup(int exitStatus);

int main(int argc, char **argv) {
  // Initialize environment variable
  initEnvVar();

  // Initialize logging
  initLogging();

  // Set up signal handling
  struct sigaction sa;
  sa.sa_handler = handleSignals;
  sigemptyset(&sa.sa_mask);
  sa.sa_flags = 0;
  if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGQUIT, &sa, NULL) == -1) {
    fprintf(stderr, "Failed to set up signal handling\n");
    exit(EXIT_FAILURE);
  }

  // Start the main loop
  while (true) {
    // Check for new commands from the command line or the GUI
    char *command = getNextCommand();
    if (command != NULL) {
      // Spawn a new task with the given command
      spawnTask(command);
    } else {
      // No more commands available, wait for signals
      pause();
    }
  }
}

// Initialize environment variable value
void initEnvVar() {
  char *envVar = getenv(ENV_VAR_PREFIX);
  if (envVar != NULL) {
    envVarValue = malloc(strlen(envVar) + 1);
    strcpy(envVarValue, envVar);
  } else {
    envVarValue = DEFAULT_ENV_VAR_VALUE;
  }
}

// Initialize logging system
void initLogging() {
  logFile = fopen(LOG_FILE, "w");
  if (logFile == NULL) {
    perror("Failed to open log file");
    exit(EXIT_FAILURE);
  }
}

// Get the maximum amount of memory available on the system
int getMaxMemory(void) {
  int maxMemory = -1;
  FILE *memInfoFile = fopen("/proc/meminfo", "r");
  if (memInfoFile != NULL) {
    char line[256];
    while (fgets(line, sizeof(line), memInfoFile) != NULL) {
      // Check for "MemTotal" line
      if (strncmp("MemTotal", line, strlen("MemTotal")) == 0) {
        maxMemory = atoi(line + strlen("MemTotal:")) * 1024;
        break;
      }
    }
    fclose(memInfoFile);
  }
  return maxMemory;
}

// Update the memory profile tool
void memoryProfileUpdate() {
  char memprofArgs[128];
  sprintf(memprofArgs, "%d", getMaxMemory());
  system(MEMORY_PROFILING_TOOL " -m " memprofArgs);
}

// Spawn a new task with the given command
void spawnTask(char *command) {
  if (numTasks >= MAX_TASKS) {
    fprintf(stderr, "Too many tasks running\n");
    return;
  }
  pid_t pid = fork();
  if (pid == -1) {
    perror("Failed to spawn task");
    return;
  }
  if (pid == 0) {
    // Child process
    setenv(ENV_VAR_PREFIX, envVarValue, true);
    execl("/bin/sh", "sh", "-c", command, NULL);
    perror("Failed to execute task");
    exit(EXIT_FAILURE);
  } else {
    // Parent process
    childPids[numTasks] = pid;
    childActive[numTasks] = true;
    numTasks++;
  }
}

// Kill a task with the given PID and status
void killTask(pid_t pid, int status) {
  for (int i = 0; i < numTasks; i++) {
    if (childPids[i] == pid) {
      childActive[i] = false;
      kill(pid, SIGKILL);
      waitpid(pid, &status, WNOHANG);
      break;
    }
  }
}

// Handle signals by killing tasks and updating the signal bus
void handleSignals(int signal) {
  if (signal == SIGINT || signal == SIGQUIT) {
    // Cleanly exit on INT/QUIT signal
    for (int i = 0; i < numTasks; i++) {
      killTask(childPids[i], 0);
    }
    freeEnvVar();
    fclose(logFile);
    exit(EXIT_SUCCESS);
  } else if (signal == SIGCHLD) {
    // Reap child processes
    while (true) {
      int status = 0;
      pid_t pid = waitpid(-1, &status, WNOHANG);
      if (pid <= 0) break;
      for (int i = 0; i < numTasks; i++) {
        if (childPids[i] == pid) {
          childActive[i] = false;
          break;
        }
      }
    }
  } else if (signal == SIGUSR1) {
    // Update the memory profile tool
    memoryProfileUpdate();
  }
}

// Free the environment variable value
void freeEnvVar() {
  if (envVarValue != DEFAULT_ENV_VAR_VALUE) {
    free(envVarValue);
    envVarValue = NULL;
  }
}

// Close the log file
void closeLogFile() {
  fclose(logFile);
}
