    unordered_map<string, string> data; // Map of keys to values in the node
    vector<string> keys;                // List of all keys stored in the node
    size_t capacity;                    // Capacity of the node
    chrono::time_point<chrono::high_resolution_clock> last_accessed;  // Timestamp of the last access to the node
};

// Define the structure for cache storage
struct CacheStorage {
    unordered_map<string, CacheNode*> nodes;   // Map of keys to nodes in the storage
    vector<CacheNode> nodes_;                 // List of all nodes in the storage
    size_t capacity;                          // Capacity of the storage
};

// Define the structure for cache eviction policies
struct EvictionPolicy {
    string name;                             // Name of the policy
    unordered_map<string, float> weights;   // Weights for each key in the policy
    unordered_map<string, string> nodes;     // Map of keys to nodes in the policy
};

// Define the structure for cache tiered storage systems
struct TieredStorage {
    vector<CacheNode*> nodes_;               // List of all nodes in the storage system
    size_t capacity;                         // Capacity of the storage system
};

// Define the structure for cache load balancing policies
struct LoadBalancingPolicy {
    string name;                             // Name of the policy
    unordered_map<string, float> weights;   // Weights for each node in the policy
};

// Define the structure for cache metrics
struct CacheMetrics {
