    size_t misses;                           // Number of cache misses
    size_t evictions;                        // Number of cache evictions
    chrono::time_point<chrono::high_resolution_clock> last_updated;  // Timestamp of the last update to the metrics
};

// Define the structure for cache node statistics
struct CacheNodeStats {
