};

// Define the structure for cache storage statistics
struct CacheStorageStats {
    size_t hits;                             // Number of cache hits
    size_t misses;                           // Number of cache misses
    size_t evictions;                        // Number of cache evictions
    chrono::time_point<chrono::high_resolution_clock> last_updated;  // Timestamp of the last update to the statistics
};

// Define the structure for cache metrics and storage statistics
struct CacheMetricsStorageStats {
    CacheMetrics metrics_;                   // Metrics of the cache
    CacheStorageStats storage_stats_;        // Statistics of the cache storage
};

// Functions for managing cache nodes
CacheNode* createNode(size_t capacity) {
    CacheNode* node = new CacheNode;
    node->data.reserve(capacity);
    node->keys.reserve(capacity);
    return node;
}

void deleteNode(CacheNode* node) {
    delete node;
}

bool addKeyToNode(CacheNode* node, const string& key) {
