    return true;
}

bool removeKeyFromNode(CacheNode* node, const string& key) {
    // Check if the key exists in the node
    auto it = node->data.find(key);
    if (it == node->data.end()) {
        return false;
    }

    // Remove the key from the node and update the last accessed time
    node->data.erase(it);
    node->keys.pop_back();
    node->last_accessed = chrono::high_resolution_clock::now();

    return true;
}

// Functions for managing cache storage
CacheNode* getNodeForKey(const string& key) {
    // Find the node that contains the key
    auto it = nodes_.find(key);
    if (it == nodes_.end()) {
        return nullptr;
    }

    return it->second;
}

void updateNodeForKey(const string& key, CacheNode* node) {
    // Update the map of keys to nodes
    auto it = nodes_.find(key);
    if (it != nodes_.end()) {
        delete it->second;
    }

    nodes_[key] = node;
}

bool addKeyToStorage(const string& key) {
    // Check if the key already exists in the storage system
    auto it = nodes_.find(key);
    if (it != nodes_.end()) {
        return false;
    }

    // Add the key to the storage system and update the last updated time
    CacheNode* node = createNode(capacity_ / nodes_.size());
    nodes_.push_back({ key, node });
    last_updated = chrono::high_resolution_clock::now();

    return true;
}

bool removeKeyFromStorage(const string& key) {
    // Check if the key exists in the storage system
    auto it = nodes_.find(key);
    if (it == nodes_.end()) {
        return false;
    }

    // Remove the key from the storage system and update the last updated time
    deleteNode(it->second);
    nodes_.erase(it);
    last_updated = chrono::high_resolution_clock::now();

    return true;
}

// Functions for managing cache load balancing policies
void updateLoadBalancingPolicies() {
    // Update the weights of each key in the load balancing policies
    for (auto& policy : load_balancing_policies_) {
        float total_weight = 0;
        for (auto& key : policy.weights) {
            total_weight += key.second;
        }

        // Update the weights of each node in the policy
        for (auto& node : policy.nodes) {
            auto it = nodes_.find(node.first);
            if (it == nodes_.end()) {
                continue;
            }

            float weight = policy.weights[node.first] / total_weight * 100;
            node.second->updateWeight(weight);
        }
    }
}

// Functions for managing cache tiered storage systems
TieredStorage* createTieredStorage(size_t capacity) {
    TieredStorage* storage = new TieredStorage;
    storage->nodes_.reserve(capacity);
    return storage;
}

void deleteTieredStorage(TieredStorage* storage) {
    delete storage;
}

bool addNodeToTieredStorage(TieredStorage* storage, CacheNode* node) {
    // Check if the node already exists in the storage system
    for (auto& it : storage->nodes_) {
        if (it == node) {
            return false;
        }
    }

    storage->nodes_.push_back(node);

    return true;
}

bool removeNodeFromTieredStorage(TieredStorage* storage, CacheNode* node) {
    // Check if the node exists in the storage system
    for (auto it = storage->nodes_.begin(); it != storage->nodes_.end(); ++it) {
        if (*it == node) {
            delete *it;
            storage->nodes_.erase(it);
            return true;
        }
    }

    return false;
}

// Functions for managing cache metrics and storage statistics
CacheMetricsStorageStats getCacheMetricsStorageStats() {
    CacheMetricsStorageStats stats;
    // Update the metrics of the cache
    stats.metrics_ = getCacheMetrics();

    // Update the statistics of the cache storage system
    for (auto& it : nodes_) {
        stats.storage_stats_.hits += it.second->getHits();
        stats.storage_stats_.misses += it.second->getMisses();
        stats.storage_stats_.evictions += it.second->getEvictions();
    }

    return stats;
}

void clearCacheMetricsStorageStats() {
    // Clear the metrics of the cache
    clearCacheMetrics();

    // Clear the statistics of the cache storage system
    for (auto& it : nodes_) {
        it.second->clearNodeStatistics();
    }
}
```

