['package com.logging;

import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.slf4j.event.Level;

public class LoggingFramework {
    private static final Logger logger = LoggerFactory.getLogger(LoggingFramework.class);
    private static final int RETRY_LIMIT = 5;
    private static final long BACKOFF_PERIOD = TimeUnit.SECONDS.toMillis(10);

    public void log(String message, Level level) {
        try {
            logger.log(level, message);
        } catch (Exception e) {
            // Handle configuration failures or internal errors by logging detailed information
            logger.error("Error occurred while logging message: " + message, e);

            int retryCount = 0;
            while (retryCount < RETRY_LIMIT) {
                try {
                    logger.log(level, message);
                    break;
                } catch (Exception ex) {
                    // Handle transient errors by retrying with backoff
                    if (ex instanceof RuntimeException) {
                        throw (RuntimeException) ex;
                    } else {
                        logger.warn("Transient error occurred while logging message: " + message, ex);
                        try {
                            Thread.sleep(BACKOFF_PERIOD);
                        } catch (InterruptedException iex) {
                            // Ignore interruption and continue retrying
                        }
                    }
                }
                retryCount++;
            }
        }
    }
}

