#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <semaphore.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <errno.h>
#include <limits.h>
#include <stdbool.h>
#include <time.h>

#define MAX_RECORDS 10000
#define KEY_LEN 32
#define OFFSET_LEN 64
#define MEMORY_SIZE (MAX_RECORDS * (KEY_LEN + OFFSET_LEN))

typedef struct {
    int key;
    long offset;
} Record;

Record records[MAX_RECORDS];
int record_count = 0;
sem_t semaphore;
pthread_mutex_t mutex;
bool running = true;

void initialize() {
    // Initialize the data structure managing the collection of records
    for (int i = 0; i < MAX_RECORDS; i++) {
        records[i].key = -1;
        records[i].offset = -1;
    }
}

void cleanup() {
    // Clean up all allocated resources
    for (int i = 0; i < record_count; i++) {
        free(records[i].key);
        free(records[i].offset);
    }
}

bool addRecord(int key, long offset) {
    // Add a new record to the data structure
    pthread_mutex_lock(&mutex);
    if (record_count < MAX_RECORDS) {
        records[record_count].key = key;
        records[record_count].offset = offset;
        record_count++;
        pthread_mutex_unlock(&mutex);
        return true;
    } else {
        pthread_mutex_unlock(&mutex);
        return false;
    }
}

bool removeRecord(int key) {
    // Remove a record from the data structure
    bool removed = false;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].key == key) {
            records[i].key = -1;
            records[i].offset = -1;
            record_count--;
            removed = true;
            break;
        }
    }
    return removed;
}

bool updateRecord(int key, long offset) {
    // Update an existing record in the data structure
    bool updated = false;
    for (int i = 0; i < MAX_RECORDS; i++) {
        if (records[i].key == key) {
            records[i].offset = offset;
            updated = true;
            break;
        }
    }
    return updated;
}

void retrieveRecords() {
    // Retrieve all records from the data structure
    for (int i = 0; i < record_count; i++) {
        printf("Record: %d, offset: %ld\n", records[i].key, records[i].offset);
    }
}

void *threadFunc(void *arg) {
    // Thread function to perform operations on the data structure
    while (running) {
        sem_wait(&semaphore);
        // Perform operations on the data structure here
        sem_post(&semaphore);
    }
}

int main() {
    // Initialize the data structure and other resources
    initialize();
    // Start a thread to perform operations on the data structure
    pthread_t thread;
    int ret = pthread_create(&thread, NULL, threadFunc, NULL);
    if (ret != 0) {
        printf("Error creating thread: %d\n", ret);
        return -1;
    }
    // Perform operations on the data structure from the main thread
    while (running) {
        sem_wait(&semaphore);
        // Add or remove records as needed
        if (addRecord(42, 100)) {
            printf("Added record: key = 42, offset = 100\n");
        } else {
            printf("Error adding record: no more space available\n");
        }
        if (removeRecord(87)) {
            printf("Removed record: key = 87\n");
        } else {
            printf("Error removing record: not found\n");
        }
        // Update an existing record
        updateRecord(42, 200);
        // Retrieve all records from the data structure
        retrieveRecords();
        sem_post(&semaphore);
    }
    // Clean up resources before exiting
    cleanup();
    return 0;
}
```

