// CloudServiceManager.h
#include <iostream>
#include <vector>
#include <unordered_map>
#include <mutex>
#include <thread>

class CloudServiceManager {
public:
    CloudServiceManager();
    ~CloudServiceManager();

    void addService(const std::string& serviceName, const std::vector<std::string>& dependencies = {});
    void removeService(const std::string& serviceName);

    void startService(const std::string& serviceName);
    void stopService(const std::string& serviceName);

    void enableService(const std::string& serviceName);
    void disableService(const std::string& serviceName);

    bool isServiceAvailable(const std::string& serviceName) const;
    bool isServiceEnabled(const std::string& serviceName) const;

    void updateDependencies(const std::string& serviceName, const std::vector<std::string>& dependencies);

private:
    struct Service {
        std::string name;
        std::vector<std::string> dependencies;
        bool enabled;
        bool available;

        Service(const std::string& name, const std::vector<std::string>& dependencies) : name(name), dependencies(dependencies), enabled(false), available(true) {}
    };

    std::unordered_map<std::string, Service> services_;
    mutable std::mutex mutex_;

    void startServiceThread();
    void stopServiceThread();

    bool isServiceDependencyAvailable(const std::string& serviceName) const;
};
```

