import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class IoTDataProcessor {
  private static final Logger LOGGER = LoggerFactory.getLogger(IoTDataProcessor.class);

  // Kafka consumer properties
  private static final String BOOTSTRAP_SERVERS = "localhost:9092";
  private static final String GROUP_ID = "iot-data-processor";
  private static final String TOPIC = "iot-data";
  private static final int MAX_POLL_RECORDS = 100;

  // Kafka producer properties
  private static final String PRODUCER_BOOTSTRAP_SERVERS = "localhost:9092";
  private static final String PRODUCER_TOPIC = "iot-analytics";

  // Third-party analytics service properties
  private static final String ANALYTICS_SERVICE_URL = "https://example.com/api/v1/analytics";
  private static final String ANALYTICS_SERVICE_USERNAME = "username";
  private static final String ANALYTICS_SERVICE_PASSWORD = "password";

  // Custom message broker properties
  private static final String MESSAGE_BROKER_URL = "http://localhost:8080/api/v1/messages";
  private static final String MESSAGE_BROKER_USERNAME = "username";
  private static final String MESSAGE_BROKER_PASSWORD = "password";

  // Retry logic properties
  private static final int MAX_RETRIES = 3;
  private static final long RETRY_DELAY = 5000L;

  // Error handling and logging properties
  private static final boolean LOG_ERRORS = true;

  public static void main(String[] args) {
    // Set up the Kafka consumer and producer
    Properties consumerProps = new Properties();
    consumerProps.put("bootstrap.servers", BOOTSTRAP_SERVERS);
    consumerProps.put("group.id", GROUP_ID);
    consumerProps.put("enable.auto.commit", "true");
    consumerProps.put("auto.commit.interval.ms", "1000");
    consumerProps.put("session.timeout.ms", "30000");
    consumerProps.put("key.deserializer", StringDeserializer.class);
    consumerProps.put("value.deserializer", StringSerializer.class);

    Properties producerProps = new Properties();
    producerProps.put("bootstrap.servers", PRODUCER_BOOTSTRAP_SERVERS);
    producerProps.put("acks", "all");
    producerProps.put("retries", 0);
    producerProps.put("batch.size", 16384);
    producerProps.put("linger.ms", 1);
    producerProps.put("buffer.memory", 33554432);
    producerProps.put("key.serializer", StringSerializer.class);
    producerProps.put("value.serializer", StringSerializer.class);

    // Set up the Kafka consumer and producer clients
    KafkaConsumer<String, String> consumer = new KafkaConsumer<>(consumerProps);
    Producer<String, String> producer = new KafkaProducer<>(producerProps);

    // Subscribe to the IoT data topic
    consumer.subscribe(Collections.singletonList(TOPIC));

    while (true) {
      ConsumerRecords<String, String> records = consumer.poll(Duration.ofMillis(1000));

      // Process the IoT data records
      for (ConsumerRecord<String, String> record : records) {
        try {
          processIoTDataRecord(record);
        } catch (Exception e) {
          LOGGER.error("Error processing IoT data record", e);
        }
      }

      // Send the processed data to the third-party analytics service
      sendProcessedDataToAnalyticsService();

      // Send the processed data to the custom message broker
      sendProcessedDataToMessageBroker();
    }
  }

  private static void processIoTDataRecord(ConsumerRecord<String, String> record) {
    LOGGER.info("Received IoT data record: {}", record);

    // Deserialize the IoT data record from JSON to a Java object
    ObjectMapper mapper = new ObjectMapper();
    try {
      IoTData iotData = mapper.readValue(record.value(), IoTData.class);

      // Perform any necessary data processing or validation here
      // ...

      // Send the processed data to the custom message broker
      sendProcessedDataToMessageBroker(iotData);
    } catch (JsonProcessingException e) {
      LOGGER.error("Error deserializing IoT data record", e);
    }
  }

  private static void sendProcessedDataToAnalyticsService() throws Exception {
    // Create a new HTTP POST request to the third-party analytics service
    HttpPost postRequest = new HttpPost(ANALYTICS_SERVICE_URL);

    // Set the authentication credentials for the third-party analytics service
    postRequest.addHeader("Authorization", "Basic " + Base64.getEncoder().encodeToString((ANALYTICS_SERVICE_USERNAME + ":" + ANALYTICS_SERVICE_PASSWORD).getBytes()));

    // Set the JSON payload for the third-party analytics service
    JsonObject jsonPayload = new JsonObject();
    jsonPayload.addProperty("timestamp", Instant.now().toEpochMilli());
    jsonPayload.addProperty("data", "processed data from IoT devices");

    postRequest.setEntity(new StringEntity(jsonPayload.toString()));

    // Execute the HTTP POST request to the third-party analytics service
    CloseableHttpClient httpclient = HttpClients.createDefault();
    try {
      HttpResponse response = httpclient.execute(postRequest);

      if (response.getStatusLine().getStatusCode() != 201) {
        LOGGER.error("Error sending data to analytics service: {}", response.getStatusLine());
      } else {
        LOGGER.info("Data sent to analytics service successfully");
      }
    } finally {
      postRequest.releaseConnection();
    }
  }

  private static void sendProcessedDataToMessageBroker(IoTData iotData) throws Exception {
    // Create a new HTTP POST request to the custom message broker
    HttpPost postRequest = new HttpPost(MESSAGE_BROKER_URL);

    // Set the authentication credentials for the custom message broker
    postRequest.addHeader("Authorization", "Basic " + Base64.getEncoder().encodeToString((MESSAGE_BROKER_USERNAME + ":" + MESSAGE_BROKER_PASSWORD).getBytes()));

    // Set the JSON payload for the custom message broker
    JsonObject jsonPayload = new JsonObject();
    jsonPayload.addProperty("timestamp", Instant.now().toEpochMilli());
    jsonPayload.addProperty("deviceId", iotData.getDeviceId());
    jsonPayload.addProperty("data", "processed data from IoT devices");

    postRequest.setEntity(new StringEntity(jsonPayload.toString()));

    // Execute the HTTP POST request to the custom message broker
    CloseableHttpClient httpclient = HttpClients.createDefault();
    try {
      HttpResponse response = httpclient.execute(postRequest);

      if (response.getStatusLine().getStatusCode() != 201) {
        LOGGER.error("Error sending data to message broker: {}", response.getStatusLine());
      } else {
        LOGGER.info("Data sent to message broker successfully");
      }
    } finally {
      postRequest.releaseConnection();
    }
  }
}
```

This program will continuously poll the `iot-data` topic for new IoT data records, and process them as needed. It will then send the processed data to a third-party analytics service, and finally send the processed data to a custom message broker.

Here are some things to note about this code:

* The `IoTData` class is used to deserialize the JSON payload from the IoT devices into a Java object. This allows us to access specific fields of the data more easily.
* The `processData()` method is where any necessary data processing or validation takes place. In this example, we're simply logging the received data to the console.
* The `sendProcessedDataToAnalyticsService()` and `sendProcessedDataToMessageBroker()` methods are where we send the processed data to the third-party analytics service and custom message broker, respectively. These methods use the `HttpPost` class from Apache HttpComponents to make an HTTP POST request with a JSON payload.
* The `Base64.getEncoder().encodeToString()` method is used to encode the username and password for the authentication credentials of the third-party analytics service and custom message broker, so that they can be included in the HTTP headers.
* The `CloseableHttpClient` class from Apache HttpComponents is used to create an instance of the HTTP client that will be used to send requests to the third-party analytics service and custom message broker. This ensures that resources are properly cleaned up after use, which can help prevent memory leaks or other issues.
* The `releaseConnection()` method is called on the `postRequest` object before it goes out of scope, to ensure that any open connections are properly closed.

This code should be enough to get you started with your own data processing and integration projects using Apache Kafka and Apache HttpComponents. Of course, there are many other libraries and tools available for handling different aspects of the data processing pipeline, so feel free to explore and find what works best for you!']

