using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.IO;

namespace WebApplicationManager
{
    public class Service
    {
        private readonly List<WebApplication> _webApplications = new List<WebApplication>();
        private readonly Dictionary<string, FSA> _fsaCache = new Dictionary<string, FSA>();
        private readonly object _lockObj = new object();

        public async Task StartAsync(int[] currentStates, int numStates, string fsaName, int lastState)
        {
            // Validate input parameters
            if (currentStates == null || currentStates.Length != numStates)
                throw new ArgumentException("Invalid number of states", nameof(currentStates));
            if (numStates <= 0)
                throw new ArgumentOutOfRangeException(nameof(numStates), "Number of states must be positive");
            if (fsaName == null || fsaName.Length == 0)
                throw new ArgumentNullException(nameof(fsaName));
            if (lastState < 0)
                throw new ArgumentOutOfRangeException(nameof(lastState), "Last state must be non-negative");

            // Ensure thread safety when managing multiple concurrent requests for starting and updating web applications
            lock (_lockObj)
            {
                var fsa = GetFSA(fsaName);
                if (fsa == null)
                    throw new InvalidOperationException($"Invalid FSA name: {fsaName}");

                // Allocate memory for a new state list
                try
                {
                    currentStates = new int[numStates];
                }
                catch (OutOfMemoryException)
                {
                    return null;
                }

                // Initialize the new state list with the last state
                currentStates.Initialize();
                currentStates[lastState] = 1;

                // Start the web application
                var webApp = new WebApplication(fsa, currentStates);
                _webApplications.Add(webApp);
            }
        }

        public async Task UpdateAsync(int[] currentStates, int numStates, string fsaName)
        {
            // Validate input parameters
            if (currentStates == null || currentStates.Length != numStates)
                throw new ArgumentException("Invalid number of states", nameof(currentStates));
            if (numStates <= 0)
                throw new ArgumentOutOfRangeException(nameof(numStates), "Number of states must be positive");
            if (fsaName == null || fsaName.Length == 0)
                throw new ArgumentNullException(nameof(fsaName));

            // Ensure thread safety when managing multiple concurrent requests for starting and updating web applications
            lock (_lockObj)
            {
                var fsa = GetFSA(fsaName);
                if (fsa == null)
                    throw new InvalidOperationException($"Invalid FSA name: {fsaName}");

                // Update the state list for the web application
                foreach (var webApp in _webApplications.Where(w => w.FSA == fsa))
                {
                    var newStates = new int[numStates];
                    Array.Copy(currentStates, newStates, Math.Min(newStates.Length, currentStates.Length));
                    webApp.CurrentStates = newStates;
                }
            }
        }

        private FSA GetFSA(string fsaName)
        {
            if (_fsaCache.ContainsKey(fsaName))
                return _fsaCache[fsaName];

            // Load the FSA from disk or some other data source
            var fsaFile = Path.Combine("path", $"{fsaName}.fsa");
            if (!File.Exists(fsaFile))
                throw new InvalidOperationException($"FSA file not found: {fsaFile}");
            var fsaData = File.ReadAllBytes(fsaFile);
            return new FSA(fsaData);
        }
    }

    public class WebApplication
    {
        public FSA FSA { get; set; }
        public int[] CurrentStates { get; set; }

        public WebApplication(FSA fsa, int[] currentStates)
        {
            FSA = fsa;
            CurrentStates = currentStates;
        }
    }

    public class FSA
    {
        private readonly byte[] _data;

        public FSA(byte[] data)
        {
            _data = data;
        }
    }
}

