using Newtonsoft.Json;

public class DataIngestionPipeline
{
    private readonly List<IDataDeserializer> _deserializers = new List<IDataDeserializer>();

    public DataIngestionPipeline()
    {
        _deserializers.Add(new JsonDataDeserializer());
        _deserializers.Add(new CsvDataDeserializer());
        _deserializers.Add(new TxtDataDeserializer());
    }

    public async Task<List<object>> DeserializeAsync(Stream data, int fileSize)
    {
        var deserializer = GetDeserializer(data);
        return await deserializer.DeserializeAsync(data, fileSize);
    }

    private IDataDeserializer GetDeserializer(Stream data)
    {
        var magicBytes = new byte[4];
        data.Read(magicBytes, 0, 4);
        foreach (var deserializer in _deserializers)
        {
            if (deserializer.CanDeserialize(magicBytes))
            {
                return deserializer;
            }
        }
        throw new NotSupportedException("The file format is not supported.");
    }
}

public interface IDataDeserializer
{
    bool CanDeserialize(byte[] magicBytes);
    Task<List<object>> DeserializeAsync(Stream data, int fileSize);
}

public class JsonDataDeserializer : IDataDeserializer
{
    public bool CanDeserialize(byte[] magicBytes)
    {
        return magicBytes[0] == '{' && magicBytes[1] == '"' && magicBytes[2] == '"';
    }

    public async Task<List<object>> DeserializeAsync(Stream data, int fileSize)
    {
        var json = await new StreamReader(data).ReadToEndAsync();
        return JsonConvert.DeserializeObject<List<object>>(json);
    }
}

public class CsvDataDeserializer : IDataDeserializer
{
    public bool CanDeserialize(byte[] magicBytes)
    {
        return magicBytes[0] == '\"' && magicBytes[1] == '"';
    }

    public async Task<List<object>> DeserializeAsync(Stream data, int fileSize)
    {
        var csv = await new StreamReader(data).ReadToEndAsync();
        return CsvHelper.DeserializeCsvToList<object>(csv);
    }
}

public class TxtDataDeserializer : IDataDeserializer
{
    public bool CanDeserialize(byte[] magicBytes)
    {
        return magicBytes[0] == '{' && magicBytes[1] == '"' && magicBytes[2] == '"';
    }

    public async Task<List<object>> DeserializeAsync(Stream data, int fileSize)
    {
        var txt = await new StreamReader(data).ReadToEndAsync();
        return TxtHelper.DeserializeTxtToList<object>(txt);
    }
}
```
