// Set up connection pooling and idle timeouts for efficient resource management
const MAX_CONCURRENT_REQUESTS = 10;
const IDLE_TIMEOUT = 60 * 1000; // 1 minute
let activeRequests = [];

// Define retry logic with exponential backoff strategies for transient errors
function retry(operation, options) {
  const MAX_RETRIES = 3;
  let retries = 0;
  let lastError;

  return operation()
    .catch((error) => {
      lastError = error;
      if (retries < MAX_RETRIES && isTransientError(error)) {
        console.log(`Retrying operation after ${Math.pow(2, retries)} seconds...`);
        return new Promise((resolve, reject) => {
          setTimeout(() => resolve(retry(operation, options)), Math.pow(2, retries) * 1000);
        });
      } else {
        throw lastError;
      }
    })
}

