Here is a sample implementation of a modular, scalable, and secure middleware service in C# that integrates with multiple third-party authentication and identity services:
```
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.Extensions.Caching.Redis;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using OAuth2;
using SAML;

namespace MiddlewareService
{
    public class AuthenticationMiddleware : IMiddleware
    {
        private readonly ILogger<AuthenticationMiddleware> _logger;
        private readonly IConfiguration _configuration;
        private readonly IDistributedCache _cache;
        private readonly OAuth2Client _oauth2Client;
        private readonly SAMLClient _samlClient;

        public AuthenticationMiddleware(ILogger<AuthenticationMiddleware> logger, IConfiguration configuration)
        {
            _logger = logger;
            _configuration = configuration;
            _cache = new RedisDistributedCache(_configuration.GetValue<string>("RedisConnectionString"));
            _oauth2Client = new OAuth2Client(new Uri(_configuration.GetValue<string>("OAuth2Url")));
            _samlClient = new SAMLClient(new Uri(_configuration.GetValue<string>("SAMLUrl")));
        }

        public async Task InvokeAsync(HttpContext context)
        {
            var userId = await GetUserIdAsync(context);

            if (userId != null)
            {
                _logger.LogInformation($"User {userId} authenticated successfully.");

                // Add user ID to the request context
                context.Items["UserId"] = userId;

                // Proceed to next middleware in the pipeline
                await Next(context);
            }
            else
            {
                _logger.LogInformation($"Authentication failed.");

                // Redirect to login page
                var loginPath = "/login";
                context.Response.Redirect(loginPath);
            }
        }

        private async Task<string> GetUserIdAsync(HttpContext context)
        {
            // Check if user ID is already in the request context
            if (context.Items.ContainsKey("UserId"))
            {
                return (string)context.Items["UserId"];
            }

            // Extract authentication data from the request headers
            var authHeader = context.Request.Headers["Authorization"].FirstOrDefault();
            if (!string.IsNullOrEmpty(authHeader))
            {
                // Validate authorization header using OAuth2 or SAML
                if (authHeader.StartsWith("Bearer "))
                {
                    var accessToken = authHeader.Substring("Bearer ".Length);
                    return await _oauth2Client.GetUserIdAsync(accessToken);
                }
                else if (authHeader.StartsWith("SAML"))
                {
                    var samlResponse = authHeader.Substring("SAML".Length);
                    return await _samlClient.GetUserIdAsync(samlResponse);
                }
            }

            // No authentication data found, try to read user ID from session cache
            var sessionCacheKey = context.Session?.Id ?? "";
            if (!string.IsNullOrEmpty(sessionCacheKey))
            {
                return await _cache.GetStringAsync(sessionCacheKey);
            }

            // No user ID found, authentication failed
            return null;
        }
    }
}
```
