// Define a structure to hold resource bundle metadata
typedef struct {
    char* name;
    char* contentType;
    size_t size;
} ResourceBundle;

// Define a function to load a resource bundle from a remote API
static void* loadResourceFromRemoteAPI(const char* url) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "Failed to initialize cURL\n");
        return NULL;
    }

    // Set up the request and perform it
    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);
    curl_easy_setopt(curl, CURLOPT_USERAGENT, "resourceLoader/1.0");
    curl_easy_setopt(curl, CURLOPT_ACCEPT_ENCODING, "identity");
    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to load resource from %s: %s\n", url, curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return NULL;
    }

    // Get the response body and size
    char* body = NULL;
    size_t size = 0;
    res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &size);
    if (res != CURLE_OK) {
        fprintf(stderr, "Failed to get response body from %s: %s\n", url, curl_easy_strerror(res));
        curl_easy_cleanup(curl);
        return NULL;
    }

    // Allocate memory for the resource bundle and copy the response body
    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        fprintf(stderr, "Failed to allocate memory for resource bundle\n");
        curl_easy_cleanup(curl);
        return NULL;
    }
    bundle->name = malloc(strlen(url) + 1);
    if (!bundle->name) {
        fprintf(stderr, "Failed to allocate memory for resource name\n");
        free(bundle);
        curl_easy_cleanup(curl);
        return NULL;
    }
    strcpy(bundle->name, url);
    bundle->contentType = malloc(strlen("text/plain") + 1);
    if (!bundle->contentType) {
        fprintf(stderr, "Failed to allocate memory for content type\n");
        free(bundle->name);
        free(bundle);
        curl_easy_cleanup(curl);
        return NULL;
    }
    strcpy(bundle->contentType, "text/plain");
    bundle->size = size;
    if (size > 0) {
        body = malloc(size + 1);
        if (!body) {
            fprintf(stderr, "Failed to allocate memory for resource body\n");
            free(bundle->name);
            free(bundle->contentType);
            free(bundle);
            curl_easy_cleanup(curl);
            return NULL;
        }
        strcpy(body, res);
    } else {
        fprintf(stderr, "Failed to retrieve response body from %s: %s\n", url, curl_easy_strerror(res));
        free(bundle->name);
        free(bundle->contentType);
        free(bundle);
        curl_easy_cleanup(curl);
        return NULL;
    }

    // Clean up cURL resources and return the resource bundle
    curl_easy_cleanup(curl);
    return bundle;
}

// Define a function to load a resource bundle from a local file
static void* loadResourceFromLocalFile(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        fprintf(stderr, "Failed to open %s: %s\n", filename, strerror(errno));
        return NULL;
    }

    // Get the file size and allocate memory for the resource bundle
    struct stat st;
    if (fstat(fileno(file), &st) == -1) {
        fprintf(stderr, "Failed to get file size of %s: %s\n", filename, strerror(errno));
        fclose(file);
        return NULL;
    }
    long size = st.st_size;
    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        fprintf(stderr, "Failed to allocate memory for resource bundle\n");
        fclose(file);
        return NULL;
    }
    bundle->name = malloc(strlen(filename) + 1);
    if (!bundle->name) {
        fprintf(stderr, "Failed to allocate memory for resource name\n");
        free(bundle);
        fclose(file);
        return NULL;
    }
    strcpy(bundle->name, filename);
    bundle->contentType = malloc(strlen("text/plain") + 1);
    if (!bundle->contentType) {
        fprintf(stderr, "Failed to allocate memory for content type\n");
        free(bundle->name);
        free(bundle);
        fclose(file);
        return NULL;
    }
    strcpy(bundle->contentType, "text/plain");
    bundle->size = size;
    if (size > 0) {
        char* data = malloc(size + 1);
        if (!data) {
            fprintf(stderr, "Failed to allocate memory for resource body\n");
            free(bundle->name);
            free(bundle->contentType);
            free(bundle);
            fclose(file);
            return NULL;
        }
        size_t n = fread(data, 1, size, file);
        if (n != size) {
            fprintf(stderr, "Failed to read %ld bytes from %s: %s\n", size, filename, strerror(errno));
            free(data);
            free(bundle->name);
            free(bundle->contentType);
            free(bundle);
            fclose(file);
            return NULL;
        }
        data[size] = '\0';
        bundle->body = data;
    } else {
        fprintf(stderr, "Failed to read from %s: %s\n", filename, strerror(errno));
        free(bundle->name);
        free(bundle->contentType);
        free(bundle);
        fclose(file);
        return NULL;
    }

    // Clean up and return the resource bundle
    fclose(file);
    return bundle;
}

