    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &responseCode);
    if (responseCode != 200) {
        fprintf(stderr, "Received non-OK response code %ld from %s\n", responseCode, url);
        curl_easy_cleanup(curl);
