    }

    // Allocate memory for the resource bundle and copy the response body
    ResourceBundle* bundle = malloc(sizeof(ResourceBundle));
    if (!bundle) {
        fprintf(stderr, "Failed to allocate memory for resource bundle\n");
        curl_easy_cleanup(curl);
        return NULL;
    }
    bundle->name = malloc(strlen(url) + 1);
    if (!bundle->name) {
        fprintf(stderr, "Failed to allocate memory for resource name\n");
        free(bundle);
        curl_easy_cleanup(curl);
        return NULL;
    }
    strcpy(bundle->name, url);
    bundle->contentType = malloc(strlen("text/plain") + 1);
    if (!bundle->contentType) {
        fprintf(stderr, "Failed to allocate memory for resource content type\n");
        free(bundle->name);
        free(bundle);
        curl_easy_cleanup(curl);
        return NULL;
    }
    strcpy(bundle->contentType, "text/plain");
    bundle->size = size;
    char* data = malloc(size + 1);
    if (!data) {
        fprintf(stderr, "Failed to allocate memory for resource body\n");
        free(bundle->name);
        free(bundle->contentType);
        free(bundle);
        curl_easy_cleanup(curl);
        return NULL;
    }
    data[size] = '\0';
    bundle->body = data;

    // Clean up and return the resource bundle
    curl_easy_cleanup(curl);
    return bundle;
}

// Define a function to free a resource bundle
static void freeResourceBundle(void* bundle) {
    ResourceBundle* b = (ResourceBundle*)bundle;
    if (b->body != NULL) {
        free(b->body);
    }
    free(b);
}

// Define a function to write the response body to a file
static size_t write_callback(void* contents, size_t size, size_t nmemb, void* userp) {
    ((struct write_info*)userp)->size += size * nmemb;
    char* buf = malloc(size * nmemb + 1);
    if (buf == NULL) {
        return 0;
    }
    memcpy(buf, contents, size * nmemb);
    buf[size * nmemb] = '\0';
    struct write_info* info = (struct write_info*)userp;
    if (info->stream != NULL) {
        fprintf(info->stream, "%s", buf);
    }
    free(buf);
    return size * nmemb;
}

int main() {
