    }
    // Print the contents of the resource bundle
    printf("Name: %s\n", bundle->name);
    printf("Content Type: %s\n", bundle->contentType);
    printf("Size: %ld bytes\n", bundle->size);
    printf("Body:\n%s\n", bundle->body);
    // Free the resource bundle
    freeResourceBundle(bundle);
    return 0;
}
