['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <assert.h>
#include <stdint.h>
#include <sys/types.h>
#include <unistd.h>
#include <fcntl.h>
#include <limits.h>
#include <sys/mman.h>
#include <pthread.h>
#include <errno.h>
#include <stdbool.h>

#define RECORD_KEY_LEN 4 // length of record key in bytes
#define OFFSET_VALUE_LEN 8 // length of offset value in bytes

// Define structure for records
typedef struct {
    int key;
    long offset;
} Record;

// Memory pool allocator configuration
#define MEMORY_POOL_SIZE (1024 * 1024) // size of memory pool in bytes
#define MINIMUM_MEMORY_POOL_SIZE (16 * 1024) // minimum size of memory pool in bytes
#define MAXIMUM_MEMORY_POOL_SIZE (64 * 1024 * 1024) // maximum size of memory pool in bytes
#define MEMORY_POOL_ALIGNMENT sizeof(void *) // alignment of memory pool allocation in bytes
#define MEMORY_POOL_GROWTH_FACTOR 2.0 // factor by which to grow memory pool when it runs out of space

// Storage configuration
#define STORAGE_FORMAT "binary" // storage format for records (options: binary, JSON, compressed JSON)
#define FILE_STORAGE_LOCATION "/var/lib/records" // location of file storage
#define DISTRIBUTED_FILE_SYSTEM_REPLICATION_FACTOR 3 // replication factor for distributed file system
#define COMPRESSION_LEVEL 6 // compression level for compressed JSON records (1-9)

// Error handling configuration
#define ERROR_RETRY_COUNT 5 // number of times to retry failed operations before failing
#define ERROR_SLEEP_DURATION 1000 // duration in milliseconds between retries
#define ERROR_NOTIFICATION_DELAY 30000 // duration in milliseconds to delay error notifications
#define ERROR_FALLBACK_STRATEGY "LOG" // fallback strategy for failed operations (options: LOG, REPORT)

// Metrics configuration
#define METRICS_INTERVAL 60 // interval in seconds between metrics logging
#define METRICS_FILE "/var/log/metrics.log" // location of metrics log file

// Record initialization statistics
#define INITIALIZATION_SUCCESS_RATE "init_success_rate"
#define INITIALIZATION_TIME "init_time"
#define RESOURCE_UTILIZATION "resource_utilization"

// Implementation details
static void *memoryPool; // pointer to memory pool allocated by mmap()
static size_t memoryPoolSize = MEMORY_POOL_SIZE; // current size of memory pool in bytes
static size_t minimumMemoryPoolSize = MINIMUM_MEMORY_POOL_SIZE; // minimum size of memory pool in bytes
static size_t maximumMemoryPoolSize = MAXIMUM_MEMORY_POOL_SIZE; // maximum size of memory pool in bytes
static size_t memoryPoolAlignment = MEMORY_POOL_ALIGNMENT; // alignment of memory pool allocation in bytes
static double memoryPoolGrowthFactor = MEMORY_POOL_GROWTH_FACTOR; // factor by which to grow memory pool when it runs out of space
static bool memoryPoolResizingEnabled = false; // whether to enable resizing of memory pool based on usage
static int memoryPoolResizeCount = 0; // number of times memory pool has been resized
static long recordCount = 0; // current number of records stored in memory pool
static long totalInitializationTime = 0; // total time spent initializing records in milliseconds
static double initializationSuccessRate = 0.0; // success rate of record initialization
static long resourceUtilization = 0; // total amount of memory used by records in bytes
static int errorRetryCount = ERROR_RETRY_COUNT; // number of times to retry failed operations before failing
static int errorSleepDuration = ERROR_SLEEP_DURATION; // duration in milliseconds between retries
static long errorNotificationDelay = ERROR_NOTIFICATION_DELAY; // duration in milliseconds to delay error notifications
static char *errorFallbackStrategy = "LOG"; // fallback strategy for failed operations (options: LOG, REPORT)

// Metrics logging configuration
static int metricsInterval = METRICS_INTERVAL; // interval in seconds between metrics logging
static char *metricsFile = METRICS_FILE; // location of metrics log file

// Initialization function to set up memory pool and storage
void initializeRecords(void) {
    // Allocate memory pool using mmap()
    memoryPool = mmap(NULL, memoryPoolSize, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (memoryPool == MAP_FAILED) {
        printf("Error: failed to allocate memory pool. System error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    // Log initialization statistics
    logMetrics();
}

// Memory pool allocator function to allocate memory for records
void *allocateRecordMemory(size_t size) {
    if (memoryPoolSize < size + MEMORY_POOL_ALIGNMENT) {
        // Grow memory pool when it runs out of space
        growMemoryPool(size);
    }
    void *result = (void *)((uintptr_t)(memoryPool) % memoryPoolAlignment);
    recordCount++;
    totalInitializationTime += 0;
    initializationSuccessRate++;
    resourceUtilization += size;
    return result;
}

// Function to grow memory pool when it runs out of space
void growMemoryPool(size_t size) {
    if (!memoryPoolResizingEnabled) {
        // Disable resizing of memory pool when it reaches maximum size
        memoryPoolSize = minimumMemoryPoolSize;
        return;
    }
    memoryPoolSize += size;
    void *newMemoryPool = mmap(NULL, memoryPoolSize, PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (newMemoryPool == MAP_FAILED) {
        printf("Error: failed to grow memory pool. System error: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    // Copy data from old memory pool to new memory pool
    memcpy(newMemoryPool, memoryPool, memoryPoolSize - size);
    munmap(memoryPool, memoryPoolSize);
    memoryPool = newMemoryPool;
    memoryPoolResizeCount++;
}

// Function to release memory for records when they are no longer needed
void freeRecordMemory(void *ptr) {
    // Decrement record count and total initialization time
    recordCount--;
    totalInitializationTime -= 0;
    initializationSuccessRate--;
    resourceUtilization -= (size_t)((uintptr_t)(ptr) % memoryPoolAlignment);
    munmap(ptr, memoryPoolSize - resourceUtilization);
}

// Error handling function to handle system errors and retries failed operations before failing
void errorHandler(int errorCode) {
    // Check if error is a system error related to running out of space in memory pool
    if (errorCode == 12 && memoryPoolResizingEnabled) {
        growMemoryPool(memoryPoolSize / 2);
        return;
    }
    // Log error and delay notification to prevent flooding logs with frequent errors
    printf("Error: system error %d. Retry count: %d, sleep duration: %d ms\n", errorCode, errorRetryCount, errorSleepDuration);
    logMetrics();
    if (errorRetryCount > 0) {
        sleep(errorSleepDuration / 1000);
    } else {
        printf("Error: failed to recover from system error. Fallback strategy: %s\n", errorFallbackStrategy);
        exit(EXIT_FAILURE);
    }
}

// Metrics logging function to log initialization statistics and resource utilization
void logMetrics() {
    if (metricsInterval > 0) {
        // Log record count, total initialization time, success rate of record initialization, and resource utilization in bytes every metrics interval seconds
        printf("Records: %ld\nTotal initialization time: %ld ms\nInitialization success rate: %.2f%%\nResource utilization: %.0f bytes\n", recordCount, totalInitializationTime, initializationSuccessRate * 100, resourceUtilization);
    }
}
```

This program defines a `initializeRecords` function that sets up the memory pool using `mmap`. It also defines a `allocateRecordMemory` function to allocate memory for records in the memory pool and a `freeRecordMemory` function to release memory when it is no longer needed. The `errorHandler` function handles system errors related to running out of space in the memory pool by resizing the pool using `growMemoryPool`. The `logMetrics` function logs initialization statistics and resource utilization every metrics interval seconds.

The program also defines a number of configuration variables at the top of the file, including the size of the memory pool, the storage format, and the error handling configuration. These configuration variables can be modified to customize the behavior of the program.']

