        record->value = rand() % 100 + 1; // Random value within the specified range using a provided seed
        array->records[i] = record;
    }

    // Initialize the capacity and count of the array
    array->capacity = 10;
    array->count = 10;
}

// Define a function to truncate a string if necessary, or return NULL if it does not exceed the specified size limit.
char *truncateStringIfNecessary(const char *string, int sizeLimit) {
    // Validate the input parameters
    assert(string != NULL && sizeLimit > 0);

    // Get the length of the string
    int length = strlen(string);

    // Check if the string exceeds the specified size limit
    if (length <= sizeLimit) {
        return (char *)string;
    } else {
        char *truncatedString = malloc(sizeLimit + 1);
        assert(truncatedString != NULL);
        memcpy(truncatedString, string, sizeLimit - 1);
        truncatedString[sizeLimit] = '\0';
        return truncatedString;
    }
}
