public:
    std::string algorithm;
    int mode;
    std::string key;
};

// Encryption queue entry
struct EncryptionQueueEntry {
    std::string plaintext;
    EncryptionConfig config;
    std::mutex mutex;
    std::condition_variable cv;
};

// Decryption queue entry
struct DecryptionQueueEntry {
    std::string ciphertext;
    EncryptionConfig config;
    std::mutex mutex;
    std::condition_variable cv;
};

// Key management module
class KeyManagementModule {
public:
    // Generate new encryption key
    std::string generateKey();

    // Store encryption key in memory
    void storeKey(const std::string& key);

    // Retrieve encryption key from memory
    std::string retrieveKey(const std::string& key);

    // Rotate encryption key
    void rotateKey(const std::string& oldKey, const std::string& newKey);

    // Revoke encryption key
    void revokeKey(const std::string& key);
};

// Performance metrics module
