public:
    // Record encryption throughput
    void recordEncryptionThroughput(float throughput);

    // Record decryption throughput
    void recordDecryptionThroughput(float throughput);

    // Record latency statistics
    void recordLatencyStatistics(const std::chrono::duration<double>& duration);

    // Record error rates
    void recordErrorRates(float errorRate);

    // Record memory usage profile
    void recordMemoryUsageProfile(size_t memoryUsage);
};

// Asynchronous encryption function
