    // Create queue entry
    EncryptionQueueEntry entry;
    entry.plaintext = plaintext;
    entry.config = config;

    // Lock mutex and wait for encryption to complete
    std::unique_lock<std::mutex> lock(entry.mutex);
    while (!entry.cv.wait_for(lock, std::chrono::seconds(10), [&] { return entry.ciphertext.size() > 0; })) {
        // Handle timeout and error cases
    }

    // Unlock mutex and return ciphertext
    lock.unlock();
    return entry.ciphertext;
}

// Asynchronous decryption function
void decryptDataAsync(const std::string& ciphertext, const EncryptionConfig& config) {
    // Create queue entry
    DecryptionQueueEntry entry;
    entry.ciphertext = ciphertext;
    entry.config = config;

    // Lock mutex and wait for decryption to complete
    std::unique_lock<std::mutex> lock(entry.mutex);
    while (!entry.cv.wait_for(lock, std::chrono::seconds(10), [&] { return entry.plaintext.size() > 0; })) {
        // Handle timeout and error cases
    }

    // Unlock mutex and return plaintext
    lock.unlock();
    return entry.plaintext;
}

