    std::optional<std::string> retrieve(const std::string& key) {
        return _preferences.find(key) != _preferences.end() ? std::make_optional(_preferences[key]) : std::nullopt;
    }

private:
    // Map to store user preferences
    std::map<std::string, std::string> _preferences;
