// Define a message class to represent messages between devices
class Message {
public:
    // Constructor
    Message(const std::string& from, const std::string& to, const std::string& payload) : _from(from), _to(to), _payload(payload) {}

    // Getter functions for the message fields
    std::string getFrom() { return _from; }
    std::string getTo() { return _to; }
    std::string getPayload() { return _payload; }

private:
    // The sender and receiver of the message
    std::string _from;
    std::string _to;

    // The payload of the message
    std::string _payload;
};

// Define a message queue class to store and retrieve messages
class MessageQueue {
public:
    // Insert a new message into the queue
    void insert(const Message& message) { _messages.push_back(message); }

    // Retrieve the next available message from the queue
    std::optional<Message> retrieve() {
        if (_messages.empty()) {
            return std::nullopt;
        } else {
            auto message = _messages.front();
            _messages.pop_front();
            return std::make_optional(message);
        }
    }

private:
    // Queue to store messages
    std::deque<Message> _messages;
};

// Define a device class to represent devices in the system
