public:
    // Add a new device to the system
    void addDevice(const std::string& name, const std::string& address) {
        _devices[name] = std::make_unique<Device>(name, address);
    }

    // Remove a device from the system
    void removeDevice(const std::string& name) {
        _devices.erase(name);
    }

    // Getter function to retrieve all devices in the system
    const std::map<std::string, std::unique_ptr<Device>>& getDevices() { return _devices; }

private:
    // Map to store devices by their names
    std::map<std::string, std::unique_ptr<Device>> _devices;
};

// Define a message broker class to handle messages between devices
class MessageBroker {
public:
    // Constructor
    MessageBroker(const DeviceManager& deviceManager) : _deviceManager(deviceManager) {}

    // Publish a message from a sender device to all receiver devices
    void publish(const std::string& from, const std::string& payload) {
        for (auto& [name, device] : _deviceManager.getDevices()) {
            if (device->getAddress() != from) {
                Message message(from, name, payload);
                _messageQueue.insert(message);
            }
        }
    }

    // Subscribe to messages from a specific sender device
    void subscribe(const std::string& from) {
        _subscribers.insert(from);
    }

    // Retrieve the next available message from the queue and return it
    std::optional<Message> retrieve() {
        if (_messageQueue.empty()) {
            return std::nullopt;
        } else {
            auto message = _messageQueue.retrieve();
            if (message.has_value()) {
                if (_subscribers.find(message->getFrom()) != _subscribers.end()) {
                    return message;
                }
            }
        }
        return std::nullopt;
    }

private:
    // The device manager to retrieve devices from the system
    const DeviceManager& _deviceManager;

    // Map to store subscribed sender devices by their addresses
    std::set<std::string> _subscribers;

    // Queue to store messages for delivery
    MessageQueue _messageQueue;
};

