// Define the session ID type and the Session class
using SessionID = std::string;
class Session {
    public:
        // Constructor for creating a new session
        Session(SessionID id, const std::vector<std::string>& args) :
            _id(id), _args(args) {}

        // Destructor for destroying the session
        ~Session() {}

        // Accessors for the session ID and arguments
        SessionID get_id() { return _id; }
        const std::vector<std::string>& get_args() { return _args; }

    private:
        SessionID _id;
        std::vector<std::string> _args;
};

// Define the CommandLineTool class
class CommandLineTool {
    public:
        // Constructor for creating a new tool instance
        CommandLineTool(int argc, char* argv[]) :
            _argc(argc), _argv(argv) {}

        // Destructor for destroying the tool instance
        ~CommandLineTool() {}

        // Parse the command-line arguments and create a new session
        Session parse_args() {
            // Check if the --case-sensitive argument was passed
            bool case_sensitive = false;
            for (int i = 1; i < _argc; ++i) {
                if (_argv[i] == "--case-sensitive") {
                    case_sensitive = true;
                }
            }

            // Check if the --output argument was passed
            std::string output_file;
            for (int i = 1; i < _argc; ++i) {
                if (_argv[i] == "--output") {
                    output_file = _argv[i + 1];
                }
            }

            // Check if the --count argument was passed
            int line_count = 0;
            for (int i = 1; i < _argc; ++i) {
                if (_argv[i] == "--count") {
                    line_count = std::stoi(_argv[i + 1]);
                }
            }

            // Create a new session with the appropriate arguments
            return Session(SessionID::generate(), { case_sensitive, output_file, line_count });
        }

        // Process the input data and write it to the output file
        void process_input(const std::vector<std::string>& input) {
            // Check if a session ID was passed as an argument
            SessionID id;
            for (int i = 1; i < _argc; ++i) {
                if (_argv[i] == "--session") {
                    id = std::string(_argv[i + 1]);
                }
            }

            // Create a new session with the appropriate arguments
            Session session(id, _args);

            // Check if the input is from a file or piped data
            std::ifstream infile;
            if (session.get_args().at(1) == "--input-from-file") {
                infile.open(session.get_args().at(2));
            } else {
                infile = std::cin;
            }

            // Check if the output is to a file or stdout
            std::ofstream outfile;
            if (session.get_args().at(1) == "--output-to-file") {
                outfile.open(session.get_args().at(2));
            } else {
                outfile = std::cout;
            }

            // Process the input data and write it to the output file
            while (infile >> std::ws) {
                std::string line = infile.rdbuf()->str();
                if (session.get_args().at(0)) {
                    for (char& c : line) {
                        c = std::tolower(c);
                    }
                }
                outfile << line << std::endl;
            }
        }
};

// Define the cross-language library class
class Library {
    public:
        // Constructor for creating a new instance of the library
        Library() {}

        // Destructor for destroying the library instance
        ~Library() {}

        // Parse the command-line arguments and create a new session
        Session parse_args(int argc, char* argv[]) {
            return CommandLineTool(argc, argv).parse_args();
        }

        // Process the input data and write it to the output file
        void process_input(const std::vector<std::string>& input) {
            CommandLineTool().process_input(input);
        }
};

// Main function for running the tool
int main(int argc, char* argv[]) {
    // Create a new instance of the library class
    Library lib;

    // Parse the command-line arguments and create a new session
    Session session = lib.parse_args(argc, argv);

    // Check if the input is from a file or piped data
