    if (session.get_args().at(1) == "--output-to-file") {
        outfile.open(session.get_args().at(2));
    } else {
        outfile = std::cout;
    }

    // Process the input data and write it to the output file
    while (infile >> std::ws) {
        std::string line = infile.rdbuf()->str();
        if (session.get_args().at(0)) {
            for (char& c : line) {
                c = std::tolower(c);
            }
        }
        outfile << line << std::endl;
