    std::string uuid;
    std::chrono::time_point<std::chrono::system_clock> timestamp;
    uint32_t sessionDuration;
    std::vector<std::string> activities;
};

struct ExternalAPIResponse {
    bool success;
    std::string errorMessage;
};

// Define a concurrent hash map for storing user activity logs and their corresponding external API responses
using UserActivityLogMap = std::map<std::string, ExternalAPIResponse>;

// Define a class for managing user activity logs and integrating with external APIs
class ActivityLogger {
public:
    // Constructor to initialize the logger with an external API object
    explicit ActivityLogger(std::shared_ptr<ExternalAPI> api) : api_(api) {}

    // Function to add a new user activity log entry
    void AddLogEntry(const UserActivityLog& log) {
        std::lock_guard<std::mutex> lock(mutex_);
        logs_.push_back(log);
    }

    // Function to retrieve all user activity log entries for a given UUID
    std::vector<UserActivityLog> GetAllLogEntriesForUuid(const std::string& uuid) {
        std::lock_guard<std::mutex> lock(mutex_);
        return std::find_if(logs_.begin(), logs_.end(), [uuid](const UserActivityLog& log) {
            return log.uuid == uuid;
        });
    }

    // Function to update an existing user activity log entry
    void UpdateLogEntry(const UserActivityLog& log) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = std::find_if(logs_.begin(), logs_.end(), [uuid](const UserActivityLog& log) {
            return log.uuid == uuid;
        });
        if (it != logs_.end()) {
            *it = log;
        }
    }

    // Function to delete a user activity log entry for a given UUID
    void DeleteLogEntry(const std::string& uuid) {
        std::lock_guard<std::mutex> lock(mutex_);
        logs_.erase(std::remove_if(logs_.begin(), logs_.end(), [uuid](const UserActivityLog& log) {
            return log.uuid == uuid;
        }), logs_.end());
    }

private:
    // External API object to be used for synchronization and logging purposes
    std::shared_ptr<ExternalAPI> api_;

    // Vector of user activity logs
    std::vector<UserActivityLog> logs_;

    // Mutex for thread-safe access to the vector of user activity logs
    std::mutex mutex_;
};

// Define a class for managing the user activity log map and integrating with external APIs
