Here's an example of a C# function that processes high-volume transactions, filtering them based on age, transaction volume in the last three seconds, and a weighted sum calculation:
```csharp
using System;
using System.Linq;
using System.Collections.Generic;

public class TransactionProcessor {
    private readonly List<Transaction> _transactions = new List<Transaction>();
    private readonly Dictionary<string, decimal> _weightedSums = new Dictionary<string, decimal>();

    public void ProcessTransactions(IEnumerable<Transaction> transactions) {
        foreach (var transaction in transactions) {
            // Filter transactions based on age and volume in the last three seconds
            if (transaction.Timestamp > DateTime.UtcNow.AddSeconds(-3)) {
                continue;
            }

            // Calculate weighted sum for each unique ID
            var id = transaction.Id;
            decimal weightedSum = 0;
            if (_weightedSums.ContainsKey(id)) {
                weightedSum = _weightedSums[id];
            }
            weightedSum += transaction.Amount * transaction.Weight;
            _weightedSums[id] = weightedSum;
        }
    }

    public (string, decimal) GetMaximumWeightedSum() {
        return (_transactions.OrderByDescending(t => t.WeightedSum).First().Id, _transactions.OrderByDescending(t => t.WeightedSum).First().WeightedSum);
    }
}
```
