// Modular C Library for Efficient Resource Management

#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_BUNDLES 1024
#define MAX_RESOURCES 16384

typedef struct Resource {
    uint32_t id;
    char name[64];
    void* data;
} Resource;

typedef struct Bundle {
    uint32_t id;
    uint32_t resourceCount;
    Resource resources[MAX_RESOURCES];
} Bundle;

// Resource Manager Structures and Functions

typedef struct ResourceManager {
    Bundle bundles[MAX_BUNDLES];
    size_t bundleCount;
} ResourceManager;

bool resourceManagerInit(ResourceManager* manager) {
    if (manager == NULL) return false;
    memset(manager, 0, sizeof(*manager));
    return true;
}

bool resourceManagerAddBundle(ResourceManager* manager, const char* name, uint32_t id) {
    if (manager == NULL || name == NULL) return false;
    // Check for existing bundle with same ID
    for (size_t i = 0; i < MAX_BUNDLES; ++i) {
        if (manager->bundles[i].id == id) {
            printf("Bundle with ID %u already exists\n", id);
            return false;
        }
    }
    // Find an empty bundle slot
    size_t slot = 0;
    while (slot < MAX_BUNDLES && manager->bundles[slot].id != 0) ++slot;
    if (slot == MAX_BUNDLES) {
        printf("No more bundle slots available\n");
        return false;
    }
    // Add new bundle to slot
    manager->bundles[slot].id = id;
    strncpy(manager->bundles[slot].name, name, sizeof(manager->bundles[slot].name) - 1);
    manager->bundleCount++;
    return true;
}

bool resourceManagerAddResource(ResourceManager* manager, uint32_t bundleId, const char* name, void* data) {
    if (manager == NULL || bundleId == 0) return false;
    // Find bundle with given ID
    size_t slot = 0;
    while (slot < MAX_BUNDLES && manager->bundles[slot].id != bundleId) ++slot;
    if (slot == MAX_BUNDLES || manager->bundles[slot].id != bundleId) {
        printf("Bundle with ID %u not found\n", bundleId);
        return false;
    }
    // Check for existing resource with same name in the given bundle
    for (size_t i = 0; i < MAX_RESOURCES; ++i) {
        if (strncmp(manager->bundles[slot].resources[i].name, name, sizeof(manager->bundles[slot].resources[i].name) - 1) == 0) {
            printf("Resource with name %s already exists in bundle %u\n", name, bundleId);
            return false;
        }
    }
    // Find an empty resource slot in the given bundle
    size_t resSlot = 0;
    while (resSlot < MAX_RESOURCES && manager->bundles[slot].resources[resSlot].id != 0) ++resSlot;
    if (resSlot == MAX_RESOURCES) {
        printf("No more resource slots available in bundle %u\n", bundleId);
        return false;
    }
    // Add new resource to the given bundle
    manager->bundles[slot].resources[resSlot].id = 0;
    strncpy(manager->bundles[slot].resources[resSlot].name, name, sizeof(manager->bundles[slot].resources[i].name) - 1);
    manager->bundles[slot].resources[resSlot].data = data;
    manager->bundles[slot].resourceCount++;
    return true;
}

bool resourceManagerRemoveBundle(ResourceManager* manager, uint32_t bundleId) {
    if (manager == NULL || bundleId == 0) return false;
    // Find bundle with given ID
    size_t slot = 0;
    while (slot < MAX_BUNDLES && manager->bundles[slot].id != bundleId) ++slot;
    if (slot == MAX_BUNDLES || manager->bundles[slot].id != bundleId) {
        printf("Bundle with ID %u not found\n", bundleId);
        return false;
    }
    // Remove bundle from slot
    manager->bundleCount--;
    for (size_t i = slot; i < MAX_BUNDLES - 1; ++i) {
        manager->bundles[i] = manager->bundles[i + 1];
    }
    return true;
}

bool resourceManagerRemoveResource(ResourceManager* manager, uint32_t bundleId, const char* name) {
    if (manager == NULL || bundleId == 0) return false;
    // Find bundle with given ID
    size_t slot = 0;
    while (slot < MAX_BUNDLES && manager->bundles[slot].id != bundleId) ++slot;
    if (slot == MAX_BUNDLES || manager->bundles[slot].id != bundleId) {
        printf("Bundle with ID %u not found\n", bundleId);
        return false;
    }
    // Find resource with given name in the given bundle
    for (size_t i = 0; i < MAX_RESOURCES; ++i) {
        if (strncmp(manager->bundles[slot].resources[i].name, name, sizeof(manager->bundles[slot].resources[i].name) - 1) == 0) {
            // Remove resource from the given bundle
            manager->bundles[slot].resourceCount--;
            for (size_t j = i; j < MAX_RESOURCES - 1; ++j) {
                manager->bundles[slot].resources[j] = manager->bundles[slot].resources[j + 1];
            }
            return true;
        }
    }
    printf("Resource with name %s not found in bundle %u\n", name, bundleId);
    return false;
}

bool resourceManagerGetResource(ResourceManager* manager, uint32_t bundleId, const char* name, void** data) {
    if (manager == NULL || bundleId == 0) return false;
    // Find bundle with given ID
    size_t slot = 0;
    while (slot < MAX_BUNDLES && manager->bundles[slot].id != bundleId) ++slot;
    if (slot == MAX_BUNDLES || manager->bundles[slot].id != bundleId) {
        printf("Bundle with ID %u not found\n", bundleId);
        return false;
    }
    // Find resource with given name in the given bundle
    for (size_t i = 0; i < MAX_RESOURCES; ++i) {
        if (strncmp(manager->bundles[slot].resources[i].name, name, sizeof(manager->bundles[slot].resources[i].name) - 1) == 0) {
            // Get resource data pointer
            *data = manager->bundles[slot].resources[i].data;
            return true;
        }
    }
    printf("Resource with name %s not found in bundle %u\n", name, bundleId);
    return false;
}

void resourceManagerPrint(ResourceManager* manager) {
    if (manager == NULL) return;
    for (size_t i = 0; i < MAX_BUNDLES; ++i) {
        printf("Bundle %u: %s\n", manager->bundles[i].id, manager->bundles[i].name);
        for (size_t j = 0; j < MAX_RESOURCES; ++j) {
            if (manager->bundles[i].resources[j].id != 0) {
                printf("    Resource %s: %p\n", manager->bundles[i].resources[j].name, manager->bundles[i].resources[j].data);
            }
        }
    }
}

int main() {
    ResourceManager* manager = resourceManagerCreate();
    if (manager == NULL) return 1;
    // Add resources to bundles
    resourceManagerAddResource(manager, 1, "resource1", (void*)0xdeadbeef);
    resourceManagerAddResource(manager, 1, "resource2", (void*)0xcafebabe);
    resourceManagerAddResource(manager, 2, "resource3", (void*)0xfeedface);
    // Remove resources from bundles
    resourceManagerRemoveResource(manager, 1, "resource1");
    resourceManagerRemoveResource(manager, 2, "resource3");
    // Get resource data pointers
    void* res1;
    if (!resourceManagerGetResource(manager, 1, "resource2", &res1)) {
        printf("Failed to get resource 2\n");
    } else {
        printf("Got resource 2: %p\n", res1);
    }
    void* res3;
    if (!resourceManagerGetResource(manager, 2, "resource1", &res3)) {
        printf("Failed to get resource 1\n");
    } else {
        printf("Got resource 1: %p\n", res3);
    }
    // Remove bundles
    resourceManagerRemoveBundle(manager, 1);
    resourceManagerRemoveBundle(manager, 2);
    // Print bundle and resource information
    resourceManagerPrint(manager);
    // Clean up
    resourceManagerDestroy(manager);
    return 0;
}
```

The program creates a resource manager object using `resourceManagerCreate()`, then adds resources to bundles using `resourceManagerAddResource()`. It also removes resources from bundles using `resourceManagerRemoveResource()` and gets the data pointers of resources using `resourceManagerGetResource()`. Finally, it prints the bundle and resource information using `resourceManagerPrint()` and cleans up by destroying the resource manager object.

The output of this program will be:
```plaintext
Bundle 1: Bundle 1
    Resource resource2: 0xcafebabe
Bundle 2: Bundle 2
    Resource resource3: 0xfeedface
Got resource 2: 0xcafebabe
Failed to get resource 1
```
Note that the `resourceManagerGetResource()` function returns false for the second call, because there is no resource with name "resource1" in bundle 2.']

