#include <pthread.h>
#include <curl/curl.h>
#include "resource_bundle.h"

struct resource_bundle {
    char *data;
    size_t data_size;
    struct curl_slist *cache;
};

static pthread_mutex_t fetch_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t fetch_cond = PTHREAD_COND_INITIALIZER;
static resource_bundle *fetched_resource_bundles = NULL;
static size_t num_fetched_resource_bundles = 0;
static int max_num_fetched_resource_bundles = 0;
static int max_cache_size = 1024*1024*1024; // 1GB default cache size
static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cache_cond = PTHREAD_COND_INITIALIZER;
static resource_bundle *cache = NULL;
static size_t num_cache_entries = 0;
static int max_num_cache_entries = 1024*1024; // 1MB default cache size
static pthread_mutex_t cache_size_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cache_size_cond = PTHREAD_COND_INITIALIZER;

// fetches the resource bundle with the given ID from the distributed configuration service
// returns NULL if the resource is not found or on error
void *fetchResourceBundle(const char *resource_id) {
    void *resource_bundle = NULL;
    CURL *curl;
    CURLcode res;
    struct curl_slist *cache;

    // create a new cache entry if the resource ID is not in the cache yet
    pthread_mutex_lock(&cache_lock);
    size_t i;
    for (i = 0; i < num_cache_entries; ++i) {
        if (strcmp(resource_id, cache[i].data) == 0) {
            resource_bundle = &cache[i];
            break;
        }
    }
    if (!resource_bundle) {
        // allocate a new cache entry and populate it with the fetched data
        resource_bundle = malloc(sizeof(struct resource_bundle));
        resource_bundle->data = NULL;
        resource_bundle->data_size = 0;
        resource_bundle->cache = NULL;
        if (!resource_bundle) {
            pthread_mutex_unlock(&cache_lock);
            return NULL;
        }

        // perform the fetch and populate the cache entry
        curl = curl_easy_init();
        if (curl) {
            char url[1024];
            snprintf(url, sizeof(url), "http://distributed-configuration.com/resource/%s", resource_id);
            curl_easy_setopt(curl, CURLOPT_URL, url);
            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                fprintf(stderr, "fetchResourceBundle: failed to fetch resource bundle with ID %s\n", resource_id);
                curl_easy_cleanup(curl);
                return NULL;
            }
            cache = curl_easy_getinfo(curl, CURLINFO_HEADER_OUT);
            if (!cache) {
                fprintf(stderr, "fetchResourceBundle: failed to retrieve cache headers for resource bundle with ID %s\n", resource_id);
                curl_easy_cleanup(curl);
                return NULL;
            }
            char *data = curl_easy_strerror(res);
            size_t data_size = strlen(data);
            if (data_size > 0) {
                resource_bundle->data = malloc(data_size + 1);
                memcpy(resource_bundle->data, data, data_size);
                resource_bundle->data[data_size] = '\0';
                resource_bundle->data_size = data_size;
                resource_bundle->cache = cache;
            } else {
                fprintf(stderr, "fetchResourceBundle: failed to load resource bundle with ID %s\n", resource_id);
                curl_easy_cleanup(curl);
                return NULL;
            }
        }

        // add the new cache entry to the list of fetched bundles
        pthread_mutex_lock(&fetch_lock);
        if (num_fetched_resource_bundles >= max_num_fetched_resource_bundles) {
            void *new_fetched_resource_bundles = realloc(fetched_resource_bundles, (max_num_fetched_resource_bundles + 1) * sizeof(struct resource_bundle));
            if (!new_fetched_resource_bundles) {
                fprintf(stderr, "fetchResourceBundle: failed to allocate memory for new fetched resource bundle\n");
                pthread_mutex_unlock(&fetch_lock);
                free(resource_bundle->data);
                free(resource_bundle);
                return NULL;
            }
            fetched_resource_bundles = new_fetched_resource_bundles;
        }
        fetched_resource_bundles[num_fetched_resource_bundles++] = resource_bundle;
        pthread_cond_broadcast(&fetch_cond);
        pthread_mutex_unlock(&fetch_lock);
    } else {
        // update the cache entry with the current timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        resource_bundle->cache = curl_slist_append(resource_bundle->cache, "Timestamp:");
        char *timestamp = malloc(1024);
        if (!timestamp) {
            fprintf(stderr, "fetchResourceBundle: failed to allocate memory for timestamp\n");
            pthread_mutex_unlock(&cache_lock);
            return NULL;
        }
        snprintf(timestamp, 1024, "%d-%09lu", ts.tv_sec, ts.tv_nsec);
        resource_bundle->cache = curl_slist_append(resource_bundle->cache, timestamp);
        free(timestamp);
    }
    pthread_mutex_unlock(&cache_lock);

    return resource_bundle;
}

// returns the resource bundle with the given ID, or NULL if it is not found
void *getResourceBundle(const char *resource_id) {
    void *resource_bundle = NULL;
    pthread_mutex_lock(&cache_lock);
    size_t i;
    for (i = 0; i < num_cache_entries; ++i) {
        if (strcmp(resource_id, cache[i].data) == 0) {
            resource_bundle = &cache[i];
            break;
        }
    }
    pthread_mutex_unlock(&cache_lock);
    return resource_bundle;
}

// returns the size of the resource bundle with the given ID, or 0 if it is not found
size_t getResourceBundleSize(const char *resource_id) {
    size_t size = 0;
    void *resource_bundle = getResourceBundle(resource_id);
    if (resource_bundle) {
        struct curl_slist *entry = resource_bundle->cache;
        while (entry != NULL) {
            size += strlen(entry->data);
            entry = entry->next;
        }
    }
    return size;
}

// frees the memory allocated for a resource bundle
void freeResourceBundle(void *resource_bundle) {
    if (resource_bundle) {
        struct curl_slist *entry = resource_bundle->cache;
        while (entry != NULL) {
            entry = entry->next;
        }
    }
}
