// LogManager.java
package com.example;

import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class LogManager {
    private static final Logger logger = LoggerFactory.getLogger(LogManager.class);

    // Constants
    private static final int LOG_QUEUE_SIZE = 10000;
    private static final int MIN_LOG_FLUSH_INTERVAL = 5;
    private static final int MAX_LOG_FLUSH_INTERVAL = 60;
    private static final int RETRY_COUNT = 3;
    private static final boolean USE_EXTERNAL_ALERTER = true;
    private static final String LOG_FILE_PATH = "/var/log/example-logs";
    private static final String DEFAULT_LOG_LEVEL = "INFO";
    private static final String DEFAULT_OUTPUT_FORMAT = "JSON";
    private static final String DEFAULT_ALERTING_SYSTEM = "PagerDuty";

    // Fields
    private volatile Queue<LogEntry> logQueue;
    private ScheduledExecutorService scheduler;
    private Map<String, AlertingSystem> alertingSystems;

    public LogManager() {
        logQueue = new LinkedBlockingDeque<>(LOG_QUEUE_SIZE);
        scheduler = Executors.newSingleThreadScheduledExecutor();
        alertingSystems = new HashMap<>();

        // Initialize alerting systems
        if (USE_EXTERNAL_ALERTER) {
            initExternalAlertingSystems();
        }
    }

    public void log(LogEntry entry) {
        try {
            logQueue.put(entry);
        } catch (InterruptedException e) {
            logger.error("Failed to put log entry in queue", e);
        }
    }

    private void initExternalAlertingSystems() {
        alertingSystems.put("PagerDuty", new PagerDutyAlertingSystem());
        alertingSystems.put("Slack", new SlackAlertingSystem());
        alertingSystems.put("Email", new EmailAlertingSystem());
    }

    public void flushLogQueue() {
        // Flush the log queue
        while (!logQueue.isEmpty()) {
            LogEntry entry = logQueue.poll();
            if (entry != null) {
                try {
                    sendLogEntryToAlertingSystem(entry);
                } catch (Exception e) {
                    logger.error("Failed to send log entry to alerting system", e);
                }
            }
        }
    }

    private void sendLogEntryToAlertingSystem(LogEntry entry) throws Exception {
        AlertingSystem system = getAlertingSystem(entry.getAlertingSystem());
        system.sendNotification(entry.getErrorMessage(), entry.getContext());
    }

    public void setLogLevel(String logLevel) {
        // Set the log level for all alerting systems
        for (Map.Entry<String, AlertingSystem> entry : alertingSystems.entrySet()) {
            entry.getValue().setLogLevel(logLevel);
        }
    }

    public void setOutputFormat(String outputFormat) {
        // Set the output format for all alerting systems
        for (Map.Entry<String, AlertingSystem> entry : alertingSystems.entrySet()) {
            entry.getValue().setOutputFormat(outputFormat);
        }
    }

    public void setFilePath(String filePath) {
        // Set the file path for all alerting systems
        for (Map.Entry<String, AlertingSystem> entry : alertingSystems.entrySet()) {
            entry.getValue().setFilePath(filePath);
        }
    }

    public void setRetryCount(int retryCount) {
        // Set the retry count for all alerting systems
        for (Map.Entry<String, AlertingSystem> entry : alertingSystems.entrySet()) {
            entry.getValue().setRetryCount(retryCount);
        }
    }

    public void setUseExternalAlerter(boolean useExternalAlerter) {
        // Set the use external alerter flag for all alerting systems
        for (Map.Entry<String, AlertingSystem> entry : alertingSystems.entrySet()) {
            entry.getValue().setUseExternalAlerter(useExternalAlerter);
        }
    }
}
