from datetime import datetime
from collections import deque

class LogManager:
    def __init__(self):
        self.log_queue = deque()
        self.loggers = {}

    def add_logger(self, name, level=logging.INFO):
        if name not in self.loggers:
            self.loggers[name] = logging.getLogger(name)
            self.loggers[name].setLevel(level)

        return self.loggers[name]

    def log(self, level, message):
        if level == "info":
            level = logging.INFO
        elif level == "warning":
            level = logging.WARNING
        elif level == "error":
            level = logging.ERROR

        self.log_queue.append((level, message))

    def process_logs(self):
        while self.log_queue:
            level, message = self.log_queue.popleft()

            for logger in self.loggers.values():
                if level >= logger.level:
                    logger.log(level, message)

    def start(self):
        while True:
            try:
                self.process_logs()
            except Exception as e:
                print("Error processing logs:", str(e))
            time.sleep(1)

if __name__ == "__main__":
    logging.basicConfig(format="%(asctime)s - %(levelname)s - %(message)s")

    log_manager = LogManager()
    log_manager.add_logger("example")

    log_manager.log("info", "This is an informational message")
    log_manager.log("warning", "This is a warning message")
    log_manager.log("error", "This is an error message")

    try:
        raise ValueError("This is an error")
    except ValueError as e:
        log_manager.log("error", str(e))

    log_manager.start()']

