import logging
from typing import Dict, List, Optional

class LoggingFramework:
    """
    A scalable logging framework that supports multiple backends (file, console, cloud storage) and integrates with a distributed configuration management system for dynamic fetching of logging levels, formats, and retention policies.
    """

    def __init__(self, config: Dict[str, str], backends: List[logging.Handler]):
        self._config = config
        self._backends = backends

    def log(self, message: str, level: int, metadata: Optional[Dict[str, str]] = None):
        """
        Log a message with the specified severity level and metadata.
        """
        for backend in self._backends:
            if backend.should_log(level, metadata):
                backend.log(message, level, metadata)

    def get_config(self, key: str) -> Optional[str]:
        """
        Get the value of a configuration setting from the distributed configuration management system.
        """
        return self._config.get(key)

    @staticmethod
    def parse_logging_level(level: str) -> int:
        """
        Parse a logging level string to an integer representation.
        """
        if level == "DEBUG":
            return logging.DEBUG
        elif level == "INFO":
            return logging.INFO
        elif level == "WARNING":
            return logging.WARNING
        elif level == "ERROR":
            return logging.ERROR
        else:
            raise ValueError(f"Invalid logging level: {level}")

    @staticmethod
    def parse_log_format(format_string: str) -> List[str]:
        """
        Parse a log format string into a list of fields.
        """
        return format_string.split()

    @staticmethod
    def parse_retention_policy(policy_string: str) -> int:
        """
        Parse a retention policy string to an integer representation.
        """
        if policy_string == "INFINITE":
            return float("inf")
        else:
            try:
                return int(policy_string)
            except ValueError:
                raise ValueError(f"Invalid retention policy: {policy_string}")

    @staticmethod
    def load_configuration():
        """
        Load the logging configuration from the distributed configuration management system.
        """
        # Fetch the logging configuration from the distributed configuration management system
        config = get_config()

        # Parse the logging levels, formats, and retention policies from the configuration
        log_levels = {k: LoggingFramework.parse_logging_level(v) for k, v in config["log_levels"].items()}
        log_formats = {k: LoggingFramework.parse_log_format(v) for k, v in config["log_formats"].items()}
        retention_policies = {k: LoggingFramework.parse_retention_policy(v) for k, v in config["retention_policies"].items()}

        # Initialize the logging framework with the parsed configuration
        logging_framework = LoggingFramework(config=config, backends=[])

        # Add the configured logging backends to the framework
        for backend_name, backend_config in config["backends"].items():
            if backend_name == "file":
                backend = FileBackend(filename=backend_config["filename"])
            elif backend_name == "console":
                backend = ConsoleBackend()
            elif backend_name == "cloud_storage":
                backend = CloudStorageBackend(bucket_name=backend_config["bucket_name"], prefix=backend_config["prefix"])
            else:
                raise ValueError(f"Invalid logging backend name: {backend_name}")
            logging_framework.add_backend(backend)

        return logging_framework, log_levels, log_formats, retention_policies

class FileBackend(logging.Handler):
    """
    A logging backend that writes to a file on the local filesystem.
    """
    def __init__(self, filename: str):
        self._filename = filename
        super().__init__()

    def should_log(self, level: int, metadata: Optional[Dict[str, str]]) -> bool:
        return True

    def log(self, message: str, level: int, metadata: Optional[Dict[str, str]] = None):
        with open(self._filename, "a") as f:
            f.write(message + "\n")

class ConsoleBackend(logging.Handler):
    """
    A logging backend that writes to the console (stdout or stderr).
    """
    def __init__(self):
        super().__init__()

    def should_log(self, level: int, metadata: Optional[Dict[str, str]]) -> bool:
        return True

    def log(self, message: str, level: int, metadata: Optional[Dict[str, str]] = None):
        print(message)

class CloudStorageBackend(logging.Handler):
    """
    A logging backend that writes to a cloud storage service (e.g., AWS S3 or GCS).
    """
    def __init__(self, bucket_name: str, prefix: str):
        self._bucket_name = bucket_name
        self._prefix = prefix
        super().__init__()

    def should_log(self, level: int, metadata: Optional[Dict[str, str]]) -> bool:
        return True

    def log(self, message: str, level: int, metadata: Optional[Dict[str, str]] = None):
        # Upload the log message to the cloud storage service
        upload_to_cloud_storage(bucket_name=self._bucket_name, prefix=self._prefix, data=message)

def get_config() -> Dict[str, str]:
    """
    Fetch the logging configuration from the distributed configuration management system.
    """
    # Simulate a request to the distributed configuration management system
    config = {
        "log_levels": {"DEBUG": "10", "INFO": "20", "WARNING": "30", "ERROR": "40"},
        "log_formats": {"default": "%(asctime)s - %(name)s - %(levelname)s - %(message)s"},
        "retention_policies": {"INFINITE": "inf", "10_DAYS": "864000", "30_DAYS": "2592000"},
        "backends": {
            "file": {"filename": "/path/to/log.txt"},
            "console": {},
            "cloud_storage": {"bucket_name": "my-bucket", "prefix": "logs"}
        }
    }
    return config

def upload_to_cloud_storage(bucket_name: str, prefix: str, data: bytes):
    """
    Simulate an upload to a cloud storage service.
    """
    print(f"Uploading log message to bucket {bucket_name} with prefix {prefix}")
