For the `themeManager` function, we can use a state machine to manage theme bitmap processing in low-power modes. Here's an example implementation:
```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_THEMES 1024
#define MAX_BITMAPS 1024
#define MAX_CACHE_SIZE (1024 * 1024) // 1 MB

typedef struct {
    char* theme;
    int num_bitmaps;
    int bitmap_sizes[MAX_BITMAPS];
} ThemeInfo;

typedef struct {
    char* filename;
    size_t file_size;
    void* data;
    pthread_mutex_t mutex; // used for synchronization
} BitmapData;

// state machine states
enum State {
    IDLE,
    BUSY,
    PAUSED
};

// state machine transitions
int transition(enum State state, enum State next) {
    if (state == IDLE && next == BUSY) {
        // start processing themes
        return 1;
    } else if (state == BUSY && next == PAUSED) {
        // pause processing themes
        return 1;
    } else if (state == PAUSED && next == IDLE) {
        // resume processing themes
        return 1;
    } else {
        return 0;
    }
}

// state machine functions
void idle_func(ThemeInfo* theme) {
    printf("Theme %s is available\n", theme->theme);
}

void busy_func(ThemeInfo* theme) {
    // download bitmaps for theme
    int num_bitmaps = theme->num_bitmaps;
    for (int i = 0; i < num_bitmaps; i++) {
        int bitmap_size = theme->bitmap_sizes[i];
        char* filename = theme->bitmap_filenames[i];
        download_bitmap(filename, bitmap_size);
    }
}

void paused_func(ThemeInfo* theme) {
    // pause downloading bitmaps for theme
}

// main function
int main() {
    ThemeInfo themes[MAX_THEMES];
    BitmapData bitmaps[MAX_BITMAPS];
    int num_themes = 0;
    int num_bitmaps = 0;

    enum State state = IDLE;

    while (1) {
        if (state == IDLE) {
            // check for new themes
            num_themes = check_for_new_themes(themes, MAX_THEMES);
            if (num_themes > 0) {
                state = BUSY;
            }
        } else if (state == BUSY) {
            // process themes
            for (int i = 0; i < num_themes; i++) {
                ThemeInfo* theme = &themes[i];
                transition(state, state);
            }
        } else if (state == PAUSED) {
            // pause processing themes
        }
    }

    return 0;
}
