For the `UnstructuredLogComponent` class, we can use a data structure to manage a collection of records, each with an integer key and a long offset. Here's an example implementation:
```c++
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <memory>
#include <mutex>

using namespace std;

class UnstructuredLogComponent {
private:
    // data structure to manage a collection of records
    struct Record {
        int key;
        long offset;
        string value;
    };

    vector<Record> records;
    unordered_map<int, Record*> recordMap;
    mutex recordLock;

public:
    UnstructuredLogComponent() {}

    ~UnstructuredLogComponent() {
        // clean up allocated resources
        for (auto& record : records) {
            delete record.value;
        }
    }

    int addRecord(int key, long offset, string value) {
        lock_guard<mutex> lock(recordLock);

        Record* newRecord = new Record();
        newRecord->key = key;
        newRecord->offset = offset;
        newRecord->value = move(value);

        records.push_back(*newRecord);
        recordMap[key] = newRecord;

        return 1;
    }

    int removeRecord(int key) {
        lock_guard<mutex> lock(recordLock);

        auto it = recordMap.find(key);
        if (it != recordMap.end()) {
            Record* record = it->second;
            records.erase(records.begin() + it->first);
            delete record;

            return 1;
        } else {
            return 0;
        }
    }

    string getRecordValue(int key) {
        lock_guard<mutex> lock(recordLock);

        auto it = recordMap.find(key);
        if (it != recordMap.end()) {
            Record* record = it->second;
            return record->value;
        } else {
            return "";
        }
    }
};
```
For the `UnstructuredLogDataset` class, we can use a combination of a hash table and a vector to efficiently manage a large dataset of unstructured log records. Here's an example implementation:
```c++
#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>

using namespace std;

class UnstructuredLogDataset {
private:
    // hash table to map keys to records
    unordered_map<int, string> keyMap;

    // vector to store all the records
    vector<string> records;

    mutex recordLock;

public:
    UnstructuredLogDataset() {}

    ~UnstructuredLogDataset() {
        // clean up allocated resources
        for (auto& record : records) {
            delete record.value;
        }
    }

    int addRecord(int key, string value) {
        lock_guard<mutex> lock(recordLock);

        auto it = keyMap.find(key);
        if (it != keyMap.end()) {
            records[it->second] = move(value);
        } else {
            keyMap[key] = records.size();
            records.push_back(move(value));
        }

        return 1;
    }

    int removeRecord(int key) {
        lock_guard<mutex> lock(recordLock);

        auto it = keyMap.find(key);
        if (it != keyMap.end()) {
            string value = records[it->second];
            records.erase(records.begin() + it->second);
            delete value;

            return 1;
        } else {
            return 0;
        }
    }

    string getRecordValue(int key) {
        lock_guard<mutex> lock(recordLock);

        auto it = keyMap.find(key);
        if (it != keyMap.end()) {
            return records[it->second];
        } else {
            return "";
        }
    }
};
```
Note that these are just examples and may need to be modified based on the specific requirements of your application. Additionally, you should make sure that any data structures or classes used in this way are properly thread-safe to avoid race conditions and other issues.']

