    for (i = 0; i < MAX_INSTANCES; i++) {
        for (j = 0; j < MAX_DATASET_SIZE; j++) {
            uf->parent[i][j] = -1;
        }
    }

    // Set up thread-safe data structures and synchronization mechanisms for ensuring reliable operation in a highly concurrent environment
    pthread_mutex_t mutex;
    pthread_cond_t cond;

    // Define the main processing loop
    while (1) {
        // Acquire the semaphore to access the union-find data structure
        sem_wait(&semaphore);

        // Determine disjoint sets of nodes using the union-find algorithm
        for (i = 0; i < MAX_INSTANCES; i++) {
            for (j = 0; j < MAX_DATASET_SIZE; j++) {
                if (uf->parent[i][j] != -1) {
                    // Find the representative node of the current disjoint set
                    int rep = find(uf, i, j);

                    // Update the representative node's parent and child pointers
                    uf->parent[rep][j] = uf->parent[i][j];
                    uf->parent[i][j] = rep;
                }
            }
        }

        // Release the semaphore to allow other instances to access the union-find data structure
        sem_post(&semaphore);

        // Query the graph database and external data ecosystem for each disjoint set of nodes
        for (i = 0; i < MAX_INSTANCES; i++) {
            for (j = 0; j < MAX_DATASET_SIZE; j++) {
                if (uf->parent[i][j] != -1) {
                    // Query the graph database and external data ecosystem for the current node
                    int node = uf->parent[i][j];

                    // Update the node's information in the union-find data structure
                    update(uf, i, j);
                }
            }
        }

        // Synchronize access to the union-find data structure and output the average latency between all pairs of nodes within each disjoint set
        sem_wait(&semaphore);
        for (i = 0; i < MAX_INSTANCES; i++) {
            for (j = 0; j < MAX_DATASET_SIZE; j++) {
                if (uf->parent[i][j] != -1) {
                    // Calculate the average latency between all pairs of nodes within the current disjoint set
                    int avg_latency = calculate_average_latency(uf, i, j);

                    // Output the average latency and log a warning message if the set contains fewer than five nodes
                    printf("Average latency between all pairs of nodes within disjoint set %d: %d\n", i, avg_latency);
                }
            }
        }
        sem_post(&semaphore);

        // Sleep for a short period to ensure efficient resource allocation and minimize pauses due to garbage collection
        usleep(100000);
    }

    return 0;
}

// Define the union-find algorithm used for determining disjoint sets of nodes
int find(struct union_find *uf, int i, int j) {
    // Recursively search for the representative node of the current disjoint set
    if (uf->parent[i][j] == -1) {
        return i;
    } else {
        return find(uf, uf->parent[i][j], j);
    }
}

// Define the update method used for updating a node's information in the union-find data structure
void update(struct union_find *uf, int i, int j) {
    // Update the node's parent and child pointers
    uf->parent[i][j] = find(uf, i, j);
}

// Define the calculate_average_latency method used for calculating the average latency between all pairs of nodes within a disjoint set
int calculate_average_latency(struct union_find *uf, int i, int j) {
    // Calculate the sum of all latencies between all pairs of nodes within the current disjoint set
    int total_latency = 0;
    for (int k = 0; k < MAX_DATASET_SIZE; k++) {
        if (uf->parent[i][k] != -1) {
            // Calculate the latency between the current node and its child nodes
            int latency = calculate_latency(uf, i, k);

            // Add the latency to the total sum
            total_latency += latency;
        }
    }

    // Return the average latency between all pairs of nodes within the current disjoint set
    return total_latency / (MAX_DATASET_SIZE - 1);
}

