1. Dynamic Logging Pipeline:
```scss
import logging

class LoggingPipeline:
    def __init__(self):
        self.sinks = []
        self.levels = ['trace', 'debug', 'info', 'warning', 'error']

    def add_sink(self, sink):
        self.sinks.append(sink)

    def remove_sink(self, sink):
        self.sinks.remove(sink)

    def log(self, level, message):
        for sink in self.sinks:
            if level <= self.levels.index(sink[0]):
                sink[1](message)

    def dynamic_config(self, config):
        self.levels = config['levels']
        self.sinks = []
        for sink in config['sinks']:
            self.add_sink(sink)
```
