    def add_tracer(self, tracer):
        self.tracers.append(tracer)

    def remove_tracer(self, tracer):
        self.tracers.remove(tracer)

    def trace(self, log):
        for tracer in self.tracers:
            if tracer.should_trace(log):
                tracer.add_trace(log)

    def get_traces(self, service, start=None, end=None):
        traces = []
        for tracer in self.tracers:
            if tracer.service == service:
                traces += tracer.get_traces(start, end)
        return traces
