using System.Threading;
using Microsoft.Web.Administration;

namespace WebsiteDeploymentManager
{
    public class DeploymentService
    {
        private const int MAX_RETRY_ATTEMPTS = 5;
        private const int RETRY_INTERVAL = 1000; // in milliseconds

        private readonly Dictionary<string, string> _sites;
        private readonly Dictionary<string, Site> _iisSites;
        private readonly List<Thread> _threads;
        private readonly ObjectLock _lock;

        public DeploymentService()
        {
            _sites = new Dictionary<string, string>();
            _iisSites = new Dictionary<string, Site>();
            _threads = new List<Thread>();
            _lock = new ObjectLock();
        }

        public bool DeploySite(string siteName, string directoryPath, string sslCertificateFilePath)
        {
            try
            {
                // Verify the existence of both web.config and SSL certificate files
                if (!File.Exists(Path.Combine(directoryPath, "web.config")))
                {
                    LogError($"Missing web.config file for site {siteName}");
                    return false;
                }

                if (!File.Exists(sslCertificateFilePath))
                {
                    LogError($"Missing SSL certificate file for site {siteName}");
                    return false;
                }

                // Generate a unique identifier for the deployed website based on its configuration and current timestamp
                var id = GenerateUniqueIdentifier(directoryPath, sslCertificateFilePath);

                // Create a new IIS website entry with proper handling of exceptions and retries for transient failures
                Site iisSite;
                try
                {
                    iisSite = CreateIisSite(siteName, directoryPath, sslCertificateFilePath);
                }
                catch (Exception ex) when (ex is COMException || ex is HttpRequestException)
                {
                    LogError($"Failed to create IIS website for site {siteName} - {ex.Message}");
                    return false;
                }

                // Integrate with IIS through COM interop and ensure proper thread-safe operations and minimizing contention on shared resources
                lock (_lock)
                {
                    _sites[id] = siteName;
                    _iisSites[id] = iisSite;
                    _threads.Add(new Thread(() => MonitorIisSite(id, iisSite)));
                }
            }
            catch (Exception ex)
            {
                LogError($"Failed to deploy site {siteName} - {ex.Message}");
                return false;
            }

            return true;
        }

        private void MonitorIisSite(string id, Site iisSite)
        {
            try
            {
                var healthCheckInterval = TimeSpan.FromMinutes(10);
                var previousError = "";
                while (true)
                {
                    if (iisSite == null)
                    {
                        break;
                    }

                    // Check the health of the deployed website and log any errors or metrics
                    if (!MonitorHealth(iisSite))
                    {
                        LogError($"Website {id} is not healthy - {previousError}");
                    }
                    else
                    {
                        LogMetric($"Website {id} is healthy");
                    }

                    // Wait for the next health check interval
                    Thread.Sleep(healthCheckInterval);
                }
            }
            catch (Exception ex)
            {
                LogError($"Failed to monitor IIS website {id} - {ex.Message}");
            }
        }

        private bool MonitorHealth(Site iisSite)
        {
            try
            {
                // Check the health of the deployed website by querying its status
                var status = iisSite.GetStatus();
                if (status == ServerState.Stopped || status == ServerState.Unknown)
                {
                    return false;
                }

                // Check for any errors or warnings in the event log
                var errorCount = GetErrorCount(iisSite);
                if (errorCount > 0)
                {
                    LogError($"Website {iisSite.Name} has {errorCount} error(s)");
                    return false;
                }
            }
            catch (Exception ex)
            {
                LogError($"Failed to check the health of website {iisSite.Name} - {ex.Message}");
                return false;
            }

            return true;
        }

        private int GetErrorCount(Site iisSite)
        {
            // Query the event log for any errors or warnings related to the deployed website
            var errorCount = 0;
            using (var serverManager = new ServerManager())
            {
                foreach (var logEntry in serverManager.GetEventLogSection("system").LogEntries)
                {
                    if (logEntry.SourceName == iisSite.Name &&
                        (logEntry.Type == EventLogEntryType.Error || logEntry.Type == EventLogEntryType.Warning))
                    {
                        errorCount++;
                    }
                }
            }

            return errorCount;
        }

        private Site CreateIisSite(string siteName, string directoryPath, string sslCertificateFilePath)
        {
            // Create a new IIS website entry with proper handling of exceptions and retries for transient failures
            var attempts = 0;
            while (true)
            {
                try
                {
                    return ServerManager.OpenRemote("127.0.0.1").Sites.Add(siteName, directoryPath, sslCertificateFilePath);
                }
                catch (Exception ex) when (ex is COMException || ex is HttpRequestException)
                {
                    if (attempts >= MAX_RETRY_ATTEMPTS)
                    {
                        throw new DeploymentException($"Failed to create IIS website for site {siteName} - {ex.Message}", ex);
                    }

                    attempts++;
                    Thread.Sleep(RETRY_INTERVAL);
                }
            }
        }

        private string GenerateUniqueIdentifier(string directoryPath, string sslCertificateFilePath)
        {
            // Generate a unique identifier for the deployed website based on its configuration and current timestamp
            return $"{directoryPath} - {sslCertificateFilePath} - {DateTime.UtcNow.Ticks}";
        }

        private void LogError(string message)
        {
            // Log error messages to a file or console output for troubleshooting purposes
            Console.WriteLine($"ERROR: {message}");
        }

        private void LogMetric(string message)
        {
            // Log metric messages to a file or console output for monitoring and analysis purposes
            Console.WriteLine($"METRIC: {message}");
        }
    }
}
