        {
            using var memoryStream = new MemoryStream();
            using var streamWriter = new StreamWriter(memoryStream);
            await streamWriter.WriteAsync(decryptedStream);
            await streamWriter.FlushAsync();
            memoryStream.Position = 0;
            return JsonSerializer.Deserialize<object>(memoryStream);
        }

        private async Task<Stream> ReadStreamToEndAsync(Stream stream)
        {
            var bufferSize = 4096;
            var buffer = new byte[bufferSize];
            using var memoryStream = new MemoryStream();
            int bytesRead;
            while ((bytesRead = await stream.ReadAsync(buffer, 0, bufferSize)) > 0)
            {
                memoryStream.Write(buffer, 0, bytesRead);
            }
            return memoryStream;
        }
    }
