  encryptionKeyLength: 256,
  encryptionAlgorithm: 'aes-256-cbc',
  mfaThreshold: 10,
  userConsentDuration: 30,
  expirationTime: 30 * 24 * 60 * 60, // 30 days in seconds
};

// Define a function to fetch the latest configuration from the KMS service
async function getLatestConfiguration() {
  try {
    const kmsClient = new kms.KMSClient(config);
    const encryptionKey = crypto.createCipher(config.encryptionAlgorithm, config.kmsAccessKeyId, config.kmsSecretAccessKey, config.kmsRegion);
    const ciphertextBlob = await request({
      url: config.keyManagementServiceEndpoint + '/latest-configuration',
      method: 'GET',
      headers: {
        'X-Authorization': encryptionKey.update(config.kmsAccessKeyId).digest('base64'),
        'X-Expiration-Time': config.expirationTime,
      },
    });
    const decryptedConfiguration = JSON.parse(encryptionKey.update(ciphertextBlob, 'utf8', 'utf8').toString());
    return decryptedConfiguration;
  } catch (error) {
    logger.error(`Error fetching latest configuration: ${error.message}`);
    throw error;
  }
}

