    // Tile pooling system for managing memory fragmentation and optimizing performance through Level of Detail (LOD) management and efficient data structures
    private static final class TilePool {
        private static final int MAX_TILE_SIZE = 1024; // maximum size of a tile in bytes
        private static final long MAX_MEMORY_CONSUMPTION = 80 * 1024 * 1024; // maximum amount of memory consumed by the cache (in bytes)

        private static final Map<String, Tile> tiles = new HashMap<>();

        public static void addTile(String key, byte[] data) {
            if (tiles.size() >= MAX_MEMORY_CONSUMPTION / MAX_TILE_SIZE) {
                // Evict the least recently used tile if necessary
                tiles.remove(tiles.keySet().iterator().next());
            }
            Tile newTile = new Tile(data);
            tiles.put(key, newTile);
        }

        public static byte[] getTile(String key) {
