    // Robust backpressure mechanism to handle excessive requests gracefully
    private static final class BackpressureHandler {
        private static final int MAX_CONCURRENT_REQUESTS = 100; // maximum number of concurrent requests allowed
        private static final long REQUEST_DELAY = 50; // delay between consecutive requests (in milliseconds)

        private static final Map<String, Request> pendingRequests = new HashMap<>();
        private static int numPendingRequests = 0;

        public static boolean isBackpressured() {
            return numPendingRequests >= MAX_CONCURRENT_REQUESTS;
        }

        public static void handleRequest(DataFetchRequest request) {
            if (isBackpressured()) {
                // Add the request to the pending requests map and schedule it for execution after the delay
                pendingRequests.put(request.key, request);
                Timer timer = new Timer();
                timer.schedule(new RequestTimerTask(request), REQUEST_DELAY);
            } else {
