// C++ Library Module: System Monitoring and Alerting

#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>

// Structures to hold system monitoring metrics and alerts
struct SYSTEM_MONITORING_METRICS {
    std::string metric;
    double value;
};

struct ALERT_CONDITION {
    std::string condition;
    double threshold;
};

// Class to handle system monitoring and alerting logic
class SystemMonitor {
private:
    // Map of current system metrics by name
    std::map<std::string, SYSTEM_MONITORING_METRICS> metrics_;

    // Vector of alert conditions and their respective thresholds
    std::vector<ALERT_CONDITION> alerts_;

    // Mutex to protect concurrent access to the metrics map
    std::mutex metrics_mtx_;

    // Condition variable to signal new alerts
    std::condition_variable alert_cv_;

public:
    SystemMonitor() {}

    // Add a new system metric to the monitoring
    void addMetric(const SYSTEM_MONITORING_METRICS& metric) {
        metrics_mtx_.lock();
        metrics_.insert({metric.name, metric});
        metrics_mtx_.unlock();
    }

    // Remove a system metric from the monitoring
    void removeMetric(const std::string& name) {
        metrics_mtx_.lock();
        metrics_.erase(name);
        metrics_mtx_.unlock();
    }

    // Return the current value of a system metric
    double getMetricValue(const std::string& name) {
        return metrics_.at(name).value;
    }

    // Set the value of a system metric
    void setMetricValue(const std::string& name, const double& value) {
        metrics_mtx_.lock();
        SYSTEM_MONITORING_METRICS& metric = metrics_.at(name);
        metric.value = value;
        metrics_mtx_.unlock();
    }

    // Add an alert condition to the system
    void addAlertCondition(const ALERT_CONDITION& condition) {
        alerts_.push_back(condition);
    }

    // Remove an alert condition from the system
    void removeAlertCondition(const std::string& name) {
        for (auto it = alerts_.begin(); it != alerts_.end(); ++it) {
            if (it->condition == name) {
                alerts_.erase(it);
                break;
            }
        }
    }

    // Check if an alert condition has been met and send alerts accordingly
    void checkAlertConditions() {
        for (auto& alert : alerts_) {
            double threshold = alert.threshold;
            std::string condition = alert.condition;
            bool is_alerted = false;
            metrics_mtx_.lock();
            if (metrics_.count(condition) > 0) {
                SYSTEM_MONITORING_METRICS& metric = metrics_.at(condition);
                double value = metric.value;
                is_alerted = value >= threshold;
            }
            metrics_mtx_.unlock();
            if (is_alerted) {
                // Send alert notification to external system
            }
        }
    }
};

// Main loop to collect and process system monitoring data
void mainLoop() {
    while (true) {
        SystemMonitor monitor;
        // Collect system metrics from various sources
        std::vector<SYSTEM_MONITORING_METRICS> metrics = collectMetrics();
        for (auto& metric : metrics) {
            monitor.addMetric(metric);
        }
        // Check alert conditions and send notifications as needed
        monitor.checkAlertConditions();
        // Sleep for a short period to avoid overloading the system
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }
}

// Function to collect system metrics from various sources
std::vector<SYSTEM_MONITORING_METRICS> collectMetrics() {
    std::vector<SYSTEM_MONITORING_METRICS> metrics;
    // Collect metrics from external monitoring systems
    for (auto& source : monitoring_sources_) {
        metrics.push_back(source.getMetric());
    }
    // Collect metrics from local system resources
    for (auto& resource : local_resources_) {
        metrics.push_back(resource.getMetric());
    }
    return metrics;
}

// Main entry point to start the system monitoring and alerting loop
int main() {
    // Initialize monitoring sources and local resources
    initializeMonitoringSources();
    initializeLocalResources();
    // Start the main loop
    std::thread monitor_loop(mainLoop);
    return 0;
}']

['package FlexibleRecommendationSystem;

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class RecommendationEngine {
    private final ExecutorService executor;
    private final Map<String, List<String>> contentMap = new ConcurrentHashMap<>();
    private final Map<String, String> userContentHistory = new ConcurrentHashMap<>();

    public RecommendationEngine() {
        this.executor = Executors.newFixedThreadPool(10);
    }

    public List<String> getRecommendedContent(String userId) {
        List<String> recommendedContent = new ArrayList<>();

        // Get user content history from map
        String userHistory = userContentHistory.get(userId);

        if (userHistory != null) {
            // Split user history by comma and space
            String[] contentIds = userHistory.split(",\\s*");

            // Iterate over content IDs and retrieve corresponding content
            for (String contentId : contentIds) {
                List<String> content = contentMap.get(contentId);
                if (content != null) {
                    recommendedContent.addAll(content);
                }
            }
        }

        return recommendedContent;
    }

    public void updateUserHistory(String userId, String contentId) {
        // Get current user history from map
        String userHistory = userContentHistory.get(userId);

        if (userHistory != null) {
            // Split user history by comma and space
            String[] contentIds = userHistory.split(",\\s*");

            // Add new content ID to end of list
            List<String> updatedContentIds = new ArrayList<>();
            for (String id : contentIds) {
                if (!id.equals(contentId)) {
                    updatedContentIds.add(id);
                }
            }
            updatedContentIds.add(contentId);

            // Update user history with new list of content IDs
            userContentHistory.put(userId, String.join(",", updatedContentIds));
        } else {
            // Add new entry for user and content ID
            userContentHistory.put(userId, contentId);
        }
    }

    public void addContent(String contentId, List<String> content) {
        contentMap.put(contentId, content);
    }

    public void removeContent(String contentId) {
        contentMap.remove(contentId);
    }
}

// ExecutorService for managing threads
class RecommendationExecutor implements Executor {
    private final ExecutorService executor;

    public RecommendationExecutor() {
        this.executor = Executors.newFixedThreadPool(10);
    }

    @Override
    public void execute(Runnable command) {
        executor.execute(command);
    }
}

// Thread pool for executing recommendation tasks
class RecommendationThreadpool implements ThreadPoolExecutor {
    private final ExecutorService executor;

    public RecommendationThreadpool() {
        this.executor = Executors.newFixedThreadPool(10);
    }

    @Override
    public void submit(Runnable task) {
        executor.submit(task);
    }
}

// Thread pool for executing recommendation tasks
class RecommendationThreadpool implements ThreadPoolExecutor {
    private final ExecutorService executor;

    public RecommendationThreadpool() {
        this.executor = Executors.newFixedThreadPool(10);
    }

    @Override
    public void submit(Runnable task) {
        executor.submit(task);
    }
}']

