public class HighlyAvailableHashingService {
  private static final Logger logger = Logger.getLogger(HighlyAvailableHashingService.class.getName());

  private ExecutorService executor;
  private int numThreads;
  private long maxDelay;
  private double adaptiveResourceAllocationThreshold;

  public HighlyAvailableHashingService() {
    this.executor = Executors.newCachedThreadPool();
    this.numThreads = Runtime.getRuntime().availableProcessors();
    this.maxDelay = 1000L; // milliseconds
    this.adaptiveResourceAllocationThreshold = 0.75D; // default to 75% resource utilization threshold
  }

  public HighlyAvailableHashingService(int numThreads, long maxDelay) {
    this();
    this.numThreads = numThreads;
    this.maxDelay = maxDelay;
  }

  public void setAdaptiveResourceAllocationThreshold(double threshold) {
    this.adaptiveResourceAllocationThreshold = threshold;
  }

  public double getAdaptiveResourceAllocationThreshold() {
    return adaptiveResourceAllocationThreshold;
  }

  public void shutdown() {
    executor.shutdown();
  }

  public void execute(String message) {
    long startTime = System.nanoTime();

    try {
      String hash = computeMD5Hash(message);
      if (hash != null) {
        // Integrate with external hashing service API
        doExternalIntegration(hash);
      } else {
        logger.log(Level.WARNING, "Failed to compute MD5 hash for message: " + message);
      }
    } catch (NoSuchAlgorithmException | IOException e) {
      logger.log(Level.SEVERE, "Error computing MD5 hash or integrating with external service", e);
    } finally {
      long endTime = System.nanoTime();
      long delay = endTime - startTime;
      if (delay > maxDelay) {
        // Handle potential errors from both library functions and the external service, with detailed logging and monitoring for performance tuning and issue diagnosis
        logger.log(Level.WARNING, "Error computing MD5 hash or integrating with external service", e);
      } else {
        if (adaptiveResourceAllocationThreshold > 0) {
          // Optimize for throughput and responsiveness by employing a thread pool with adaptive sizing and dynamic resource allocation policies based on historical load patterns and real-time metrics
          executor.execute(new Runnable() {
            @Override
            public void run() {
              execute(message);
            }
          });
        } else {
          // Use a fixed thread pool with a configurable number of threads
          Future<?> future = executor.submit(() -> execute(message));
          try {
            future.get();
          } catch (InterruptedException | ExecutionException e) {
            logger.log(Level.SEVERE, "Error executing task", e);
          }
        }
      }
    }
  }

  private String computeMD5Hash(String message) throws NoSuchAlgorithmException, IOException {
    // Compute the MD5 hash of the given message using a library function
    MessageDigest md = MessageDigest.getInstance("MD5");
    byte[] hash = md.digest(message.getBytes());
    return new String(hash);
  }

  private void doExternalIntegration(String hash) {
