Here is an example of a scalable Java-based RESTful API service that integrates with an external relational database, a message broker, and multiple third-party APIs for handling asynchronous tasks and notifications:
```
@RestController
public class MyApiService {

  @Autowired
  private MyDatabase myDatabase;

  @Autowired
  private MyMessageBroker myMessageBroker;

  @Autowired
  private MyThirdPartyApi1 myThirdPartyApi1;

  @Autowired
  private MyThirdPartyApi2 myThirdPartyApi2;

  @GetMapping("/api/v1/resource")
  public ResponseEntity<Resource> getResource(@RequestParam("id") Long id) {
    // Perform query on external database to retrieve resource
    Resource resource = myDatabase.getResourceById(id);

    // Publish message to message broker for asynchronous processing
    MyMessageBroker.publishMessage(resource, "my-queue");

    // Call third-party API 1 to perform additional processing
    myThirdPartyApi1.processResource(resource);

    // Call third-party API 2 to perform additional processing
    myThirdPartyApi2.processResource(resource);

    return ResponseEntity.ok(resource);
  }

  @PutMapping("/api/v1/resource")
  public ResponseEntity<Void> updateResource(@RequestBody Resource resource) {
    // Perform query on external database to retrieve existing resource
    Resource existingResource = myDatabase.getResourceById(resource.getId());

    // Validate that the resource exists and is authorized to be updated
    if (existingResource == null || !existingResource.isAuthorized()) {
      return ResponseEntity.notFound().build();
    }

    // Update resource in external database
    myDatabase.updateResource(resource);

    // Publish message to message broker for asynchronous processing
    MyMessageBroker.publishMessage(resource, "my-queue");

    return ResponseEntity.ok().build();
  }

  @DeleteMapping("/api/v1/resource")
  public ResponseEntity<Void> deleteResource(@RequestParam("id") Long id) {
    // Perform query on external database to retrieve existing resource
    Resource existingResource = myDatabase.getResourceById(id);

    // Validate that the resource exists and is authorized to be deleted
    if (existingResource == null || !existingResource.isAuthorized()) {
      return ResponseEntity.notFound().build();
    }

    // Update resource in external database
    myDatabase.deleteResource(id);

    // Publish message to message broker for asynchronous processing
    MyMessageBroker.publishMessage(existingResource, "my-queue");

    return ResponseEntity.ok().build();
  }
}
```
