// Define record structure and initialize fields
typedef struct {
    int value;
} Record;

// Initialize an array of records with random values within a specified range
void allocateAndInitializeRecords(Record* records, size_t num_records, unsigned int seed) {
    // Generate random numbers within the specified range for each record
    srand(seed);
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = rand() % 100 + 1;
    }
}

// Truncate a string if necessary and return it with a trailing slash
const char* truncateStringIfNecessary(const char* str, size_t max_size) {
    // Check if the string is too long
    size_t len = strlen(str);
    if (len > max_size) {
        // Allocate memory for the truncated string
        const char* new_str = malloc(max_size + 1);
        // Copy the first `max_size` characters of the original string
        memcpy((char*)new_str, str, max_size);
        // Add a trailing slash if necessary
        if (len > max_size) {
            new_str[max_size] = '/';
        } else {
            new_str[max_size - 1] = '\0';
        }
        // Free the original string and return the truncated one
        free((void*)str);
        str = new_str;
    }
    return str;
}

// Merge two sorted arrays of records and return a new sorted array
Record* mergeAndSortRecords(Record* arr1, Record* arr2, size_t num_records) {
    // Allocate memory for the merged array
    Record* merged = malloc(num_records * sizeof(Record));
    size_t i1 = 0, i2 = 0, j = 0;
    while (i1 < num_records && i2 < num_records) {
        // Compare the values of the two arrays and merge them
        if (arr1[i1].value <= arr2[i2].value) {
            merged[j++] = arr1[i1++];
        } else {
            merged[j++] = arr2[i2++];
        }
    }
    // Copy the remaining elements from either array to the merged array
    while (i1 < num_records) {
        merged[j++] = arr1[i1++];
    }
    while (i2 < num_records) {
        merged[j++] = arr2[i2++];
    }
    // Sort the merged array using a stable sort algorithm
    for (size_t i = 0; i < num_records - 1; ++i) {
        for (size_t j = i + 1; j < num_records; ++j) {
            if (merged[i].value > merged[j].value) {
                Record temp = merged[i];
                merged[i] = merged[j];
                merged[j] = temp;
            }
        }
    }
    // Return the sorted merged array
    return merged;
}
```
