// Define the function that allocates and initializes the memory pool
void allocateAndInitializeRecords(int num_records, int seed) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&mempool_mutex);

    // Allocate space for the arrays of long offsets and int keys
    OffsetArray *offsets = malloc(sizeof(OffsetArray) * num_records);
    KeyArray *keys = malloc(sizeof(KeyArray) * num_records);

    // Initialize the array of records with random values within a specified range
    RecordArray *records = malloc(sizeof(RecordArray) * num_records);
    for (int i = 0; i < num_records; i++) {
        int value = rand_r(&seed) % INT_MAX + 1;
        records[i].record.value = value;
    }

    // Set the offsets and keys in the arrays based on the record values
    for (int i = 0; i < num_records; i++) {
        offsets[i].offset = &(records[i].record);
        keys[i].key = records[i].record.value;
    }

    // Unlock the mutex to release thread safety
    pthread_mutex_unlock(&mempool_mutex);
}

