void enqueueTask(const Task& task) {
    // Prioritize tasks based on priority and historical execution times
    if (task.priority > 0) {
        priority_queue<Task, vector<Task>, greater<Task>> taskQueue;
        taskQueue.push(task);
    } else {
        queue<Task> taskQueue;
        taskQueue.push(task);
    }

    // Task-pooling mechanism to manage memory usage effectively and ensure cache locality
    static unordered_map<int, vector<Task>> taskPool;
    if (taskPool.count(task.taskID) == 0) {
        taskPool[task.taskID] = {task};
    } else {
        taskPool[task.taskID].push_back(task);
    }

    // Adaptive algorithm to dynamically adjust task prioritization based on resource availability and performance metrics
    if (resourceAvailability > 0 && performanceMetrics < 50) {
        priority = 1;
    } else {
        priority = -1;
    }
}
