// Define the Record structure to hold an integer value and a string name
typedef struct {
    int value;
    char* name;
} Record;

// Define the MemoryPool structure to manage the array of Records
typedef struct {
    size_t capacity;
    size_t size;
    Record** records;
} MemoryPool;

// Function to create a new MemoryPool instance
MemoryPool* memory_pool_create(size_t capacity) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) {
        return NULL;
    }

    pool->capacity = capacity;
    pool->size = 0;
    pool->records = (Record**)malloc(pool->capacity * sizeof(Record*));
    if (!pool->records) {
        free(pool);
        return NULL;
    }

    // Initialize the records array with NULL values
    for (size_t i = 0; i < pool->capacity; ++i) {
        pool->records[i] = NULL;
    }

    return pool;
}

// Function to add a new Record to the MemoryPool instance
void memory_pool_add(MemoryPool* pool, int value, char* name) {
    // Check if the pool is full and needs to be resized
    if (pool->size >= pool->capacity) {
        size_t new_capacity = pool->capacity * 2;
        Record** new_records = (Record**)realloc(pool->records, new_capacity * sizeof(Record*));
        if (!new_records) {
            // Reallocation failed, return an error
            return NULL;
        }

        pool->capacity = new_capacity;
        pool->records = new_records;
    }

    // Create a new Record instance and add it to the records array
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        // Memory allocation failed, return an error
        return NULL;
    }

    record->value = value;
    record->name = strdup(name);
    pool->records[pool->size++] = record;
}

// Function to remove a Record from the MemoryPool instance
void memory_pool_remove(MemoryPool* pool, int index) {
    // Check if the index is valid and return an error if it's not
    if (index < 0 || index >= pool->size) {
        return NULL;
    }

    Record** record = &pool->records[index];
    free((*record)->name);
    free(*record);
    *record = NULL;
}

// Function to retrieve a Record from the MemoryPool instance
Record* memory_pool_get(MemoryPool* pool, int index) {
    // Check if the index is valid and return an error if it's not
    if (index < 0 || index >= pool->size) {
        return NULL;
    }

    return pool->records[index];
}

// Function to print all Records in the MemoryPool instance
void memory_pool_print(MemoryPool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        Record* record = pool->records[i];
        printf("Record %d: value=%d, name=%s\n", i, record->value, record->name);
    }
}

// Function to clean up the MemoryPool instance and free all memory
void memory_pool_destroy(MemoryPool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        Record** record = &pool->records[i];
        free((*record)->name);
        free(*record);
        *record = NULL;
    }

    free(pool->records);
    free(pool);
}
```
