    char *body = curl_easy_getinfo(curl, CURLINFO_STRING);
    if (!body) {
        syslog(LOG_ERR, "Failed to fetch resource bundle %s: empty response body", name);
        pthread_mutex_unlock(&mutex);
        return NULL;
