    // Parse the resource bundle data into a structured format (e.g., JSON)
    ...

    // Cache the resource bundle and release the mutex
    int i = 0;
    for (i = 0; i < MAX_BUNDLES; i++) {
        if (!bundles[i].name) {
            bundles[i].name = name;
            bundles[i].data = data;
            bundles[i].last_accessed = now;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);

    return data;
}

// Thread-safe function to retrieve a resource bundle from the cache
void *getResourceBundle(const char *name) {
    // Acquire the mutex
    pthread_mutex_lock(&mutex);

    // Check if the resource bundle is already in the cache
    for (int i = 0; i < MAX_BUNDLES; i++) {
        if (bundles[i].name && strcmp(bundles[i].name, name) == 0) {
            bundles[i].last_accessed = time(NULL);
