// countDisjointPairs function in C++
#include <algorithm>
#include <cstdio>
#include <iostream>
#include <vector>

struct UnionFind {
    std::vector<int> parent;
    int count;

    UnionFind(int size) : parent(size), count(size) {
        for (int i = 0; i < size; i++) {
            parent[i] = i;
        }
    }

    void unite(int x, int y) {
        int rootX = findRoot(x);
        int rootY = findRoot(y);
        if (rootX == rootY) return;
        count--;
        parent[rootX] = rootY;
    }

    int findRoot(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
};

int countDisjointPairs(const std::vector<int>& arr) {
    UnionFind uf(arr.size());
    int pairs = 0;
    for (int i = 0; i < arr.size(); i++) {
        for (int j = i + 1; j < arr.size(); j++) {
            if (uf.findRoot(i) != uf.findRoot(j)) {
                pairs++;
                uf.unite(i, j);
            }
        }
    }
    return pairs;
}

