void print_vec(const vec* v) {
    printf("Vector: [");
    for (int i = 0; i < v->n; ++i) {
        printf("%.2f ", v->x[i]);
    }
    printf("]\n");
}

void add_vecs(const vec* a, const vec* b, vec* c) {
    if (a->n != b->n || a->n != c->n) {
        fprintf(stderr, "Error: Vector sizes do not match\n");
        return;
    }
    for (int i = 0; i < a->n; ++i) {
        c->x[i] = a->x[i] + b->x[i];
    }
}

void subtract_vecs(const vec* a, const vec* b, vec* c) {
    if (a->n != b->n || a->n != c->n) {
        fprintf(stderr, "Error: Vector sizes do not match\n");
        return;
    }
    for (int i = 0; i < a->n; ++i) {
        c->x[i] = a->x[i] - b->x[i];
    }
}

void scale_vec(const vec* v, float scalar, vec* result) {
    if (v->n != result->n) {
        fprintf(stderr, "Error: Vector sizes do not match\n");
        return;
    }
    for (int i = 0; i < v->n; ++i) {
        result->x[i] = scalar * v->x[i];
    }
}

float dot_product(const vec* a, const vec* b) {
    if (a->n != b->n) {
        fprintf(stderr, "Error: Vector sizes do not match\n");
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < a->n; ++i) {
        sum += a->x[i] * b->x[i];
    }
    return sum;
}
