// Global variables
char *input_directory;
char *output_file;
char *log_service_url;
int num_threads = 4; // Default number of threads for processing files
sem_t *file_semaphore; // Semaphore for synchronizing access to input file pointers
sem_t *data_semaphore; // Semaphore for synchronizing access to data structures
pthread_mutex_t *output_lock; // Mutex for protecting output file write operations

// Function declarations
void parse_arguments(int argc, char **argv);
bool check_input_directory();
bool check_output_file();
bool check_log_service_url();
void* process_file(void *thread_id);
void compute_hash(char *transaction);
FILE *open_file(const char *path, const char *mode);
void close_file(FILE *fp);
void log_error(int error_code, char *message);

// Main function
int main(int argc, char **argv) {
  // Parse command line arguments
  parse_arguments(argc, argv);

  // Check input directory, output file, and logging service URL
  if (!check_input_directory() || !check_output_file() || !check_log_service_url()) {
    return EXIT_FAILURE;
  }

  // Initialize semaphores and mutex
  sem_init(&file_semaphore, 0, 1);
  sem_init(&data_semaphore, 0, num_threads);
  pthread_mutex_init(&output_lock, NULL);

  // Initialize array to store file pointers
  FILE **files = calloc(num_threads, sizeof(FILE *));

  // Create threads for processing files
  pthread_t *threads = calloc(num_threads, sizeof(pthread_t));
  for (int i = 0; i < num_threads; ++i) {
    if (pthread_create(&threads[i], NULL, process_file, (void *)i)) {
      log_error(errno, "Failed to create thread");
    }
  }

  // Join threads and close files
  for (int i = 0; i < num_threads; ++i) {
    pthread_join(threads[i], NULL);
    sem_post(&file_semaphore);
  }

  // Close output file and free memory
  fclose(output_file);
  free(files);
  free(threads);
  return EXIT_SUCCESS;
}

// Parse command line arguments
void parse_arguments(int argc, char **argv) {
  int i = 1;
  while (i < argc) {
    if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
      input_directory = argv[++i];
    } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
      output_file = argv[++i];
    } else if (strcmp(argv[i], "--log-service-url") == 0 && i + 1 < argc) {
      log_service_url = argv[++i];
    } else if (strcmp(argv[i], "--help") == 0) {
      printf("Usage: %s -i <input_directory> -o <output_file> [--log-service-url <logging_service_url>]\n", argv[0]);
      exit(EXIT_SUCCESS);
    } else if (strcmp(argv[i], "--version") == 0) {
      printf("%s version %d.%d\n", argv[0], 1, 0);
      exit(EXIT_SUCCESS);
    } else {
      fprintf(stderr, "Invalid argument: %s\n", argv[i]);
      exit(EXIT_FAILURE);
    }
    ++i;
  }
}

// Check input directory
bool check_input_directory() {
  struct stat info;
  if (stat(input_directory, &info) != 0 || !S_ISDIR(info.st_mode)) {
    log_error(errno, "Failed to access input directory");
    return false;
  }
  return true;
}

// Check output file
bool check_output_file() {
  FILE *fp = fopen(output_file, "wb");
  if (fp == NULL) {
    log_error(errno, "Failed to open output file for writing");
    return false;
  }
  fclose(fp);
  return true;
}

// Check logging service URL
bool check_log_service_url() {
  if (log_service_url == NULL) {
    printf("Logging service URL not specified, using default\n");
    log_service_url = "https://example.com/logging";
  }
  return true;
}

// Process a file in parallel
void* process_file(void *thread_id) {
  int thread_num = (intptr_t)thread_id;

  // Acquire semaphore for accessing input directory
  while (sem_wait(&file_semaphore)) {
    if (errno != EINTR) {
      log_error(errno, "Failed to acquire file semaphore");
      break;
    }
  }

  // Acquire semaphore for accessing data structures
  while (sem_wait(&data_semaphore)) {
    if (errno != EINTR) {
      log_error(errno, "Failed to acquire data semaphore");
      break;
    }
  }

  // Open file for reading and initialize array of hashes for this thread
  char filename[PATH_MAX];
  snprintf(filename, PATH_MAX, "%s/thread_%d.txt", input_directory, thread_num);
  FILE *fp = open_file(filename, "rb");
  if (fp == NULL) {
    log_error(errno, "Failed to open input file for reading");
    return NULL;
  }
  char **hashes = calloc(num_threads, sizeof(char *));

  // Read lines from file and compute hashes in parallel
  while (!feof(fp)) {
    char line[BUFSIZ];
    if (fgets(line, BUFSIZ, fp) != NULL) {
      compute_hash(line, hashes);
    }
  }

  // Write hashes to output file
  sem_post(&data_semaphore);
  while (sem_wait(&file_semaphore)) {
    if (errno != EINTR) {
      log_error(errno, "Failed to acquire file semaphore");
      break;
    }
  }
  write_hashes(hashes);

  // Release resources and return
  fclose(fp);
  free(hashes);
  return NULL;
}

// Compute hash for a line of text
void compute_hash(char *line, char **hashes) {
  int i = 0;
  while (line[i] != '\0') {
    hashes[thread_num][i] = line[i];
    ++i;
  }
}

// Write hashes to output file
void write_hashes(char **hashes) {
  FILE *fp = fopen(output_file, "ab");
  if (fp == NULL) {
    log_error(errno, "Failed to open output file for writing");
    return;
  }
  for (int i = 0; i < num_threads; ++i) {
    fwrite(hashes[i], sizeof(char), BUFSIZ, fp);
  }
  fclose(fp);
}
