    int rxUeInformationTag = pdu->rxUeInformationTag;
    int crcIndicationRel8Tag = pdu->crcIndicationRel8Tag;

    // Use OpenSSL to compute the CRC checksum of the extracted fields
    unsigned char *data = (unsigned char *)malloc(sizeof(int) * 2);
    memcpy(data, &rxUeInformationTag, sizeof(int));
    memcpy(data + sizeof(int), &crcIndicationRel8Tag, sizeof(int));
