#include <iostream>
#include <string>
#include <map>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <chrono>

using namespace std;

struct TX_POWER_REPORT {
    uint32_t rnti;
    double power_level;
    string timestamp;
};

class StreamingDataEngine {
private:
    mutex data_mutex_;
    condition_variable data_cv_;
    map<uint32_t, vector<TX_POWER_REPORT>> data_;
    bool is_running_;
    uint32_t max_rnti_;
    uint32_t num_threads_;

public:
    StreamingDataEngine(uint32_t max_rnti, uint32_t num_threads) :
        data_mutex_(mutex()),
        data_cv_(condition_variable()),
        data_(map<uint32_t, vector<TX_POWER_REPORT>>()),
        is_running_(false),
        max_rnti_(max_rnti),
        num_threads_(num_threads) { }

    void start() {
        is_running_ = true;
        thread data_thread(&StreamingDataEngine::data_processing, this);
        data_thread.detach();
    }

    void stop() {
        is_running_ = false;
    }

    bool add_report(const TX_POWER_REPORT& report) {
        unique_lock<mutex> lock(data_mutex_);
        if (report.rnti > max_rnti_) {
            return false;
        }
        data_[report.rnti].push_back(report);
        data_cv_.notify_all();
        return true;
    }

    bool retrieve_reports(uint32_t rnti, vector<TX_POWER_REPORT>& reports) {
        unique_lock<mutex> lock(data_mutex_);
        if (rnti > max_rnti_) {
            return false;
        }
        reports = data_[rnti];
        return true;
    }

    bool update_report(const TX_POWER_REPORT& report) {
        unique_lock<mutex> lock(data_mutex_);
        if (report.rnti > max_rnti_) {
            return false;
        }
        data_[report.rnti][0] = report;
        data_cv_.notify_all();
        return true;
    }

    bool delete_reports(uint32_t rnti) {
        unique_lock<mutex> lock(data_mutex_);
        if (rnti > max_rnti_) {
            return false;
        }
        data_.erase(rnti);
        data_cv_.notify_all();
        return true;
    }

private:
    void data_processing() {
        while (is_running_) {
            unique_lock<mutex> lock(data_mutex_);
            data_cv_.wait(lock, [this] { return !data_.empty(); });
            for (const auto& report : data_) {
                // Process the reports here.
            }
        }
    }
};
```
