```
<?php

namespace App\Auth;

use App\Http\Requests\RegistrationRequest;
use App\Http\Requests\LoginRequest;
use App\Http\Requests\PasswordResetRequest;
use App\Http\Requests\SessionManagementRequest;
use App\Exceptions\AuthenticationException;
use App\Helpers\RateLimiter;
use App\Helpers\TokenManager;
use App\Models\User;
use Illuminate\Support\Facades\Hash;
use Illuminate\Support\Facades\Mail;
use Illuminate\Support\Facades\Cache;

class AuthenticationService {
    /**
     * Register a new user with the service.
     *
     * @param RegistrationRequest $request
     * @return User
     */
    public function register(RegistrationRequest $request) {
        // Validate input data
        $this->validate($request);

        // Create a new user in the database
        $user = User::create([
            'email' => $request->input('email'),
            'password' => Hash::make($request->input('password')),
            'activated' => false,
        ]);

        // Send registration confirmation email
        Mail::to($user)->send(new RegistrationConfirmationEmail($user));

        return $user;
    }

    /**
     * Log a user in and generate a session token.
     *
     * @param LoginRequest $request
     * @return User
     */
    public function login(LoginRequest $request) {
        // Validate input data
        $this->validate($request);

        // Check if the user exists in the database
        $user = User::where('email', $request->input('email'))->first();
        if (!$user) {
            throw new AuthenticationException('Invalid email or password.');
        }

        // Check if the user's account is activated
        if ($user->activated === false) {
            throw new AuthenticationException('Your account has not been activated yet. Please check your email for the activation link.');
        }

        // Check if the password matches
        if (!Hash::check($request->input('password'), $user->password)) {
            throw new AuthenticationException('Invalid email or password.');
        }

        // Generate a session token and store it in the database
        $token = TokenManager::generateToken();
        $user->tokens()->create([
            'token' => $token,
            'expires_at' => now()->addMinutes(30)
        ]);

        return $user;
    }

    /**
     * Reset a user's password and generate a password reset token.
     *
     * @param PasswordResetRequest $request
     * @return User
     */
    public function resetPassword(PasswordResetRequest $request) {
        // Validate input data
        $this->validate($request);

        // Check if the user exists in the database
        $user = User::where('email', $request->input('email'))->first();
        if (!$user) {
            throw new AuthenticationException('Invalid email or password.');
        }

        // Send a password reset email
        Mail::to($user)->send(new PasswordResetEmail($user));

        return $user;
    }

    /**
     * Validate input data and check if the user is authenticated.
     *
     * @param SessionManagementRequest $request
     * @return User|null
     */
    public function authenticate(SessionManagementRequest $request) {
        // Validate input data
        $this->validate($request);

        // Check if the user is authenticated
        $user = User::where('email', $request->input('email'))->first();
        if (!$user) {
            throw new AuthenticationException('Invalid email or password.');
        }

        // Check if the token is valid and has not expired
        $token = TokenManager::validateToken($request->input('token'));
        if ($token === null) {
            throw new AuthenticationException('Invalid session token.');
        }

        return $user;
    }

    /**
     * Validate input data and check if the user is authenticated.
     *
     * @param SessionManagementRequest $request
     * @return void
     */
    public function invalidateToken(SessionManagementRequest $request) {
        // Validate input data
        $this->validate($request);

        // Check if the token is valid and has not expired
        $token = TokenManager::invalidateToken($request->input('token'));
        if ($token === null) {
            throw new AuthenticationException('Invalid session token.');
        }
    }

    /**
     * Validate input data and check if the user is authenticated.
     *
     * @param SessionManagementRequest $request
     * @return void
     */
    public function extendToken(SessionManagementRequest $request) {
        // Validate input data
        $this->validate($request);

        // Check if the token is valid and has not expired
        $token = TokenManager::extendToken($request->input('token'));
        if ($token === null) {
            throw new AuthenticationException('Invalid session token.');
        }
    }

    /**
     * Validate input data and check if the user is authenticated.
     *
     * @param SessionManagementRequest $request
     * @return void
     */
    public function logout(SessionManagementRequest $request) {
        // Validate input data
        $this->validate($request);

        // Check if the token is valid and has not expired
        $token = TokenManager::invalidateToken($request->input('token'));
        if ($token === null) {
            throw new AuthenticationException('Invalid session token.');
        }
    }

    /**
     * Validate input data and check if the user is authenticated.
     *
     * @param SessionManagementRequest $request
     * @return void
     */
    public function resetPassword(PasswordResetRequest $request) {
        // Validate input data
        $this->validate($request);

        // Check if the user exists in the database
        $user = User::where('email', $request->input('email'))->first();
        if (!$user) {
            throw new AuthenticationException('Invalid email or password.');
        }

        // Send a password reset email
        Mail::to($user)->send(new PasswordResetEmail($user));
    }

    /**
     * Validate input data and check if the user is authenticated.
     *
     * @param SessionManagementRequest $request
     * @return void
     */
    public function activateAccount(SessionManagementRequest $request) {
        // Validate input data
        $this->validate($request);

        // Check if the token is valid and has not expired
        $token = TokenManager::invalidateToken($request->input('token'));
        if ($token === null) {
            throw new AuthenticationException('Invalid activation token.');
        }

        // Update the user's activation status
        User::where('email', $request->input('email'))->update(['activated' => true]);
    }
}
