  power_report_entries_worker_thread_.join();
}

void PowerReportModule::addPowerReportEntry(uint32_t rnti, double timestamp, double power_level) {
  std::lock_guard<std::mutex> lock(power_report_entries_mutex_);
  power_report_entries_.insert({rnti, {rnti, timestamp, power_level}});
  power_report_entries_cv_.notify_all();
}

PowerReportEntry PowerReportModule::getPowerReportEntryByRnti(uint32_t rnti) {
  std::lock_guard<std::mutex> lock(power_report_entries_mutex_);
  return power_report_entries_.at(rnti);
}

void PowerReportModule::updatePowerReportEntryByRnti(uint32_t rnti, double timestamp, double power_level) {
  std::lock_guard<std::mutex> lock(power_report_entries_mutex_);
  if (power_report_entries_.find(rnti) != power_report_entries_.end()) {
    power_report_entries_.at(rnti).timestamp = timestamp;
    power_report_entries_.at(rnti).power_level = power_level;
  } else {
    // If the entry does not exist, add a new one
    addPowerReportEntry(rnti, timestamp, power_level);
  }
}

void PowerReportModule::deletePowerReportEntryByRnti(uint32_t rnti) {
  std::lock_guard<std::mutex> lock(power_report_entries_mutex_);
  if (power_report_entries_.find(rnti) != power_report_entries_.end()) {
    power_report_entries_.erase(rnti);
  }
}

void PowerReportModule::workerThread() {
  while (true) {
    std::unique_lock<std::mutex> lock(power_report_entries_mutex_);
    power_report_entries_cv_.wait(lock, [this] { return !power_report_entries_.empty(); });
    // Process the entries in the map
  }
}
