Here is a possible implementation of a modular, thread-safe C++ library for managing a dynamic collection of `DEVICE_STATUS_REPORT` structures:
```cpp
#include <iostream>
#include <map>
#include <mutex>
#include <string>
#include <thread>
#include <vector>

struct DeviceStatusReport {
  std::string udid;
  uint64_t timestamp;
  double temperature;
  double humidity;
  double pressure;
};

class DeviceStatusReportManager {
 public:
  DeviceStatusReportManager() {}

  void AddDevice(const std::string& udid) {
    std::lock_guard<std::mutex> lock(device_map_mutex_);
    device_status_reports_.insert({udid, DeviceStatusReport{}});
  }

  void UpdateDeviceReadings(const std::string& udid, double temperature,
                           double humidity, double pressure) {
    std::lock_guard<std::mutex> lock(device_map_mutex_);
    auto iter = device_status_reports_.find(udid);
    if (iter != device_status_reports_.end()) {
      iter->second.temperature = temperature;
      iter->second.humidity = humidity;
      iter->second.pressure = pressure;
    } else {
      std::cerr << "Device not found: " << udid << std::endl;
    }
  }

  void RemoveDevice(const std::string& udid) {
    std::lock_guard<std::mutex> lock(device_map_mutex_);
    device_status_reports_.erase(udid);
  }

  const DeviceStatusReport* GetDeviceReadings(const std::string& udid) const {
    std::lock_guard<std::mutex> lock(device_map_mutex_);
    auto iter = device_status_reports_.find(udid);
    if (iter != device_status_reports_.end()) {
      return &iter->second;
    } else {
      return nullptr;
    }
  }

 private:
  std::mutex device_map_mutex_;
  std::map<std::string, DeviceStatusReport> device_status_reports_;
};
```
This implementation uses a `std::map` to store the `DeviceStatusReport` structures and a `std::mutex` to protect the map from concurrent access. The `AddDevice`, `UpdateDeviceReadings`, and `RemoveDevice` methods are thread-safe, while the `GetDeviceReadings` method is const and can be safely called from multiple threads without any locks.

