class TestFramework:
    def __init__(self, specs):
        self.specs = specs
        self.tests = []
        self.results = {}
        self.logger = None
        self.lock = Lock()

    def run(self):
        for spec in self.specs:
            test_id, test_config = spec
            self.tests.append(TestCase(test_id, test_config))

        with ThreadPoolExecutor(max_workers=len(self.tests)) as executor:
            results = []
            for test in self.tests:
                result = executor.submit(test.run)
                results.append(result)

            for result in results:
                if not result.successful():
                    self.logger.error("Test {} failed with error {}: {}".format(result.test_id, result.exception.code, result.exception.message))
                else:
                    self.results[result.test_id] = result.output

            self.logger.info("All tests completed successfully")
            return self.results

class TestCase:
    def __init__(self, test_id, config):
        self.test_id = test_id
        self.config = config

    def run(self):
        try:
            # Execute the test case using the configuration provided
            output = self.execute()
            return TestResult(test_id=self.test_id, successful=True, output=output)
        except Exception as e:
            return TestResult(test_id=self.test_id, successful=False, exception=e)

    def execute(self):
        # Implement the test case logic here using the configuration provided
        pass

class TestResult:
    def __init__(self, test_id, successful, output=None, exception=None):
        self.test_id = test_id
        self.successful = successful
        self.output = output
        self.exception = exception
