    var itemsToFetch = recommendedItems.Select(r => r.ItemId).Distinct().ToList();
    var fetchedItems = await FetchItemsAsync(itemsToFetch);
    var enrichedItems = EnrichItems(recommendedItems, fetchedItems);

    // Error Handling and Reliability
