        if (retryCount < 5)
        {
            await Task.Delay(TimeSpan.FromSeconds(Math.Pow(2, retryCount)));
            return await context.CallActivityAsync<List<Recommendation>>("GeneratePersonalizedRecommendations", context.Input);
        }
