  {
    name: 'rule1',
    dependencies: ['rule2'],
    transformer: async (data) => {
      // Perform transformation logic on data using rule2
      const result = await performTransformation(data);
      return result;
    },
  },
  {
    name: 'rule2',
    dependencies: [],
    transformer: async (data) => {
      // Perform transformation logic on data
      const result = await performTransformation(data);
      return result;
    },
  },
];

