const outputFile = 'output.txt';

// Create a promise that resolves when all transformations are complete or rejects if any step fails
const processBinaryFile = async () => {
  // Load the binary file asynchronously
  const data = await loadBinaryFile(inputFile);

  // Apply each parsing rule in sequence, passing the output of each rule to the next one
  let result = data;
  for (const rule of rules) {
    try {
      // Apply the current rule and get the result
      const transformedData = await rule.transformer(result);
      // Update the result with the transformed data
      result = transformedData;
    } catch (error) {
      console.log(`Error applying rule ${rule.name}: ${error}`);
      return Promise.reject(error);
    }
  }

  // Write the transformed data to the output file asynchronously
  await writeFileAsync(outputFile, result);

  return Promise.resolve();
};

// Load the binary file asynchronously
