  try {
    const buffer = fs.readFileSync(path.join(__dirname, filePath));
    return buffer;
  } catch (error) {
    console.log(`Error loading file ${filePath}: ${error}`);
    return Promise.reject(error);
  }
};

// Write the transformed data to the output file asynchronously
