```python
import time
from requests import request
from urllib.parse import urlencode

def send_request(method, endpoint, params=None):
    # Send a request to an external service
    response = request(method, endpoint, params=params)

    if response.status_code == 200:
        return response.json()
    else:
        raise Exception("Failed to fetch data from {}".format(endpoint))

def deploy(service):
    # Deploy a new version of the service
    endpoint = "https://deployment-api.com/services/{}/deploy".format(service)
    params = {"version": "1.2.3"}
    response = send_request("POST", endpoint, params=params)

    if not response["success"]:
        raise Exception("Failed to deploy service {}".format(service))
    else:
        return response

def rollback(service):
    # Roll back a failed deployment
    endpoint = "https://deployment-api.com/services/{}/rollback".format(service)
    params = {"version": "1.2.3"}
    response = send_request("POST", endpoint, params=params)

    if not response["success"]:
        raise Exception("Failed to roll back deployment of service {}".format(service))
    else:
        return response

def monitor_deployment():
    # Monitor the status of deployments and handle failures
    while True:
        # Get a list of services with active deployments
        services = request("GET", "https://deployment-api.com/services")

        for service in services:
            if service["status"] == "FAILED":
                # Roll back the failed deployment
                rollback(service["name"])

        time.sleep(60) # Sleep for 1 minute between iterations
