#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <pthread.h>
#include <errno.h>
#include <stdbool.h>
#include "authentication_state_update.h"

#define AUTHENTICATION_STATE_FILE "/var/run/authentication-state.json"
#define MAX_CONCURRENT_UPDATES 100
#define MIN_PASSWORD_LENGTH 8
#define MAX_PASSWORD_COMPLEXITY 256
#define PASSWORD_UNIQUENESS_THRESHOLD 0.9

typedef struct {
    char *user;
    bool authenticated;
} user_authentication_state;

static pthread_mutex_t authentication_state_lock = PTHREAD_MUTEX_INITIALIZER;
static user_authentication_state *authentication_state_map;
static size_t authentication_state_map_size;
static size_t authentication_state_map_capacity;
static size_t authentication_state_update_count;

// Function to initialize the authentication state map and lock.
void init_authentication_state() {
    authentication_state_map = malloc(sizeof(user_authentication_state) * 1024);
    authentication_state_map_size = 0;
    authentication_state_map_capacity = 1024;
    pthread_mutex_init(&authentication_state_lock, NULL);
}

// Function to update the authentication state for a given user.
void update_authentication_state(const char *user, bool authenticated) {
    pthread_mutex_lock(&authentication_state_lock);
    size_t index = hash_string(user) % authentication_state_map_capacity;
    while (index < authentication_state_map_size && strcmp(authentication_state_map[index].user, user) != 0) {
        index++;
    }
    if (index == authentication_state_map_size) {
        // User not found in map. Add new entry.
        if (authentication_state_update_count >= MAX_CONCURRENT_UPDATES) {
            pthread_mutex_unlock(&authentication_state_lock);
            return;
        }
        size_t new_size = authentication_state_map_capacity + 1024;
        user_authentication_state *new_map = realloc(authentication_state_map, sizeof(user_authentication_state) * new_size);
        if (new_map == NULL) {
            pthread_mutex_unlock(&authentication_state_lock);
            return;
        }
        authentication_state_map = new_map;
        authentication_state_map[index].user = strdup(user);
        authentication_state_map[index].authenticated = authenticated;
        authentication_state_map_size++;
        authentication_state_update_count++;
    } else {
        // User found in map. Update entry.
        authentication_state_map[index].authenticated = authenticated;
    }
    pthread_mutex_unlock(&authentication_state_lock);
}

// Function to retrieve the authentication state for a given user.
bool get_authentication_state(const char *user) {
    bool result = false;
    pthread_mutex_lock(&authentication_state_lock);
    size_t index = hash_string(user) % authentication_state_map_capacity;
    while (index < authentication_state_map_size && strcmp(authentication_state_map[index].user, user) != 0) {
        index++;
    }
    if (index == authentication_state_map_size) {
        // User not found in map. Return default value.
        result = false;
    } else {
        // User found in map. Return stored value.
        result = authentication_state_map[index].authenticated;
    }
    pthread_mutex_unlock(&authentication_state_lock);
    return result;
}

// Function to hash a string and produce a unique index for the authentication state map.
size_t hash_string(const char *str) {
    size_t hash = 5381;
    int c;
    while ((c = *str++) != '\0') {
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }
    return hash % authentication_state_map_capacity;
}

// Function to load the authentication state from a file.
void load_authentication_state(const char *file) {
    FILE *fp = fopen(file, "r");
    if (fp == NULL) {
        return;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        char *user = strtok(line, "\t");
        bool authenticated = false;
        if (strcmp(user, "true") == 0) {
            authenticated = true;
        } else if (strcmp(user, "false") == 0) {
            authenticated = false;
        }
        update_authentication_state(user, authenticated);
    }
    fclose(fp);
}

// Function to save the authentication state to a file.
void save_authentication_state(const char *file) {
    FILE *fp = fopen(file, "w");
    if (fp == NULL) {
        return;
    }
    for (size_t i = 0; i < authentication_state_map_size; i++) {
        fprintf(fp, "%s\t%d\n", authentication_state_map[i].user, authentication_state_map[i].authenticated);
    }
    fclose(fp);
}
