        printf("Error: session token length is out of bounds\n");
        return;
    }
    for (int i = 0; i < token_length; ++i) {
        char c = session_token[i];
        if (!isalpha(c) && !isdigit(c)) {
            printf("Error: session token does not meet entropy requirements\n");
            return;
        }
