void removeIndicator(struct NfarxIndications* nfarx_indications, size_t index);
int getIndicatorCount(struct NfarxIndications* nfarx_indications);
struct NFAPI_CRC_INDICATION_PDU_T* getIndicator(struct NfarxIndications* nfarx_indications, size_t index);
void resetNfarxIndications(struct NfarxIndications* nfarx_indications);
void destroyNfarxIndications(struct NfarxIndications* nfarx_indications);

// Function definitions
void initializeNfarxIndications(struct NfarxIndications* nfarx_indications, size_t capacity, unsigned short seed, void* memory_pool) {
    if (nfarx_indications == NULL || capacity < 1 || capacity > NFARX_INDICATIONS_MAX_CAPACITY) return;
    nfarx_indications->capacity = capacity;
    nfarx_indications->count = 0;
    nfarx_indications->growth_factor = NFARX_INDICATIONS_GROWTH_FACTOR;
    nfarx_indications->seed = seed;
    nfarx_indications->memory_pool = memory_pool;
    nfarx_indications->indications = (struct NFAPI_CRC_INDICATION_PDU_T**) malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T*) * capacity);
}

void increaseCapacity(struct NfarxIndications* nfarx_indications) {
    if (nfarx_indications == NULL || nfarx_indications->capacity >= NFARX_INDICATIONS_MAX_CAPACITY) return;
    size_t new_capacity = nfarx_indications->capacity * nfarx_indications->growth_factor;
    if (new_capacity > NFARX_INDICATIONS_MAX_CAPACITY) new_capacity = NFARX_INDICATIONS_MAX_CAPACITY;
    struct NFAPI_CRC_INDICATION_PDU_T** new_indications = (struct NFAPI_CRC_INDICATION_PDU_T**) realloc(nfarx_indications->indications, sizeof(struct NFAPI_CRC_INDICATION_PDU_T*) * new_capacity);
    if (new_indications == NULL) return;
    nfarx_indications->capacity = new_capacity;
    nfarx_indications->indications = new_indications;
}

void insertIndicator(struct NfarxIndications* nfarx_indications, struct NFAPI_CRC_INDICATION_PDU_T* indicator) {
    if (nfarx_indications == NULL || indicator == NULL) return;
    size_t index = nfarx_indications->count++;
    if (index >= nfarx_indications->capacity) increaseCapacity(nfarx_indications);
    memcpy(nfarx_indications->indications[index], indicator, sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
}

void removeIndicator(struct NfarxIndications* nfarx_indications, size_t index) {
    if (nfarx_indications == NULL || index >= nfarx_indications->count) return;
    memcpy(nfarx_indications->indications[index], nfarx_indications->indications[--nfarx_indications->count], sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
}

int getIndicatorCount(struct NfarxIndications* nfarx_indications) {
    if (nfarx_indications == NULL) return -1;
    return nfarx_indications->count;
}

struct NFAPI_CRC_INDICATION_PDU_T* getIndicator(struct NfarxIndications* nfarx_indications, size_t index) {
    if (nfarx_indications == NULL || index >= nfarx_indications->count) return NULL;
    return nfarx_indications->indications[index];
}

void resetNfarxIndications(struct NfarxIndications* nfarx_indications) {
    if (nfarx_indications == NULL) return;
    nfarx_indications->count = 0;
}

void destroyNfarxIndications(struct NfarxIndications* nfarx_indications) {
    if (nfarx_indications == NULL) return;
    free(nfarx_indications->indications);
    nfarx_indications->indications = NULL;
    nfarx_indications->count = 0;
    nfarx_indications->capacity = 0;
}
