package main

import (
	"context"
	"log"
	"time"

	"github.com/google/uuid"
)

func main() {
	ctx := context.Background()

	// Set up the queuing system
	queue := make(chan *task, 10)
	defer close(queue)

	// Start the processing pipeline
	go func() {
		for {
			select {
			case task := <-queue:
				log.Printf("Processing task %s\n", task.ID)
				// Perform data processing steps here
				time.Sleep(1 * time.Second)
				log.Printf("Task %s completed\n", task.ID)
			}
		}
	}()

	// Set up the data ingestion system
	ingestor := NewIngestor(queue)
	defer ingestor.Close()

	// Handle real-time data ingestion from diverse IoT devices
	for {
		select {
		case sensorData := <-ingestor.SensorDataChan:
			task := &task{
				ID:        uuid.NewString(),
				SensorData: sensorData,
			}
			queue <- task
		case <-ctx.Done():
			return
		}
	}
}

type task struct {
	ID         string
	SensorData []byte
}

type Ingestor struct {
	SensorDataChan chan []byte
}

func NewIngestor(queue chan *task) *Ingestor {
	return &Ingestor{
		SensorDataChan: queue,
	}
}

func (i *Ingestor) Close() error {
	close(i.SensorDataChan)
	return nil
}
