// RealTimeNetworkMonitor.cpp
#include "RealTimeNetworkMonitor.h"

#include <iostream>
#include <string>
#include <vector>

// Constructor
RealTimeNetworkMonitor::RealTimeNetworkMonitor(const std::string& key, const std::string& metadata) {
  // Add the data source to the map
  dataSources_[key] = new DataSource(metadata);
}

// Destructor
RealTimeNetworkMonitor::~RealTimeNetworkMonitor() {
  // Delete all the data sources
  for (const auto& [key, dataSource] : dataSources_) {
    delete dataSource;
  }
}

// Adds a data source to the network monitor
void RealTimeNetworkMonitor::addDataSource(const std::string& key, const std::string& metadata) {
  // Check if the data source already exists
  if (dataSources_.find(key) != dataSources_.end()) {
    return;
  }

  // Add the data source to the map
  dataSources_[key] = new DataSource(metadata);
}

// Removes a data source from the network monitor
void RealTimeNetworkMonitor::removeDataSource(const std::string& key) {
  // Check if the data source exists
  if (dataSources_.find(key) == dataSources_.end()) {
    return;
  }

  // Delete the data source
  delete dataSources_[key];

  // Remove the data source from the map
  dataSources_.erase(key);
}

// Starts the network monitor and begins monitoring the data sources
void RealTimeNetworkMonitor::start() {
  // Start a new thread for monitoring the network conditions and adjusting buffer size
  std::thread monitorThread(&RealTimeNetworkMonitor::monitorNetworkThread, this);

  // Detach the thread so that it can run independently
  monitorThread.detach();
}

// Stops the network monitor and cleans up resources
void RealTimeNetworkMonitor::stop() {
  // Join all the threads created by the data sources
  for (const auto& [key, dataSource] : dataSources_) {
    if (dataSource->thread != nullptr) {
      dataSource->thread->join();
    }
  }
}

// Function for adjusting buffer size based on network latency
void RealTimeNetworkMonitor::adjustBufferForLatency(const double& currentLatency) {
  // Check if the current latency is within the acceptable range
  if (currentLatency <= maximumAcceptableLatency_) {
    return;
  }

  // Calculate an optimal buffer size based on the current latency and the maximum buffer size constraint
  double optimalBufferSize = std::max(bufferSizeConstraint_, std::ceil(currentLatency / optimalBufferFactor_));

  // Adjust the buffer size for each data source
  for (const auto& [key, dataSource] : dataSources_) {
    dataSource->adjustBufferSize(optimalBufferSize);
  }
}

// Function for handling lost packets and retransmissions
void RealTimeNetworkMonitor::handlePacketLossAndRetransmission() {
  // Check if the current buffer size is within the acceptable range
  if (bufferSize_ <= maximumAcceptableBufferSize_) {
    return;
  }

  // Calculate an optimal buffer size based on the current buffer size and the maximum buffer size constraint
  double optimalBufferSize = std::min(bufferSizeConstraint_, std::ceil(bufferSize_ * optimalBufferFactor_));

  // Adjust the buffer size for each data source
  for (const auto& [key, dataSource] : dataSources_) {
    dataSource->adjustBufferSize(optimalBufferSize);
  }
}

// Function for detecting anomalies in the data stream
void RealTimeNetworkMonitor::detectAnomalies() {
  // Check if the current buffer size is within the acceptable range
  if (bufferSize_ <= maximumAcceptableBufferSize_) {
    return;
  }

  // Calculate an optimal buffer size based on the current buffer size and the maximum buffer size constraint
  double optimalBufferSize = std::min(bufferSizeConstraint_, std::ceil(bufferSize_ * optimalBufferFactor_));

  // Adjust the buffer size for each data source
  for (const auto& [key, dataSource] : dataSources_) {
    dataSource->adjustBufferSize(optimalBufferSize);
  }
}

// Function for monitoring the network conditions and adjusting buffer size
void RealTimeNetworkMonitor::monitorNetworkThread() {
  // Loop forever to monitor the network conditions and adjust the buffer size
  while (true) {
    // Calculate the current latency based on the buffer size and the maximum acceptable latency
    double currentLatency = std::max(0.0, bufferSize_ / optimalBufferFactor_ - maximumAcceptableLatency_);

    // Adjust the buffer size for each data source based on the current latency
    adjustBufferForLatency(currentLatency);

    // Calculate the current buffer size based on the maximum acceptable buffer size and the optimal buffer size factor
    double currentBufferSize = std::min(maximumAcceptableBufferSize_, std::ceil(bufferSizeFactor_ * optimalBufferSize_));

    // Adjust the buffer size for each data source based on the current buffer size
    handlePacketLossAndRetransmission();
  }
}
