    if (request.startsWith("fetch_employee")) {
        handleFetchEmployeeRequest(request, config);
    } else {
        throw invalid_argument("Invalid employee request type");
    }
}

void handleFetchEmployeeRequest(const string& request, const ServiceConfig& config) {
    // Extract the employee ID from the request
    int id = stoi(request.substr(strlen("fetch_employee")));

    // Check if the employee is in the cache
    Employee employee;
    bool found = false;

    cache_mtx.lock();
    for (const auto& emp : config.employees) {
        if (emp.id == id) {
            employee = emp;
            found = true;
            break;
        }
    }
    cache_mtx.unlock();

    // If the employee is not in the cache, fetch it from the RESTful API
    if (!found) {
        Employee newEmployee = apiClient.getEmployeeData(id);

        // Update the cache with the new employee data
        cache_mtx.lock();
        cache[newEmployee.id] = newEmployee;
        cache_mtx.unlock();
    }

    // Return the employee data to the client
    string response = "{\"employee\":";
    response += serialize(employee);
    response += "}";
    sendResponse(response);
}
