// Structure to represent an NFAPI_CRC_INDICATION_PDU
typedef struct {
    uint32_t crc;
    uint8_t num_ues;
    struct ue_info {
        uint16_t ue_id;
        uint16_t cell_id;
        uint8_t num_crcs;
        uint8_t *crcs;
    } ues[NFAPI_MAX_NUM_UES];
} nfapi_crc_indication_pdu_t;

// Global variable to store the linked list of NFAPI_CRC_INDICATION_PDUs
static nfapi_crc_indication_pdu_t *list = NULL;

// Lock to protect access to the linked list
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new NFAPI_CRC_INDICATION_PDU to the linked list
void nfapi_add_crc_indication_pdu(nfapi_crc_indication_pdu_t *pdu) {
    // Acquire lock to modify the linked list
    pthread_mutex_lock(&lock);

    // Check if the linked list is empty
    if (list == NULL) {
        // Initialize the linked list with the new PDU
        list = pdu;
    } else {
        // Add the new PDU to the end of the linked list
        nfapi_crc_indication_pdu_t *curr = list;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = pdu;
    }

    // Release lock to allow other threads to access the linked list
    pthread_mutex_unlock(&lock);
}

// Function to remove an NFAPI_CRC_INDICATION_PDU from the linked list
void nfapi_remove_crc_indication_pdu(nfapi_crc_indication_pdu_t *pdu) {
    // Acquire lock to modify the linked list
    pthread_mutex_lock(&lock);

    // Check if the linked list is empty
    if (list == NULL) {
        // Release lock and return since there are no PDUs in the linked list
        pthread_mutex_unlock(&lock);
        return;
    }

    // Check if the PDU to be removed is at the head of the linked list
    if (pdu == list) {
        // Remove the PDU from the head of the linked list and update the head pointer
        nfapi_crc_indication_pdu_t *next = pdu->next;
        free(pdu);
        list = next;
    } else {
        // Search for the PDU to be removed in the linked list
        nfapi_crc_indication_pdu_t *curr = list, *prev = NULL;
        while (curr != NULL && curr != pdu) {
            prev = curr;
            curr = curr->next;
        }

        // Check if the PDU was found in the linked list
        if (curr == NULL) {
            // Release lock and return since the PDU to be removed was not found in the linked list
            pthread_mutex_unlock(&lock);
            return;
        }

        // Remove the PDU from the linked list and update the next pointer of the previous PDU
        prev->next = curr->next;
        free(curr);
    }

    // Release lock to allow other threads to access the linked list
    pthread_mutex_unlock(&lock);
}

// Function to retrieve an NFAPI_CRC_INDICATION_PDU from the linked list
nfapi_crc_indication_pdu_t *nfapi_get_crc_indication_pdu(uint32_t crc) {
    // Acquire lock to access the linked list
    pthread_mutex_lock(&lock);

    // Search for the PDU with the specified CRC value in the linked list
    nfapi_crc_indication_pdu_t *curr = list;
    while (curr != NULL && curr->crc != crc) {
        curr = curr->next;
    }

    // Check if the PDU was found in the linked list
    if (curr == NULL) {
        // Release lock and return since no PDU with the specified CRC value was found in the linked list
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Return a copy of the found PDU
    nfapi_crc_indication_pdu_t *copy = malloc(sizeof(nfapi_crc_indication_pdu_t));
    memcpy(copy, curr, sizeof(nfapi_crc_indication_pdu_t));

    // Release lock to allow other threads to access the linked list
    pthread_mutex_unlock(&lock);

    return copy;
}
