    while (fgets(line, MAX_PATH_LENGTH - 1, config_file)) {
        // Parse configuration file lines
        if (strlen(line) > MAX_PATH_LENGTH) {
            handle_error(-5, "Invalid line in configuration file");
        }
    }

    fclose(config_file);
}

