        compression_level = 5;
    }

    if (quality_settings < 1 || quality_settings > 100) {
        quality_settings = 80;
    }
}

void handle_errors(struct conversion_result result) {
    if (result.length == 0) {
        handle_error(-6, "Conversion failed");
    } else {
        print_debug("Successfully converted %s to %s", input_file, output_dir);
    }
}

void handle_error(int errnum, char* message) {
