                }

                _logger.LogInformation($"{applicationName} has been successfully deployed.");

                // Update web application configuration
                var configCommand = $"config --name {applicationName} --group {deploymentGroup}";
                await ExecuteConfigCommandAsync(configCommand);

                deploymentResult = true;
            }
            else
            {
                _logger.LogInformation($"{applicationName} is already deployed.");
            }

            return deploymentResult;
        }

        // Public Method for Monitoring Web Applications
        public async Task<bool> IsWebApplicationDeployedAsync(string applicationName, string deploymentGroup)
        {
            var isDeployed = false;

            try
            {
                var uri = $"{deploymentGroup}/{applicationName}";
                var response = await _httpClient.GetAsync(uri);

                if (response.IsSuccessStatusCode)
                {
                    isDeployed = true;
                }
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to check if web application is deployed.");
            }

            return isDeployed;
        }

        // Private Method for Executing Deployment Commands
        private async Task ExecuteDeployCommandAsync(string command)
        {
            try
            {
                var uri = $"{_configuration["Deployment:Url"]}/{command}";
                await _httpClient.PostAsync(uri, null);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to execute deployment command.");
            }
        }

        // Private Method for Executing Configuration Commands
        private async Task ExecuteConfigCommandAsync(string command)
        {
            try
            {
                var uri = $"{_configuration["Configuration:Url"]}/{command}";
                await _httpClient.PostAsync(uri, null);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Failed to execute configuration command.");
            }
        }
    }
}']

