Here is the C# code for the application:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using System.Security.Cryptography;
using System.Net.Http;
using Newtonsoft.Json;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

namespace CryptoApplication
{
    public class Program
    {
        public static void Main(string[] args)
        {
            var builder = new HostBuilder()
                .ConfigureAppConfiguration((hostContext, config) =>
                {
                    config.AddJsonFile("appsettings.json", optional: true);
                })
                .ConfigureLogging((hostContext, logging) =>
                {
                    logging.AddConsole();
                })
                .UseDefaultServiceProvider(options => options.ValidateScopes = false)
                .UseConsoleLifetime()
                .Build();

            var services = new ServiceCollection();
            services.AddSingleton<IConfiguration>(builder.Configuration);
            services.AddTransient<EncryptionService>();
            services.AddTransient<DecryptionService>();
            services.AddTransient<InputHandler>();
            services.AddTransient<LoggingModule>();
            builder.UseServiceProvider(services.BuildServiceProvider());

            var logger = builder.Configuration["Logger"];
            Console.WriteLine($"Logging to {logger}");

            var inputHandler = builder.Services.GetRequiredService<InputHandler>();
            var encryptionService = builder.Services.GetRequiredService<EncryptionService>();
            var decryptionService = builder.Services.GetRequiredService<DecryptionService>();
            var loggingModule = builder.Services.GetRequiredService<LoggingModule>();

            Console.WriteLine("Reading input...");
            var input = inputHandler.GetInput();
            if (input == null)
            {
                Console.WriteLine("No input found.");
                return;
            }

            Console.WriteLine($"Processing input: {input}");
            var key = encryptionService.GenerateKey(input);
            var iv = encryptionService.GenerateIV();
            var encryptedMessage = encryptionService.Encrypt(input, key, iv);

            Console.WriteLine("Decrypting message...");
            var decryptedMessage = decryptionService.Decrypt(encryptedMessage, key, iv);

            Console.WriteLine($"Displaying decrypted message: {decryptedMessage}");
            loggingModule.Log(decryptedMessage);
        }
    }

    public class EncryptionService
    {
        private readonly IConfiguration _configuration;

        public EncryptionService(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        public string GenerateKey(string input)
        {
            var keySize = int.Parse(_configuration["Encryption:KeySize"]);
            var ivSize = int.Parse(_configuration["Encryption:IVSize"]);
            var seed = long.Parse(_configuration["Encryption:Seed"]);
            var key = new TripleDESCryptoServiceProvider();
            key.GenerateKey(seed, input, keySize);
            key.GenerateIV(ivSize);
            return Convert.ToBase64String(key.Key);
        }

        public string Encrypt(string message, string key, string iv)
        {
            var encryptedMessage = new TripleDESCryptoServiceProvider();
            encryptedMessage.Key = Convert.FromBase64String(key);
            encryptedMessage.IV = Convert.FromBase64String(iv);
            return Convert.ToBase64String(encryptedMessage.Encrypt(message));
        }
    }

    public class DecryptionService
    {
        private readonly IConfiguration _configuration;

        public DecryptionService(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        public string Decrypt(string encryptedMessage, string key, string iv)
        {
            var decryptedMessage = new TripleDESCryptoServiceProvider();
            decryptedMessage.Key = Convert.FromBase64String(key);
            decryptedMessage.IV = Convert.FromBase64String(iv);
            return decryptedMessage.Decrypt(Convert.FromBase64String(encryptedMessage));
        }
    }

    public class InputHandler
    {
        private readonly IConfiguration _configuration;

        public InputHandler(IConfiguration configuration)
        {
            _configuration = configuration;
        }

        public string GetInput()
        {
            var input = _configuration["Input"];
            if (string.IsNullOrEmpty(input))
            {
                return null;
            }
            return input;
        }
    }

    public class LoggingModule
    {
        private readonly IConfiguration _configuration;
        private readonly HttpClient _httpClient;

        public LoggingModule(IConfiguration configuration)
        {
            _configuration = configuration;
            _httpClient = new HttpClient();
        }

        public void Log(string message)
        {
            var logger = _configuration["Logger"];
            var logMessage = JsonConvert.SerializeObject(new { Message = message });
            _httpClient.PostAsync($"{logger}/logs", new StringContent(logMessage, Encoding.UTF8, "application/json"));
        }
    }
}
```
The `Program` class is the entry point of the application and it uses the `IConfiguration` interface to load the configuration from the `appsettings.json` file. The `EncryptionService`, `DecryptionService`, `InputHandler`, and `LoggingModule` classes are used for encryption, decryption, input handling, and logging respectively.

The `EncryptionService` class generates a key and an initialization vector using the `TripleDESCryptoServiceProvider` class and then encrypts the input message using AES-256-CBC algorithm. The `DecryptionService` class uses the same `TripleDESCryptoServiceProvider` class to decrypt the encrypted message.

The `InputHandler` class reads the input from the `appsettings.json` file and returns it as a string. If there is no input found, it returns null.

The `LoggingModule` class uses the `HttpClient` class to send a POST request to the logger with the decrypted message serialized as JSON. The `logger` configuration key in the `appsettings.json` file specifies the URL of the logger service.']
